/* Kuvonch Academy — ingliz tili grammatikasi modullari (grammatika kitobi asosida) */
window.EN_GRAMMAR = [{"id":"p1-01","en":"Simple Sentence Structure","uz":"Sodda gap tuzilishi","emoji":"🧱","level":"A2","group":"Gap va ot","summary":"Ingliz tilidagi sodda gap S + P + C + M formulasi asosida quriladi: ega, kesim, to'ldiruvchi va aniqlovchi (hol). Har bir bo'lakning vazifasi va gapdagi o'rni bilan tanishamiz.","blocks":[{"t":"formula","x":"S + P + C + M"},{"t":"list","items":["<b>S – Subject</b> – ega","<b>P – Predicate</b> – kesim","<b>C – Complement</b> – to'ldiruvchi","<b>M – Modifier</b> – aniqlovchi (hol)"]},{"t":"h","x":"S – Subject (ega)"},{"t":"p","x":"Ega – gapda ish-harakatni bajaruvchi shaxs yoki narsa. U <b>who?</b> (kim?) va <b>what?</b> (nima?) so'roqlariga javob beradi. Har qanday gapda ega bo'lishi <b>shart</b>."},{"t":"ex","en":"He jumps high. – Who jumps high?","uz":"U baland sakraydi. – Kim baland sakraydi?"},{"t":"p","x":"Ega odatda kesimdan oldin keladi. Ish-harakat bo'lmagan gaplarda gap mazmuni ega haqida bo'ladi:"},{"t":"ex","en":"Coffee is delicious. – What is delicious?","uz":"Qahva mazali. – Nima mazali?"},{"t":"p","x":"Ega bitta yoki bir nechta so'zdan iborat bo'lishi mumkin:"},{"t":"ex","en":"Tom runs fast.","uz":"Tom tez yuguradi. (bir so'zli ega)"},{"t":"ex","en":"An old weak woman is crossing the road. Be careful!","uz":"Keksa, holsiz ayol yo'lni kesib o'tyapti. Ehtiyot bo'ling! (bir necha so'zli ega)"},{"t":"rule","x":"Diqqat: ba'zi gaplarda ega o'z o'rnida kelmaydi. <i>There is an apple.</i> gapida haqiqiy ega – <b>apple</b>, <b>there</b> esa soxta (qalbaki) ega. Buning sababi so'roq gapda ko'rinadi: so'roq tuzilganda <b>to be</b> fe'li there'dan oldinga o'tadi (<i>Is there an apple?</i>) – bu esa haqiqiy egaga xos emas."},{"t":"h","x":"P – Predicate (kesim)"},{"t":"p","x":"Kesim ish-harakatning bajarilishini bildiradi va gapda egadan keyin keladi. Kesim ham gapda <b>doim bo'lishi shart</b>."},{"t":"ex","en":"Ted always cries.","uz":"Ted doim yig'laydi."},{"t":"p","x":"Kesim bir nechta so'zdan iborat bo'lishi mumkin:"},{"t":"ex","en":"He is going home.","uz":"U uyga ketyapti."},{"t":"rule","x":"Agar <b>to be</b> gapda asosiy fe'l (ordinary verb) sifatida kelsa, u o'zidan keyingi to'ldiruvchi bilan birgalikda kesim hisoblanadi. Bunday gaplar o'zbek tiliga <b>“-dir”</b> qo'shimchasi bilan tarjima qilinadi."},{"t":"ex","en":"He is a student.","uz":"U talabadir."},{"t":"h","x":"C – Complement (to'ldiruvchi)"},{"t":"p","x":"To'ldiruvchi kesimdan keyin keladi va uni to'ldiradi. U <b>what?</b> (nimani?) va <b>whom?</b> (kimni?) so'roqlariga javob beradi. Har qanday gapda to'ldiruvchi bo'lishi <b>shart emas</b>."},{"t":"ex","en":"I saw Bill. – Whom did you see?","uz":"Men Billni ko'rdim. – Kimni ko'rding?"},{"t":"ex","en":"He took it. – What did he take?","uz":"U uni oldi. – U nimani oldi?"},{"t":"ex","en":"I sleep.","uz":"Men uxlayman. (to'ldiruvchisiz gap)"},{"t":"p","x":"To'ldiruvchi bir necha so'zdan iborat bo'lishi mumkin:"},{"t":"ex","en":"Tom was driving his new car.","uz":"Tom yangi mashinasini haydayotgan edi."},{"t":"h","x":"M – Modifier (aniqlovchi / hol)"},{"t":"p","x":"Modifier gapda to'ldiruvchidan keyin keladi va gapga qo'shimcha ma'no berib, uni aniqlashtiradi. Uning uch turi bor:"},{"t":"table","head":["Turi","Nimani bildiradi","So'rog'i"],"rows":[["Modifier of time","Ish-harakat qachon bo'lganini","When?"],["Modifier of place","Ish-harakat qayerda bo'lganini","Where?"],["Modifier of manner","Ish-harakat qanday holatda bo'lganini","How?"]]},{"t":"ex","en":"I saw him yesterday. – When did you see him?","uz":"Men uni kecha ko'rdim. – Uni qachon ko'rding?"},{"t":"ex","en":"I saw him at school. – Where did you see him?","uz":"Men uni maktabda ko'rdim. – Uni qayerda ko'rding?"},{"t":"ex","en":"I drive fast. – How do you drive?","uz":"Men tez haydayman. – Qanday haydaysan?"},{"t":"h","x":"Modifierlar tartibi"},{"t":"formula","x":"1. Manner (qanday) → 2. Place (qayerda) → 3. Time (qachon)"},{"t":"ex","en":"Tom was running fast on the highway two days ago.","uz":"Tom ikki kun oldin katta yo'lda tez yugurayotgan edi."},{"t":"rule","x":"Agar gapda bittadan ortiq modifier bo'lsa, <b>modifier of time</b>ni gap boshiga chiqarish mumkin – gap ma'nosi o'zgarmaydi."},{"t":"ex","en":"Yesterday he was swimming in the pool.","uz":"Kecha u hovuzda suzayotgan edi."},{"t":"ex","en":"He was swimming in the pool yesterday.","uz":"U kecha hovuzda suzayotgan edi."},{"t":"ex","en":"Ann, my cousin, and Tom have been learning English by heart in the library for two hours.","uz":"Ann, mening amakivachcham va Tom ikki soatdan beri kutubxonada inglizcha yod olishyapti. (S + P + C + M: manner, place, time)"}],"quiz":[{"q":"What is the subject in: «Coffee is delicious.»?","o":["is delicious","Coffee","delicious","is"],"a":1,"e":"Ega what? so'rog'iga javob beradi: What is delicious? – Coffee."},{"q":"Which part, besides the subject, must be present in every sentence?","o":["Modifier of place","Complement","Predicate","Modifier of time"],"a":2,"e":"Ega va kesim har qanday gapda bo'lishi shart; to'ldiruvchi va modifier esa shart emas."},{"q":"Find the complement: «I saw Bill.»","o":["I","Bill","saw","saw Bill"],"a":1,"e":"To'ldiruvchi whom? so'rog'iga javob beradi: Whom did you see? – Bill."},{"q":"In «I saw him yesterday», the word «yesterday» is a ...","o":["modifier of manner","complement","modifier of time","modifier of place"],"a":2,"e":"Yesterday – When? so'rog'iga javob beradi, demak bu modifier of time."},{"q":"Choose the sentence with the correct order of modifiers.","o":["Tom was running two days ago fast on the highway.","Tom was running on the highway fast two days ago.","Tom was running two days ago on the highway fast.","Tom was running fast on the highway two days ago."],"a":3,"e":"Tartib: manner (fast) → place (on the highway) → time (two days ago)."},{"q":"Which sentence has NO complement?","o":["Tom was driving his new car.","He took it.","I saw Bill.","I sleep."],"a":3,"e":"I sleep gapida what?/whom? so'rog'iga javob beruvchi bo'lak yo'q – to'ldiruvchi shart emas."},{"q":"What is the real subject in «There is an apple.»?","o":["There","apple","There is","is"],"a":1,"e":"There – soxta ega; haqiqiy ega apple. So'roqda to be there'dan oldinga o'tadi: Is there an apple?"},{"q":"A modifier of manner answers the question ...","o":["Where?","Whom?","When?","How?"],"a":3,"e":"Modifier of manner ish-harakat qanday holatda bajarilganini bildiradi va How? so'rog'iga javob beradi."},{"q":"Which sentence has the same meaning and is correct: «He was swimming in the pool yesterday.»","o":["In the pool he yesterday was swimming.","He yesterday was in the pool swimming.","Was swimming he in the pool yesterday.","Yesterday he was swimming in the pool."],"a":3,"e":"Modifier of time'ni gap boshiga chiqarish mumkin, ma'no o'zgarmaydi."},{"q":"In «He is a student.», what is the predicate?","o":["He","is a student","student","a student"],"a":1,"e":"To be asosiy fe'l bo'lib kelsa, o'zidan keyingi bo'lak bilan birga kesim bo'ladi: «U talabadir»."}]},{"id":"p1-02","en":"Nouns and Gender","uz":"Ot turlari va jins","emoji":"🏷️","level":"A1","group":"Gap va ot","summary":"Otlarning to'rt turi (common, proper, abstract, collective) va otlarning jinsi – erkak, ayol va jinssiz (masculine, feminine, neuter) – haqida dars.","blocks":[{"t":"h","x":"Noun – Ot"},{"t":"p","x":"Ot <b>who?</b> (kim?) va <b>what?</b> (nima?) so'roqlariga javob beradi. Otlar to'rt guruhga bo'linadi:"},{"t":"table","head":["Turi","Ma'nosi","Misollar"],"rows":[["Common noun (turdosh ot)","Odamlar, joylar, narsalar va hayvonlar","man, door, corner, dog"],["Proper noun (atoqli ot)","Aniq nomlar, atamalar","John, France, Santa Claus, New Year"],["Abstract noun (mavhum ot)","Ko'z bilan ko'rib, qo'l bilan ushlab bo'lmaydigan tushunchalar","beauty, courage, friendship"],["Collective noun (jamlovchi ot)","Bir guruh odamlar, hayvonlar yoki narsalar","family, crowd"]]},{"t":"h","x":"Gender – Jins"},{"t":"p","x":"Gender otning qaysi jinsga tegishli ekanini ko'rsatadi. Uning uch ko'rinishi bor:"},{"t":"list","items":["<b>Masculine</b> (erkak jinsi) – o'g'il bolalar, erkaklar va erkak hayvonlar: <i>boy, uncle, cock</i>","<b>Feminine</b> (ayol jinsi) – qizlar, ayollar va urg'ochi hayvonlar: <i>girl, aunt, hen</i>","<b>Neuter</b> (jinssiz) – jonsiz narsalar, jinsi noma'lum hayvonlar va hali o'g'il-qizligi ma'lum bo'lmagan chaqaloqlar: <i>table</i>"]},{"t":"rule","x":"Istisno: kema va mashinalar haqida erkalab gapirilganda ba'zan <b>feminine</b> (she) ishlatiladi."},{"t":"ex","en":"She is my baby. (about a car)","uz":"U mening jonginam. (mashina haqida)"},{"t":"h","x":"Jinsga oid juft so'zlar"},{"t":"p","x":"<b>Odamlar uchun:</b>"},{"t":"table","head":["Masculine","Feminine"],"rows":[["father","mother"],["husband","wife"],["king","queen"],["widower","widow"]]},{"t":"p","x":"<b>Uy va yovvoyi hayvonlar uchun:</b>"},{"t":"table","head":["Masculine","Feminine"],"rows":[["bull (buqa)","cow (sigir)"],["dog (it)","bitch (urg'ochi it)"],["drake (erkak o'rdak)","duck (o'rdak)"],["ram (qo'chqor)","ewe (sovliq)"],["jack (erkak eshak)","jenny (urg'ochi eshak)"],["tiger (yo'lbars)","tigress (urg'ochi yo'lbars)"],["stallion (ayg'ir)","mare (biya)"]]},{"t":"p","x":"<b>Kasblar (occupations) uchun:</b>"},{"t":"table","head":["Masculine","Feminine"],"rows":[["actor","actress"],["conductor","conductress"],["heir","heiress"],["hero","heroine"],["manager","manageress"],["steward","stewardess"],["waiter","waitress"],["host","hostess"]]},{"t":"h","x":"Jinsi so'zning o'zidan bilinmaydigan otlar"},{"t":"p","x":"Shunday otlar borki, ularning jinsini to'g'ridan-to'g'ri aniqlab bo'lmaydi. Bunday hollarda jinsni <b>olmoshlar</b> (he, she, his, her) orqali bilib olamiz:"},{"t":"ex","en":"My neighbour bought a bike for his son.","uz":"Qo'shnim o'g'liga velosiped sotib oldi. (his → masculine)"},{"t":"ex","en":"My neighbour bought a bike for her son.","uz":"Qo'shnim o'g'liga velosiped sotib oldi. (her → feminine)"},{"t":"ex","en":"My student is clever. He studies at the lyceum.","uz":"Mening o'quvchim aqlli. U litseyda o'qiydi. (he → masculine)"},{"t":"p","x":"Bunday otlarga quyidagilar kiradi:"},{"t":"list","items":["<b>Odamlar:</b> baby, child, cousin, infant, parent, relation, relative, spouse, teenager, adult, guest, foreigner, friend, person, pupil, neighbour","<b>Kasblar:</b> teacher, student, artist, assistant, cook, dancer, driver, doctor, guide, journalist, lawyer","<b>Hayvonlar:</b> sheep, cat, horse, deer, crocodile, donkey va boshqalar"]}],"quiz":[{"q":"«Friendship» is a(n) ... noun.","o":["proper","abstract","collective","common"],"a":1,"e":"Do'stlikni ko'rib yoki ushlab bo'lmaydi – bu mavhum (abstract) ot."},{"q":"«France» is a(n) ... noun.","o":["proper","collective","common","abstract"],"a":0,"e":"Mamlakat nomi – aniq atama, ya'ni atoqli ot (proper noun)."},{"q":"«Crowd» is a(n) ... noun.","o":["abstract","collective","neuter","proper"],"a":1,"e":"Crowd (olomon) bir guruh odamlarni bildiradi – collective noun."},{"q":"What is the feminine form of «actor»?","o":["actress","actorine","actrice","actoress"],"a":0,"e":"Kasblarda ayol jinsi ko'pincha -ess bilan yasaladi: actor – actress."},{"q":"What is the feminine form of «hero»?","o":["heroin","heroette","heroess","heroine"],"a":3,"e":"Hero – heroine (qahramon ayol)."},{"q":"What is the female of «bull»?","o":["cow","hen","ewe","mare"],"a":0,"e":"Bull (buqa) – cow (sigir)."},{"q":"«Table» belongs to which gender?","o":["collective","masculine","feminine","neuter"],"a":3,"e":"Jonsiz narsalar neuter (jinssiz) hisoblanadi."},{"q":"A man says about his car: «___ is my baby.» Which pronoun is traditionally used?","o":["He","She","It's","They"],"a":1,"e":"Kema va mashinalar haqida erkalab gapirilganda feminine (she) ishlatiladi."},{"q":"«My neighbour bought a bike for her son.» The neighbour is ...","o":["a woman","unknown","a man","a child"],"a":0,"e":"Neighbour so'zining jinsi olmosh orqali bilinadi: her → ayol (feminine)."},{"q":"What is the feminine form of «widower»?","o":["widowess","widow","widowine","widowa"],"a":1,"e":"Bu juftlikda ayol jinsi qisqaroq: widower (beva erkak) – widow (beva ayol)."}]},{"id":"p1-03","en":"Plurals of Nouns: Regular Rules","uz":"Otlarning ko'plik shakli: asosiy qoidalar","emoji":"📚","level":"A1","group":"Gap va ot","summary":"Otlarga -s, -es, -ies, -ves qo'shib ko'plik yasash qoidalari, -s ning talaffuzi va o, y, f/fe bilan tugaydigan so'zlardagi istisnolar.","blocks":[{"t":"p","x":"Ikki va undan ortiq narsa, buyum, hayvon, odam yoki joy haqida gapirganda <b>plural</b> (ko'plik) shaklidan foydalanamiz. Otlar asosan oxiriga <b>-s</b> qo'shish orqali ko'plikka aylantiriladi."},{"t":"ex","en":"dog – dogs, boy – boys","uz":"it – itlar, bola – bolalar"},{"t":"h","x":"-s ning talaffuzi"},{"t":"p","x":"Agar ot <b>p, k, f</b> tovushlari bilan tugasa, -s qo'shimchasi <b>[s]</b> deb talaffuz qilinadi. Boshqa hollarda (unli va jarangli tovushlardan keyin) <b>[z]</b> deb aytiladi."},{"t":"ex","en":"shops, cliffs, weeks","uz":"[s] deb o'qiladi"},{"t":"ex","en":"dogs, boys","uz":"[z] deb o'qiladi"},{"t":"h","x":"-es qo'shimchasi"},{"t":"p","x":"Agar birlikdagi ot <b>o, ch, sh, s, ss, x</b> harflari bilan tugasa, ko'plik uchun <b>-es</b> qo'shiladi."},{"t":"ex","en":"church – churches, tomato – tomatoes","uz":"cherkov – cherkovlar, pomidor – pomidorlar"},{"t":"ex","en":"box – boxes, bus – buses, dish – dishes, glass – glasses","uz":"quti, avtobus, likopcha, stakan – ko'plikda"},{"t":"rule","x":"Istisno: <b>o</b> bilan tugaydigan ba'zi so'zlarga faqat <b>-s</b> qo'shiladi: <i>dynamo, kilo, kimono, photo, soprano, zoo, video, kangaroo, piano</i> → dynamos, kilos, kimonos, photos, sopranos, zoos, videos, kangaroos, pianos."},{"t":"h","x":"-y bilan tugaydigan otlar"},{"t":"p","x":"Agar ot <b>undosh + y</b> bilan tugasa, <b>y</b> tushirilib, <b>-ies</b> qo'shiladi:"},{"t":"ex","en":"baby – babies, lady – ladies","uz":"chaqaloq – chaqaloqlar, xonim – xonimlar"},{"t":"p","x":"Agar ot <b>unli + y</b> bilan tugasa, shunchaki <b>-s</b> qo'shiladi:"},{"t":"ex","en":"boy – boys, guy – guys","uz":"bola – bolalar, yigit – yigitlar"},{"t":"h","x":"-f / -fe bilan tugaydigan otlar"},{"t":"p","x":"<b>f, fe</b> bilan tugaydigan <b>12 ta</b> so'z borki, ularda f/fe tushirilib, o'rniga <b>-ves</b> qo'yiladi:"},{"t":"table","head":["Birlik","Ko'plik","Birlik","Ko'plik"],"rows":[["shelf","shelves","life","lives"],["calf","calves","self","selves"],["half","halves","sheaf","sheaves"],["knife","knives","thief","thieves"],["leaf","leaves","wolf","wolves"],["loaf","loaves","wife","wives"]]},{"t":"p","x":"Quyidagi <b>4 ta</b> so'zning ko'pligi ikki xil yasaladi – yoki shunchaki -s qo'shiladi, yoki f tushirilib -ves qo'shiladi:"},{"t":"table","head":["Birlik","Ko'plik (-s)","Ko'plik (-ves)"],"rows":[["scarf","scarfs","scarves"],["wharf","wharfs","wharves"],["dwarf","dwarfs","dwarves"],["hoof","hoofs","hooves"]]},{"t":"rule","x":"Yuqoridagi 16 ta so'zdan tashqari, f yoki fe bilan tugaydigan qolgan barcha otlarga oddiy <b>-s</b> qo'shiladi: <i>cliff – cliffs, giraffe – giraffes</i>."}],"quiz":[{"q":"Choose the correct plural: tomato","o":["tomatoies","tomatos","tomatoes","tomato"],"a":2,"e":"o bilan tugagan ko'p otlarga -es qo'shiladi: tomatoes."},{"q":"Choose the correct plural: photo","o":["photoes","photos","photies","photo"],"a":1,"e":"Photo – istisno so'zlardan biri, unga faqat -s qo'shiladi."},{"q":"Choose the correct plural: baby","o":["babies","babys","babis","babyes"],"a":0,"e":"Undosh + y: y tushiriladi va -ies qo'shiladi."},{"q":"Choose the correct plural: boy","o":["boyes","boyz","boies","boys"],"a":3,"e":"Unli + y bo'lsa, shunchaki -s qo'shiladi."},{"q":"Choose the correct plural: knife","o":["knives","knivs","knifees","knifes"],"a":0,"e":"Knife – -ves oladigan 12 ta so'zdan biri."},{"q":"Choose the correct plural: giraffe","o":["giraffies","giraffes","giraves","giraffves"],"a":1,"e":"Giraffe 16 ta maxsus so'z ro'yxatiga kirmaydi, shuning uchun -s qo'shiladi."},{"q":"Which plural form(s) of «scarf» are correct?","o":["only scarves","only scarfs","both scarfs and scarves","scarfes"],"a":2,"e":"Scarf, wharf, dwarf, hoof so'zlarining ko'pligi ikki xil bo'lishi mumkin."},{"q":"Choose the correct plural: box","o":["boxs","boxes","boxies","boxen"],"a":1,"e":"x bilan tugagan otlarga -es qo'shiladi."},{"q":"In which word is the final -s pronounced [s]?","o":["pens","shops","boys","dogs"],"a":1,"e":"p, k, f dan keyin -s [s] deb o'qiladi; boshqa hollarda [z]."},{"q":"Choose the correct plural: piano","o":["pianoes","pianies","piani","pianos"],"a":3,"e":"Piano – o bilan tugasa ham faqat -s oladigan istisno so'z."}]},{"id":"p1-04","en":"Plurals of Nouns: Irregular and Special Forms","uz":"Otlarning ko'plik shakli: noqonuniy va maxsus shakllar","emoji":"🐑","level":"A2","group":"Gap va ot","summary":"Shakli o'zgaradigan otlar, birlik va ko'plikda bir xil otlar, doim ko'plikda yoki doim birlikda ishlatiladigan otlar, chet tilidan kirgan so'zlar va qisqartmalarning ko'pligi.","blocks":[{"t":"h","x":"Shakli o'zgaradigan otlar"},{"t":"p","x":"Ba'zi otlarning ko'plik shakli yasalganda so'zning o'zi o'zgaradi va <b>-s qo'shilmaydi</b>:"},{"t":"table","head":["Birlik","Ko'plik"],"rows":[["foot","feet"],["tooth","teeth"],["mouse","mice"],["child","children"],["ox","oxen"],["man","men"],["woman","women"]]},{"t":"h","x":"Birlik va ko'plikda bir xil otlar"},{"t":"p","x":"Ba'zi otlarning shakli birlikda ham, ko'plikda ham bir xil: <b>sheep, fish, deer</b>. Ularning birlik yoki ko'plikda ekanini kesim (fe'l) yoki olmosh orqali bilib olamiz."},{"t":"ex","en":"One sheep is white. Two sheep are black.","uz":"Bitta qo'y oq. Ikkita qo'y qora."},{"t":"rule","x":"Istisno: ba'zan <b>fishes</b> so'zi ham uchraydi. Bunda gap baliqlarning soni haqida emas, balki ularning <b>turlari</b> haqida bo'ladi."},{"t":"ex","en":"There are fish.","uz":"Baliqlar bor."},{"t":"ex","en":"There are fishes.","uz":"Turli xil baliqlar bor."},{"t":"h","x":"Doim ko'plikda ishlatiladigan otlar"},{"t":"p","x":"Ba'zi otlarning birlik shakli yo'q. Ular doim ko'plik hisoblanadi va o'zidan keyin <b>ko'plikdagi fe'lni</b> talab qiladi: <b>police, clothes</b>."},{"t":"ex","en":"The police are coming.","uz":"Politsiya kelyapti."},{"t":"p","x":"Ikki qismdan iborat kiyim va asboblar ham doim ko'plik hisoblanadi:"},{"t":"list","items":["<b>Kiyimlar:</b> pants, trousers, pyjamas va boshqalar","<b>Asboblar:</b> binoculars, scales, scissors, pliers va boshqalar"]},{"t":"ex","en":"My trousers are new. Where are the scissors?","uz":"Shimim yangi. Qaychi qayerda?"},{"t":"p","x":"Qoidaga bo'ysunmaydigan va doim ko'plikda ishlatiladigan so'zlar:"},{"t":"p","x":"<i>arms, earnings, goods, wares, grounds, greens, pains, damages, outskirts, premises, quarters, surroundings, valuables, particulars, riches, savings, spirits, stairs</i>"},{"t":"h","x":"-ics bilan tugaydigan otlar"},{"t":"p","x":"<b>-ics</b> bilan tugaydigan ba'zi so'zlar ko'plik hisoblanadi: <i>physics, mathematics, athletics, politics, ethics</i>."},{"t":"ex","en":"His mathematics are weak.","uz":"Uning matematikadan bilimi sust."},{"t":"rule","x":"Istisno: fan nomi sifatida kelganda bu so'zlar <b>birlik</b> ma'nosida ishlatiladi."},{"t":"ex","en":"Mathematics is an exact subject.","uz":"Matematika – aniq fan."},{"t":"h","x":"Doim birlikda ishlatiladigan otlar"},{"t":"p","x":"Ba'zi otlar ko'rinishdan ko'plikda bo'lsa ham (oxiri -s bilan tugasa ham), doim birlik hisoblanadi va <b>birlikdagi fe'l</b> talab qiladi. Ularning ko'plik shakli yo'q:"},{"t":"p","x":"<i>news, shingles, mumps, rickets, billiards, bowls, darts, draughts, dominoes</i>"},{"t":"ex","en":"The news is good.","uz":"Yangilik yaxshi."},{"t":"h","x":"Chet tillardan kirgan so'zlar"},{"t":"p","x":"Boshqa tillardan (asosan lotin va yunon tilidan) kirgan so'zlarning ko'pligi o'sha tilning qoidasi bo'yicha yasaladi:"},{"t":"table","head":["Birlik","Ko'plik"],"rows":[["radius","radii"],["crisis","crises"],["erratum","errata"],["terminus","termini"],["cactus","cacti"],["memorandum","memoranda"],["phenomenon","phenomena"],["oasis","oases"],["bacterium","bacteria"]]},{"t":"h","x":"Qisqartmalarning ko'pligi"},{"t":"p","x":"Qisqartma so'zlarga ko'plikda oxiriga <b>-s</b> qo'shiladi:"},{"t":"ex","en":"VIP (very important person) – VIPs (very important people)","uz":"juda muhim shaxs – juda muhim shaxslar"},{"t":"ex","en":"MP (Member of Parliament) – MPs (Members of Parliament)","uz":"parlament a'zosi – parlament a'zolari"}],"quiz":[{"q":"Choose the correct plural: child","o":["children","childs","childes","childrens"],"a":0,"e":"Child – shakli o'zgaradigan ot: children."},{"q":"Choose the correct plural: mouse","o":["mice","mousen","mouses","mices"],"a":0,"e":"Mouse – mice (shakl o'zgaradi, -s qo'shilmaydi)."},{"q":"Choose the correct plural: sheep","o":["sheepes","shoop","sheeps","sheep"],"a":3,"e":"Sheep, fish, deer birlik va ko'plikda bir xil."},{"q":"Which word means «different kinds of fish»?","o":["fishs","fishes","fishies","fish"],"a":1,"e":"Fishes – baliqlarning soni emas, turlari haqida gapirilganda ishlatiladi."},{"q":"The police ___ coming.","o":["was","are","is","has"],"a":1,"e":"Police doim ko'plik hisoblanadi va ko'plikdagi fe'l talab qiladi."},{"q":"The news ___ good.","o":["is","were","are","have been"],"a":0,"e":"News oxiri -s bo'lsa ham doim birlik – birlikdagi fe'l bilan ishlatiladi."},{"q":"Choose the correct plural: cactus","o":["cactae","cacti","cactuses only","cactusi"],"a":1,"e":"Lotincha so'z: -us → -i (cactus – cacti, radius – radii)."},{"q":"Choose the correct plural: phenomenon","o":["phenomeni","phenomena","phenomenons","phenomenae"],"a":1,"e":"Yunoncha so'z: -on → -a (phenomenon – phenomena)."},{"q":"My new trousers ___ too long.","o":["has been","are","was","is"],"a":1,"e":"Ikki qismli kiyimlar (trousers, pants) doim ko'plik."},{"q":"Mathematics ___ an exact subject.","o":["were","have","is","are"],"a":2,"e":"Fan nomi sifatida mathematics birlik ma'nosida keladi."}]},{"id":"p1-05","en":"Countable and Uncountable Nouns","uz":"Sanaladigan va sanalmaydigan otlar","emoji":"🔢","level":"A1","group":"Gap va ot","summary":"Otlar sanaladigan (countable) va sanalmaydigan (uncountable) turlarga bo'linadi. Sanalmaydigan otlarning miqdori qanday ifodalanishi va ma'nosiga qarab ikkala turda ham kelishi mumkin bo'lgan so'zlar.","blocks":[{"t":"p","x":"Otlar ikki turga bo'linadi: <b>countable noun</b> (sanaladigan ot) va <b>uncountable noun</b> (sanalmaydigan ot)."},{"t":"list","items":["<b>Countable noun</b> oldidan sonlarni ishlata olamiz; u birlikda ham, ko'plikda ham bo'lishi mumkin: <i>one book, two books</i>.","<b>Uncountable noun</b> oldidan sonlarni ishlata olmaymiz; u faqat birlikda keladi: <i>water, gold</i>."]},{"t":"h","x":"Qaysi otlar sanalmaydi?"},{"t":"p","x":"<b>Modda nomlari</b> sanalmaydigan ot hisoblanadi: <i>beer, gold, coffee, cream, bread, iron</i> va boshqalar."},{"t":"p","x":"<b>Mavhum otlar</b> ham sanalmaydi: <i>advice, beauty, death, love</i> va boshqalar."},{"t":"rule","x":"Diqqat: ba'zi so'zlar o'zbek tilida sanalsa ham, ingliz tilida <b>sanalmaydi</b>: <i>news, rubbish, information, weather, hair, traffic, travel, work, shopping, parking</i> va boshqalar. Shuning uchun <i>an information</i> yoki <i>informations</i> deyilmaydi."},{"t":"h","x":"Sanalmaydigan otlarning miqdorini ko'rsatish"},{"t":"list","items":["<b>some, any, much, no, a little, little</b> va boshqalar","<b>a bit of, a drop of, a piece of, a sheet of</b> va boshqalar"]},{"t":"ex","en":"some gold","uz":"biroz oltin"},{"t":"ex","en":"a drop of oil","uz":"bir tomchi moy"},{"t":"ex","en":"a piece of advice, a sheet of paper","uz":"bitta maslahat, bir varaq qog'oz"},{"t":"h","x":"Ma'nosiga qarab sanaladigan ham, sanalmaydigan ham bo'ladigan otlar"},{"t":"p","x":"<b>1. time</b> – vaqt (sanalmaydi) / marta (sanaladi)"},{"t":"ex","en":"How much time do you need to finish the job?","uz":"Ishni tugatishga sizga qancha vaqt kerak?"},{"t":"ex","en":"How many times have you been to London?","uz":"Siz Londonda necha marta bo'lgansiz?"},{"t":"p","x":"<b>2. glass</b> – shisha (sanalmaydi) / stakan (sanaladi)"},{"t":"ex","en":"Windows are made of glass.","uz":"Derazalar shishadan yasaladi."},{"t":"ex","en":"I drank a glass of wine.","uz":"Men bir stakan vino ichdim."},{"t":"p","x":"<b>3. hair</b> – soch (sanalmaydi) / soch tolasi (sanaladi)"},{"t":"ex","en":"She has brown hair.","uz":"Uning sochlari jigarrang."},{"t":"ex","en":"He found a hair in the bag.","uz":"U sumkasidan bitta soch tolasi topdi."},{"t":"p","x":"<b>4. iron</b> – temir (sanalmaydi) / dazmol (sanaladi)"},{"t":"ex","en":"Iron is a metal.","uz":"Temir – metall."},{"t":"ex","en":"I pressed my shirt with an iron.","uz":"Men ko'ylagimni dazmolladim."},{"t":"p","x":"<b>5. paper</b> – qog'oz (sanalmaydi) / gazeta (sanaladi)"},{"t":"ex","en":"I need paper to write a letter.","uz":"Xat yozishim uchun qog'oz kerak."},{"t":"ex","en":"I bought a paper.","uz":"Men gazeta sotib oldim."},{"t":"p","x":"<b>6. experience</b> – tajriba, malaka (sanalmaydi) / voqea, hodisa (sanaladi)"},{"t":"ex","en":"I didn't have much experience with computers.","uz":"Kompyuter bo'yicha malakam ko'p emas edi."},{"t":"ex","en":"We had many interesting experiences on our trip.","uz":"Sayohatimizda ko'plab qiziqarli voqealar bo'ldi."}],"quiz":[{"q":"Which noun is uncountable in English?","o":["book","chair","apple","information"],"a":3,"e":"Information o'zbek tilida sanalsa ham, ingliz tilida sanalmaydigan ot."},{"q":"Can I give you some ___?","o":["an advice","advices","a advices","advice"],"a":3,"e":"Advice – mavhum, sanalmaydigan ot: a/an olmaydi va ko'plikka aylanmaydi."},{"q":"Fill in: «a ___ of oil»","o":["slice","loaf","sheet","drop"],"a":3,"e":"Suyuqlik miqdori uchun a drop of ishlatiladi: a drop of oil."},{"q":"How ___ time do you need to finish the job?","o":["many","few","much","a few"],"a":2,"e":"Time «vaqt» ma'nosida sanalmaydi, shuning uchun much."},{"q":"How ___ times have you been to London?","o":["a little","many","much","little"],"a":1,"e":"Times «marta» ma'nosida sanaladi, shuning uchun many."},{"q":"He found ___ in the bag (one single strand).","o":["hair","an hair","a hair","hairs"],"a":2,"e":"Bitta soch tolasi sanaladi: a hair. Umuman soch esa sanalmaydi: She has brown hair."},{"q":"Windows are made of ___.","o":["glass","the glasses","glasses","a glass"],"a":0,"e":"Material (shisha) ma'nosida glass sanalmaydi."},{"q":"I bought ___ to read the news. (= a newspaper)","o":["a paper","a sheet of paper","paper","papers of"],"a":0,"e":"Paper «gazeta» ma'nosida sanaladi: a paper."},{"q":"Choose the correct sentence.","o":["The weathers are nice today.","The weather is nice today.","A weather is nice today.","Weathers are nice today."],"a":1,"e":"Weather sanalmaydigan ot: a/an olmaydi, ko'plikka aylanmaydi."},{"q":"We had many interesting ___ on our trip.","o":["experiencies","an experience","experience","experiences"],"a":3,"e":"«Voqea, hodisa» ma'nosida experience sanaladi va ko'plikka aylanadi."}]},{"id":"p1-06","en":"The Possessive Form","uz":"Egalik shakli","emoji":"🔑","level":"A2","group":"Gap va ot","summary":"Egalikni ifodalashning ikki usuli: 's / ' (apostrof) va of predlogi. Qachon qaysi biri ishlatilishi, maxsus holatlar va istisnolar.","blocks":[{"t":"p","x":"Bir narsa boshqa kishiga yoki narsaga tegishli ekanini ko'rsatish uchun <b>possessive</b> (egalik) shaklidan foydalanamiz. Uning ikki shakli bor: <b>'s</b> va <b>of</b>."},{"t":"h","x":"1. Apostrophe + s ('s)"},{"t":"p","x":"<b>'s</b> asosan kishilar, mamlakatlar va hayvonlar uchun ishlatiladi:"},{"t":"ex","en":"a man's book, Russia's export, a bull's horn","uz":"erkakning kitobi, Rossiyaning eksporti, buqaning shoxi"},{"t":"p","x":"<b>-s bilan tugamaydigan</b> ko'plikdagi otlarga <b>'s</b> qo'shiladi:"},{"t":"ex","en":"the children's room, the fish's mouth","uz":"bolalarning xonasi, baliqning og'zi"},{"t":"p","x":"Ko'plik shakli <b>-s bilan tugagan</b> otlarga faqat <b>'</b> (apostrof) qo'shiladi:"},{"t":"ex","en":"the girls' school, the eagles' nest, the Smiths' house","uz":"qizlar maktabi, burgutlar uyasi, Smitlar oilasining uyi"},{"t":"p","x":"<b>-s bilan tugaydigan birlikdagi</b> otlarga <b>'s</b> yoki faqat <b>'</b> qo'shish mumkin:"},{"t":"ex","en":"James's house = James' house","uz":"Jeymsning uyi"},{"t":"p","x":"Bir necha so'zdan iborat otning egalik shakli yasalganda <b>'s oxirgi so'zga</b> qo'shiladi:"},{"t":"ex","en":"my brother-in-law's car, the Prince of England's order","uz":"pochchamning mashinasi, Angliya shahzodasining buyrug'i"},{"t":"p","x":"Qisqartma otlarda <b>'s</b> oxirgi harfdan keyin qo'yiladi:"},{"t":"ex","en":"a VIP's job, the MP's briefcase","uz":"muhim shaxsning ishi, deputatning portfeli"},{"t":"h","x":"'s ning maxsus holatlari"},{"t":"rule","x":"Istisno: jonsiz bo'lsa ham <b>kema va qayiqlar</b> uchun 's ishlatish mumkin: <i>the ship's captain, the yacht's mast</i>."},{"t":"p","x":"<b>Vaqt ifodalari</b>da ham 's ishlatiladi:"},{"t":"ex","en":"a week's holiday, in two years' time, today's paper","uz":"bir haftalik ta'til, ikki yildan keyin, bugungi gazeta"},{"t":"p","x":"Qassobxona, do'konlar, dorixona kabi joylarda 's ishlatilsa, ikkinchi so'zni (shop, office, house) tushirib qoldirish mumkin:"},{"t":"list","items":["the butcher's, the baker's, the chemist's = the butcher's / baker's / chemist's <b>shop</b>","the doctor's, the dentist's, the house agent's = ... <b>office</b>","kishi ismi + 's = ...'s <b>house</b>"]},{"t":"ex","en":"I'll buy it from the chemist's shop. = I'll buy it from the chemist's.","uz":"Men uni dorixonadan sotib olaman."},{"t":"ex","en":"I should go to the dentist's office. = I should go to the dentist's.","uz":"Men tish shifokoriga borishim kerak."},{"t":"ex","en":"I had breakfast at Bill's house. = I had breakfast at Bill's.","uz":"Men Billnikida nonushta qildim."},{"t":"p","x":"Bir so'zni ikki marta takrorlamaslik uchun uni tushirib qoldirish mumkin:"},{"t":"ex","en":"Mary's hair is black but Ann's is brown.","uz":"Merining sochi qora, Annniki esa jigarrang."},{"t":"h","x":"2. of predlogi"},{"t":"p","x":"Bu tuzilma asosan <b>jonsiz narsalar</b> uchun ishlatiladi. <b>of</b> o'zbek tilidagi <b>“-ning”</b> qo'shimchasiga mos keladi."},{"t":"ex","en":"the roof of the church","uz":"cherkovning tomi"},{"t":"ex","en":"the wall of the room","uz":"xonaning devori"},{"t":"rule","x":"Agar egalik qiluvchi bo'lak ibora (phrase) yoki ergash gap (clause) bo'lib kelsa, <b>of</b> tuzilmasidan foydalaniladi."},{"t":"ex","en":"I took the advice of the couple I met on the train.","uz":"Men poyezdda tanishgan er-xotinning maslahatiga amal qildim."},{"t":"ex","en":"I took the hat of the man who was speaking in the hall.","uz":"Men zalda gapirayotgan kishining shlyapasini oldim."}],"quiz":[{"q":"This is the ___ room.","o":["children'","children's","childrens'","childrens"],"a":1,"e":"Children -s bilan tugamaydigan ko'plik, shuning uchun 's qo'shiladi."},{"q":"This school is only for girls. It is a ___ school.","o":["girles'","girl's","girls'","girls's"],"a":2,"e":"Ko'plik -s bilan tugasa, faqat apostrof qo'shiladi: girls'."},{"q":"Which is correct for «the house of James»?","o":["Both James's house and James' house","Jameses' house","Only James' house","Only James's house"],"a":0,"e":"-s bilan tugaydigan birlikdagi otlarga 's yoki ' qo'shish mumkin."},{"q":"Choose the correct form.","o":["my brother's-in-law car","my brothers-in-law car","my brother-in's-law car","my brother-in-law's car"],"a":3,"e":"Bir necha so'zli otda 's oxirgi so'zga qo'shiladi."},{"q":"For things (inanimate nouns) we usually say ...","o":["the church's roof only","the roof's church","the roof of the church","the church of the roof"],"a":2,"e":"Jonsiz narsalar uchun asosan of tuzilmasi ishlatiladi."},{"q":"I'm going on ___ holiday.","o":["a week's","a week of's","a weeks's","a weeks"],"a":0,"e":"Vaqt ifodalarida 's ishlatiladi: a week's holiday."},{"q":"«I'll buy it at the chemist's.» What does «the chemist's» mean?","o":["the chemist's shop","chemistry","the chemist's family","the chemist himself"],"a":0,"e":"Do'kon nomlarida 's dan keyin shop so'zini tushirib qoldirish mumkin."},{"q":"«Mary's hair is black but Ann's is brown.» What word is left out after «Ann's»?","o":["Mary","hair","is","house"],"a":1,"e":"Takrorlanmasligi uchun hair so'zi tushirib qoldirilgan."},{"q":"The Smith family lives here. This is ___ house.","o":["the Smiths'","the Smith's'","the Smiths's","the Smithes'"],"a":0,"e":"Smiths – -s bilan tugagan ko'plik, shuning uchun faqat apostrof: the Smiths'."},{"q":"Choose the correct sentence.","o":["I took the couple's I met on the train advice.","I took the couple I met on the train's advice of.","I took the advice of the couple I met on the train.","I took of the couple advice I met on the train."],"a":2,"e":"Egalik qiluvchi bo'lak clause bo'lsa, of tuzilmasi ishlatiladi."}]},{"id":"p1-07","en":"Collective Nouns","uz":"Jamlovchi otlar","emoji":"👥","level":"B1","group":"Gap va ot","summary":"Jamlovchi otlar bir butun sifatida qaralsa birlikdagi, alohida a'zolar nazarda tutilsa ko'plikdagi fe'l bilan ishlatiladi. Vaqt, pul va o'lchovlar bir butun sifatida birlikdagi fe'l oladi.","blocks":[{"t":"p","x":"<b>Collective noun</b> – bir guruh odamlar, hayvonlar yoki narsalarni bildiruvchi ot: <i>team, family, crowd</i> va boshqalar."},{"t":"h","x":"Bir butun sifatida – birlik"},{"t":"p","x":"Agar guruhga <b>bir butun</b> sifatida qaralsa, u birlik hisoblanadi va o'zidan keyin <b>birlikdagi fe'l</b> talab qiladi:"},{"t":"ex","en":"Our team is the best.","uz":"Bizning jamoa eng zo'ri."},{"t":"h","x":"Alohida a'zolar – ko'plik"},{"t":"p","x":"Agar guruhning <b>har bir a'zosiga alohida</b> qaralsa, u ko'plik hisoblanadi va <b>ko'plikdagi fe'l</b> talab qiladi:"},{"t":"ex","en":"Our team are changing their clothes.","uz":"Jamoamiz a'zolari kiyimlarini almashtirishyapti."},{"t":"h","x":"Vaqt, pul va o'lchov"},{"t":"rule","x":"Vaqt (time), pul (money) va o'lchov (measure) haqida <b>bir butun miqdor</b> sifatida gapirganda ko'plik shaklidagi ot bo'lsa ham <b>birlikdagi fe'l</b> ishlatiladi."},{"t":"ex","en":"Five minutes isn't enough to solve the test, but ten minutes is enough to copy it.","uz":"Testni yechishga besh daqiqa yetmaydi, ko'chirishga esa o'n daqiqa yetadi. (vaqt)"},{"t":"ex","en":"Twenty-five dollars is too much to pay for that.","uz":"Bunga yigirma besh dollar to'lash juda qimmat. (pul)"},{"t":"ex","en":"Twenty miles is too long to run in an hour.","uz":"Bir soatda yigirma mil yugurish juda uzoq. (o'lchov)"}],"quiz":[{"q":"Our team ___ the best in the city. (the team as a whole)","o":["have","were","is","are"],"a":2,"e":"Guruh bir butun sifatida qaralsa, birlikdagi fe'l ishlatiladi."},{"q":"Our team ___ changing their clothes.","o":["is","has","are","was"],"a":2,"e":"Har bir a'zo alohida nazarda tutilgan (their clothes), shuning uchun ko'plik fe'l."},{"q":"Twenty-five dollars ___ too much to pay for that.","o":["have been","is","are","were"],"a":1,"e":"Pul miqdori bir butun sifatida birlikdagi fe'l oladi."},{"q":"Five minutes ___ enough to solve the test.","o":["isn't","aren't","weren't","haven't"],"a":0,"e":"Vaqt miqdori bir butun sifatida – birlikdagi fe'l: isn't."},{"q":"Twenty miles ___ too long to run in an hour.","o":["have","were","is","are"],"a":2,"e":"O'lchov bir butun sifatida birlikdagi fe'l bilan ishlatiladi."},{"q":"My family ___ very large. (as one unit)","o":["is","were","have","are"],"a":0,"e":"Oila bir butun sifatida qaralmoqda – birlik fe'l."},{"q":"The family ___ arguing among themselves.","o":["has","are","was","is"],"a":1,"e":"Oila a'zolari alohida harakat qilmoqda (themselves) – ko'plik fe'l."},{"q":"Which statement is correct?","o":["A collective noun always takes a singular verb.","A collective noun always takes a plural verb.","A collective noun takes a singular verb when the group is seen as one whole.","A collective noun never takes a verb."],"a":2,"e":"Bir butun – birlik fe'l; alohida a'zolar – ko'plik fe'l."}]},{"id":"p1-08","en":"Compound Nouns and Nouns as Adjectives","uz":"Qo'shma otlar va sifat vazifasidagi otlar","emoji":"🔗","level":"B1","group":"Gap va ot","summary":"Qo'shma otlarning ko'plik shaklini yasash qoidalari hamda boshqa ot oldida sifat vazifasida kelgan otlarning doim birlikda turishi.","blocks":[{"t":"h","x":"Compound nouns – qo'shma otlar"},{"t":"p","x":"<b>Compound noun</b> – bir nechta so'zdan tuzilgan, lekin bitta narsani bildiradigan ot:"},{"t":"p","x":"<i>boy-friend, travel-agent, son-in-law, break-in</i>"},{"t":"h","x":"Ko'plik yasash qoidalari"},{"t":"p","x":"<b>1. Odatda oxirgi so'z</b> ko'plikka aylantiriladi:"},{"t":"ex","en":"boy-friend – boy-friends, break-in – break-ins","uz":"yigit – yigitlar, o'g'irlik uchun bostirib kirish – bostirib kirishlar"},{"t":"p","x":"<b>2. man yoki woman</b> qatnashgan qo'shma otlarda <b>ikkala so'z ham</b> ko'plikka aylantiriladi:"},{"t":"table","head":["Birlik","Ko'plik"],"rows":[["man-driver","men-drivers"],["woman-driver","women-drivers"]]},{"t":"p","x":"<b>3. fe'l + er + ravish</b> (verb + er + adverb) shaklidagi qo'shma otlarda <b>birinchi so'z</b> ko'plikka aylanadi:"},{"t":"table","head":["Birlik","Ko'plik"],"rows":[["hanger-on","hangers-on"],["runner-up","runners-up"]]},{"t":"p","x":"<b>4. ot + predlog + ot</b> (noun + preposition + noun) shaklidagi qo'shma otlarda ham <b>birinchi so'z</b> ko'plikka aylanadi:"},{"t":"table","head":["Birlik","Ko'plik"],"rows":[["son-in-law","sons-in-law"],["mother-in-law","mothers-in-law"],["lady-in-waiting","ladies-in-waiting"]]},{"t":"h","x":"Nouns functioning as an adjective – sifat vazifasidagi otlar"},{"t":"p","x":"Agar bir ot boshqa ot oldidan kelsa, u <b>sifat</b> vazifasini bajaradi:"},{"t":"ex","en":"wool – a wool coat; gold – a gold watch","uz":"jun – jun palto; oltin – oltin soat"},{"t":"rule","x":"Sifat vazifasida kelgan ot <b>doim birlikda</b> bo'ladi, hatto ko'plikdagi otni aniqlab kelsa ham: <b>history teachers</b> – to'g'ri; <i>histories teachers</i> – noto'g'ri."},{"t":"rule","x":"Agar sifat vazifasidagi ot <b>son + ot</b> shaklida bo'lsa, ular orasiga <b>chiziqcha (-)</b> qo'yish shart va ot birlikda qoladi."},{"t":"ex","en":"We took a tour that lasted two weeks.","uz":"Biz ikki hafta davom etgan sayohatga chiqdik."},{"t":"ex","en":"We took a two-week tour.","uz":"Biz ikki haftalik sayohatga chiqdik."}],"quiz":[{"q":"Choose the correct plural: boy-friend","o":["boys-friends","boys-friend","boy-friendes","boy-friends"],"a":3,"e":"Odatda qo'shma otning oxirgi so'zi ko'plikka aylanadi."},{"q":"Choose the correct plural: woman-driver","o":["women-driver","women-drivers","womans-drivers","woman-drivers"],"a":1,"e":"man/woman qatnashsa, ikkala so'z ham ko'plikka aylanadi."},{"q":"Choose the correct plural: runner-up","o":["runners-up","runners-ups","runner-ups","runner-upes"],"a":0,"e":"Verb + er + adverb shaklida birinchi so'z ko'plikka aylanadi."},{"q":"Choose the correct plural: son-in-law","o":["son-ins-law","sons-in-laws","son-in-laws","sons-in-law"],"a":3,"e":"Noun + preposition + noun shaklida birinchi ot ko'plikka aylanadi."},{"q":"Choose the correct plural: lady-in-waiting","o":["lady-in-waitings","ladies-in-waitings","ladies-in-waiting","ladys-in-waiting"],"a":2,"e":"Birinchi so'z ko'plikka aylanadi va y → ies: ladies-in-waiting."},{"q":"Choose the correct phrase.","o":["histories teacher","history teachers","history's teachers","histories teachers"],"a":1,"e":"Sifat vazifasidagi ot doim birlikda qoladi."},{"q":"We took a ___ tour.","o":["two-week's","two-week","two-weeks","two weeks"],"a":1,"e":"Son + ot sifat vazifasida chiziqcha bilan va birlikda yoziladi."},{"q":"A watch made of gold is a ___.","o":["golds watch","gold watch","gold's watch","watch gold"],"a":1,"e":"Ot boshqa ot oldida kelib sifat vazifasini bajaradi: gold watch."},{"q":"Choose the correct plural: hanger-on","o":["hangers-on","hanger-ons","hangers-ons","hanger-on"],"a":0,"e":"Verb + er + adverb: birinchi so'z ko'plikka aylanadi."},{"q":"Choose the correct plural: break-in","o":["breaks-in","break-ins","breaks-ins","break-in"],"a":1,"e":"Bu qo'shma otda oxirgi so'z ko'plikka aylanadi: break-ins."}]},{"id":"p1-09","en":"The Indefinite Article: a / an","uz":"Noaniq artikl: a / an","emoji":"🅰️","level":"A1","group":"Artikl va son","summary":"Artikl turlari, a va an ning qaysi tovushlardan oldin ishlatilishi, noaniq artiklning ma'nolari va u ishlatilmaydigan holatlar.","blocks":[{"t":"p","x":"<b>Artikl</b> o'zidan keyingi otni aniqlashtirib keladi. Uning ikki turi bor:"},{"t":"list","items":["<b>Indefinite article</b> (noaniq artikl) – <b>a / an</b>","<b>Definite article</b> (aniq artikl) – <b>the</b>"]},{"t":"h","x":"a yoki an?"},{"t":"p","x":"Noaniq artikl barcha jinslar uchun bir xil:"},{"t":"ex","en":"a girl, a boy, an uncle, an aunt, a table","uz":"bir qiz, bir bola, bir amaki, bir xola, bir stol"},{"t":"p","x":"<b>a</b> – <b>undosh tovush</b> bilan boshlanadigan so'zlar oldidan ishlatiladi:"},{"t":"ex","en":"a boy, a girl, a university, a European","uz":"university va European yozuvda unli bilan boshlansa ham, [j] undosh tovushi bilan o'qiladi"},{"t":"p","x":"<b>an</b> – <b>unli tovush</b> bilan boshlanadigan so'zlar oldidan ishlatiladi:"},{"t":"ex","en":"an aunt, an uncle, an hour, an MP","uz":"hour'da h o'qilmaydi; MP [em-pi:] unli tovush bilan boshlanadi"},{"t":"rule","x":"Diqqat: a/an tanlash harfga emas, <b>tovushga</b> bog'liq."},{"t":"h","x":"Noaniq artiklning ma'nolari"},{"t":"p","x":"a/an odatda <b>one</b> (bitta) ma'nosida keladi:"},{"t":"ex","en":"I need a visa.","uz":"Menga bitta viza kerak."},{"t":"p","x":"a/an ning yana bir ma'nosi – <b>any</b> (biror, birorta):"},{"t":"ex","en":"Have you got a book?","uz":"Sizda birorta kitob bormi?"},{"t":"p","x":"Noaniq artikl <b>birlikdagi, sanaladigan va biz uchun noma'lum</b> bo'lgan otlar oldidan keladi:"},{"t":"ex","en":"I bought an ice-cream.","uz":"Men bitta muzqaymoq sotib oldim."},{"t":"p","x":"Gapda ot kesimning to'ldiruvchisi (noun-complement) bo'lib kelsa, uning oldidan noaniq artikl ishlatiladi. Bunday vazifada ko'pincha <b>kasb nomlari</b> keladi:"},{"t":"ex","en":"It was an earthquake.","uz":"Bu zilzila edi."},{"t":"ex","en":"She will be a dancer.","uz":"U raqqosa bo'ladi."},{"t":"h","x":"Noaniq artikl ishlatilmaydigan holatlar"},{"t":"list","items":["<b>1. Ko'plikdagi otlar oldidan:</b> a dog – dogs","<b>2. Sanalmaydigan otlar oldidan:</b> gold, iron, wood","<b>3. Ovqatlanish vaqtlari oldidan:</b> breakfast, lunch, dinner"]},{"t":"ex","en":"I had breakfast.","uz":"Men nonushta qildim."},{"t":"ex","en":"Tom has dinner at 8 p.m. every day.","uz":"Tom har kuni soat 20:00 da kechki ovqat qiladi."},{"t":"rule","x":"Istisno: agar ovqatlanish vaqti oldidan <b>sifat</b> kelsa, artikl ishlatish mumkin."},{"t":"ex","en":"I had a good breakfast.","uz":"Men yaxshilab nonushta qildim."},{"t":"rule","x":"Istisno: biror kishi sharafiga beriladigan <b>maxsus ziyofat</b> (ovqatlanish) uchun artikl ishlatiladi."},{"t":"ex","en":"I was invited to a dinner which was given to celebrate Bill's birthday.","uz":"Meni Billning tug'ilgan kunini nishonlash uchun berilgan ziyofatga taklif qilishdi."}],"quiz":[{"q":"Choose the correct article: ___ hour","o":["a","—","the only","an"],"a":3,"e":"Hour so'zida h o'qilmaydi, so'z unli tovush bilan boshlanadi – an."},{"q":"Choose the correct article: ___ university","o":["an","—","an or a","a"],"a":3,"e":"University [ju:] – undosh [j] tovushi bilan boshlanadi, shuning uchun a."},{"q":"Choose the correct article: ___ MP","o":["the both","an","—","a"],"a":1,"e":"MP [em-pi:] deb o'qiladi – unli tovush bilan boshlanadi: an MP."},{"q":"Choose the correct article: ___ uncle","o":["an","one an","a","—"],"a":0,"e":"Uncle unli tovush bilan boshlanadi – an."},{"q":"I had ___ breakfast at seven.","o":["— (no article)","one","a","an"],"a":0,"e":"Ovqatlanish vaqtlari oldidan artikl ishlatilmaydi."},{"q":"I had ___ good breakfast.","o":["—","two","an","a"],"a":3,"e":"Ovqatlanish vaqti oldidan sifat kelsa, artikl ishlatish mumkin."},{"q":"She will be ___ dancer.","o":["an","—","a","one of"],"a":2,"e":"Kasb nomi noun-complement bo'lib kelganda noaniq artikl ishlatiladi."},{"q":"This ring is made of ___ gold.","o":["one","a","— (no article)","an"],"a":2,"e":"Sanalmaydigan otlar oldidan noaniq artikl ishlatilmaydi."},{"q":"«Have you got a book?» Here «a» means ...","o":["this","all","the","any"],"a":3,"e":"a/an ning bir ma'nosi – any (birorta)."},{"q":"Which is INCORRECT?","o":["dogs","a dogs","an apple","a dog"],"a":1,"e":"Ko'plikdagi otlar oldidan noaniq artikl ishlatilmaydi."}]},{"id":"p1-10","en":"The Definite Article: the","uz":"Aniq artikl: the","emoji":"🎯","level":"A1","group":"Artikl va son","summary":"Aniq artikl the ning ma'nosi va ishlatilish holatlari: yagona narsalar, aniq ma'lum otlar, ibora bilan aniqlangan otlar, tartib sonlar, orttirma daraja va only. a va the ning farqi.","blocks":[{"t":"formula","x":"the = this / that (bu / o'sha)"},{"t":"p","x":"<b>the</b> barcha jinslar uchun ishlatiladi:"},{"t":"ex","en":"the boy, the table, the girl","uz":"(o'sha) bola, stol, qiz"},{"t":"p","x":"<b>the</b> ni birlik va ko'plikda ishlata olamiz:"},{"t":"ex","en":"the boy, the boys","uz":"(o'sha) bola, (o'sha) bolalar"},{"t":"p","x":"<b>the</b> ni sanalmaydigan otlar oldidan ham ishlatish mumkin:"},{"t":"ex","en":"the gold, the glass","uz":"(o'sha) oltin, (o'sha) shisha"},{"t":"h","x":"the ishlatiladigan holatlar"},{"t":"p","x":"<b>1. Yagona (unique) narsalar oldidan:</b>"},{"t":"ex","en":"the sun, the moon, the sky, the equator, the stars","uz":"quyosh, oy, osmon, ekvator, yulduzlar"},{"t":"p","x":"<b>2. Ot aniq (ma'lum) bo'lganda</b> – masalan, avval tilga olingan bo'lsa:"},{"t":"ex","en":"I saw a man. The man was speaking to a woman.","uz":"Men bir odamni ko'rdim. U odam bir ayol bilan gaplashayotgan edi."},{"t":"p","x":"<b>3. Otni ibora (phrase) yoki ergash gap (clause) aniqlab kelsa:</b>"},{"t":"ex","en":"the girl in blue","uz":"ko'k kiyimdagi qiz"},{"t":"ex","en":"the couple I met on the train","uz":"men poyezdda tanishgan er-xotin"},{"t":"p","x":"<b>4. Tartib sonlar va sifatning orttirma darajasi oldidan:</b>"},{"t":"ex","en":"the first, the second, the best, the most beautiful","uz":"birinchi, ikkinchi, eng yaxshi, eng go'zal"},{"t":"p","x":"<b>5. only oldidan</b> the ishlatilsa, u <b>“yagona”</b> degan ma'noni beradi:"},{"t":"ex","en":"The only person who could speak English was he.","uz":"Ingliz tilida gapira oladigan yagona kishi u edi."},{"t":"h","x":"Taqqoslang: a va the"},{"t":"table","head":["Gap","Ma'nosi"],"rows":[["The girl in blue in the crowd","Olomon ichidagi ko'k kiyimli yagona (aniq) qiz"],["A girl in blue in the crowd","Olomon ichidagi ko'k kiyimli ko'plab qizlardan biri"],["A dog is barking.","Qayerdadir bir it vovullayapti (qaysi it ekani noma'lum)"],["The dog is barking.","(Ma'lum, ko'rib turgan) o'sha it vovullayapti"]]}],"quiz":[{"q":"___ sun rises in the east.","o":["A","An","The","— (no article)"],"a":2,"e":"Yagona narsalar (sun, moon, sky) oldidan the ishlatiladi."},{"q":"I saw a man. ___ man was speaking to a woman.","o":["— (no article)","An","A","The"],"a":3,"e":"Ot avval tilga olingani uchun endi aniq – the."},{"q":"He is ___ best student in our group.","o":["a","the","— (no article)","an"],"a":1,"e":"Sifatning orttirma darajasi oldidan the ishlatiladi."},{"q":"January is ___ first month of the year.","o":["an","the","a","— (no article)"],"a":1,"e":"Tartib sonlar oldidan the ishlatiladi."},{"q":"«The only person who could speak English was he.» What does «the only» mean?","o":["any person","every person","one of many","the single one (yagona)"],"a":3,"e":"Only oldidan the kelsa, «yagona» ma'nosini beradi."},{"q":"Look at ___ girl in blue over there!","o":["an","a","— (no article)","the"],"a":3,"e":"Ot ibora (in blue) bilan aniqlanganda va aniq bir qiz nazarda tutilsa, the ishlatiladi."},{"q":"«A dog is barking.» This means ...","o":["our own dog is barking","all dogs are barking","the only dog is barking","some dog somewhere is barking"],"a":3,"e":"a – noma'lum, qaysidir it; the – ma'lum, aniq it."},{"q":"«The» can be used with ...","o":["singular, plural and uncountable nouns","only uncountable nouns","only plural nouns","only singular nouns"],"a":0,"e":"The birlik, ko'plik va sanalmaydigan otlar bilan ham ishlatiladi."},{"q":"___ couple I met on the train were very kind.","o":["An","— (no article)","The","A"],"a":2,"e":"Ot ergash gap (I met on the train) bilan aniqlangan – the."},{"q":"Paris is one of ___ most beautiful cities in the world.","o":["— (no article)","the","an","a"],"a":1,"e":"Orttirma daraja (most beautiful) oldidan the ishlatiladi."}]},{"id":"p2-01","en":"Cardinal Numerals","uz":"Sanoq (miqdor) sonlar","emoji":"🔢","level":"A1","group":"Artikl va son","summary":"Sanoq sonlar predmetning miqdorini bildiradi. Ushbu darsda sonlarning yozilishi, and so'zining ishlatilishi, a/one hamda hundred, thousand, dozen so'zlarining ko'plik shakli o'rganiladi.","blocks":[{"t":"p","x":"Ingliz tilida sonlar (<b>numerals</b>) gapda <b>sifat</b> (adjective) vazifasini bajaradi va ikki turga bo'linadi: <b>cardinal numerals</b> (miqdor yoki sanoq sonlar) va <b>ordinal numerals</b> (tartib sonlar)."},{"t":"h","x":"Cardinal numerals – sanoq sonlar"},{"t":"p","x":"Sanoq sonlar predmetning <b>miqdorini</b> ko'rsatadi (<i>nechta?</i> savoliga javob beradi)."},{"t":"table","head":["Son","Yozilishi","Son","Yozilishi"],"rows":[["1","one","11","eleven"],["2","two","12","twelve"],["3","three","13","thirteen"],["4","four","14","fourteen"],["5","five","15","fifteen"],["6","six","16","sixteen"],["7","seven","17","seventeen"],["8","eight","18","eighteen"],["9","nine","19","nineteen"],["10","ten","20","twenty"]]},{"t":"table","head":["Son","Yozilishi","Son","Yozilishi"],"rows":[["21","twenty-one","50","fifty"],["22","twenty-two","60","sixty"],["30","thirty","70","seventy"],["31","thirty-one","80","eighty"],["32","thirty-two","90","ninety"],["40","forty","100","a hundred"],["41","forty-one","1 000","a thousand"],["42","forty-two","1 000 000","a million"],["","","1 000 000 000","a billion"]]},{"t":"rule","x":"Diqqat: 21–99 oralig'idagi qo'shma sonlar chiziqcha bilan yoziladi: <b>twenty-one, forty-two</b>. <b>forty</b> so'zida u harfi yo'q (fourty emas!)."},{"t":"h","x":"and so'zining ishlatilishi"},{"t":"p","x":"Agar son 3 yoki undan ortiq raqamdan iborat bo'lsa, <b>birlik va o'nliklardan oldin</b> <b>and</b> so'zi ishlatiladi:"},{"t":"list","items":["400 – four hundred","1400 – one thousand, four hundred","401 – four hundred <b>and</b> one","1401 – one thousand, four hundred <b>and</b> one","410 – four hundred <b>and</b> ten","499 – four hundred <b>and</b> ninety-nine"]},{"t":"p","x":"Yuz minglik va yuz millionlik sonlarda ham xuddi shu qoida amal qiladi:"},{"t":"list","items":["401 401 401 – four hundred and one million, four hundred and one thousand, four hundred and one","123 456 789 – one hundred and twenty-three million, four hundred and fifty-six thousand, seven hundred and eighty-nine"]},{"t":"h","x":"A yoki one?"},{"t":"p","x":"<b>Hundred, thousand, million</b> va boshqalar yakka o'zi kelsa, ulardan oldin <b>a</b> ishlatgan ma'qulroq, ammo <b>one</b> ham xato emas:"},{"t":"list","items":["a hundred = one hundred","a thousand = one thousand"]},{"t":"p","x":"Bundan tashqari <b>a</b> quyidagi sonlarda ham ishlatiladi (100–199 va 1000–1099 oralig'ida):"},{"t":"list","items":["101 – a hundred (and) one","103 – a hundred and three","199 – a hundred and ninety-nine","1001 – a thousand and one","1002 – a thousand and two","1099 – a thousand and ninety-nine"]},{"t":"rule","x":"Boshqa hollarda <b>a</b> artiklini ishlatib bo'lmaydi, faqat <b>one</b> ishlatiladi: 1140 – <b>one</b> thousand, one hundred and forty."},{"t":"h","x":"Hundred, thousand, dozen – birlikmi, ko'plikmi?"},{"t":"p","x":"Agar <b>hundred, thousand, million, dozen</b> (o'n ikkitalik) va h.k. <b>aniq miqdorni</b> ko'rsatsa, ular <b>ko'plik shakliga o'tmaydi</b> (-s qo'shilmaydi):"},{"t":"ex","en":"Six hundred people.","uz":"Olti yuz kishi."},{"t":"ex","en":"Two thousand birds.","uz":"Ikki ming qush."},{"t":"ex","en":"Three dozen eggs.","uz":"Uch dyujina (36 ta) tuxum."},{"t":"p","x":"Agar bu so'zlar aniq miqdorni emas, balki <b>“ko'plab, yuzlab, minglab”</b> ma'nosida kelsa, ular <b>ko'plik shakliga</b> o'tadi va ulardan keyin albatta <b>of</b> predlogi qo'yiladi:"},{"t":"ex","en":"Hundreds of people.","uz":"Yuzlab odamlar."},{"t":"ex","en":"Thousands of birds.","uz":"Minglab qushlar."},{"t":"ex","en":"Dozens of eggs.","uz":"Ko'plab tuxumlar."},{"t":"formula","x":"aniq son + hundred/thousand + ot  |  hundreds/thousands + of + ot"}],"quiz":[{"q":"How do you say 401?","o":["four hundred one and","four hundreds and one","four hundred and one","four hundred-one"],"a":2,"e":"Uch xonali sonlarda birlik/o'nlikdan oldin and qo'yiladi."},{"q":"Choose the correct spelling of 40.","o":["fourty","forty","fourthy","fortie"],"a":1,"e":"40 – forty, u harfisiz yoziladi."},{"q":"Choose the correct phrase.","o":["Six hundreds people","Six hundred people","Six hundred of people","Six hundreds of people"],"a":1,"e":"Aniq miqdorda hundred ko'plik shakliga o'tmaydi va of ishlatilmaydi."},{"q":"There were ___ people at the concert (= very many).","o":["hundred of","hundreds","hundreds of","hundred"],"a":2,"e":"“Yuzlab” ma'nosida hundreds of ishlatiladi."},{"q":"How do you say 1140?","o":["a thousand, a hundred and forty","one thousand, one hundred and forty","a thousand one hundred forty and","thousand, hundred and forty"],"a":1,"e":"1140 kabi sonlarda a ishlatilmaydi, faqat one."},{"q":"Which is correct for 1001?","o":["a thousand and one","a thousands one","one thousands and one","thousand one and"],"a":0,"e":"1001–1099 oralig'ida a thousand and ... deyish mumkin."},{"q":"She bought three ___ eggs.","o":["dozens","dozens of","dozen","dozen of"],"a":2,"e":"Aniq miqdor (three) bo'lsa, dozen birlikda va of'siz keladi."},{"q":"Which number is written correctly?","o":["twentyone","twenty-one","twenty and one","one-twenty"],"a":1,"e":"21–99 oralig'idagi qo'shma sonlar chiziqcha bilan yoziladi."},{"q":"How do you say 499?","o":["four hundred ninety and nine","four hundred and ninety-nine","four hundreds ninety-nine","four hundred and ninety and nine"],"a":1,"e":"and faqat bir marta, o'nliklardan oldin qo'yiladi."},{"q":"___ of birds flew over the lake (= very many).","o":["Thousand","Two thousands","Thousands","Thousand's"],"a":2,"e":"Noaniq ko'p miqdor uchun thousands of ishlatiladi."}]},{"id":"p2-02","en":"Ordinal Numerals and Fractions","uz":"Tartib sonlar va kasr sonlar","emoji":"🥇","level":"A2","group":"Artikl va son","summary":"Tartib sonlar tartibni bildiradi (nechanchi?). Darsda tartib sonlarning yasalishi, kasrlarni o'qish, raqam bilan yozish va qirollar unvonlarini aytish qoidalari o'rganiladi.","blocks":[{"t":"h","x":"Ordinal numerals – tartib sonlar"},{"t":"p","x":"Tartib sonlar <b>nechanchi?</b> savoliga javob beradi, tartibni bildiradi va gapda <b>sifat</b> hisoblanadi."},{"t":"table","head":["Son","Tartib son","Son","Tartib son"],"rows":[["1","first","11","eleventh"],["2","second","12","twelfth"],["3","third","13","thirteenth"],["4","fourth","14","fourteenth"],["5","fifth","15","fifteenth"],["6","sixth","16","sixteenth"],["7","seventh","17","seventeenth"],["8","eighth","18","eighteenth"],["9","ninth","19","nineteenth"],["10","tenth","20","twentieth"]]},{"t":"table","head":["Son","Tartib son","Son","Tartib son"],"rows":[["21","twenty-first","50","fiftieth"],["22","twenty-second","60","sixtieth"],["30","thirtieth","70","seventieth"],["31","thirty-first","80","eightieth"],["32","thirty-second","90","ninetieth"],["40","fortieth","100","the hundredth"],["41","forty-first","1000","the thousandth"],["42","forty-second","1001","the thousand and first"],["","","1 000 000","the millionth"]]},{"t":"rule","x":"Diqqat: 1, 2, 3 noqonuniy – <b>first, second, third</b>. Yozilishida o'zgarish bor: five – <b>fifth</b>, nine – <b>ninth</b>, twelve – <b>twelfth</b>, eight – <b>eighth</b>. -ty bilan tugaganlarda y → ie: twenty – <b>twentieth</b>."},{"t":"p","x":"Qo'shma tartib sonlarda faqat <b>oxirgi qism</b> tartib songa aylanadi, and qoidasi esa sanoq sonlardagidek amal qiladi:"},{"t":"ex","en":"123,456th – one hundred and twenty-three thousand, four hundred and fifty-sixth","uz":"123 456-chi"},{"t":"h","x":"Kasr sonlar (fractions)"},{"t":"p","x":"Kasrning <b>surati</b> sanoq son, <b>maxraji</b> esa tartib son bilan ifodalanadi. Agar surat 1 dan katta bo'lsa, tartib son <b>ko'plik shakliga</b> o'tadi (-s qo'shiladi):"},{"t":"formula","x":"surat (cardinal) + maxraj (ordinal, surat > 1 bo'lsa + s)"},{"t":"list","items":["1/10 – <b>a</b> (one) tenth (a ishlatgan ma'qulroq)","3/7 – three seven<b>ths</b>"]},{"t":"rule","x":"Istisno: ½ – <b>a half</b>; ¼ – <b>a quarter</b>."},{"t":"p","x":"<b>Butun son + kasr</b>dan keyin to'g'ridan-to'g'ri ko'plikdagi ot ishlatiladi:"},{"t":"ex","en":"2 ¼ miles – two and a quarter miles","uz":"ikki butun chorak mil"},{"t":"p","x":"Faqat kasr sondan keyin ot ishlatmoqchi bo'lsak, <b>of</b> predlogidan foydalanish shart:"},{"t":"ex","en":"¼ of a second = a quarter of a second","uz":"soniyaning chorak qismi"},{"t":"rule","x":"Lekin <b>half</b> so'zidan keyin <b>of</b> ishlatish ixtiyoriy: <i>Half (of) my earnings are paid in taxes.</i> – Daromadimning yarmi soliqqa to'lanadi."},{"t":"h","x":"Tartib sonni raqam bilan yozish"},{"t":"p","x":"Tartib sonni raqam bilan yozganda raqamdan keyin so'zning <b>oxirgi ikki harfi</b> qo'shiladi:"},{"t":"list","items":["first – 1<b>st</b>","second – 2<b>nd</b>","third – 3<b>rd</b>","fourth – 4<b>th</b>","the hundred and first – 101<b>st</b>"]},{"t":"h","x":"Qirol va qirolichalarning unvoni"},{"t":"p","x":"Qirol, qirolicha va boshqalarning unvoni (title) yozilganda <b>Rim raqamlari</b> ishlatiladi. To'liq aytilganda esa tartib son ishlatiladi va undan oldin albatta <b>the</b> artikli qo'yiladi:"},{"t":"ex","en":"Charles V – Charles the Fifth","uz":"Karl V – Karl Beshinchi"},{"t":"ex","en":"Elizabeth II – Elizabeth the Second","uz":"Yelizaveta II – Yelizaveta Ikkinchi"}],"quiz":[{"q":"What is the ordinal form of 80?","o":["eighth","eightyth","eightieth","eightteenth"],"a":2,"e":"-ty bilan tugagan sonlarda y → ie bo'lib, -th qo'shiladi: eightieth."},{"q":"What is the ordinal form of 12?","o":["twelveth","twelfth","twelvth","twelfeth"],"a":1,"e":"twelve – twelfth (ve → f)."},{"q":"How do you say 3/7?","o":["three seventh","three sevens","three sevenths","third seven"],"a":2,"e":"Surat 1 dan katta bo'lsa, maxraj ko'plikda: sevenths."},{"q":"How do you say ½?","o":["a second","one twoth","a half","a halve"],"a":2,"e":"½ – istisno: a half."},{"q":"Choose the correct phrase.","o":["a quarter a second","a quarter of a second","quarter second of","a quarters of second"],"a":1,"e":"Kasrdan keyin ot kelsa of ishlatiladi."},{"q":"How do you say 2 ¼ miles?","o":["two and a quarter miles","two and a quarter of miles","two quarters miles","two and quarter of a mile"],"a":0,"e":"Butun son + kasrdan keyin to'g'ridan-to'g'ri ko'plikdagi ot keladi."},{"q":"Which sentence is correct?","o":["Half my earnings are paid in taxes.","Half of earnings my are paid in taxes.","A halves of my earnings are paid in taxes.","Halfs my earnings are paid in taxes."],"a":0,"e":"half'dan keyin of ixtiyoriy: Half (of) my earnings..."},{"q":"How do you read “Elizabeth II”?","o":["Elizabeth two","Elizabeth second","Elizabeth the second","Elizabeth the two"],"a":2,"e":"Unvonlarda the + tartib son ishlatiladi."},{"q":"Choose the correct written form of “twenty-third”.","o":["23th","23rd","23nd","23st"],"a":1,"e":"third – 3rd, oxirgi ikki harf qo'shiladi."},{"q":"How do you say 1/10?","o":["a ten","a tenth","one tens","the ten"],"a":1,"e":"1/10 – a (one) tenth, a ishlatgan ma'qulroq."}]},{"id":"p2-03","en":"Personal Pronouns: Subject and Object","uz":"Kishilik olmoshlari: ega va to'ldiruvchi shakli","emoji":"👤","level":"A1","group":"Olmosh, sifat, ravish","summary":"Kishilik olmoshlari ikki xil bo'ladi: ega o'rnida keluvchi subject pronoun va to'ldiruvchi o'rnida keluvchi object pronoun. Darsda ularning qachon ishlatilishi o'rganiladi.","blocks":[{"t":"p","x":"Ot o'rnida keladigan so'zlar <b>olmosh</b> (pronoun) deyiladi. Olmoshlar bir necha turga bo'linadi. Birinchisi – <b>personal pronoun</b> (kishilik olmoshi). U ikki turga bo'linadi: <b>subject pronoun</b> va <b>object pronoun</b>."},{"t":"table","head":["","Shaxs","Subject","Object"],"rows":[["Birlik","1-shaxs","I","me"],["Birlik","2-shaxs","you","you"],["Birlik","3-shaxs","he / she / it","him / her / it"],["Ko'plik","1-shaxs","we","us"],["Ko'plik","2-shaxs","you","you"],["Ko'plik","3-shaxs","they","them"]]},{"t":"rule","x":"<b>You</b> va <b>it</b> subject va object shaklida bir xil yoziladi."},{"t":"h","x":"Subject pronoun"},{"t":"p","x":"Subject pronoun gapda <b>ega</b> o'rnida keladi:"},{"t":"ex","en":"I go to school.","uz":"Men maktabga boraman."},{"t":"ex","en":"We are students.","uz":"Biz talabamiz."},{"t":"ex","en":"She wears glasses.","uz":"U ko'zoynak taqadi."},{"t":"h","x":"to be dan keyingi olmosh"},{"t":"p","x":"<b>to be</b> dan keyin keladigan olmosh gapning tuzilishiga qarab tanlanadi:"},{"t":"list","items":["1. Olmoshdan keyin <b>ergash gap</b> (who/that ...) kelsa, <b>subject pronoun</b> ishlatiladi: <i>It was <b>she</b> who knew the real culprit.</i>","2. Olmosh <b>yakka o'zi</b> kelsa, <b>object pronoun</b> ishlatgan ma'qulroq: <i>It was <b>me</b>.</i> (rasmiy uslubda: <i>It was I.</i>)"]},{"t":"h","x":"We / You + ot"},{"t":"p","x":"<b>We</b> va <b>you</b> dan keyin to'g'ridan-to'g'ri ot ishlatish mumkin; boshqa olmoshlardan keyin bunday qilish xato:"},{"t":"ex","en":"We students always get low marks.","uz":"Biz talabalar doim past baho olamiz."},{"t":"ex","en":"You students always get low marks.","uz":"Sizlar talabalar doim past baho olasizlar."},{"t":"h","x":"Object pronoun"},{"t":"p","x":"Object pronoun gapda <b>to'ldiruvchi</b> (complement) o'rnida keladi:"},{"t":"ex","en":"They called us on the telephone.","uz":"Ular bizga telefon qilishdi."},{"t":"ex","en":"He bought it.","uz":"U uni sotib oldi."},{"t":"p","x":"Object pronoun <b>predlogdan keyin</b> ham ishlatiladi:"},{"t":"ex","en":"Mary is going to class with me.","uz":"Meri men bilan darsga ketyapti."},{"t":"p","x":"<b>Fe'l + predlog</b> birikmasidan keyin ham object pronoun ishlatiladi:"},{"t":"ex","en":"The policeman was looking for him.","uz":"Politsiyachi uni qidirayotgan edi."},{"t":"rule","x":"Diqqat: predlogdan keyin har doim ham object pronoun kelmaydi. Agar predlogdan keyin <b>ergash gap (clause)</b> – ega va fe'l – kelsa, <b>subject pronoun</b> ishlatiladi."},{"t":"ex","en":"Janet will make her presentation after him.","uz":"Janet o'z taqdimotini undan keyin qiladi."},{"t":"ex","en":"Janet will make her presentation after he finishes his speech.","uz":"Janet o'z taqdimotini u nutqini tugatgandan keyin qiladi."}],"quiz":[{"q":"___ go to school every day.","o":["Me","I","My","Mine"],"a":1,"e":"Ega o'rnida subject pronoun (I) keladi."},{"q":"They called ___ on the telephone.","o":["we","our","us","ours"],"a":2,"e":"To'ldiruvchi o'rnida object pronoun (us) keladi."},{"q":"Mary is going to class with ___.","o":["I","me","my","mine"],"a":1,"e":"Predlogdan keyin object pronoun ishlatiladi."},{"q":"The policeman was looking for ___.","o":["he","his","him","himself"],"a":2,"e":"Fe'l + predlogdan keyin object pronoun keladi."},{"q":"Janet will speak after ___ finishes his speech.","o":["him","he","his","himself"],"a":1,"e":"Predlogdan keyin ergash gap (ega + fe'l) kelsa, subject pronoun ishlatiladi."},{"q":"Who broke the window? – It was ___. (short answer, informal)","o":["me","my","mine","myself"],"a":0,"e":"Olmosh yakka kelsa, object pronoun ishlatgan ma'qul: It was me."},{"q":"It was ___ who knew the truth.","o":["her","she","hers","herself"],"a":1,"e":"Olmoshdan keyin who-ergash gap kelsa, subject pronoun ishlatiladi."},{"q":"Which sentence is correct?","o":["They students are lazy.","He students are lazy.","We students are lazy.","Them students are lazy."],"a":2,"e":"Faqat we va you dan keyin to'g'ridan-to'g'ri ot qo'yish mumkin."},{"q":"Which pronouns have the same subject and object form?","o":["he and she","you and it","we and they","I and he"],"a":1,"e":"you – you, it – it: shakli o'zgarmaydi."},{"q":"The object form of “they” is ___.","o":["their","theirs","them","themselves"],"a":2,"e":"they – them."}]},{"id":"p2-04","en":"Reflexive and Reciprocal Pronouns","uz":"O'zlik va o'zaro (birgalik) olmoshlari","emoji":"🪞","level":"A2","group":"Olmosh, sifat, ravish","summary":"O'zlik olmoshlari (myself, himself ...) ish-harakat bajaruvchining o'ziga qaytganda yoki ta'kid uchun ishlatiladi; each other / one another esa “bir-biri” ma'nosini beradi. Darsda ularning ishlatilmaydigan holatlari ham ko'rib chiqiladi.","blocks":[{"t":"h","x":"Reflexive pronoun – o'zlik olmoshi"},{"t":"table","head":["Birlik","Ma'nosi","Ko'plik","Ma'nosi"],"rows":[["myself","o'zim, o'zimga","ourselves","o'zimiz, o'zimizga"],["yourself","o'zing(iz), o'zingizga","yourselves","o'zlaringiz, o'zlaringizga"],["himself","o'zi, o'ziga (o'g'il bola)","themselves","o'zlari, o'zlariga"],["herself","o'zi, o'ziga (qiz bola)","",""],["itself","o'zi, o'ziga (jonsiz yoki jinsi noaniq narsa)","",""]]},{"t":"rule","x":"-<b>self</b> qo'shimchasi ko'plikda -<b>selves</b> ga aylanadi."},{"t":"h","x":"1. Ega va to'ldiruvchi bir shaxs bo'lsa"},{"t":"p","x":"Agar ega ish-harakatni bajarib, uni o'zi qabul qilsa (ya'ni <b>ega va to'ldiruvchi bitta shaxs</b> bo'lsa), reflexive pronoun ishlatiladi:"},{"t":"ex","en":"John bought him a car.","uz":"Jon unga (boshqa odamga) mashina sotib oldi."},{"t":"ex","en":"John bought himself a car.","uz":"Jon o'ziga mashina sotib oldi."},{"t":"ex","en":"We hurt ourselves playing football.","uz":"Biz futbol o'ynayotib o'zimizni jarohatladik."},{"t":"ex","en":"Tom and Ann blamed themselves for the accident.","uz":"Tom va Ann bu baxtsiz hodisada o'zlarini aybdor deb bilishdi."},{"t":"ex","en":"This refrigerator defrosts itself.","uz":"Bu muzlatgich o'zini o'zi eritadi."},{"t":"p","x":"Xuddi shunday, <b>predlogdan keyin</b> ham reflexive pronoun kelishi mumkin:"},{"t":"ex","en":"He spoke to himself.","uz":"U o'zi bilan o'zi gaplashdi."},{"t":"ex","en":"I'm annoyed with myself.","uz":"Men o'zimdan ranjidim."},{"t":"rule","x":"Ammo predlog <b>joylashuvni</b> bildirsa, reflexive pronoun emas, object pronoun ishlatiladi: <i>Did you take your dog with <b>you</b>?</i> – Itingizni o'zingiz bilan oldingizmi? <i>They put the children among <b>them</b>.</i> – Ular bolalarni o'z oralariga qo'yishdi."},{"t":"h","x":"2. Ta'kid uchun"},{"t":"p","x":"Egani <b>ta'kidlash</b> uchun reflexive pronoun egadan keyin yoki ba'zan gap oxirida qo'yiladi (“shaxsan o'zi” ma'nosi):"},{"t":"ex","en":"I myself believe that the proposal is good.","uz":"Men o'zim bu taklif yaxshi deb hisoblayman."},{"t":"ex","en":"John himself bought the gifts.","uz":"Jon sovg'alarni shaxsan o'zi sotib oldi."},{"t":"ex","en":"I did it myself.","uz":"Buni men o'zim qildim (boshqa odam emas)."},{"t":"p","x":"Biror <b>otni</b> ta'kidlash uchun reflexive pronoun shu otdan keyin qo'yiladi:"},{"t":"ex","en":"I saw Tom himself.","uz":"Men Tomning shaxsan o'zini ko'rdim."},{"t":"ex","en":"He spoke to the President himself.","uz":"U shaxsan Prezidentning o'zi bilan gaplashdi."},{"t":"h","x":"3. by + reflexive pronoun = alone"},{"t":"formula","x":"by + myself / himself ... = alone (yolg'iz, hech kimning yordamisiz)"},{"t":"ex","en":"John cleaned the room by himself.","uz":"Jon xonani yolg'iz o'zi tozaladi."},{"t":"ex","en":"I did it by myself.","uz":"Buni yakka o'zim qildim (boshqalar yordamisiz)."},{"t":"ex","en":"I did it myself.","uz":"Buni men qildim (boshqa odam qilmagan)."},{"t":"h","x":"Reflexive pronoun ishlatilmaydigan holatlar"},{"t":"list","items":["<b>take / bring something with ...</b> dan keyin: <i>I went out and took an umbrella with <b>me</b>.</i> – Chiqib ketdim va o'zim bilan soyabon oldim. <i>He brought the letter with <b>him</b>.</i> – U xatni o'zi bilan olib keldi.","<b>feel, relax, concentrate</b> fe'llaridan keyin: <i>He feels good</i> (<s>himself</s> emas) – U o'zini yaxshi his qilyapti. <i>Before a speech, you should concentrate.</i> – Nutqdan oldin diqqatingizni jamlashingiz kerak.","<b>wash, dress, shave</b> fe'llaridan keyin (odatda): <i>I washed.</i> – Men yuvindim. <i>I got up, washed and dressed.</i> – Men turdim, yuvindim va kiyindim.","<b>meet</b> fe'li bilan: ega <b>we</b> bo'lsa ourselves/us, ega <b>I</b> bo'lsa myself/me ishlatilmaydi: <i>What time shall we meet?</i> – Soat nechada uchrashamiz? <i>I met him at the stadium.</i> – Men u bilan stadionda uchrashdim. <i>They met them in the theatre.</i> <i>He met him.</i>"]},{"t":"h","x":"Reciprocal pronoun – o'zaro olmosh"},{"t":"p","x":"<b>each other</b> va <b>one another</b> – “bir-biri, bir-biriga” ma'nosini beradi. Ularning ma'nosi bir xil va bir-birining o'rnida ishlatilishi mumkin. Reflexive bilan farqiga e'tibor bering:"},{"t":"ex","en":"Tom looked at himself and Ann looked at herself. They looked at themselves.","uz":"Tom o'ziga qaradi, Ann ham o'ziga qaradi. Ular o'zlariga qarashdi."},{"t":"ex","en":"Tom looked at Ann and Ann looked at Tom. They looked at each other.","uz":"Tom Annga qaradi, Ann Tomga qaradi. Ular bir-birlariga qarashdi."},{"t":"ex","en":"Sue and Bill like each other / one another.","uz":"Syu va Bill bir-birlarini yoqtirishadi."}],"quiz":[{"q":"John bought ___ a new car (for John).","o":["him","his","himself","he"],"a":2,"e":"Ega va to'ldiruvchi bitta shaxs: himself."},{"q":"We hurt ___ playing football.","o":["ourselfs","ourselves","us","ourself"],"a":1,"e":"Ko'plikda -selves: ourselves."},{"q":"I went out and took an umbrella with ___.","o":["myself","me","mine","my"],"a":1,"e":"take/bring something with ... dan keyin object pronoun ishlatiladi."},{"q":"Choose the correct sentence.","o":["He feels himself good.","He feels good.","He feels him good.","He feels hisself good."],"a":1,"e":"feel fe'lidan keyin reflexive pronoun ishlatilmaydi."},{"q":"John cleaned the room ___ (= alone).","o":["by him","by himself","with himself","for him"],"a":1,"e":"by + reflexive pronoun = alone."},{"q":"Tom looked at Ann and Ann looked at Tom. They looked at ___.","o":["themselves","them","each other","theirs"],"a":2,"e":"O'zaro harakat: each other / one another."},{"q":"What time shall we ___?","o":["meet ourselves","meet us","meet","meet each ourselves"],"a":2,"e":"Ega we bo'lsa, meet'dan keyin ourselves/us ishlatilmaydi."},{"q":"He spoke to the President ___ (= personally).","o":["himself","him","his","itself"],"a":0,"e":"Otni ta'kidlash uchun reflexive pronoun otdan keyin qo'yiladi."},{"q":"This refrigerator defrosts ___.","o":["himself","itself","themselves","it"],"a":1,"e":"Jonsiz narsa uchun itself."},{"q":"I got up, ___ and dressed.","o":["washed myself me","washed","washed me","washed mine"],"a":1,"e":"wash, dress, shave fe'llaridan keyin odatda reflexive pronoun qo'yilmaydi."}]},{"id":"p2-05","en":"Indefinite Pronoun One / Ones","uz":"Noaniq olmosh: one / ones","emoji":"☝️","level":"A2","group":"Olmosh, sifat, ravish","summary":"one va ones oldin aytilgan otni takrorlamaslik uchun uning o'rnida ishlatiladi. Darsda ularning this/that, sifat va the bilan ishlatilishi ko'rib chiqiladi.","blocks":[{"t":"p","x":"<b>One / ones</b> oldin eslatib o'tilgan otning o'rnida keladi va uni takrorlashdan qutqaradi."},{"t":"list","items":["<b>one</b> = (a) + oldin aytilgan birlikdagi ot","<b>ones</b> = oldin aytilgan ko'plikdagi ot"]},{"t":"rule","x":"<b>a</b> artikli faqat birlikdagi otlar uchun ishlatiladi, shuning uchun <b>ones</b> dan oldin a qo'yilmaydi."},{"t":"ex","en":"I need a pen. Do you have one?","uz":"Menga ruchka kerak. Sizda bormi (bitta)?"},{"t":"ex","en":"I need some books. Have you got any good ones?","uz":"Menga kitoblar kerak. Sizda yaxshilari bormi?"},{"t":"h","x":"this / that / these / those + one(s)"},{"t":"p","x":"Gap <b>solishtirish yoki tanlash</b> haqida bo'lsa, this, that, these, those dan keyin one/ones ishlatiladi:"},{"t":"ex","en":"This chair is too low. I'll sit on that one.","uz":"Bu stul juda past. Men anavisiga o'tiraman."},{"t":"ex","en":"I like these blue ones best.","uz":"Menga mana bu ko'klari ko'proq yoqadi."},{"t":"h","x":"Sifat + one(s)"},{"t":"p","x":"One/ones <b>sifatdan keyin</b> oldin aytilgan ot o'rnida ishlatiladi:"},{"t":"ex","en":"I lost my camera; this is a new one.","uz":"Fotoapparatimni yo'qotdim, bu yangisi."},{"t":"ex","en":"Don't buy expensive apples, buy cheaper ones.","uz":"Qimmat olma olma, arzonrog'ini ol."},{"t":"ex","en":"Hard beds are healthier than soft ones.","uz":"Qattiq karavotlar yumshoqlaridan foydaliroq."},{"t":"h","x":"the + one(s)"},{"t":"p","x":"<b>the</b> artiklidan keyin ham one/ones oldin aytilgan ot o'rnida keladi:"},{"t":"ex","en":"Which hotel did you stay at? – The one near the station.","uz":"Qaysi mehmonxonada qoldingiz? – Bekat yonidagisida."},{"t":"ex","en":"Which cigarettes are yours? – The ones on the table.","uz":"Qaysi sigaretalar sizniki? – Stol ustidagilari."}],"quiz":[{"q":"I need a pen. Do you have ___?","o":["it","one","ones","a one"],"a":1,"e":"Birlikdagi ot o'rnida one."},{"q":"Don't buy expensive apples, buy cheaper ___.","o":["one","ones","a ones","it"],"a":1,"e":"Ko'plikdagi ot (apples) o'rnida ones."},{"q":"This chair is too low. I'll sit on that ___.","o":["ones","one","it","them"],"a":1,"e":"that + one (birlik)."},{"q":"Which hotel did you stay at? – ___ near the station.","o":["One","The one","The ones","A ones"],"a":1,"e":"Aniq bir narsani ko'rsatish uchun the one."},{"q":"Which cigarettes are yours? – ___ on the table.","o":["The one","One","The ones","Ones"],"a":2,"e":"Ko'plik (cigarettes): the ones."},{"q":"I lost my camera; this is a new ___.","o":["one","ones","it","a one"],"a":0,"e":"Sifatdan keyin birlikdagi ot o'rnida one."},{"q":"Hard beds are healthier than soft ___.","o":["one","ones","it","a one"],"a":1,"e":"beds – ko'plik, shuning uchun ones."},{"q":"Which is NOT correct?","o":["a new one","these ones","a ones","the blue ones"],"a":2,"e":"a artikli faqat birlikda; a ones xato."},{"q":"I like these blue ___ best.","o":["one","ones","a one","it"],"a":1,"e":"these + ko'plik: ones."}]},{"id":"p2-06","en":"Adjectives: Position and Order","uz":"Sifatlar: o'rni va tartibi","emoji":"🎨","level":"A2","group":"Olmosh, sifat, ravish","summary":"Sifat ot haqida qo'shimcha ma'lumot beradi va son-jinsga qarab o'zgarmaydi. Darsda attributive va predicative sifatlar, bog'lovchi fe'llar hamda bir nechta sifatning tartibi o'rganiladi.","blocks":[{"t":"p","x":"<b>Adjective</b> (sifat) – “describing”, ya'ni tasvirlovchi so'z bo'lib, ot haqida qo'shimcha ma'lumot beradi."},{"t":"p","x":"Sifatlar birlikdagi va ko'plikdagi otlar uchun hamda barcha jinslar uchun <b>bir xil shaklda</b> bo'ladi:"},{"t":"ex","en":"a good boy – good boys; a good girl – good girls","uz":"yaxshi bola – yaxshi bolalar; yaxshi qiz – yaxshi qizlar"},{"t":"rule","x":"Istisno: <b>this</b> va <b>that</b> faqat birlikdagi otlardan oldin, <b>these</b> va <b>those</b> esa ko'plikdagi otlardan oldin ishlatiladi: <i>this man – these men; that dog – those dogs.</i>"},{"t":"h","x":"Sifatning o'rni (Position of adjectives)"},{"t":"p","x":"Kelgan o'rniga ko'ra sifat ikki xil bo'ladi: <b>attributive</b> (aniqlovchi) va <b>predicative</b> (kesim tarkibidagi) sifat."},{"t":"p","x":"<b>Attributive adjective</b> – otdan <b>oldin</b> keladi:"},{"t":"list","items":["a big house – katta uy","an ugly woman – xunuk ayol","an interesting book – qiziqarli kitob"]},{"t":"p","x":"<b>Predicative adjective</b> – fe'ldan <b>keyin</b> keladi:"},{"t":"ex","en":"I am happy.","uz":"Men baxtliman."},{"t":"ex","en":"She became rich.","uz":"U boy bo'lib ketdi."},{"t":"ex","en":"They seemed sad.","uz":"Ular g'amgin ko'rinishdi."},{"t":"ex","en":"It tasted delicious.","uz":"Uning ta'mi mazali edi."},{"t":"p","x":"Predicative sifat faqat quyidagi (bog'lovchi) fe'llardan keyin keladi:"},{"t":"rule","x":"<b>be, become, seem, appear, feel, get / grow</b> (become ma'nosida), <b>keep, look, make, smell, sound, taste</b>"},{"t":"p","x":"Boshqa fe'llardan keyin sifat emas, <b>ravish</b> (adverb) ishlatiladi:"},{"t":"ex","en":"He looked sad.","uz":"U g'amgin ko'rindi. (look = ko'rinmoq → sifat)"},{"t":"ex","en":"He looked at me sadly.","uz":"U menga g'amgin qaradi. (look at = qaramoq → ravish)"},{"t":"h","x":"Fact va opinion sifatlar"},{"t":"p","x":"Ma'nosiga ko'ra sifatlar ikki xil: <b>fact adjective</b> – ot haqidagi aniq, haqiqiy ma'lumot (<i>black cat, round ball</i>); <b>opinion adjective</b> – odamning fikri, qarashiga asoslangan ma'lumot (<i>clever guy, beautiful girl</i>)."},{"t":"h","x":"Sifatlarning ketma-ketligi (Order of adjectives)"},{"t":"p","x":"Kitobda keltirilgan tartib:"},{"t":"table","head":["№","Turi","Misollar"],"rows":[["1","Size (o'lcham, uzunlik; little bundan mustasno)","long, short, big, small, giant"],["2","General description (fikr / opinion)","beautiful, nice, clever, good, sharp, elegant"],["3","Age (yosh; little shu yerga kiradi)","old, new, young, sonlar"],["4","Shape (shakl, kenglik)","round, triangular, wide, narrow"],["5","Colour (rang)","black, red, blue"],["6","Material (material)","plastic, wooden, velvet"],["7","Origin (qayerda tayyorlangani)","Chinese, French, German"],["8","Purpose (nima maqsadda)","walking (stick), sleeping (bag)"]]},{"t":"ex","en":"a long sharp knife","uz":"uzun o'tkir pichoq"},{"t":"ex","en":"an old plastic bucket","uz":"eski plastik chelak"},{"t":"ex","en":"a small round bath","uz":"kichkina dumaloq vanna"},{"t":"ex","en":"an elegant French clock","uz":"nafis fransuz soati"},{"t":"ex","en":"blue velvet jeans","uz":"ko'k baxmal shim"},{"t":"rule","x":"Eslatma: ko'pchilik zamonaviy grammatika kitoblarida <b>opinion</b> (fikr) sifati o'lchamdan ham oldin qo'yiladi: <i>a beautiful big house</i>. Har ikki holda ham fikr va o'lcham <b>yosh, shakl, rang, material, kelib chiqish va maqsad</b>dan oldin keladi."}],"quiz":[{"q":"Choose the correct phrase.","o":["goods boys","good boys","goods boy","a good boys"],"a":1,"e":"Sifat ko'plikda o'zgarmaydi."},{"q":"___ dogs are very friendly.","o":["That","This","Those","A"],"a":2,"e":"Ko'plikdagi otdan oldin these/those."},{"q":"It tasted ___.","o":["deliciously","delicious","delicioused","more deliciously"],"a":1,"e":"taste – bog'lovchi fe'l, undan keyin sifat keladi."},{"q":"He looked at me ___.","o":["sad","sadly","sadder","sadness"],"a":1,"e":"look at (qaramoq) oddiy fe'l, undan keyin ravish."},{"q":"Which verb is NOT followed by a predicative adjective?","o":["seem","become","run","smell"],"a":2,"e":"run bog'lovchi fe'llar ro'yxatiga kirmaydi."},{"q":"In “a big house”, the adjective “big” is ___.","o":["predicative","attributive","an adverb","a pronoun"],"a":1,"e":"Otdan oldin kelgan sifat attributive."},{"q":"Choose the correct order.","o":["a plastic old bucket","an old plastic bucket","a bucket old plastic","a plastic bucket old"],"a":1,"e":"Age (old) materialdan (plastic) oldin keladi."},{"q":"Choose the correct order.","o":["a French elegant clock","an elegant French clock","a clock elegant French","a French clock elegant"],"a":1,"e":"Opinion (elegant) origin (French) dan oldin keladi."},{"q":"Choose the correct order.","o":["velvet blue jeans","blue velvet jeans","jeans blue velvet","velvet jeans blue"],"a":1,"e":"Colour materialdan oldin keladi."},{"q":"Choose the correct order.","o":["a round small bath","a small round bath","a bath small round","a round bath small"],"a":1,"e":"Size (small) shakldan (round) oldin keladi."}]},{"id":"p2-07","en":"Degrees of Adjectives","uz":"Sifat darajalari","emoji":"📈","level":"A2","group":"Olmosh, sifat, ravish","summary":"Sifatning uch darajasi bor: oddiy, qiyosiy va orttirma. Darsda -er/-est va more/most bilan yasalishi, imlo qoidalari, than va the ning ishlatilishi o'rganiladi.","blocks":[{"t":"p","x":"Sifat darajasiga ko'ra uchga bo'linadi: <b>positive</b> (oddiy), <b>comparative</b> (qiyosiy) va <b>superlative</b> (orttirma)."},{"t":"h","x":"1. Positive adjective"},{"t":"p","x":"Oddiy daraja ot haqida <b>yakka o'zi</b>, boshqa ot bilan solishtirmasdan ma'lumot beradi:"},{"t":"ex","en":"A is a big box.","uz":"A – katta quti."},{"t":"h","x":"2. Comparative adjective"},{"t":"p","x":"Qiyosiy daraja <b>ikki narsa solishtirilganda</b> ishlatiladi. Solishtirishda <b>than</b> (“-dan”) so'zi qo'llanadi:"},{"t":"ex","en":"B is bigger than A.","uz":"B A dan kattaroq."},{"t":"ex","en":"He is cleverer than his classmates.","uz":"U sinfdoshlaridan aqlliroq."},{"t":"ex","en":"He is taller than me.","uz":"U mendan baland."},{"t":"ex","en":"Don't buy expensive apples, buy cheaper ones.","uz":"Qimmat olma olma, arzonrog'ini ol."},{"t":"h","x":"Qiyosiy darajaning yasalishi"},{"t":"list","items":["<b>Bir bo'g'inli</b> sifatlarga <b>-er</b> qo'shiladi: bright – brighter. Sifat <b>-e</b> bilan tugasa, faqat <b>-r</b> qo'shiladi: brave – braver.","<b>Ikki va undan ko'p bo'g'inli</b> sifatlardan oldin <b>more</b> qo'yiladi, sifat o'zgarmaydi: interesting – more interesting; frightening – more frightening.","Bir bo'g'inli sifat <b>unli + undosh</b> bilan tugasa, oxirgi undosh <b>ikkilanadi</b>: big – bigger, sad – sadder, fat – fatter, wet – wetter."]},{"t":"rule","x":"Istisno: <b>-y</b> yoki <b>-er</b> bilan tugaydigan <b>ikki bo'g'inli</b> sifatlarga ham -er qo'shiladi (y → i): clever – cleverer, happy – happier, pretty – prettier, busy – busier."},{"t":"h","x":"3. Superlative adjective"},{"t":"p","x":"Orttirma daraja <b>uch yoki undan ortiq</b> narsa solishtirilganda ishlatiladi va “eng” ma'nosini beradi:"},{"t":"ex","en":"B is bigger than A, C is bigger than B. C is the biggest box.","uz":"B A dan katta, C B dan katta. C – eng katta quti."},{"t":"h","x":"Orttirma darajaning yasalishi"},{"t":"list","items":["<b>Bir bo'g'inli</b> sifatlarga <b>-est</b> qo'shiladi: bright – brightest, brave – bravest.","<b>Ikki va undan ko'p bo'g'inli</b> sifatlardan oldin <b>most</b> qo'yiladi: interesting – most interesting, frightening – most frightening.","<b>Unli + undosh</b> bilan tugaydigan bir bo'g'inli sifatlarda oxirgi undosh ikkilanadi: big – biggest, sad – saddest."]},{"t":"rule","x":"Istisno: <b>-er</b> yoki <b>-y</b> bilan tugaydigan ikki bo'g'inli sifatlarga <b>-est</b> qo'shiladi: clever – cleverest, happy – happiest."},{"t":"rule","x":"Barcha orttirma darajadagi sifatlardan oldin <b>the</b> artikli ishlatilishi shart: beautiful – <b>the</b> most beautiful; tall – <b>the</b> tallest."},{"t":"table","head":["Positive","Comparative","Superlative"],"rows":[["bright","brighter","the brightest"],["brave","braver","the bravest"],["big","bigger","the biggest"],["happy","happier","the happiest"],["clever","cleverer","the cleverest"],["interesting","more interesting","the most interesting"]]}],"quiz":[{"q":"B is ___ than A.","o":["big","bigger","biggest","more big"],"a":1,"e":"Ikki narsa solishtirilganda qiyosiy daraja: bigger (g ikkilanadi)."},{"q":"The comparative form of “brave” is ___.","o":["braveer","braver","more brave","bravest"],"a":1,"e":"-e bilan tugasa faqat -r qo'shiladi."},{"q":"The comparative form of “interesting” is ___.","o":["interestinger","more interesting","most interesting","interestinger than"],"a":1,"e":"Ko'p bo'g'inli sifat: more + sifat."},{"q":"The comparative form of “happy” is ___.","o":["happyer","more happy","happier","happiest"],"a":2,"e":"-y bilan tugagan ikki bo'g'inli sifat: y → i + er."},{"q":"The comparative form of “wet” is ___.","o":["weter","wetter","more wet","wettest"],"a":1,"e":"Unli + undosh: oxirgi undosh ikkilanadi."},{"q":"He is taller ___ me.","o":["then","that","than","as"],"a":2,"e":"Qiyosda than ishlatiladi."},{"q":"C is ___ box of the three.","o":["biggest","the biggest","the bigger","most big"],"a":1,"e":"Orttirma darajadan oldin the shart."},{"q":"The superlative form of “clever” is ___.","o":["the most clever","the cleverest","the cleverer","cleverest than"],"a":1,"e":"-er bilan tugagan ikki bo'g'inli sifatga -est qo'shiladi."},{"q":"This is ___ film I have ever seen.","o":["the most interesting","the interestingest","more interesting","most interesting than"],"a":0,"e":"Ko'p bo'g'inli sifat: the most + sifat."},{"q":"He is ___ than his classmates.","o":["clever","cleverer","more cleverest","the cleverest"],"a":1,"e":"Ikki tomonni solishtirish – qiyosiy daraja: cleverer."}]},{"id":"p2-08","en":"Irregular Adjectives; Little/Few; Many/Much/A Lot Of","uz":"Noto'g'ri sifatlar; little/few; many/much/a lot of","emoji":"⚖️","level":"A2","group":"Olmosh, sifat, ravish","summary":"Ba'zi sifatlarning qiyosiy va orttirma shakli butunlay o'zgaradi (good – better – the best). Darsda farther/further, elder/older farqi hamda a little/little, a few/few, many/much/a lot of ishlatilishi o'rganiladi.","blocks":[{"t":"h","x":"Irregular adjectives – noto'g'ri sifatlar"},{"t":"p","x":"Quyidagi sifatlarning qiyosiy va orttirma darajasi yasalganda <b>shakl almashinishi</b> yuz beradi:"},{"t":"table","head":["Positive","Comparative","Superlative"],"rows":[["good","better","the best"],["bad","worse","the worst"],["far","farther / further","the farthest / the furthest"],["old","elder / older","the eldest / the oldest"],["little","less","the least"],["many / much","more","the most"]]},{"t":"h","x":"Farther / farthest va further / furthest"},{"t":"p","x":"<b>Masofa</b> ma'nosida ishlatilganda ular orasida hech qanday farq yo'q:"},{"t":"ex","en":"York is further / farther than Lincoln.","uz":"York Linkolndan uzoqroq."},{"t":"ex","en":"York is the furthest / farthest.","uz":"York eng uzoqda."},{"t":"p","x":"<b>Further</b> ba'zan “qo'shimcha, yana” ma'nosida ham keladi:"},{"t":"ex","en":"Further discussion would be useless.","uz":"Qo'shimcha muhokama foydasiz bo'lardi."},{"t":"ex","en":"Further supplies will be needed.","uz":"Qo'shimcha zaxiralar kerak bo'ladi."},{"t":"h","x":"Elder / eldest va older / oldest"},{"t":"p","x":"<b>Elder / eldest</b> asosan <b>oila a'zolari</b> uchun ishlatiladi va “kattaroq, eng katta” ma'nosini beradi:"},{"t":"ex","en":"my elder brother","uz":"mening akam (katta akam)"},{"t":"rule","x":"<b>than</b> bilan <b>elder</b> hech qachon ishlatilmaydi, uning o'rniga <b>older</b> qo'llanadi: <s>Tom is elder than Jane.</s> – NOTO'G'RI. <i>Tom is older than Jane.</i> – TO'G'RI."},{"t":"h","x":"A little / little va a few / few"},{"t":"p","x":"<b>A little / little</b> faqat <b>sanalmaydigan</b> (uncountable) otlar oldidan, <b>a few / few</b> esa faqat <b>ko'plikdagi sanaladigan</b> otlar oldidan ishlatiladi. Ma'nosi – “oz, ozgina”."},{"t":"ex","en":"I have a little money.","uz":"Menda ozgina pul bor."},{"t":"ex","en":"We have little time.","uz":"Vaqtimiz juda kam (deyarli yo'q)."},{"t":"ex","en":"A few people came.","uz":"Bir necha kishi keldi."},{"t":"ex","en":"Few boys smoke.","uz":"Chekadigan bolalar juda kam."},{"t":"table","head":["Shakl","Ma'nosi"],"rows":[["a little / a few","oz miqdor, lekin <b>deyarli yetarli</b> (ijobiy)"],["little / few","yetishmovchilik, <b>deyarli yo'q</b> (salbiy)"]]},{"t":"ex","en":"We have a little knowledge.","uz":"Bizda ozgina bilim bor."},{"t":"ex","en":"We have little knowledge.","uz":"Bizda deyarli bilim yo'q."},{"t":"ex","en":"There are few butterflies in the city centre.","uz":"Shahar markazida kapalaklar deyarli yo'q."},{"t":"ex","en":"There are a few butterflies in the village.","uz":"Qishloqda bir nechta kapalak bor."},{"t":"h","x":"Many / much va a lot of"},{"t":"list","items":["<b>many</b> – faqat ko'plikdagi otlar oldidan: many books, many pens","<b>much</b> – faqat sanalmaydigan otlar oldidan: much time, much knowledge","<b>a lot of</b> – ikkalasi oldidan ham: a lot of books, a lot of time"]},{"t":"p","x":"<b>Many</b> va <b>much</b> asosan <b>so'roq va inkor</b> gaplarda, <b>a lot of</b> esa asosan <b>darak (tasdiq)</b> gaplarda ishlatiladi:"},{"t":"ex","en":"Did you read many books?","uz":"Ko'p kitob o'qidingmi?"},{"t":"ex","en":"I don't drink much water.","uz":"Men ko'p suv ichmayman."},{"t":"ex","en":"I have got a lot of friends.","uz":"Mening do'stlarim ko'p."},{"t":"p","x":"<b>A lot of</b> otsiz ishlatilganda <b>of</b> tushib qoladi:"},{"t":"ex","en":"Do you have enough money? – Yes, a lot.","uz":"Puling yetarlimi? – Ha, ko'p."},{"t":"formula","x":"a lot / much = often (tez-tez, ko'p)"},{"t":"ex","en":"Do you watch TV much? – No, not much.","uz":"Televizorni ko'p ko'rasanmi? – Yo'q, ko'p emas."},{"t":"ex","en":"I like watching films, so I go to the cinema a lot.","uz":"Men film ko'rishni yaxshi ko'raman, shuning uchun kinoga tez-tez boraman."}],"quiz":[{"q":"The comparative form of “bad” is ___.","o":["badder","more bad","worse","worst"],"a":2,"e":"bad – worse – the worst."},{"q":"This is ___ day of my life.","o":["the goodest","the best","the better","most good"],"a":1,"e":"good – better – the best."},{"q":"Tom is ___ than Jane.","o":["elder","older","eldest","more old"],"a":1,"e":"than bilan elder ishlatilmaydi, older qo'llanadi."},{"q":"___ discussion would be useless (= additional).","o":["Farther","Further","Farthest","Far"],"a":1,"e":"“Qo'shimcha” ma'nosida faqat further."},{"q":"I have ___ money, enough to buy a coffee.","o":["a few","few","a little","many"],"a":2,"e":"Sanalmaydigan ot + “ozgina, yetarli” ma'nosi: a little."},{"q":"There are ___ butterflies in the city centre; almost none.","o":["a few","few","a little","much"],"a":1,"e":"“Deyarli yo'q” ma'nosida few (ko'plikdagi ot)."},{"q":"I don't drink ___ water.","o":["many","much","a few","few"],"a":1,"e":"Sanalmaydigan ot, inkor gap: much."},{"q":"Did you read ___ books?","o":["much","many","a little","little"],"a":1,"e":"Ko'plikdagi ot, so'roq gap: many."},{"q":"Do you have enough money? – Yes, ___.","o":["a lot of","a lot","much of","many"],"a":1,"e":"Otsiz ishlatilganda of tushib qoladi: a lot."},{"q":"The superlative form of “little” is ___.","o":["the littlest","the less","the least","the lesser"],"a":2,"e":"little – less – the least."}]},{"id":"p2-09","en":"Possessive Adjectives and Possessive Pronouns","uz":"Egalik sifatlari va egalik olmoshlari","emoji":"🔑","level":"A1","group":"Olmosh, sifat, ravish","summary":"my, your, his kabi egalik sifatlari otdan oldin keladi, mine, yours, hers kabi egalik olmoshlari esa otsiz ishlatiladi. Darsda a friend of mine tuzilmasi va this/that/these/those ham ko'rib chiqiladi.","blocks":[{"t":"h","x":"Possessive adjective – egalik sifati"},{"t":"table","head":["Kishilik olmoshi","Egalik sifati"],"rows":[["I","my"],["you","your"],["he","his"],["she","her"],["it","its"],["we","our"],["they","their"]]},{"t":"p","x":"Egalik sifati gapda <b>sifat</b> vazifasini bajaradi, egalikni ko'rsatadi va <b>otdan oldin</b> keladi:"},{"t":"ex","en":"It's my book.","uz":"Bu mening kitobim. (my – egalik sifati)"},{"t":"p","x":"Egalik sifati birlikdagi va ko'plikdagi otlar oldidan <b>bir xil shaklda</b> keladi:"},{"t":"list","items":["my book – mening kitobim","my books – mening kitoblarim"]},{"t":"h","x":"Possessive pronoun – egalik olmoshi"},{"t":"table","head":["Egalik sifati","Egalik olmoshi"],"rows":[["my","mine"],["your","yours"],["his","his"],["her","hers"],["its","its"],["our","ours"],["their","theirs"]]},{"t":"formula","x":"possessive pronoun = possessive adjective + noun"},{"t":"ex","en":"It's my book. It's mine.","uz":"Bu mening kitobim. Bu meniki."},{"t":"rule","x":"Egalik olmoshidan keyin <b>hech qachon ot ishlatilmaydi</b>: <s>mine book</s>."},{"t":"ex","en":"Do you have a pen? I've lost mine.","uz":"Ruchkang bormi? Men o'zimnikini yo'qotib qo'ydim."},{"t":"h","x":"of + possessive pronoun"},{"t":"formula","x":"a ... of + possessive pronoun = one of + possessive adjective + ko'plikdagi ot"},{"t":"ex","en":"a friend of mine = one of my friends","uz":"do'stlarimdan biri"},{"t":"ex","en":"a brother of hers = one of her brothers","uz":"uning akalaridan biri"},{"t":"h","x":"This / that / these / those"},{"t":"table","head":["So'z","Ishlatilishi","Tarjimasi"],"rows":[["this","birlikdagi ot oldidan","mana bu"],["that","birlikdagi ot oldidan","anavi"],["these","ko'plikdagi ot oldidan","mana bular"],["those","ko'plikdagi ot oldidan","anavilar"]]},{"t":"p","x":"Bu so'zlar odatda <b>sifat</b> hisoblanadi."},{"t":"ex","en":"This man – these men; that dog – those dogs.","uz":"Bu odam – bu odamlar; anavi it – anavi itlar."}],"quiz":[{"q":"It's my book. It's ___.","o":["my","mine","me","myself"],"a":1,"e":"Ot o'rnida egalik olmoshi: mine."},{"q":"This is ___ house (they own it).","o":["theirs","their","them","they"],"a":1,"e":"Otdan oldin egalik sifati: their."},{"q":"Do you have a pen? I've lost ___.","o":["my","mine","me","my pen's"],"a":1,"e":"Otsiz ishlatiladigan egalik olmoshi: mine."},{"q":"Which is correct?","o":["a friend of my","a friend of mine","a friend of me","a mine friend"],"a":1,"e":"a friend of mine = one of my friends."},{"q":"“A brother of hers” means ___.","o":["her only brother","one of her brothers","her brother's friend","his brother"],"a":1,"e":"of + egalik olmoshi = one of + egalik sifati + ko'plik."},{"q":"The possessive pronoun for “our” is ___.","o":["ours","our's","ourselves","us"],"a":0,"e":"our – ours (apostrofsiz)."},{"q":"Choose the correct sentence.","o":["This is hers bag.","This bag is hers.","This is her's bag.","This bag is her's."],"a":1,"e":"hers otsiz keladi va apostrof olmaydi."},{"q":"I like ___ shoes over there.","o":["this","that","those","these one"],"a":2,"e":"Uzoqdagi ko'plikdagi narsa: those."},{"q":"___ books on my desk are new.","o":["This","These","That","It"],"a":1,"e":"Yaqindagi ko'plikdagi narsa: these."},{"q":"Which pair has the SAME form?","o":["my – mine","her – hers","his – his","our – ours"],"a":2,"e":"his egalik sifati va olmoshida bir xil (its ham)."}]},{"id":"p2-10","en":"Adverbs: Formation","uz":"Ravishlar va ularning yasalishi","emoji":"🏃","level":"A2","group":"Olmosh, sifat, ravish","summary":"Ravish ish-harakat qanday bajarilganini bildiradi va asosan sifatga -ly qo'shib yasaladi. Darsda imlo qoidalari, istisnolar (good – well, true – truly) va -ly bilan tugaydigan sifatlar o'rganiladi.","blocks":[{"t":"p","x":"<b>Ravish</b> (adverb) ish-harakat <b>qanday</b> bajarilganini ko'rsatadi:"},{"t":"ex","en":"He walked slowly.","uz":"U sekin yurdi."},{"t":"ex","en":"Our team played badly.","uz":"Jamoamiz yomon o'ynadi."},{"t":"h","x":"Yasalishi"},{"t":"p","x":"Ravish asosan sifatga <b>-ly</b> qo'shimchasini qo'shib yasaladi: slow – slowly, bad – badly."},{"t":"table","head":["Qoida","Sifat","Ravish"],"rows":[["Ko'p hollarda + ly","slow, bad","slowly, badly"],["-y → -ily","happy, heavy","happily, heavily"],["-e saqlanadi + ly","extreme","extremely"],["undosh + le → -ly (e tushadi)","gentle, capable","gently, capably"],["unli + l → + ly (ll bo'ladi)","beautiful, final","beautifully, finally"]]},{"t":"rule","x":"Istisno: quyidagi 3 so'z -e bilan tugasa ham, <b>e tushib</b> -ly qo'shiladi: <b>true – truly, due – duly, whole – wholly</b>."},{"t":"h","x":"good – well"},{"t":"rule","x":"Istisno: <b>good</b> sifatining ravishi <b>well</b> – shakl butunlay o'zgaradi."},{"t":"ex","en":"A good team.","uz":"Yaxshi jamoa."},{"t":"ex","en":"Our team played well.","uz":"Jamoamiz yaxshi o'ynadi."},{"t":"h","x":"-ly bilan tugaydigan sifatlar"},{"t":"p","x":"<b>Kindly</b> so'zi ham sifat, ham ravish bo'la oladi:"},{"t":"ex","en":"He is a kindly person.","uz":"U mehribon odam."},{"t":"ex","en":"He looked after me kindly.","uz":"U menga mehribonlik bilan g'amxo'rlik qildi."},{"t":"p","x":"-ly bilan tugaydigan qolgan sifatlarni (friendly, lonely, likely, lovely ...) ravish sifatida ishlatib bo'lmaydi – ularning ravish shakli yo'q. Bu kamchilikni to'ldirish uchun <b>sinonim ravish</b> yoki <b>ravish birikmasi</b> (in a ... way) ishlatiladi:"},{"t":"list","items":["likely → probably","lonely → alone","friendly → in a friendly way"]},{"t":"ex","en":"He is a friendly person.","uz":"U samimiy odam."},{"t":"ex","en":"He welcomed us in a friendly way.","uz":"U bizni samimiy kutib oldi."},{"t":"h","x":"His-tuyg'u ifodalovchi ravishlar"},{"t":"p","x":"<b>coolly, coldly, hotly, warmly</b> ravishlari his-tuyg'ularni ifodalash uchun ishlatiladi:"},{"t":"ex","en":"We received them coldly.","uz":"Biz ularni sovuq qabul qildik."},{"t":"ex","en":"They denied the accusation hotly.","uz":"Ular ayblovni jahl bilan rad etishdi."},{"t":"ex","en":"She welcomed us warmly.","uz":"U bizni iliq kutib oldi."}],"quiz":[{"q":"The adverb of “happy” is ___.","o":["happyly","happily","happly","happy"],"a":1,"e":"-y → -ily."},{"q":"The adverb of “extreme” is ___.","o":["extremly","extremely","extremelly","extremaly"],"a":1,"e":"-e saqlanib -ly qo'shiladi."},{"q":"The adverb of “true” is ___.","o":["truely","truly","truelly","trully"],"a":1,"e":"Istisno: true – truly (e tushadi)."},{"q":"The adverb of “gentle” is ___.","o":["gentlely","gently","gentlly","gentily"],"a":1,"e":"Undosh + le: e tushib y qo'shiladi."},{"q":"The adverb of “beautiful” is ___.","o":["beautifuly","beautifully","beautifullly","beautifulily"],"a":1,"e":"Unli + l: -ly qo'shiladi (ll)."},{"q":"Our team played ___.","o":["good","well","goodly","best"],"a":1,"e":"good sifatining ravishi – well."},{"q":"He welcomed us ___.","o":["friendly","friendlily","in a friendly way","friendlyly"],"a":2,"e":"friendly sifat, ravish shakli yo'q – in a friendly way."},{"q":"Which word can be BOTH an adjective and an adverb?","o":["friendly","lonely","kindly","lovely"],"a":2,"e":"kindly ham sifat, ham ravish."},{"q":"The adverb of “whole” is ___.","o":["wholely","wholly","wholy","wholelly"],"a":1,"e":"Istisno: whole – wholly."},{"q":"She welcomed us ___ (in a friendly, kind way).","o":["warm","warmly","hotly","coldly"],"a":1,"e":"warmly – iliq, samimiy."}]},{"id":"p2-11","en":"Adverbs with the Same Form as Adjectives","uz":"Sifat bilan bir xil shakldagi ravishlar va -ly li ma'nodoshlari","emoji":"🔀","level":"B1","group":"Olmosh, sifat, ravish","summary":"fast, hard, late, right kabi so'zlar ham sifat, ham ravish bo'ladi. Ularning ba'zilariga -ly qo'shilsa butunlay boshqa ma'noli ravish hosil bo'ladi (hard – hardly, late – lately).","blocks":[{"t":"p","x":"Quyidagi so'zlarning sifat va ravish shakli <b>bir xil</b>:"},{"t":"rule","x":"back, early, enough, far, fast, ill, kindly, left, little, long, low, short, still, straight, well, wrong, deep*, direct*, hard*, high*, just*, late*, much/more/most*, near*, pretty*, right*"},{"t":"table","head":["So'z","Ravish","Sifat"],"rows":[["fast","He drives fast. – U tez haydaydi.","a fast car – tez yurar mashina"],["back","I'll come back soon. – Tez orada qaytaman.","the back door – orqa eshik"],["direct","You can dial Rome direct. – Rimga to'g'ridan-to'g'ri qo'ng'iroq qila olasiz.","a direct route – to'g'ri yo'l"],["right","Turn right here. – Shu yerda o'ngga buriling.","the right question – to'g'ri savol"],["straight","She went straight home. – U to'g'ri uyiga ketdi.","a straight line – to'g'ri chiziq"],["wrong","He led us wrong. – U bizni noto'g'ri boshladi.","the wrong answer – noto'g'ri javob"]]},{"t":"h","x":"* belgili so'zlar: -ly bilan boshqa ma'no"},{"t":"p","x":"* bilan belgilangan so'zlarga <b>-ly</b> qo'shilsa, <b>boshqa ma'noli</b> ravish hosil bo'ladi:"},{"t":"table","head":["So'z","-ly shakli","-ly shaklining ma'nosi"],"rows":[["deep (chuqur)","deeply","chuqur, qattiq (his-tuyg'u uchun)"],["direct (to'g'ri)","directly","1) darrov, tezda; 2) bevosita, to'g'ridan-to'g'ri"],["hard (qattiq; qattiq mehnat bilan)","hardly","arang, zo'rg'a, deyarli ... emas"],["high (baland)","highly","juda, juda yaxshi (very well)"],["just (adolatli; endigina)","justly","adolatli, haqqoniy"],["late (kech)","lately","so'nggi paytlarda (recently)"],["most (eng ko'p)","mostly","asosan (chiefly)"],["near (yaqin)","nearly","deyarli (almost)"],["right (to'g'ri)","rightly","adolatli, to'g'ri (justly)"],["pretty (chiroyli; ancha)","prettily","chiroyli, ozoda"],["short (qisqa)","shortly","tez orada (soon)"]]},{"t":"h","x":"Misollar"},{"t":"ex","en":"People who work deep under the ground.","uz":"Yer ostida chuqurda ishlaydigan odamlar."},{"t":"ex","en":"A deep well.","uz":"Chuqur quduq."},{"t":"ex","en":"He was deeply offended.","uz":"U qattiq xafa bo'lgan edi."},{"t":"ex","en":"He was thinking deeply.","uz":"U chuqur o'ylayotgan edi."},{"t":"ex","en":"I'll come back directly.","uz":"Men darrov qaytaman."},{"t":"ex","en":"You should ask the manager directly.","uz":"Siz to'g'ridan-to'g'ri rahbardan so'rashingiz kerak."},{"t":"ex","en":"The hard metal. / He works hard.","uz":"Qattiq metall. / U qattiq ishlaydi."},{"t":"ex","en":"We hardly managed this assignment.","uz":"Biz bu topshiriqni zo'rg'a uddaladik."},{"t":"rule","x":"Diqqat: “U qattiq ishlaydi” – <b>He works hard</b>. <s>He works hardly</s> esa “U deyarli ishlamaydi” degan teskari ma'noni beradi!"},{"t":"ex","en":"A first-class hotel was built high on the hillside.","uz":"Birinchi toifali mehmonxona tepalik yonbag'rida baland qilib qurilgan edi."},{"t":"ex","en":"Very high mountains.","uz":"Juda baland tog'lar."},{"t":"ex","en":"He is paid highly (very well).","uz":"Unga juda yaxshi maosh to'lanadi."},{"t":"p","x":"<b>Just</b> ravish bo'lsa “endigina, hozirgina”, sifat bo'lsa “adolatli, haqqoniy” ma'nosini beradi. <b>Justly</b> esa “adolatli, oqilona” ma'nosidagi ravish:"},{"t":"ex","en":"I've just finished my job.","uz":"Men ishimni endigina tugatdim."},{"t":"ex","en":"It's a just decision.","uz":"Bu haqqoniy qaror."},{"t":"ex","en":"He ruled the people justly.","uz":"U xalqni adolatli boshqardi."},{"t":"ex","en":"There's a penalty for late registration.","uz":"Kech ro'yxatdan o'tganlik uchun jarima bor."},{"t":"ex","en":"The train is running 15 minutes late.","uz":"Poyezd 15 daqiqa kechikib kelyapti."},{"t":"ex","en":"Have you seen him lately?","uz":"So'nggi paytlarda uni ko'rdingmi?"},{"t":"ex","en":"He listens to rock music mostly.","uz":"U asosan rok musiqasini tinglaydi."},{"t":"ex","en":"He lives near me.","uz":"U mening yaqinimda yashaydi."},{"t":"ex","en":"He lives in the nearest house to me.","uz":"U menga eng yaqin uyda yashaydi."},{"t":"ex","en":"I am nearly ready.","uz":"Men deyarli tayyorman."},{"t":"ex","en":"He controlled the empire rightly.","uz":"U imperiyani adolatli boshqardi."},{"t":"ex","en":"A pretty girl.","uz":"Chiroyli qiz."},{"t":"ex","en":"Her daughters are always prettily dressed.","uz":"Uning qizlari doim ozoda kiyinadi."},{"t":"p","x":"<b>Pretty</b> ravish sifatida “ancha, juda, yetarlicha” (very) ma'nosida ham keladi:"},{"t":"ex","en":"It was a pretty difficult question.","uz":"Savol ancha qiyin edi."},{"t":"ex","en":"They'll announce the results shortly (soon).","uz":"Ular natijalarni tez orada e'lon qilishadi."}],"quiz":[{"q":"He works very ___ every day (= with great effort).","o":["hardly","hard","hardy","hardely"],"a":1,"e":"hard – qattiq mehnat bilan; hardly – deyarli ... emas."},{"q":"We ___ managed this assignment; it was very difficult.","o":["hard","hardly","harder","hardest"],"a":1,"e":"hardly – zo'rg'a, arang."},{"q":"Have you seen him ___?","o":["late","lately","later","latest"],"a":1,"e":"lately – so'nggi paytlarda (recently)."},{"q":"I am ___ ready (= almost).","o":["near","nearly","nearest","nearer"],"a":1,"e":"nearly = almost."},{"q":"They'll announce the results ___ (= soon).","o":["short","shortly","shorter","shorts"],"a":1,"e":"shortly = soon."},{"q":"He is paid ___ (= very well).","o":["high","highly","higher","height"],"a":1,"e":"highly – juda yaxshi, juda ko'p."},{"q":"He was ___ offended.","o":["deep","deeply","depth","deeper"],"a":1,"e":"His-tuyg'u uchun deeply ishlatiladi."},{"q":"He drives very ___.","o":["fastly","fast","faster than","fasting"],"a":1,"e":"fast ham sifat, ham ravish; fastly degan so'z yo'q."},{"q":"He listens to rock music ___ (= chiefly).","o":["most","mostly","the most","more"],"a":1,"e":"mostly – asosan."},{"q":"It was a ___ difficult question (= quite).","o":["prettily","pretty","prettier","prettiest"],"a":1,"e":"pretty ravish sifatida “ancha” ma'nosini beradi."}]},{"id":"p2-12","en":"Degrees of Adverbs","uz":"Ravish darajalari","emoji":"🚀","level":"A2","group":"Olmosh, sifat, ravish","summary":"Ravishlar ham uch darajaga ega: positive, comparative va superlative. Ko'p bo'g'inli ravishlar more/most bilan, bir bo'g'inlilar -er/-est bilan yasaladi; early va noto'g'ri ravishlar alohida.","blocks":[{"t":"p","x":"Ravish uch darajaga bo'linadi: <b>positive</b> (oddiy), <b>comparative</b> (qiyosiy), <b>superlative</b> (orttirma)."},{"t":"h","x":"Ko'p bo'g'inli ravishlar"},{"t":"p","x":"Ravish <b>ikki yoki undan ko'p bo'g'inli</b> bo'lsa (ko'pincha -ly bilan tugaganlar), undan oldin <b>more / most</b> qo'yiladi:"},{"t":"formula","x":"quickly – more quickly – most quickly"},{"t":"ex","en":"She speaks more quickly than her sister.","uz":"U singlisidan tezroq gapiradi."},{"t":"h","x":"Bir bo'g'inli ravishlar"},{"t":"p","x":"Ravish <b>bir bo'g'inli</b> bo'lsa, unga <b>-er / -est</b> qo'shiladi:"},{"t":"formula","x":"hard – harder – hardest<br>fast – faster – fastest"},{"t":"ex","en":"He works harder than me.","uz":"U mendan ko'ra qattiqroq ishlaydi."},{"t":"rule","x":"Istisno: <b>early</b> ikki bo'g'inli bo'lsa ham -er / -est oladi: <b>early – earlier – earliest</b>."},{"t":"h","x":"Noto'g'ri ravishlar"},{"t":"p","x":"Quyidagi ravishlarning darajalari yasalganda <b>shakl almashinishi</b> yuz beradi:"},{"t":"table","head":["Positive","Comparative","Superlative"],"rows":[["well","better","best"],["little","less","least"],["much","more","most"],["far","farther / further","farthest / furthest"]]},{"t":"ex","en":"She sings better than I do.","uz":"U mendan yaxshiroq kuylaydi."},{"t":"ex","en":"I like this one most.","uz":"Menga bu eng ko'p yoqadi."}],"quiz":[{"q":"The comparative of the adverb “quickly” is ___.","o":["quicklier","more quickly","quickerly","most quickly"],"a":1,"e":"Ko'p bo'g'inli ravish: more + ravish."},{"q":"He runs ___ than his brother.","o":["fastly","more fast","faster","fastest"],"a":2,"e":"Bir bo'g'inli ravish: -er qo'shiladi."},{"q":"The comparative of “early” is ___.","o":["more early","earlier","earlyer","earliest"],"a":1,"e":"Istisno: early – earlier – earliest."},{"q":"She sings ___ than I do.","o":["weller","more well","better","best"],"a":2,"e":"well – better – best."},{"q":"The superlative of the adverb “much” is ___.","o":["muchest","most","more","mostly"],"a":1,"e":"much – more – most."},{"q":"The comparative of the adverb “little” is ___.","o":["littler","less","least","fewer"],"a":1,"e":"little – less – least."},{"q":"He works ___ of all the employees.","o":["hardest","most hardly","more hard","hardliest"],"a":0,"e":"hard – harder – hardest."},{"q":"Which group is correct?","o":["well – weller – wellest","far – farer – farest","far – further – furthest","much – mucher – muchest"],"a":2,"e":"far – farther/further – farthest/furthest."},{"q":"She arrived ___ than everyone else.","o":["more early","earlier","earlyer","most early"],"a":1,"e":"early istisno: -er oladi va y → i bo'ladi."}]},{"id":"p3-01","en":"Verbs: Ordinary and Auxiliary","uz":"Fe'l: asosiy va yordamchi fe'llar","emoji":"⚙️","level":"A1","group":"Fe'l va zamonlar","summary":"Fe'l gapda ish-harakatni bildiradi. Fe'llar asosiy (ordinary) va yordamchi (auxiliary) turlarga bo'linadi; yordamchi fe'llar zamonni ko'rsatadi hamda so'roq va inkor gaplar tuzishda ishlatiladi.","blocks":[{"t":"h","x":"Fe'l nima?"},{"t":"p","x":"<b>Verb</b> (fe'l) — gapda ish-harakatni ko'rsatuvchi so'z. Inglizcha uni <i>action word</i> (harakat so'zi) deb ham atashadi."},{"t":"ex","en":"I study at school.","uz":"Men maktabda o'qiyman."},{"t":"ex","en":"You are sitting.","uz":"Sen o'tiribsan."},{"t":"ex","en":"I am speaking.","uz":"Men gapiryapman."},{"t":"p","x":"Fe'l ikki turga bo'linadi: <b>1) auxiliary</b> (yordamchi) va <b>2) ordinary</b> (asosiy) fe'l."},{"t":"h","x":"Ordinary verb — asosiy fe'l"},{"t":"p","x":"Asosiy fe'l ish-harakatning o'zini bildiradi. Agar gapda fe'l vazifasida bir nechta so'z kelsa, ulardan asosiy ma'noni beruvchisi — gapning o'zagi — ordinary verb hisoblanadi."},{"t":"ex","en":"I speak English fluently.","uz":"Men inglizcha ravon gapiraman. (asosiy fe'l: speak)"},{"t":"ex","en":"He is spreading gossip.","uz":"U g'iybat tarqatyapti. (asosiy fe'l: spreading)"},{"t":"h","x":"Auxiliary verb — yordamchi fe'l"},{"t":"p","x":"Yordamchi fe'l asosiy fe'lning qaysi zamonga tegishli ekanini ko'rsatadi."},{"t":"ex","en":"I am going to school.","uz":"Men maktabga ketyapman. (am — yordamchi)"},{"t":"ex","en":"He has driven fast.","uz":"U tez haydadi. (has — yordamchi)"},{"t":"ex","en":"She has been learning French for 2 years.","uz":"U 2 yildan beri fransuz tilini o'rganyapti. (has been — yordamchi)"},{"t":"rule","x":"Modal so'zlar ham yordamchi fe'l hisoblanadi: <b>can, have to, ought to, should, must</b> va boshqalar."},{"t":"ex","en":"He can swim fast.","uz":"U tez suza oladi."},{"t":"ex","en":"She ought to go.","uz":"U borishi kerak."},{"t":"h","x":"So'roq va inkor gaplarda yordamchi fe'l"},{"t":"p","x":"So'roq va inkor gaplar yordamchi fe'l yordamida tuziladi."},{"t":"table","head":["Darak","Inkor","So'roq"],"rows":[["I study.","I don't study.","Do I study?"],["I did it.","I didn't do it.","Did I do it?"]]},{"t":"ex","en":"They have been living there since 1999.","uz":"Ular 1999-yildan beri u yerda yashashyapti."},{"t":"ex","en":"He didn't see me.","uz":"U meni ko'rmadi."},{"t":"h","x":"Need fe'li"},{"t":"rule","x":"Diqqat: <b>need to ...</b> shakli modal so'z hisoblanmaydi. <b>Need</b> faqat inkor gaplarda (<i>needn't</i>) kelgandagina yordamchi fe'l hisoblanadi."},{"t":"ex","en":"I don't need to learn this subject.","uz":"Menga bu fanni o'rganish shart emas. (need to — oddiy fe'l)"},{"t":"ex","en":"He needn't study.","uz":"Unga o'qish shart emas. (needn't — yordamchi fe'l)"}],"quiz":[{"q":"In the sentence \"She has been learning French\", which word is the ordinary (main) verb?","o":["has","been","learning","French"],"a":2,"e":"Asosiy ma'noni beruvchi fe'l — learning; has been — yordamchi fe'llar."},{"q":"Which word is an auxiliary verb in \"He can swim fast\"?","o":["He","can","swim","fast"],"a":1,"e":"Modal so'zlar (can, must, should...) yordamchi fe'l hisoblanadi."},{"q":"Make the sentence negative: \"I study.\"","o":["I not study.","I don't study.","I studyn't.","I am not study."],"a":1,"e":"Inkor gap yordamchi fe'l (do + not) orqali tuziladi."},{"q":"Choose the correct question form of \"I did it.\"","o":["Did I did it?","Did I do it?","Do I did it?","Done I it?"],"a":1,"e":"So'roqda did oldinga chiqadi, asosiy fe'l esa bare infinitive (do) shaklida bo'ladi."},{"q":"In which sentence is \"need\" an auxiliary verb?","o":["He needn't study.","I need to learn this subject.","She needs a pen.","They need help."],"a":0,"e":"Need faqat inkor shaklda (needn't) yordamchi fe'l bo'ladi."},{"q":"What is the main verb in \"I am going to school\"?","o":["I","am","going","school"],"a":2,"e":"am — zamonni ko'rsatuvchi yordamchi fe'l, going — asosiy fe'l."},{"q":"Which of these is a modal (auxiliary) verb?","o":["speak","ought to","study","go"],"a":1,"e":"Ought to — modal so'z, ya'ni yordamchi fe'l."},{"q":"In \"They have been living there since 1999\", which words are auxiliary verbs?","o":["have been","living","there","since"],"a":0,"e":"have been — zamonni ko'rsatadi, living — asosiy fe'l."}]},{"id":"p3-02","en":"The Verb To Be","uz":"To be fe'li","emoji":"🧩","level":"A1","group":"Fe'l va zamonlar","summary":"To be fe'lining hozirgi va o'tgan zamon shakllari (am/is/are, was/were), so'roq va inkor shakllari, qisqartmalar hamda yordamchi va asosiy fe'l sifatida ishlatilishi.","blocks":[{"t":"h","x":"Present tense — hozirgi zamon"},{"t":"table","head":["Shaxs","To be"],"rows":[["I","am"],["He / She / It","is"],["We / You / They","are"]]},{"t":"h","x":"Past tense — o'tgan zamon"},{"t":"table","head":["Shaxs","To be"],"rows":[["I / He / She / It","was"],["We / You / They","were"]]},{"t":"ex","en":"I am a student.","uz":"Men talabaman."},{"t":"ex","en":"They were driving a car.","uz":"Ular mashina haydashayotgan edi."},{"t":"h","x":"So'roq gap shakli"},{"t":"p","x":"So'roq gapda to be egadan oldinga chiqadi."},{"t":"table","head":["Zamon","So'roq shakli"],"rows":[["Present","Am I? / Is he, she, it? / Are we, you, they?"],["Past","Was I, he, she, it? / Were we, you, they?"]]},{"t":"ex","en":"Am I a student?","uz":"Men talabamanmi?"},{"t":"ex","en":"Were they driving a car?","uz":"Ular mashina haydashayotgan edimi?"},{"t":"h","x":"Inkor gap shakli"},{"t":"table","head":["Zamon","Inkor shakli"],"rows":[["Present","I am not / He, she, it is not / We, you, they are not"],["Past","I, he, she, it was not / We, you, they were not"]]},{"t":"ex","en":"I'm not a student.","uz":"Men talaba emasman."},{"t":"ex","en":"They were not driving a car.","uz":"Ular mashina haydashmayotgan edi."},{"t":"h","x":"Qisqartirish"},{"t":"rule","x":"To be ni so'roq gaplarda qisqartirish mumkin, ammo <b>qisqa javoblarda hech qachon qisqartirilmaydi</b>."},{"t":"ex","en":"What is the problem? = What's the problem?","uz":"Muammo nima?"},{"t":"ex","en":"Is he a policeman? — Yes, he is. (Not: Yes, he's.)","uz":"U politsiyachimi? — Ha."},{"t":"h","x":"To be — yordamchi fe'l sifatida"},{"t":"list","items":["Continuous zamonlarni ko'rsatish uchun: <i>He is working.</i> — U ishlayapti.","Passive (majhul) gaplarda: <i>The room was cleaned.</i> — Xona tozalandi."]},{"t":"h","x":"To be — asosiy fe'l sifatida"},{"t":"p","x":"<b>1. Biror kishi yoki narsaning mavjudligini (qayerdaligini) ko'rsatish uchun:</b>"},{"t":"ex","en":"The dog is in the corner.","uz":"It burchakda."},{"t":"ex","en":"Policemen are at the door.","uz":"Politsiyachilar eshik oldida."},{"t":"p","x":"<b>2. Biror kishi yoki narsa haqida ma'lumot berish uchun:</b>"},{"t":"ex","en":"He is a student.","uz":"U talaba."},{"t":"ex","en":"She is a beautiful girl.","uz":"U chiroyli qiz."},{"t":"ex","en":"Gold is a metal.","uz":"Oltin — metall."},{"t":"p","x":"<b>3. Jismoniy yoki ruhiy holatni ko'rsatish uchun:</b>"},{"t":"ex","en":"I'm hot.","uz":"Menga issiq."},{"t":"ex","en":"They are strong.","uz":"Ular kuchli."},{"t":"ex","en":"We are happy.","uz":"Biz baxtlimiz."},{"t":"p","x":"<b>4. Yoshni ko'rsatish uchun.</b>"},{"t":"rule","x":"Jonsiz narsalarning yoshi aytilganda <b>years old</b> albatta bo'lishi shart. Odamlar uchun <i>I'm ten.</i> yoki <i>I'm ten years old.</i> deyiladi, lekin <i>I'm ten years.</i> deyilmaydi."},{"t":"ex","en":"How old is this building? — It is four hundred years old.","uz":"Bu bino necha yoshda? — U to'rt yuz yoshda."},{"t":"ex","en":"How old are you? — I'm ten. / I'm ten years old.","uz":"Necha yoshdasan? — O'n yoshdaman."},{"t":"p","x":"<b>5. O'lcham (bo'y, balandlik, kenglik...) va og'irlikni ko'rsatish uchun:</b>"},{"t":"ex","en":"How tall are you? — I'm one metre sixty-five.","uz":"Bo'ying qancha? — Bir metru oltmish besh."},{"t":"ex","en":"How high are we now? — We are about two thousand feet up.","uz":"Hozir qancha balandlikdamiz? — Taxminan ikki ming fut."},{"t":"ex","en":"How much do you weigh? — I am sixty-five kilos.","uz":"Vazning qancha? — Oltmish besh kilo."},{"t":"rule","x":"Diqqat: <b>weight</b> — ot (og'irlik), <b>weigh</b> — fe'l (og'irlikka ega bo'lmoq, tortmoq)."},{"t":"p","x":"<b>6. Narxni ko'rsatish uchun:</b>"},{"t":"ex","en":"How much does it cost? — It is sixty pounds.","uz":"Bu qancha turadi? — Oltmish funt."}],"quiz":[{"q":"She ___ a beautiful girl.","o":["am","is","are","be"],"a":1,"e":"3-shaxs birlik (she) bilan hozirgi zamonda is ishlatiladi."},{"q":"They ___ driving a car when I saw them.","o":["was","is","were","am"],"a":2,"e":"They uchun o'tgan zamonda were ishlatiladi."},{"q":"Is he a policeman? — ___","o":["Yes, he's.","Yes, he is.","Yes, is he.","Yes, he are."],"a":1,"e":"Qisqa javoblarda to be hech qachon qisqartirilmaydi."},{"q":"How old is this building?","o":["It is four hundred years.","It is four hundred years old.","It has four hundred years.","It four hundred years old."],"a":1,"e":"Jonsiz narsalar yoshida years old albatta bo'lishi shart."},{"q":"Which answer to \"How old are you?\" is NOT correct?","o":["I'm ten.","I'm ten years old.","I'm ten years.","I am ten."],"a":2,"e":"I'm ten years deyilmaydi: yo I'm ten, yo I'm ten years old."},{"q":"How much do you ___?","o":["weight","weigh","weighs","weighting"],"a":1,"e":"Weigh — fe'l, weight — ot. Do dan keyin fe'l keladi."},{"q":"In \"The room was cleaned\", the verb to be is used to form ___.","o":["a continuous tense","a passive sentence","a question","a modal verb"],"a":1,"e":"To be yordamchi fe'l sifatida passive (majhul) gaplarda ishlatiladi."},{"q":"Choose the correct question: \"I was late.\"","o":["Was I late?","Were I late?","Did I was late?","Am I was late?"],"a":0,"e":"So'roqda was egadan oldinga chiqadi; I bilan o'tgan zamonda was."},{"q":"I ___ hot. Can you open the window?","o":["have","am","do","is"],"a":1,"e":"Jismoniy holat to be orqali ifodalanadi: I'm hot."}]},{"id":"p3-03","en":"There is / There are","uz":"There is / There are qurilmasi","emoji":"📍","level":"A1","group":"Gap va ot","summary":"There + to be qurilmasi biror narsaning mavjudligini bildiradi. To be ning shakli egaga, bir nechta ega bo'lsa birinchi kelgan egaga qarab tanlanadi.","blocks":[{"t":"h","x":"There qurilmasi qachon ishlatiladi?"},{"t":"p","x":"Agar to be fe'lining egasi <b>ot</b> bo'lsa, <b>there</b> qurilmasidan foydalanish mumkin. Bunda to be asosan «mavjud bo'lmoq, bor bo'lmoq, sodir bo'lmoq» ma'nolarida keladi."},{"t":"ex","en":"A policeman is at the door.","uz":"Eshik oldida politsiyachi turibdi."},{"t":"ex","en":"There is a policeman at the door.","uz":"Eshik oldida bir politsiyachi bor."},{"t":"ex","en":"There have been many break-ins.","uz":"Ko'plab o'g'irlik (uyga bostirib kirish) holatlari bo'ldi."},{"t":"h","x":"There ishlatib bo'lmaydigan holatlar"},{"t":"list","items":["<i>To swim is good.</i> — bu yerda there qurilmasini ishlata olmaymiz, chunki to be infinitivdan (to swim) keyin kelyapti, ega ot emas.","<i>He is swimming.</i> — bu yerda to be yordamchi fe'l vazifasida kelyapti, shuning uchun there ishlatilmaydi."]},{"t":"h","x":"Birlik yoki ko'plik?"},{"t":"p","x":"Ega birlikda bo'lsa — to be ning birlik shakli (is/was), ega ko'plikda bo'lsa — ko'plik shakli (are/were) ishlatiladi."},{"t":"ex","en":"There is a good reason.","uz":"Yaxshi sabab bor."},{"t":"ex","en":"There are some boys.","uz":"Bir necha bola bor."},{"t":"h","x":"Bir nechta ega bo'lsa"},{"t":"rule","x":"Gapda ikki yoki undan ortiq ega bo'lsa, to be ning shakli <b>birinchi kelgan egaga</b> qarab tanlanadi: birinchi ega birlikda bo'lsa — birlik shakli, ko'plikda bo'lsa — ko'plik shakli."},{"t":"ex","en":"There is a bottle of milk, some eggs and butter.","uz":"Bir shisha sut, bir nechta tuxum va sariyog' bor."},{"t":"ex","en":"There are some eggs, a bottle of milk and butter.","uz":"Bir nechta tuxum, bir shisha sut va sariyog' bor."},{"t":"ex","en":"There is water and a book.","uz":"Suv va kitob bor."},{"t":"ex","en":"There is a book and water.","uz":"Kitob va suv bor."},{"t":"rule","x":"Kitobdagi qo'shimcha izoh: agar ikkala ega ham <b>sanaladigan</b> ot bo'lsa, ko'plik shakli ham ishlatiladi: <i>There are a pen and a pencil.</i> Lekin ro'yxat uzunroq bo'lsa, odatda birinchi egaga qaraladi: <i>There is a pen, a pencil and a book.</i>"}],"quiz":[{"q":"There ___ some boys in the yard.","o":["is","are","was","be"],"a":1,"e":"Ega ko'plikda (some boys) — are."},{"q":"There ___ a good reason for it.","o":["is","are","were","be"],"a":0,"e":"Ega birlikda (a good reason) — is."},{"q":"There ___ a bottle of milk, some eggs and butter in the fridge.","o":["are","is","were","have"],"a":1,"e":"To be shakli birinchi egaga (a bottle of milk — birlik) qarab tanlanadi."},{"q":"There ___ some eggs, a bottle of milk and butter in the fridge.","o":["is","was","are","has"],"a":2,"e":"Birinchi ega (some eggs) ko'plikda, shuning uchun are."},{"q":"In which sentence can we use the \"there\" structure instead?","o":["A policeman is at the door.","He is swimming.","To swim is good.","He is tired."],"a":0,"e":"There qurilmasi ega ot bo'lganda ishlatiladi: There is a policeman at the door."},{"q":"Why can't we say \"There is swimming he\" for \"He is swimming\"?","o":["Because the subject is plural","Because to be is an auxiliary verb here","Because swimming is a noun","Because it is past tense"],"a":1,"e":"To be yordamchi fe'l bo'lib kelsa, there qurilmasi ishlatilmaydi."},{"q":"There ___ many break-ins in this street recently.","o":["has been","have been","is","was being"],"a":1,"e":"Break-ins — ko'plik, shuning uchun have been."},{"q":"In the there structure, to be mainly means ___.","o":["to have","to exist / to happen","to go","to become"],"a":1,"e":"There + to be «mavjud bo'lmoq, sodir bo'lmoq» ma'nosini beradi."}]},{"id":"p3-04","en":"The Pronoun It; It vs There","uz":"It olmoshi; It va There farqi","emoji":"🔍","level":"A2","group":"Olmosh, sifat, ravish","summary":"It olmoshi jonsiz narsalar, jinsi noma'lum hayvon va chaqaloqlar, sana, ob-havo, vaqt, masofa va ba'zi holatlarda odamlar uchun ishlatiladi. Shuningdek, It va There farqi.","blocks":[{"t":"h","x":"It qachon ishlatiladi?"},{"t":"p","x":"<b>1. Birlikdagi jonsiz narsalar uchun:</b>"},{"t":"ex","en":"Where is my bag? — I left it at home.","uz":"Sumkam qayerda? — Uni uyda qoldirdim."},{"t":"p","x":"<b>2. Jinsi biz uchun noma'lum hayvonlar yoki chaqaloqlar uchun:</b>"},{"t":"ex","en":"Look at that bird. It always comes to my window.","uz":"Anavi qushga qara. U doim derazamga keladi."},{"t":"ex","en":"Ann's new baby is very small. It's only 2 kilos.","uz":"Annaning chaqalog'i juda kichkina. U atigi 2 kilo."},{"t":"p","x":"<b>3. Sanani (date) ko'rsatish uchun:</b>"},{"t":"ex","en":"What's the date? — It's the 3rd of May.","uz":"Bugun nechanchi sana? — 3-may."},{"t":"p","x":"<b>4. Ob-havo va haroratni ko'rsatish uchun:</b>"},{"t":"ex","en":"It's raining / snowing.","uz":"Yomg'ir / qor yog'yapti."},{"t":"ex","en":"It's windy / rainy.","uz":"Shamol / yomg'irli havo."},{"t":"ex","en":"It's hot / warm / cold.","uz":"Issiq / iliq / sovuq."},{"t":"p","x":"<b>5. Vaqt iboralari bilan:</b>"},{"t":"ex","en":"What time is it? — It's 6 p.m.","uz":"Soat necha? — Kechki 6."},{"t":"ex","en":"It's late. / It's time to go home.","uz":"Kech bo'ldi. / Uyga ketish vaqti bo'ldi."},{"t":"p","x":"<b>6. Masofani ko'rsatish uchun:</b>"},{"t":"ex","en":"How far is it to York? — It is 400 kilometres.","uz":"Yorkkacha qancha masofa? — 400 kilometr."},{"t":"p","x":"<b>7. Odamlar uchun quyidagi holatlarda:</b>"},{"t":"list","items":["a) Suhbatdoshlar bir-birini ko'ra olmayotganda: <i>Who is it? — It's me, Bill.</i> (Kim u? — Menman, Bill.)","b) Shaxsi hali biz uchun noma'lum kishilarni ko'rsatishda: <i>Is that Tom over there? — No, it's Peter.</i> (Anavi Tommi? — Yo'q, bu Piter.)"]},{"t":"h","x":"It is + adjective + to ..."},{"t":"formula","x":"It is + adjective + to + verb"},{"t":"ex","en":"It's easy to criticize. = To criticize is easy.","uz":"Tanqid qilish oson."},{"t":"h","x":"It va There farqi"},{"t":"rule","x":"<b>1.</b> It biror birlikdagi ot o'rnida keladi (otning o'rnini bosadi); <b>there</b> esa hech qachon ot o'rnida ishlatilmaydi."},{"t":"ex","en":"There is a book on the table. It's mine.","uz":"Stol ustida kitob bor. U meniki."},{"t":"rule","x":"<b>2.</b> It dan keyin sifat yakka o'zi kelishi mumkin; there dan keyin sifat yakka kela olmaydi — undan keyin ot yoki olmosh keladi."},{"t":"ex","en":"It's windy.","uz":"Shamol esyapti."},{"t":"ex","en":"There was a strong wind yesterday.","uz":"Kecha kuchli shamol bo'ldi."}],"quiz":[{"q":"___ is raining outside.","o":["There","It","This","He"],"a":1,"e":"Ob-havo it bilan ifodalanadi."},{"q":"What's the date? — ___ the 3rd of May.","o":["There's","It's","This is","Today's it"],"a":1,"e":"Sana it bilan ko'rsatiladi."},{"q":"How far is it to York? — ___ 400 kilometres.","o":["There is","It is","They are","He is"],"a":1,"e":"Masofa it bilan ifodalanadi."},{"q":"(knocking on the door) Who is it? — ___ me, Bill.","o":["I'm","It's","There's","He's"],"a":1,"e":"Suhbatdoshlar bir-birini ko'ra olmaganda odam uchun it ishlatiladi."},{"q":"Look at that bird. ___ always comes to my window.","o":["He","She","It","There"],"a":2,"e":"Jinsi noma'lum hayvonlar uchun it ishlatiladi."},{"q":"___ was a strong wind yesterday.","o":["It","There","This","Its"],"a":1,"e":"Keyin ot (a strong wind) kelyapti va mavjudlik bildirilyapti — there."},{"q":"___ is very windy today.","o":["There","It","This is","Here"],"a":1,"e":"Sifat yakka kelsa, faqat it ishlatiladi: It's windy."},{"q":"There is a book on the table. ___ mine.","o":["There's","It's","Its","There are"],"a":1,"e":"It otning (a book) o'rnini bosadi; there ot o'rnida kelmaydi."},{"q":"___ easy to criticize.","o":["It's","There's","Its","That"],"a":0,"e":"It is + adjective + to ... qurilmasi."}]},{"id":"p3-05","en":"Finite and Non-finite Verbs; Infinitive, Gerund, Past Participle","uz":"Shaxsli va shaxssiz fe'llar; infinitiv, gerund va o'tgan zamon sifatdoshi","emoji":"🔤","level":"A2","group":"Infinitiv, gerund va ergash gaplar","summary":"Fe'lning finite (shaxsli) va non-finite (shaxssiz) turlari, infinitiv, gerund va past participle shakllari hamda -ing qo'shishning imlo qoidalari.","blocks":[{"t":"h","x":"Finite va non-finite verb"},{"t":"p","x":"<b>Finite verb</b> — zamonda qatnashadi va gapning kesimi (predicate) vazifasida keladi."},{"t":"ex","en":"I go to school.","uz":"Men maktabga boraman."},{"t":"ex","en":"He often watches TV.","uz":"U tez-tez televizor ko'radi."},{"t":"p","x":"<b>Non-finite verb</b> — zamonda umuman qatnashmaydi va kesim vazifasida kelmaydi."},{"t":"ex","en":"I like swimming.","uz":"Men suzishni yaxshi ko'raman. (swimming — non-finite)"},{"t":"ex","en":"To cry isn't useful.","uz":"Yig'lashdan foyda yo'q. (to cry — non-finite)"},{"t":"h","x":"Fe'lning uch shakli"},{"t":"list","items":["1. Infinitive","2. Gerund (Present participle)","3. Past participle"]},{"t":"h","x":"Infinitive"},{"t":"p","x":"Infinitiv ikki turga bo'linadi:"},{"t":"list","items":["<b>full infinitive</b>: to run, to go, to speak ...","<b>bare infinitive</b> (to siz): run, go, speak ..."]},{"t":"ex","en":"I want to run.","uz":"Men yugurmoqchiman. (full infinitive)"},{"t":"ex","en":"We let him go.","uz":"Biz uni qo'yib yubordik. (bare infinitive)"},{"t":"h","x":"Gerund yasalishi"},{"t":"formula","x":"Gerund = bare infinitive + ing"},{"t":"p","x":"eating, waiting, going, speaking ..."},{"t":"table","head":["Qoida","Misol"],"rows":[["1. Fe'l <b>-e</b> bilan tugasa, e tushib, -ing qo'shiladi","like – liking, hate – hating"],["Istisno: e tushmaydi yoki o'zgaradi","die – dying, age – ageing, singe – singeing"],["2. Fe'l <b>-ee</b> bilan tugasa, to'g'ridan-to'g'ri -ing qo'shiladi","see – seeing, agree – agreeing"],["3. Bir bo'g'inli, unli + undosh bilan tugasa, oxirgi undosh ikkilanadi","hit – hitting, run – running"],["4. <b>-l</b> bilan tugasa, l ikkilanadi (British English)","travel – travelling"],["5. Ko'p bo'g'inli, unli + undosh bilan tugasa va urg'u oxirgi bo'g'inga tushsa, undosh ikkilanadi","admit – admitting, begin – beginning"],["Urg'u oxirgi bo'g'inga tushmasa, ikkilanmaydi","enter – entering"],["6. <b>-y</b> bilan tugasa, to'g'ridan-to'g'ri -ing qo'shiladi","study – studying, enjoy – enjoying"]]},{"t":"rule","x":"Istisnolar: <b>die – dying</b> (ie → y), <b>age – ageing</b>, <b>singe – singeing</b> (singing «kuylash» bilan adashmaslik uchun e saqlanadi)."},{"t":"p","x":"Gerund gapda <b>ot</b> yoki <b>sifat</b> vazifasida kelishi mumkin:"},{"t":"ex","en":"Walking is useful.","uz":"Piyoda yurish foydali. (ot vazifasida)"},{"t":"ex","en":"This is a tiring job.","uz":"Bu charchatadigan ish. (sifat vazifasida)"},{"t":"h","x":"Past participle"},{"t":"p","x":"Past participle — fe'lning 3-shakli bo'lib, gapda sifat vazifasida kelishi mumkin."},{"t":"ex","en":"a broken cup","uz":"singan piyola"},{"t":"ex","en":"a torn book","uz":"yirtilgan kitob"}],"quiz":[{"q":"Choose the correct -ing form of \"die\".","o":["dieing","diing","dying","dyeing"],"a":2,"e":"Istisno: die – dying."},{"q":"Choose the correct -ing form of \"begin\".","o":["begining","beginning","beginnig","begainning"],"a":1,"e":"Urg'u oxirgi bo'g'inga tushadi va unli+undosh bilan tugaydi — n ikkilanadi."},{"q":"Choose the correct -ing form of \"enter\".","o":["enterring","entring","entering","enteringg"],"a":2,"e":"Urg'u oxirgi bo'g'inga tushmagani uchun r ikkilanmaydi."},{"q":"Choose the correct -ing form of \"see\".","o":["seing","seeing","seeeing","sing"],"a":1,"e":"-ee bilan tugagan fe'lga to'g'ridan-to'g'ri -ing qo'shiladi."},{"q":"Choose the correct -ing form of \"run\".","o":["runing","running","runeing","runnning"],"a":1,"e":"Bir bo'g'inli, unli+undosh bilan tugagan fe'lda undosh ikkilanadi."},{"q":"Choose the correct -ing form of \"study\".","o":["studing","studiing","studying","studieing"],"a":2,"e":"-y bilan tugagan fe'lga to'g'ridan-to'g'ri -ing qo'shiladi."},{"q":"Choose the correct -ing form of \"like\".","o":["likeing","liking","likking","likeng"],"a":1,"e":"-e bilan tugagan fe'lda e tushib qoladi."},{"q":"We let him ___.","o":["to go","go","going","gone"],"a":1,"e":"Let dan keyin bare infinitive (to siz) keladi."},{"q":"In \"I like swimming\", which verb is finite?","o":["I","like","swimming","both like and swimming"],"a":1,"e":"Like — zamonda qatnashuvchi kesim; swimming — non-finite."},{"q":"In \"a broken cup\", the word \"broken\" is a ___.","o":["gerund","full infinitive","past participle used as an adjective","bare infinitive"],"a":2,"e":"Past participle (3-shakl) sifat vazifasida keladi."}]},{"id":"p3-06","en":"Present Continuous Tense","uz":"Hozirgi davomiy zamon","emoji":"⏳","level":"A1","group":"Fe'l va zamonlar","summary":"Present Continuous tuzilishi va ishlatilishi: hozir va hozirgi davr atrofidagi harakatlar, rejalashtirilgan kelajak, asta-sekin o'zgarishlar, being + sifat va always bilan norozilik.","blocks":[{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Darak: Subject + am/is/are + V-ing + C + M"},{"t":"formula","x":"Inkor: Subject + am/is/are + not + V-ing + C + M"},{"t":"formula","x":"So'roq: Am/Is/Are + subject + V-ing + C + M?"},{"t":"p","x":"<i>C</i> — complement (to'ldiruvchi), <i>M</i> — modifier (hol: vaqt, joy, tarz)."},{"t":"ex","en":"I am speaking.","uz":"Men gapiryapman."},{"t":"ex","en":"She isn't singing.","uz":"U qo'shiq aytmayapti."},{"t":"ex","en":"Are they waiting for someone?","uz":"Ular kimnidir kutishyaptimi?"},{"t":"h","x":"Ishlatilishi"},{"t":"p","x":"<b>1. Hozir, ya'ni gapirilayotgan vaqtda sodir bo'layotgan harakat uchun:</b>"},{"t":"ex","en":"You're sitting.","uz":"Sen o'tiribsan."},{"t":"ex","en":"I'm not running.","uz":"Men yugurmayapman."},{"t":"p","x":"<b>2. Gapirilayotgan vaqt atrofida (shu kunlarda) sodir bo'layotgan harakat uchun.</b> Bunda harakat aynan gapirilayotgan paytda bo'layotgan bo'lishi shart emas."},{"t":"ex","en":"Tom and Ann are talking in a café. Tom says: \"I'm reading a book by Stephen King. I'll give it to you when I finish it.\"","uz":"Tom va Anna kafeda gaplashishyapti. Tom aytyapti: «Hozir Stiven Kingning kitobini o'qiyapman. Tugatgach, senga beraman.»"},{"t":"ex","en":"When I saw Jack, he said: \"I'm building my own house.\"","uz":"Jekni ko'rganimda, u: «O'z uyimni qurayapman», dedi."},{"t":"p","x":"<b>3. Ikki continuous fe'l and bilan bog'langanda</b> ikkinchi yordamchi fe'l tushirib qoldirilishi mumkin:"},{"t":"ex","en":"I'm teaching French and learning English.","uz":"Men fransuz tilidan dars beryapman va ingliz tilini o'rganyapman."},{"t":"ex","en":"She is knitting and listening to music.","uz":"U to'qiyapti va musiqa tinglayapti."},{"t":"p","x":"<b>4. Aniq rejalashtirilgan va yaqinda bo'ladigan ishlar uchun:</b>"},{"t":"ex","en":"She is going to the dentist on Friday.","uz":"U juma kuni tish shifokoriga boradi."},{"t":"ex","en":"They are going to the concert tomorrow.","uz":"Ular ertaga konsertga borishadi."},{"t":"ex","en":"What are you doing tomorrow afternoon?","uz":"Ertaga tushdan keyin nima qilasan?"},{"t":"rule","x":"Bu holatda vaqt ko'rsatkichi (modifier of time) albatta bo'lishi shart, aks holda gap hozirgi zamonmi yoki kelasi zamonmi — bilish qiyin: <i>I'm playing tennis.</i> (hozir) — <i>I'm playing tennis tomorrow.</i> (ertaga)."},{"t":"p","x":"<b>5. Quyidagi fe'llar continuousda ishlatilmaydi:</b> want, like, love, hate, need, prefer, depend, know, mean, understand, believe, remember, forget."},{"t":"ex","en":"I remember her name. (Not: I'm remembering.)","uz":"Uning ismini eslayman."},{"t":"ex","en":"He wants to buy that. (Not: He's wanting.)","uz":"U buni sotib olmoqchi."},{"t":"p","x":"<b>6. Asta-sekin, bosqichma-bosqich bo'layotgan o'zgarishlar uchun:</b>"},{"t":"ex","en":"Our country's economy is improving.","uz":"Mamlakatimiz iqtisodiyoti yaxshilanyapti."},{"t":"ex","en":"She is getting fat.","uz":"U semiryapti."},{"t":"ex","en":"The population is increasing.","uz":"Aholi soni ortyapti."},{"t":"p","x":"<b>7. Ba'zi sifatlar bilan to be ning continuous shakli (being)</b> ishlatiladi — bunda ega aynan gapirilayotgan vaqtda shu sifatni o'zida namoyon qiladi (o'zini shunday tutyapti)."},{"t":"table","head":["Oddiy","Being + sifat"],"rows":[["Tom is foolish. — Tom ahmoq (tabiatan).","Tom is being foolish. — Tom o'zini ahmoqona tutyapti."],["The children are quiet. — Bolalar yuvosh.","The children are being quiet. — Bolalar (hozir) o'zlarini tinch tutishyapti."]]},{"t":"p","x":"Being faqat quyidagi kabi sifatlar bilan ishlatiladi:"},{"t":"table","head":["Ijobiy","Salbiy"],"rows":[["quiet","noisy"],["good","bad"],["wise","foolish"],["cautious","rash"],["clever","stupid"],["economical","extravagant"],["generous","mean"],["helpful","unhelpful"],["optimistic","pessimistic"],["unselfish","selfish"]]},{"t":"p","x":"Shuningdek: annoying, difficult, formal, funny, irritating, mysterious, polite."},{"t":"h","x":"Always bilan norozilik"},{"t":"rule","x":"Eslatma: so'zlovchining norozligini ifodalash uchun Present Continuous <b>always</b> bilan ishlatiladi."},{"t":"ex","en":"He is always wasting his time.","uz":"U qachon qarasa vaqtini behuda sarflagani sarflagan."}],"quiz":[{"q":"Look! The children ___ in the garden.","o":["play","are playing","plays","is playing"],"a":1,"e":"Hozir sodir bo'layotgan harakat — Present Continuous; children — ko'plik."},{"q":"I ___ her name.","o":["am remembering","remember","remembering","is remember"],"a":1,"e":"Remember continuousda ishlatilmaydigan fe'llar qatoriga kiradi."},{"q":"He ___ to buy that car.","o":["is wanting","wants","want","wanting"],"a":1,"e":"Want continuousda ishlatilmaydi."},{"q":"Tom is usually sensible, but today he ___ foolish.","o":["is","is being","being","are being"],"a":1,"e":"Hozirgi xatti-harakat being + sifat bilan ifodalanadi."},{"q":"Which sentence clearly refers to the future?","o":["I'm playing tennis.","I'm playing tennis tomorrow.","I play tennis.","I'm play tennis."],"a":1,"e":"Kelajak rejasi uchun vaqt ko'rsatkichi (tomorrow) shart."},{"q":"I'm teaching French and ___ English.","o":["learn","learning","am learn","learns"],"a":1,"e":"And bilan bog'langanda ikkinchi yordamchi fe'l tushiriladi."},{"q":"The population ___ every year.","o":["increasing","is increasing","are increasing","increase"],"a":1,"e":"Bosqichma-bosqich o'zgarish — Present Continuous; population — birlik."},{"q":"He ___ late! It's so annoying.","o":["always comes","is always coming","always is come","is always come"],"a":1,"e":"Norozilik always + Present Continuous bilan ifodalanadi."},{"q":"Which adjective can be used with \"being\" (e.g. \"He is being ___\")?","o":["tall","old","polite","blue"],"a":2,"e":"Being xatti-harakatni bildiruvchi sifatlar (polite, rude, quiet...) bilan ishlatiladi."},{"q":"Choose the correct question.","o":["They are waiting for someone?","Are they waiting for someone?","Do they waiting for someone?","Are they wait for someone?"],"a":1,"e":"So'roq: Am/Is/Are + subject + V-ing."}]},{"id":"p3-07","en":"Present Simple Tense","uz":"Hozirgi oddiy zamon","emoji":"🔁","level":"A1","group":"Fe'l va zamonlar","summary":"Present Simple tuzilishi, 3-shaxs birlikda -s/-es/-ies qo'shish qoidalari, qisqa javoblar va ishlatilishi; shuningdek kitob va e'lonlardan iqtibos keltirishda «say» fe'li.","blocks":[{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Darak: Subject + V (bare infinitive) + complement + modifier"},{"t":"formula","x":"Inkor: Subject + do/does + not + V + complement + modifier"},{"t":"formula","x":"So'roq: Do/Does + subject + V + complement + modifier?"},{"t":"ex","en":"I go to school.","uz":"Men maktabga boraman."},{"t":"ex","en":"I do not go to school.","uz":"Men maktabga bormayman."},{"t":"ex","en":"Do I go to school?","uz":"Men maktabga boramanmi?"},{"t":"h","x":"Qisqa javoblar"},{"t":"formula","x":"Yes, subject + do/does. — No, subject + do/does + not."},{"t":"ex","en":"Does he work here? — Yes, he does. / No, he doesn't.","uz":"U shu yerda ishlaydimi? — Ha. / Yo'q."},{"t":"h","x":"3-shaxs birlik (he, she, it)"},{"t":"p","x":"Ega 3-shaxs birlikda bo'lsa, darak gapda fe'lga <b>-s</b> qo'shiladi. So'roq va inkor gaplarda esa <b>does</b> ishlatiladi va fe'l o'zgarmaydi."},{"t":"ex","en":"We do not go. — She does not go.","uz":"Biz bormaymiz. — U bormaydi."},{"t":"ex","en":"They talk. — He talks.","uz":"Ular gaplashadi. — U gaplashadi."},{"t":"table","head":["Fe'l oxiri","Qo'shimcha","Misol"],"rows":[["ko'pchilik fe'llar","-s","talk – talks"],["-ss, -ch, -sh, -o, -x","-es","go – goes, box – boxes, watch – watches"],["undosh + y","y → -ies","study – studies, carry – carries"],["unli + y","-s","buy – buys, stay – stays"],["have","has","I have a dog. – He has a dog."]]},{"t":"rule","x":"Inkor va so'roqda has emas, have ishlatiladi: <i>He does not have a dog.</i>"},{"t":"p","x":"<b>Do</b> va <b>have</b> ham yordamchi, ham asosiy fe'l bo'la oladi:"},{"t":"ex","en":"I do my homework. — I do not do my homework.","uz":"Men uy vazifamni qilaman. — Qilmayman. (ikkinchi do — asosiy fe'l)"},{"t":"ex","en":"He has a dog. — He does not have a dog.","uz":"Uning iti bor. — Uning iti yo'q."},{"t":"p","x":"Qisqartmalar: <b>do not = don't</b>, <b>does not = doesn't</b>."},{"t":"h","x":"Ishlatilishi"},{"t":"p","x":"<b>1. Odat tusiga kirgan harakatlar uchun:</b>"},{"t":"ex","en":"We get bad marks every lesson.","uz":"Biz har darsda yomon baho olamiz."},{"t":"ex","en":"John smokes.","uz":"Jon chekadi."},{"t":"rule","x":"Present Simple hech qachon harakat aynan gapirilayotgan vaqtda bo'layotgan-bo'lmayotganini ko'rsatmaydi. Buni aniqlashtirish uchun Present Continuous ishlatiladi: <i>My dog usually barks a lot, but he is not barking now.</i>"},{"t":"p","x":"<b>2. Umuman to'g'ri bo'lgan (true in general) narsalar uchun:</b>"},{"t":"ex","en":"She is clever. She speaks four languages.","uz":"U aqlli. U to'rt tilda gapiradi."},{"t":"ex","en":"Cats drink milk.","uz":"Mushuklar sut ichadi."},{"t":"ex","en":"Teachers teach new subjects.","uz":"O'qituvchilar yangi fanlarni o'rgatadi."},{"t":"p","x":"<b>3. Takrorlanish ravishlari va ba'zi ravish iboralari bilan:</b>"},{"t":"list","items":["Adverbs of frequency: always, never, occasionally, often, sometimes, rarely, usually, ever, seldom ...","Adverb phrases: on Mondays, in winter, every week, twice a year ..."]},{"t":"p","x":"<b>4. Gapda hech qanday harakat bo'lmasa va ma'no hozirgi zamon bo'lsa,</b> present to be (am/is/are) ishlatiladi:"},{"t":"ex","en":"He is a student. / There is an apple. / Tom is foolish.","uz":"U talaba. / Olma bor. / Tom ahmoq."},{"t":"p","x":"<b>5. Continuousda ishlatilmaydigan fe'llar bilan Present Continuous o'rnida:</b>"},{"t":"ex","en":"I believe him.","uz":"Men unga ishonyapman."},{"t":"ex","en":"Tom likes this new song.","uz":"Tomga bu yangi qo'shiq yoqyapti."},{"t":"p","x":"<b>6. Jadval, dastur asosida belgilangan kelajakdagi harakatlar uchun.</b> Shaxsiy rejalar haqida gapirilganda esa Present Continuous ishlatiladi."},{"t":"ex","en":"The train leaves at six.","uz":"Poyezd soat oltida jo'naydi. (jadval)"},{"t":"ex","en":"The concert starts at seven p.m. I am going to it.","uz":"Konsert kechki yettida boshlanadi. Men unga boraman. (shaxsiy reja)"},{"t":"ex","en":"I am watching \"Sheryurak\" tomorrow evening. It starts at nine p.m.","uz":"Ertaga kechqurun «Sheryurak»ni ko'raman. U kechki to'qqizda boshlanadi."},{"t":"h","x":"Say fe'li (iqtibos keltirish)"},{"t":"p","x":"Kitob, e'lon, gazeta va hokazolarning umumiy mazmunini aytmoqchi yoki ulardan iqtibos keltirmoqchi bo'lsak, <b>say</b> fe'lining hozirgi zamon shaklidan foydalanamiz:"},{"t":"ex","en":"What does the book say?","uz":"Kitobda nima deyilgan?"},{"t":"ex","en":"The notice says, \"Don't touch!\"","uz":"E'londa «Tegmang!» deb yozilgan."},{"t":"ex","en":"Shakespeare says, \"Neither a borrower nor a lender be.\"","uz":"Shekspir aytadi: «Na qarz ol, na qarz ber.»"},{"t":"p","x":"Bunda say o'rnida ma'noni aniqroq beradigan boshqa fe'llarni ham ishlatish mumkin:"},{"t":"ex","en":"The notice warns us not to touch.","uz":"E'lon bizni tegmaslikka ogohlantiradi."},{"t":"ex","en":"Shakespeare advises us to be neither a borrower nor a lender.","uz":"Shekspir na qarz oluvchi, na qarz beruvchi bo'lishni maslahat beradi."}],"quiz":[{"q":"He ___ to school every day.","o":["go","goes","gos","going"],"a":1,"e":"-o bilan tugagan fe'lga 3-shaxs birlikda -es qo'shiladi."},{"q":"She ___ heavy bags every morning.","o":["carrys","carries","carry","carryes"],"a":1,"e":"Undosh + y → -ies."},{"q":"He always ___ at this hotel.","o":["staies","stays","stay","stayes"],"a":1,"e":"Unli + y bo'lsa, faqat -s qo'shiladi."},{"q":"She ___ not have a dog.","o":["do","does","is","has"],"a":1,"e":"3-shaxs birlik inkorida does + not + bare infinitive."},{"q":"___ he speak English?","o":["Do","Does","Is","Has"],"a":1,"e":"3-shaxs birlik so'roqda does ishlatiladi."},{"q":"My dog usually barks a lot, but he ___ now.","o":["doesn't bark","isn't barking","not barks","don't bark"],"a":1,"e":"Hozir bo'layotgan/bo'lmayotgan harakat Present Continuous bilan."},{"q":"The train ___ at six tomorrow morning.","o":["leave","leaves","is leave","leaving"],"a":1,"e":"Jadval bo'yicha kelajak — Present Simple."},{"q":"Do you like tea? — Yes, ___.","o":["I like","I do","I am","I does"],"a":1,"e":"Qisqa javob: Yes, subject + do/does."},{"q":"What does the notice ___?","o":["tell","says","say","speaks"],"a":2,"e":"Yozuvdan iqtibos keltirishda say ishlatiladi; does dan keyin fe'l o'zgarmaydi."},{"q":"I ___ him. He is telling the truth.","o":["am believing","believe","believes","believing"],"a":1,"e":"Believe continuousda ishlatilmaydi, Present Simple ishlatiladi."}]},{"id":"p3-08","en":"Past Simple Tense; Regular and Irregular Verbs","uz":"O'tgan oddiy zamon; to'g'ri va noto'g'ri fe'llar","emoji":"⏮️","level":"A1","group":"Fe'l va zamonlar","summary":"To'g'ri fe'llarga -ed qo'shishning imlo qoidalari, noto'g'ri fe'llar, Past Simple tuzilishi va olti xil ishlatilishi.","blocks":[{"t":"h","x":"Regular va irregular fe'llar"},{"t":"p","x":"Fe'llar zamon shakliga ko'ra ikki xil bo'ladi: <b>regular</b> (to'g'ri) va <b>irregular</b> (noto'g'ri)."},{"t":"p","x":"<b>Regular verb</b> — past simple va past participle shakli <b>-ed</b> bilan tugaydigan fe'l."},{"t":"table","head":["Present simple","Past simple","Past participle"],"rows":[["work","worked","worked"]]},{"t":"h","x":"-ed qo'shish qoidalari"},{"t":"table","head":["Qoida","Misol"],"rows":[["Fe'l -e bilan tugasa, faqat -d qo'shiladi","love – loved – loved"],["Undosh + y bo'lsa, y tushib, -ied qo'shiladi","carry – carried – carried (ko'tarmoq)"],["Unli + y bo'lsa, to'g'ridan-to'g'ri -ed","obey – obeyed – obeyed"],["Bir bo'g'inli, unli + undosh bilan tugasa, undosh ikkilanadi","stop – stopped – stopped"],["Ko'p bo'g'inli, unli + undosh bilan tugasa va urg'u oxirgi bo'g'inga tushsa, undosh ikkilanadi","admit – admitted – admitted"],["Unli + l bilan tugasa, l ikkilanadi (British English)","travel – travelled – travelled"]]},{"t":"h","x":"Irregular verbs"},{"t":"p","x":"<b>Irregular verb</b> — past simple va past participle shakli -ed bilan tugamaydigan fe'l; ularda shakl o'zgaradi (yoki umuman o'zgarmaydi)."},{"t":"table","head":["Present simple","Past simple","Past participle"],"rows":[["go","went","gone"],["buy","bought","bought"],["cut","cut","cut"],["read","read","read"]]},{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Darak: S + V (past simple) + C + M"},{"t":"formula","x":"Inkor: S + did + not + bare infinitive + C + M"},{"t":"formula","x":"So'roq: Did + S + bare infinitive + C + M?"},{"t":"ex","en":"I watched a movie.","uz":"Men film ko'rdim."},{"t":"ex","en":"They didn't play chess.","uz":"Ular shaxmat o'ynashmadi."},{"t":"ex","en":"Did he arrive on time?","uz":"U o'z vaqtida keldimi?"},{"t":"h","x":"Ishlatilishi"},{"t":"p","x":"Past Simple o'tgan zamonda aniq bir vaqtda tugagan harakatlarni ko'rsatadi. Bu harakatlarning hozirgi va kelasi zamonga hech qanday aloqasi yo'q. Shuning uchun Past Simple:"},{"t":"p","x":"<b>1. O'tgan zamonda aniq vaqt bilan ko'rsatilgan harakatlar uchun:</b>"},{"t":"ex","en":"I met him yesterday.","uz":"Men uni kecha uchratdim."},{"t":"ex","en":"Tom died in 1865.","uz":"Tom 1865-yilda vafot etgan."},{"t":"p","x":"<b>2. Harakat qachon bo'lganini so'rash uchun:</b>"},{"t":"ex","en":"When did you meet him?","uz":"Uni qachon uchratding?"},{"t":"p","x":"<b>3. Vaqt ko'rsatilmasa ham, o'tgan zamonda bo'lgani aniq (kunday ravshan) bo'lgan harakatlar uchun:</b>"},{"t":"ex","en":"I bought this car in Tashkent.","uz":"Bu mashinani Toshkentda sotib oldim."},{"t":"ex","en":"The train was late.","uz":"Poyezd kechikdi."},{"t":"p","x":"<b>4. O'tgan zamonda bo'lib, qaytarilmaydigan harakatlar uchun:</b>"},{"t":"ex","en":"Shakespeare wrote Hamlet.","uz":"Shekspir «Gamlet»ni yozgan."},{"t":"ex","en":"Al-Khwarizmi founded algebra.","uz":"Al-Xorazmiy algebra faniga asos solgan."},{"t":"p","x":"<b>5. O'tgan zamondagi odatiy harakatlar uchun:</b>"},{"t":"ex","en":"They did not drink wine.","uz":"Ular vino ichishmas edi."},{"t":"ex","en":"He always took an umbrella with him.","uz":"U doim o'zi bilan soyabon olib yurar edi."},{"t":"ex","en":"He smoked.","uz":"U chekar edi."},{"t":"p","x":"<b>6. Harakat bo'lmay, faqat ma'lumot beruvchi o'tgan zamon gaplarida</b> was/were ishlatiladi:"},{"t":"ex","en":"He was a student.","uz":"U talaba edi."},{"t":"ex","en":"There were some police officers.","uz":"Bir nechta politsiyachi bor edi."}],"quiz":[{"q":"Past simple of \"carry\":","o":["carryed","carried","caried","carryd"],"a":1,"e":"Undosh + y → -ied."},{"q":"Past simple of \"obey\":","o":["obeied","obeyd","obeyed","obied"],"a":2,"e":"Unli + y bo'lsa, to'g'ridan-to'g'ri -ed qo'shiladi."},{"q":"Past simple of \"stop\":","o":["stoped","stopped","stopt","stopted"],"a":1,"e":"Bir bo'g'inli, unli+undosh — undosh ikkilanadi."},{"q":"Past simple of \"admit\":","o":["admited","admitted","admitd","admitet"],"a":1,"e":"Urg'u oxirgi bo'g'inga tushadi — t ikkilanadi."},{"q":"Past simple of \"love\":","o":["loveed","loved","lovd","lovied"],"a":1,"e":"-e bilan tugagan fe'lga faqat -d qo'shiladi."},{"q":"The three forms of \"go\" are:","o":["go – goed – goed","go – went – gone","go – gone – went","go – went – went"],"a":1,"e":"Go — noto'g'ri fe'l: go – went – gone."},{"q":"They ___ chess yesterday.","o":["didn't played","didn't play","not played","don't played"],"a":1,"e":"Inkor: did + not + bare infinitive."},{"q":"___ he arrive on time?","o":["Does","Did","Was","Do"],"a":1,"e":"O'tgan zamon so'rog'i: Did + S + bare infinitive."},{"q":"He ___ a student ten years ago.","o":["is","were","was","did"],"a":2,"e":"Harakatsiz, ma'lumot beruvchi o'tgan zamon gapi — was/were; he bilan was."},{"q":"Shakespeare ___ Hamlet.","o":["has written","writes","wrote","was writing"],"a":2,"e":"O'tgan zamonda bo'lib, qaytarilmaydigan harakat — Past Simple."}]},{"id":"p3-09","en":"Past Continuous Tense","uz":"O'tgan davomiy zamon","emoji":"🌅","level":"A2","group":"Fe'l va zamonlar","summary":"Past Continuous tuzilishi va ishlatilishi: o'tgan zamonda biror vaqt atrofida davom etgan harakatlar va asta-sekin o'zgarishlar.","blocks":[{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Darak: S + was/were + V-ing + C + M"},{"t":"formula","x":"Inkor: S + was/were + not + V-ing + C + M"},{"t":"formula","x":"So'roq: Was/Were + S + V-ing + C + M?"},{"t":"ex","en":"I was riding a bike.","uz":"Men velosiped haydayotgan edim."},{"t":"ex","en":"They were not sleeping.","uz":"Ular uxlashmayotgan edi."},{"t":"ex","en":"Was he singing a song?","uz":"U qo'shiq aytayotgan edimi?"},{"t":"h","x":"Ishlatilishi"},{"t":"p","x":"<b>1. O'tgan zamonda biror vaqt atrofida davom etayotgan harakat uchun:</b>"},{"t":"table","head":["Past Simple","Past Continuous"],"rows":[["He had breakfast at eight. — U soat sakkizda nonushta qildi (sakkizda boshladi).","He was having breakfast at eight. — U soat sakkizda nonushta qilayotgan edi (harakat davom etyotgan edi)."]]},{"t":"p","x":"<b>2. O'tgan zamonda asta-sekin, bosqichma-bosqich bo'lgan o'zgarishlar uchun:</b>"},{"t":"ex","en":"It was getting dark.","uz":"Qorong'i tushayotgan edi."},{"t":"ex","en":"The sun was rising.","uz":"Quyosh chiqayotgan edi."},{"t":"p","x":"<b>3. O'tgan zamonda boshlanib davom etgan, vaqti noma'lum harakatlar uchun:</b>"},{"t":"ex","en":"A: Do you know where Tom is? B: He is at the university. A: Really? I heard that he was studying hard.","uz":"A: Tom qayerdaligini bilasanmi? B: U universitetda. A: Rostdanmi? Eshitishimcha, u qattiq o'qiyotgan ekan."}],"quiz":[{"q":"I ___ a bike when it started to rain.","o":["was riding","were riding","am riding","rode riding"],"a":0,"e":"I bilan was + V-ing."},{"q":"They ___ sleeping when I came in.","o":["was not","were not","did not","not were"],"a":1,"e":"They bilan were + not + V-ing."},{"q":"___ he singing a song?","o":["Did","Were","Was","Is being"],"a":2,"e":"So'roq: Was/Were + S + V-ing; he bilan was."},{"q":"It ___ dark, so we went home.","o":["got","was getting","is getting","were getting"],"a":1,"e":"Asta-sekin o'zgarish — Past Continuous."},{"q":"Which sentence means the action was in progress at eight?","o":["He had breakfast at eight.","He was having breakfast at eight.","He has breakfast at eight.","He will have breakfast at eight."],"a":1,"e":"Past Continuous vaqt atrofida davom etgan harakatni bildiradi."},{"q":"The sun ___ when we left the hotel.","o":["rose","was rising","is rising","were rising"],"a":1,"e":"Bosqichma-bosqich jarayon — was rising."},{"q":"Past Continuous is formed with:","o":["did + V-ing","was/were + V-ing","have + V3","was/were + V3"],"a":1,"e":"Formula: S + was/were + V-ing."},{"q":"We ___ TV at 9 p.m. yesterday.","o":["was watching","were watching","are watching","watched watching"],"a":1,"e":"We bilan were + V-ing."}]},{"id":"p3-10","en":"Have / Has Got and Have","uz":"Have/has got va have","emoji":"🎒","level":"A1","group":"Fe'l va zamonlar","summary":"Egalikni bildiruvchi have got / has got qurilmasi: shaxsga qarab tanlanishi, inkor va so'roq shakllari hamda o'tgan zamondagi shakli (had).","blocks":[{"t":"h","x":"Has got yoki have got?"},{"t":"p","x":"3-shaxs birlik (he, she, it) uchun <b>has got</b>, boshqa shaxslar (I, you, we, they) uchun <b>have got</b> ishlatiladi."},{"t":"ex","en":"I have got a dog.","uz":"Mening itim bor."},{"t":"ex","en":"She has got two brothers.","uz":"Uning ikki akasi bor."},{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Inkor: S + have/has + not + got"},{"t":"formula","x":"So'roq: Have/Has + S + got?"},{"t":"ex","en":"I have not got a dog.","uz":"Mening itim yo'q."},{"t":"ex","en":"Has he got a book?","uz":"Uning kitobi bormi?"},{"t":"h","x":"O'tgan zamon"},{"t":"rule","x":"Have got ning o'tgan zamondagi shakli — <b>had</b>."},{"t":"ex","en":"They have a car. → They had a car.","uz":"Ularning mashinasi bor. → Ularning mashinasi bor edi."},{"t":"ex","en":"They have got a car. → They had a car.","uz":"Ularning mashinasi bor. → Ularning mashinasi bor edi."}],"quiz":[{"q":"He ___ a new phone.","o":["have got","has got","have get","has gotten got"],"a":1,"e":"3-shaxs birlik uchun has got."},{"q":"We ___ a big house.","o":["has got","have got","is got","haves got"],"a":1,"e":"We uchun have got."},{"q":"I ___ a dog. (negative)","o":["haven't got","hasn't got","don't got","not have got"],"a":0,"e":"Inkor: S + have/has + not + got."},{"q":"___ he got a book?","o":["Have","Has","Does","Is"],"a":1,"e":"So'roq: Has + he + got?"},{"q":"Past form of \"They have got a car\":","o":["They had a car.","They haved got a car.","They have gotted a car.","They has got a car."],"a":0,"e":"Have got ning o'tgan zamon shakli — had."},{"q":"She ___ any brothers.","o":["haven't got","hasn't got","not has got","don't has got"],"a":1,"e":"She — 3-shaxs birlik: hasn't got."},{"q":"___ you got a pen?","o":["Has","Have","Do","Are"],"a":1,"e":"You bilan have: Have you got ...?"},{"q":"Choose the correct sentence.","o":["My sister have got a cat.","My sister has got a cat.","My sister got has a cat.","My sister has gets a cat."],"a":1,"e":"My sister = she — has got."}]},{"id":"p3-11","en":"Future Simple Tense","uz":"Kelasi oddiy zamon","emoji":"🔮","level":"A1","group":"Fe'l va zamonlar","summary":"Future Simple (will/shall) tuzilishi, qisqartmalar, ishlatilishi va when, if kabi so'zlardan keyin kelasi zamon o'rniga Present Simple ishlatilishi.","blocks":[{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Darak: S + will/shall + bare infinitive + C + M"},{"t":"formula","x":"Inkor: S + will/shall + not + bare infinitive + C + M"},{"t":"formula","x":"So'roq: Will/Shall + S + bare infinitive + C + M?"},{"t":"rule","x":"<b>Shall</b> faqat 1-shaxs (I, we) uchun ishlatiladi. <b>Will</b> ni barcha shaxslar uchun ishlatish mumkin."},{"t":"p","x":"Qisqartmalar: <b>will not = won't</b>, <b>shall not = shan't</b>."},{"t":"ex","en":"I won't go. / I shan't go.","uz":"Men bormayman."},{"t":"ex","en":"He'll go.","uz":"U boradi."},{"t":"h","x":"Ishlatilishi"},{"t":"p","x":"<b>1. So'zlovchining kelajak haqidagi fikri, farazi, taxminini ifodalash uchun:</b>"},{"t":"ex","en":"They will sell their house.","uz":"Ular uylarini sotishadi."},{"t":"ex","en":"He will come back soon.","uz":"U tez orada qaytadi."},{"t":"p","x":"Bu holda ko'pincha quyidagi fe'l va iboralar ishlatiladi: assume (faraz qilmoq), be afraid (xavotirlanmoq), be sure / feel sure (ishonchi komil bo'lmoq), believe (ishonmoq), doubt (shubhalanmoq), expect (kutmoq, deb o'ylamoq), hope (umid qilmoq), know (bilmoq), suppose (taxmin qilmoq), think (o'ylamoq), wonder (qiziqmoq, hayron bo'lmoq)."},{"t":"p","x":"Shuningdek, ravishlar bilan: <b>perhaps, possibly, probably, surely</b>."},{"t":"ex","en":"Perhaps we shall find him at the hotel.","uz":"Balki uni mehmonxonada topamiz."},{"t":"ex","en":"I suppose they will wait for us.","uz":"Menimcha, ular bizni kutishadi."},{"t":"p","x":"<b>2. Kelajakda tabiiy ravishda takrorlanadigan (odatiy) harakatlar uchun:</b>"},{"t":"ex","en":"Spring will come again.","uz":"Bahor yana keladi."},{"t":"ex","en":"Birds will make their nests.","uz":"Qushlar in qurishadi."},{"t":"p","x":"<b>3. Continuousda ishlatilmaydigan fe'llar bilan</b> — aniq rejalashtirilgan harakat bo'lsa ham, Present Continuous o'rnida Future Simple ishlatiladi:"},{"t":"ex","en":"They will know it tomorrow.","uz":"Ular buni ertaga bilishadi."},{"t":"p","x":"<b>4. Oldindan rejalashtirilmagan (shu zahoti qabul qilingan) qarorlar uchun:</b>"},{"t":"ex","en":"A: I've got a terrible headache. B: I'll go to the chemist's and bring some medicine.","uz":"A: Boshim qattiq og'riyapti. B: Dorixonaga borib, dori olib kelaman."},{"t":"h","x":"Eslatma: when, if ... dan keyin"},{"t":"rule","x":"Murakkab gapning bir qismi <b>when, if, unless, in case, as soon as</b> va boshqalar bilan boshlansa, shu qismda Future Simple ishlatilmaydi — uning o'rniga <b>Present Simple</b> ishlatiladi."},{"t":"table","head":["Noto'g'ri","To'g'ri"],"rows":[["When I shall go home, I shall phone you.","When I go home, I shall phone you."],["He will warn Ann if he will see her.","He will warn Ann if he sees her."]]}],"quiz":[{"q":"\"Won't\" is the short form of:","o":["would not","will not","want not","was not"],"a":1,"e":"Will + not = won't."},{"q":"\"Shan't\" is the short form of:","o":["should not","shall not","shan not","she not"],"a":1,"e":"Shall + not = shan't."},{"q":"According to the rule, \"shall\" is used with:","o":["he and she","I and we","you and they","all persons"],"a":1,"e":"Shall faqat 1-shaxs (I, we) bilan."},{"q":"When I ___ home, I'll phone you.","o":["will get","shall get","get","will be getting"],"a":2,"e":"When dan keyin kelasi zamon o'rniga Present Simple."},{"q":"He will warn Ann if he ___ her.","o":["will see","sees","see","shall see"],"a":1,"e":"If dan keyin Present Simple; he — 3-shaxs: sees."},{"q":"A: I've got a terrible headache. B: Wait, I ___ you some medicine.","o":["bring","am bringing","will bring","brought"],"a":2,"e":"Shu zahoti qabul qilingan, rejalashtirilmagan qaror — will."},{"q":"Perhaps we ___ him at the hotel.","o":["find","shall find","found","are finding"],"a":1,"e":"Perhaps bilan taxmin — Future Simple."},{"q":"Spring ___ again.","o":["comes will","will come","will comes","is will come"],"a":1,"e":"Will + bare infinitive."},{"q":"They ___ the results tomorrow.","o":["are knowing","will know","knowing","will knowing"],"a":1,"e":"Know continuousda ishlatilmaydi, shuning uchun will know."}]},{"id":"p3-12","en":"Future Continuous Tense","uz":"Kelasi davomiy zamon","emoji":"🚀","level":"B1","group":"Fe'l va zamonlar","summary":"Future Continuous tuzilishi va ishlatilishi: kelajakda aniq bir vaqt atrofida davom etadigan harakatlar va oddiy, tabiiy kechadigan kelajak harakatlari.","blocks":[{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Darak: S + will/shall + be + V-ing + C + M"},{"t":"formula","x":"Inkor: S + will/shall + not + be + V-ing + C + M"},{"t":"formula","x":"So'roq: Will/Shall + S + be + V-ing + C + M?"},{"t":"h","x":"Ishlatilishi"},{"t":"p","x":"<b>1. Kelajakda aniq bir vaqt atrofida davom etayotgan bo'ladigan harakatlar uchun:</b>"},{"t":"ex","en":"Now, at nine, the students are having a lesson in the room.","uz":"Hozir soat to'qqiz, talabalar xonada dars o'tishyapti."},{"t":"ex","en":"Tomorrow at this time they will be having a lesson.","uz":"Ertaga xuddi shu vaqtda ular dars o'tishayotgan bo'lishadi."},{"t":"p","x":"<b>2. Maxsus reja yoki niyat qilinmagan, oddiy (tabiiy) kechadigan kelajak harakatlari uchun.</b> Bunda harakat odatiy holatga aylanadi."},{"t":"ex","en":"He is taking an exam next week.","uz":"Kelasi hafta u imtihon topshiryapti. (shaxsiy reja)"},{"t":"ex","en":"He will be taking an exam next week.","uz":"Kelasi hafta u imtihon topshirayotgan bo'ladi. (odatiy holat)"},{"t":"rule","x":"Bu ma'noda Future Continuous vaqt ko'rsatkichisiz ham kelishi mumkin, ammo kelajak ma'nosidagi Present Continuous doimo vaqt ko'rsatkichini talab qiladi."},{"t":"ex","en":"I am seeing him tomorrow.","uz":"Ertaga u bilan uchrashaman. (Present Continuous — tomorrow shart)"},{"t":"ex","en":"I will be seeing him.","uz":"Men u bilan ko'rishib turaman / ko'rishaman. (Future Continuous)"}],"quiz":[{"q":"Tomorrow at this time they ___ a lesson.","o":["will have","will be having","are having","will having"],"a":1,"e":"Kelajakda aniq vaqt atrofida davom etadigan harakat — will be + V-ing."},{"q":"Future Continuous is formed with:","o":["will + V-ing","will + be + V-ing","will + been + V-ing","will + have + V3"],"a":1,"e":"Formula: S + will/shall + be + V-ing."},{"q":"I ___ working at 10 p.m. tomorrow, so you can call me.","o":["won't be","won't","am not be","will not being"],"a":0,"e":"Inkor: will + not + be + V-ing."},{"q":"Choose the correct question.","o":["Will you be using the car tonight?","Will you using the car tonight?","Will be you using the car tonight?","Are you will be using the car tonight?"],"a":0,"e":"So'roq: Will + S + be + V-ing."},{"q":"Which sentence needs a time expression to show a future meaning?","o":["I am seeing him tomorrow.","I will be seeing him.","I will see him.","I shall see him."],"a":0,"e":"Kelajak ma'nosidagi Present Continuous doimo vaqt ko'rsatkichini talab qiladi."},{"q":"\"He will be taking an exam next week\" presents the exam as ___.","o":["a sudden decision","a routine, expected event","a past habit","an action happening now"],"a":1,"e":"Future Continuous reja-niyatsiz, odatiy kechadigan harakatni bildiradi."},{"q":"At 9 a.m. next Monday I ___ to Samarkand.","o":["will be flying","fly","flew","will flying"],"a":0,"e":"Kelajakda aniq vaqtda davom etadigan harakat."},{"q":"We ___ dinner when you arrive, so come straight to the kitchen.","o":["will be having","are have","will having","have been"],"a":0,"e":"Siz kelgan paytda harakat davom etayotgan bo'ladi — will be having."}]},{"id":"p3-13","en":"Non-continuous (Stative) Verbs","uz":"Davomiy zamonda ishlatilmaydigan fe'llar","emoji":"🚫","level":"B1","group":"Fe'l va zamonlar","summary":"Sezgi, egalik, his-tuyg'u va aqliy faoliyatni bildiruvchi fe'llar odatda continuousda ishlatilmaydi; ba'zilari boshqa ma'noda continuousda kela oladi.","blocks":[{"t":"h","x":"1. Sezgi fe'llari"},{"t":"p","x":"Sezishni bildiruvchi fe'llar continuousda ishlatilmaydi: <b>feel, hear, see, smell, notice, observe</b>."},{"t":"ex","en":"I feel good.","uz":"O'zimni yaxshi his qilyapman."},{"t":"h","x":"2. Bog'lovchi fe'llar (link verbs)"},{"t":"p","x":"Link verb sifatida kelgan <b>feel, look, taste, smell</b> continuousda ishlatilmaydi."},{"t":"h","x":"3. Egalik fe'llari"},{"t":"p","x":"<b>have, have got, possess, own, belong</b> continuousda ishlatilmaydi."},{"t":"ex","en":"I have got a house.","uz":"Mening uyim bor."},{"t":"ex","en":"I have a car.","uz":"Mening mashinam bor."},{"t":"ex","en":"He owns a car.","uz":"U mashinaga egalik qiladi."},{"t":"ex","en":"We possess some money.","uz":"Bizda biroz pul bor."},{"t":"ex","en":"It belongs to them.","uz":"Bu ularga tegishli."},{"t":"h","x":"4. His-tuyg'u fe'llari"},{"t":"p","x":"Quyidagilar continuousda ishlatilmaydi: admire (hurmat qilmoq), adore (juda yaxshi ko'rmoq), appreciate (qadrlamoq), care for (yoqtirmoq), desire (xohlamoq), detest (ko'rgani ko'zi yo'q), dislike (yoqtirmaslik), fear (qo'rqmoq), hate (yomon ko'rmoq), like (yoqtirmoq), loathe (jirkanmoq), respect (hurmat qilmoq), love (sevmoq), mind (qarshi bo'lmoq), value (qadrlamoq), want (xohlamoq), wish (tilamoq)."},{"t":"rule","x":"Ammo boshqa ma'noda kelsa, continuousda ishlatilishi mumkin: <b>admire</b> (havas bilan qaramoq), <b>appreciate</b> (qiymati oshmoq), <b>care for</b> (g'amxo'rlik qilmoq), <b>long for</b> (qattiq sog'inmoq, intiqlik bilan kutmoq), <b>mind</b> (qarab turmoq), <b>value</b> (moliyaviy qiymatini baholamoq), <b>enjoy</b> (zavqlanmoq), <b>like / love</b> (zavqlanmoq ma'nosida), <b>hate</b> (zavqlanmaslik ma'nosida)."},{"t":"ex","en":"How are you liking your job? — I'm hating it.","uz":"Ishing qanday, yoqyaptimi? — Umuman yoqmayapti."},{"t":"ex","en":"Do you like the job? — No, I hate it.","uz":"Ish yoqadimi? — Yo'q, yomon ko'raman."},{"t":"rule","x":"Love, like, hate fe'llarini Present Simpleda ishlatgan ma'qulroq."},{"t":"h","x":"5. Aqliy faoliyat fe'llari"},{"t":"p","x":"Quyidagilar continuousda ishlatilmaydi: agree (rozi bo'lmoq), appreciate (tushunmoq), assume (faraz qilmoq), believe (ishonmoq), expect (deb o'ylamoq), feel (o'ylamoq ma'nosida), feel sure / feel certain (ishonchi komil bo'lmoq), forget (unutmoq), know (bilmoq), mean (nazarda tutmoq), perceive (anglamoq), realize (tushunib yetmoq), recall (eslamoq), recognize (tanimoq), recollect (eslamoq), remember (eslamoq), see (tushunmoq ma'nosida), see through somebody (birovning aldamoqchi ekanini fahmlamoq), suppose (taxmin qilmoq), think (fikrda bo'lmoq), trust (ishonmoq)."},{"t":"h","x":"6. Yordamchi fe'llar"},{"t":"rule","x":"Barcha yordamchi fe'llar continuousda ishlatilmaydi, faqat <b>have</b> va <b>to be</b> bundan mustasno."},{"t":"ex","en":"I am having breakfast.","uz":"Men nonushta qilyapman."},{"t":"ex","en":"He is being selfish.","uz":"U o'zini xudbinlarcha tutyapti."},{"t":"h","x":"7. Boshqa fe'llar (qoidasiz)"},{"t":"p","x":"Quyidagilar ham continuousda ishlatilmaydi: appear (tuyulmoq), concern (tegishli bo'lmoq), contain (o'z ichiga olmoq), hold (sig'dirmoq, o'z ichiga olmoq), keep (davom ettirmoq), matter (ahamiyatga ega bo'lmoq), seem (tuyulmoq), signify (bildirmoq), sound (tuyulmoq, eshitilmoq)."},{"t":"ex","en":"It concerns us all.","uz":"Bu hammamizga tegishli."},{"t":"ex","en":"Tom keeps annoying me.","uz":"Tom meni jahlimni chiqaraveradi."},{"t":"ex","en":"It sounds good.","uz":"Bu yaxshi eshitilyapti (yaxshi fikrga o'xshaydi)."}],"quiz":[{"q":"He ___ two cars.","o":["is owning","owns","owning","are owning"],"a":1,"e":"Egalik fe'llari (own) continuousda ishlatilmaydi."},{"q":"This house ___ to my uncle.","o":["is belonging","belongs","belong","belonging"],"a":1,"e":"Belong continuousda ishlatilmaydi."},{"q":"I ___ what you mean.","o":["am knowing","know","knowing","knows"],"a":1,"e":"Know — aqliy faoliyat fe'li, continuousda kelmaydi."},{"q":"Your plan ___ good.","o":["is sounding","sounds","sound","sounding"],"a":1,"e":"Sound (tuyulmoq) continuousda ishlatilmaydi."},{"q":"Which auxiliary verbs CAN be used in the continuous?","o":["can and must","have and be","do and will","shall and should"],"a":1,"e":"Faqat have va to be continuousda kela oladi: I am having breakfast, He is being selfish."},{"q":"This box ___ old letters.","o":["is containing","contains","contain","containing"],"a":1,"e":"Contain (o'z ichiga olmoq) continuousda ishlatilmaydi."},{"q":"How ___ your new job? (= enjoying)","o":["do you liking","are you liking","you like","are you like"],"a":1,"e":"Like «zavqlanmoq» ma'nosida continuousda kela oladi."},{"q":"I ___ you. You always tell the truth.","o":["am trusting","trust","trusts","trusting"],"a":1,"e":"Trust (ishonmoq) — aqliy faoliyat fe'li."},{"q":"Which verb is NOT normally used in the continuous?","o":["eat","run","possess","write"],"a":2,"e":"Possess — egalik fe'li."}]},{"id":"p3-14","en":"Verbs with Two Uses: Feel, Look, Smell, Taste, See, Hear, Think, Expect","uz":"Ikki xil ishlatiladigan fe'llar: feel, look, smell, taste, see, hear, think, expect","emoji":"👀","level":"B1","group":"Fe'l va zamonlar","summary":"Ba'zi fe'llar bir ma'noda continuousda ishlatiladi, boshqa ma'noda (link verb, fikr, sezgi) esa ishlatilmaydi. Bu darsda har bir fe'lning ikkala holati ko'rsatiladi.","blocks":[{"t":"h","x":"FEEL"},{"t":"p","x":"<b>Continuousda ishlatiladi:</b>"},{"t":"list","items":["1. Aqliy, jismoniy, ruhiy holat yoki his-tuyg'uni bildiruvchi sifatlar bilan: angry / pleased, happy / sad, hot / cold, nervous / confident ...","2. «Touch» (ushlab ko'rmoq) ma'nosida.","3. «Feel for» (paypaslab qidirmoq) ma'nosida."]},{"t":"ex","en":"I am feeling better.","uz":"O'zimni yaxshiroq his qilyapman."},{"t":"ex","en":"Are you feeling angry?","uz":"Jahling chiqyaptimi?"},{"t":"ex","en":"The doctor is feeling her pulse.","uz":"Shifokor uning tomir urishini ushlab ko'ryapti."},{"t":"ex","en":"He was feeling for the keyhole in the dark.","uz":"U qorong'ida kalit teshigini paypaslab qidirayotgan edi."},{"t":"p","x":"<b>Continuousda ishlatilmaydi:</b>"},{"t":"list","items":["1. «Sense» (sezmoq) ma'nosida: <i>Don't you feel the house shaking?</i> (Uy silkinayotganini sezmayapsanmi?)","2. «Think» (o'ylamoq) ma'nosida: <i>I feel that it is a good idea.</i> (Menimcha, bu yaxshi fikr.)","3. Link verb sifatida: <i>The water feels cold.</i> (Suv sovuq.)"]},{"t":"h","x":"LOOK"},{"t":"p","x":"<b>Continuousda ishlatiladi:</b> look at (qaramoq), look for (qidirmoq), look in (ko'zguga va h.k. qaramoq), look into (o'rganib chiqmoq), look out (for) (izlamoq, axtarmoq), look on (tomosha qilib turmoq)."},{"t":"ex","en":"He is looking for a job.","uz":"U ish qidiryapti."},{"t":"ex","en":"They are looking out for a car.","uz":"Ular mashina axtarishyapti."},{"t":"p","x":"<b>Continuousda ishlatilmaydi:</b>"},{"t":"list","items":["1. Link verb sifatida: <i>This cake looks good.</i> (Bu tort mazali ko'rinadi.)","2. look on (= consider, deb hisoblamoq), look up to (= respect, hurmat qilmoq), look down on (= despise, mensimaslik): <i>I always look up to my relatives.</i> (Men doim qarindoshlarimni hurmat qilaman.)"]},{"t":"h","x":"SMELL"},{"t":"p","x":"<b>Continuousda ishlatilmaydi:</b> 1) hid sezmoq ma'nosida; 2) link verb sifatida."},{"t":"ex","en":"I smell gas.","uz":"Gaz hidini sezyapman."},{"t":"ex","en":"The meat smells bad.","uz":"Go'shtdan yomon hid kelyapti."},{"t":"p","x":"<b>Continuousda ishlatiladi:</b> «sniff at» (hidlab ko'rmoq) ma'nosida."},{"t":"ex","en":"Why are you smelling the meat?","uz":"Nega go'shtni hidlayapsan?"},{"t":"h","x":"TASTE"},{"t":"p","x":"<b>Continuousda ishlatilmaydi:</b> link verb sifatida."},{"t":"ex","en":"The coffee tastes bitter.","uz":"Qahva achchiq."},{"t":"p","x":"<b>Continuousda ishlatiladi:</b> «to test the flavour» (ta'tib ko'rmoq) ma'nosida."},{"t":"ex","en":"Tom is tasting his soup to check whether it is eatable.","uz":"Tom sho'rvasi yeyishga yaroqlimi-yo'qmi, ta'tib ko'ryapti."},{"t":"h","x":"SEE"},{"t":"p","x":"<b>Continuousda ishlatiladi:</b>"},{"t":"list","items":["1. Kelishilgan holda uchrashmoq (meet by appointment): <i>I am seeing my doctor tomorrow.</i> (Ertaga shifokorimga uchrashaman.)","2. Ko'rib chiqmoq, sayr qilmoq (visit): <i>Tom is seeing the town.</i> (Tom shaharni aylanyapti.)","3. See to — tartibga keltirmoq, tuzatmoq: <i>The plumber is here. He is seeing to the leak in the tank.</i> (Santexnik keldi. U bakdagi oqishni tuzatyapti.)","4. See about — chorasini ko'rmoq: <i>We are seeing about a work permit for you.</i> (Sizga ishlash ruxsatnomasi masalasini hal qilyapmiz.)","5. See somebody out — eshikkacha kuzatmoq; see somebody home — uyigacha kuzatib qo'ymoq; see somebody to a place — biror joygacha kuzatmoq: <i>Is Bill seeing you home after the party? — No, he is just seeing me to my bus.</i> (Bill seni ziyofatdan keyin uyingga kuzatib qo'yadimi? — Yo'q, avtobusimgacha kuzatib qo'yadi, xolos.)","6. See somebody off — jo'natib (kuzatib) qo'ymoq: <i>We are seeing him off at the station.</i> (Uni vokzalda kuzatib qo'yyapmiz.)"]},{"t":"h","x":"HEAR"},{"t":"p","x":"<b>Continuousda ishlatiladi:</b>"},{"t":"list","items":["1. Kitob muallifi fikricha, «listen to» (tinglamoq) ma'nosida: <i>I am hearing the music.</i> (tinglayapman) — <i>I hear the music.</i> (eshityapman, sezgi).","2. «Receive news / a letter» (xabar olmoq) ma'nosida: <i>I have been hearing all about your achievements.</i> (Yutuqlaringiz haqida ko'p eshityapman.) / <i>I hope I shall be hearing from you soon.</i> (Tez orada sizdan xabar olaman deb umid qilaman.)"]},{"t":"h","x":"THINK"},{"t":"p","x":"<b>Continuousda ishlatiladi:</b> o'ylamoq, fikr yuritmoq ma'nosida."},{"t":"ex","en":"What are you thinking about?","uz":"Nimalar haqida o'ylayapsan?"},{"t":"p","x":"<b>Continuousda ishlatilmaydi:</b> fikr so'rash yoki fikr bildirish ma'nosida."},{"t":"ex","en":"What do you think of it?","uz":"Bu haqda fikring qanday?"},{"t":"ex","en":"I think it is a stupid idea.","uz":"Menimcha, bu ahmoqona fikr."},{"t":"ex","en":"Tom is thinking of emigrating, but I think it is not a good idea.","uz":"Tom chet elga ko'chib ketishni o'ylayapti, lekin menimcha, bu yaxshi fikr emas."},{"t":"h","x":"EXPECT"},{"t":"p","x":"<b>Continuousda ishlatiladi:</b> «wait» (kutmoq) ma'nosida. (Expect «deb o'ylamoq» ma'nosida esa continuousda kelmaydi.)"},{"t":"ex","en":"I am expecting my score.","uz":"Men ballimni kutyapman."}],"quiz":[{"q":"The doctor ___ her pulse.","o":["feels","is feeling","feel","felt feeling"],"a":1,"e":"Feel «ushlab ko'rmoq» ma'nosida continuousda ishlatiladi."},{"q":"The water ___ cold.","o":["is feeling","feels","feeling","are feeling"],"a":1,"e":"Link verb sifatida feel continuousda kelmaydi."},{"q":"He ___ for a job at the moment.","o":["looks","is looking","look","looking"],"a":1,"e":"Look for (qidirmoq) continuousda ishlatiladi."},{"q":"This cake ___ delicious.","o":["is looking","looks","look","looking"],"a":1,"e":"Link verb sifatida look continuousda kelmaydi."},{"q":"Why ___ the meat? Is it bad?","o":["do you smell","are you smelling","you smell","smell you"],"a":1,"e":"Smell «hidlab ko'rmoq» ma'nosida continuousda keladi."},{"q":"I ___ gas! Open the windows!","o":["am smelling","smell","smelling","smells"],"a":1,"e":"Hid sezish ma'nosida smell continuousda ishlatilmaydi."},{"q":"The coffee ___ bitter.","o":["is tasting","tastes","taste","tasting"],"a":1,"e":"Link verb sifatida taste continuousda kelmaydi."},{"q":"I ___ my doctor tomorrow at ten.","o":["see","am seeing","seeing","sees"],"a":1,"e":"See «kelishilgan holda uchrashmoq» ma'nosida continuousda keladi."},{"q":"What ___ of my new haircut? (asking for an opinion)","o":["are you thinking","do you think","you think","are you think"],"a":1,"e":"Fikr so'rashda think continuousda ishlatilmaydi."},{"q":"We ___ him off at the station now.","o":["see","are seeing","sees","seen"],"a":1,"e":"See somebody off (kuzatib qo'ymoq) continuousda ishlatiladi."}]},{"id":"p4-01","en":"Spelling Rules: Doubling the Final Consonant","uz":"Imlo qoidalari: oxirgi undoshning ikkilanishi","emoji":"✍️","level":"A2","group":"Imlo va uslub","summary":"So'zga qo'shimcha (suffix) qo'shilganda oxirgi undosh qachon ikkilanishi va qachon ikkilanmasligi haqidagi qoidalar.","blocks":[{"t":"h","x":"Suffix nima?"},{"t":"p","x":"<b>Suffix</b> (qo'shimcha) — so'z oxiriga qo'shiladigan harflar yig'indisi. Qo'shimcha qo'shilganda ba'zan so'zning imlosi o'zgaradi."},{"t":"ex","en":"beauty + ful = beautiful","uz":"go'zal"},{"t":"h","x":"1-qoida. Bir bo'g'inli so'zlar"},{"t":"p","x":"Agar bir bo'g'inli so'z <b>bitta unli + bitta undosh</b> bilan tugasa va unga <b>unli bilan boshlanuvchi</b> qo'shimcha (-ing, -ed, -er) qo'shilsa, oxirgi undosh <b>ikkilanadi</b>."},{"t":"table","head":["So'z + qo'shimcha","Natija","Izoh"],"rows":[["hit + ing","<b>hitting</b>","1 unli + 1 undosh → ikkilanadi"],["knit + ed","<b>knitted</b>","1 unli + 1 undosh → ikkilanadi"],["run + er","<b>runner</b>","1 unli + 1 undosh → ikkilanadi"],["keep + ing","keeping","ikkita unli (ee) → ikkilanmaydi"],["help + ed","helped","ikkita undosh (lp) → ikkilanmaydi"]]},{"t":"rule","x":"Diqqat: <b>qu</b> ikki harf bo'lsa ham bitta undosh hisoblanadi: quit + ing = <b>quitting</b>."},{"t":"rule","x":"So'z oxiridagi <b>w, x, y</b> harflari hech qachon ikkilanmaydi: box + ing = <b>boxing</b>, show + ing = <b>showing</b>, play + er = <b>player</b>."},{"t":"h","x":"2-qoida. Ikki yoki uch bo'g'inli so'zlar"},{"t":"p","x":"Ikki yoki uch bo'g'inli so'z <b>bitta unli + bitta undosh</b> bilan tugasa va <b>urg'u oxirgi bo'g'inga</b> tushsa, oxirgi undosh ikkilanadi."},{"t":"table","head":["So'z + qo'shimcha","Natija","Ma'nosi"],"rows":[["be'gin + ing","<b>beginning</b>","boshlamoq"],["ac'quit + ing","<b>acquitting</b>","oqlamoq"],["de'ter + ed","<b>deterred</b>","biror narsadan to'xtatmoq, qaytarmoq"],["'murmur + ed","murmured","pichirlamoq — urg'u 1-bo'g'inda, ikkilanmaydi"]]},{"t":"rule","x":"Istisno: <b>focus + ed</b> = focused yoki focussed (diqqatni jamlamoq); <b>bias + ed</b> = biased yoki biassed (xolis bo'lmaslik). Ikkala yozuv ham to'g'ri."},{"t":"p","x":"Quyidagi so'zlarda urg'u birinchi bo'g'inga tushsa ham oxirgi undosh ikkilanadi:"},{"t":"table","head":["So'z + qo'shimcha","Natija","Ma'nosi"],"rows":[["handicap + ed","<b>handicapped</b>","xalaqit bermoq, imkoniyatini cheklamoq"],["kidnap + ed","<b>kidnapped</b>","odam (ko'pincha bola) o'g'irlamoq"],["worship + ed","<b>worshipped</b>","ibodat qilmoq, sig'inmoq"]]},{"t":"h","x":"3-qoida. l harfi bilan tugaydigan so'zlar"},{"t":"p","x":"So'z <b>bitta unli + l</b> bilan tugasa, oxirgi <b>l</b> ikkilanadi (urg'u qayerda bo'lishidan qat'i nazar). Agar so'z <b>ikkita unli + l</b> bilan tugasa va bu ikki unli <b>alohida-alohida</b> talaffuz qilinsa (cru-el, di-al), l yana ikkilanadi. Ikki unli bitta tovush bersa (cool), l ikkilanmaydi."},{"t":"table","head":["So'z + qo'shimcha","Natija","Ma'nosi"],"rows":[["appal + ed","<b>appalled</b>","dahshatga solmoq"],["cruel + ly","<b>cruelly</b>","shafqatsizlarcha"],["dial + ed","<b>dialled</b>","raqam termoq"],["cool + ed","cooled","sovutmoq — oo bitta tovush, ikkilanmaydi"]]},{"t":"rule","x":"Eslatma: bu qoida asosan Britaniya imlosiga xos. Amerika imlosida ko'pincha l ikkilanmaydi (dialed, traveled)."}],"quiz":[{"q":"Choose the correct spelling: run + er","o":["runer","runner","runnier","rouner"],"a":1,"e":"Bir bo'g'inli, 1 unli + 1 undosh: oxirgi undosh ikkilanadi."},{"q":"Choose the correct spelling: help + ed","o":["hellped","helpped","helped","helpt"],"a":2,"e":"So'z ikkita undosh (lp) bilan tugaydi, ikkilanish bo'lmaydi."},{"q":"Choose the correct spelling: quit + ing","o":["quiting","quitting","quieting","quitteng"],"a":1,"e":"qu bitta undosh hisoblanadi, shuning uchun t ikkilanadi."},{"q":"Choose the correct spelling: box + ing","o":["boxxing","boxing","boxeing","boxsing"],"a":1,"e":"x harfi hech qachon ikkilanmaydi."},{"q":"Choose the correct spelling: begin + ing","o":["begining","beginning","beginnning","begineing"],"a":1,"e":"Urg'u oxirgi bo'g'inda (be'gin), shuning uchun n ikkilanadi."},{"q":"Choose the correct spelling: murmur + ed","o":["murmurred","murmured","murmureed","murmurd"],"a":1,"e":"Urg'u birinchi bo'g'inda ('murmur), r ikkilanmaydi."},{"q":"Which word is an exception where the consonant doubles although the stress is on the first syllable?","o":["visited","opened","kidnapped","listened"],"a":2,"e":"kidnap, handicap, worship so'zlarida urg'u 1-bo'g'inda bo'lsa ham undosh ikkilanadi."},{"q":"Choose the correct spelling: keep + ing","o":["keepping","keping","keeping","keaping"],"a":2,"e":"ee — ikkita unli, shuning uchun p ikkilanmaydi."},{"q":"Choose the British spelling: cool + ed","o":["cooled","coolled","coold","cooleed"],"a":0,"e":"oo bitta tovush beradi, l ikkilanmaydi."},{"q":"Which pair shows both correct spellings?","o":["focused / focussed","focused / focusd","focussed / focusied","focuced / focussed"],"a":0,"e":"focus — istisno: focused ham, focussed ham to'g'ri."}]},{"id":"p4-02","en":"Spelling Rules: Final E and Final Y","uz":"Imlo qoidalari: oxirgi \"e\" va \"y\" harflari","emoji":"🔤","level":"A2","group":"Imlo va uslub","summary":"Qo'shimcha qo'shilganda so'z oxiridagi \"e\" qachon tushib qolishi, \"ce/ge\" bilan tugagan so'zlar va \"y\" harfining \"i\" ga aylanishi.","blocks":[{"t":"h","x":"Oxirgi \"e\" ning tushib qolishi (Omission of final E)"},{"t":"p","x":"<b>Undosh + e</b> bilan tugaydigan so'zlarga <b>unli bilan boshlanuvchi</b> qo'shimcha qo'shilsa, oxirgi <b>e</b> tushib qoladi."},{"t":"ex","en":"believe + er = believer","uz":"ishonuvchi"},{"t":"ex","en":"hope + ing = hoping","uz":"umid qilish"},{"t":"rule","x":"Istisno: quyidagi 3 ta so'zda \"e\" saqlanadi: singe + ing = <b>singeing</b> (kuydirmoq), dye + ing = <b>dyeing</b> (bo'yamoq), age + ing = <b>ageing</b> (qarimoq)."},{"t":"rule","x":"<b>like</b> so'zi uchun ikkala shakl ham to'g'ri: like + able = <b>likable</b> yoki <b>likeable</b>."},{"t":"p","x":"<b>Undosh bilan boshlanuvchi</b> qo'shimcha (-ment, -ful, -ly...) qo'shilsa, oxirgi \"e\" saqlanadi:"},{"t":"ex","en":"engage + ment = engagement","uz":"unashtirish; band bo'lish"},{"t":"ex","en":"hope + ful = hopeful","uz":"umidvor"},{"t":"p","x":"<b>-able, -ible</b> bilan tugaydigan sifatlardan ravish yasalganda oxirgi \"e\" tushib qoladi (-ly → -bly):"},{"t":"ex","en":"comfortable → comfortably","uz":"qulay → qulay tarzda"},{"t":"ex","en":"incredible → incredibly","uz":"aql bovar qilmas → aql bovar qilmas darajada"},{"t":"h","x":"Istisno so'zlar"},{"t":"table","head":["So'z","Yasalgan so'z","Izoh"],"rows":[["judge","judgement / judgment","ikkala shakl ham to'g'ri"],["true","truly","e tushadi"],["due","duly","e tushadi"],["whole","wholly","e tushadi"],["argue","argument","e tushadi (bahslashmoq → bahs)"]]},{"t":"rule","x":"So'z <b>ee</b> bilan tugasa, qo'shimcha qo'shilganda \"e\" tushmaydi: agree + ing = <b>agreeing</b>, agree + ment = <b>agreement</b>."},{"t":"h","x":"\"ce\" va \"ge\" bilan tugaydigan so'zlar"},{"t":"p","x":"<b>-ce</b> yoki <b>-ge</b> bilan tugaydigan so'zlarga <b>a</b> yoki <b>o</b> harfi bilan boshlanuvchi qo'shimcha qo'shilsa, oxirgi \"e\" <b>saqlanadi</b> (c va g ning yumshoq talaffuzi saqlanishi uchun)."},{"t":"ex","en":"courage + ous = courageous","uz":"jasur"},{"t":"ex","en":"manage + able = manageable","uz":"boshqarsa bo'ladigan"},{"t":"ex","en":"peace + able = peaceable","uz":"tinchliksevar"},{"t":"p","x":"<b>-ce</b> bilan tugagan so'zga <b>-ous</b> qo'shilsa, \"e\" harfi <b>i</b> ga aylanadi:"},{"t":"ex","en":"vice + ous = vicious","uz":"yovuz, shafqatsiz"},{"t":"ex","en":"grace + ous = gracious","uz":"mehribon, iltifotli"},{"t":"h","x":"\"y\" bilan tugaydigan so'zlar"},{"t":"p","x":"<b>Undosh + y</b> bilan tugaydigan so'zlarga qo'shimcha qo'shilsa, <b>y → i</b> ga aylanadi."},{"t":"ex","en":"carry → carried","uz":"olib bordi"},{"t":"ex","en":"happy → happily","uz":"baxtli tarzda"},{"t":"rule","x":"Istisno: <b>-ing</b> qo'shilganda y o'zgarmaydi: carry + ing = <b>carrying</b>."},{"t":"p","x":"<b>Unli + y</b> bilan tugaydigan so'zlarda qo'shimcha qo'shilganda hech qanday o'zgarish bo'lmaydi:"},{"t":"ex","en":"obey + ed = obeyed","uz":"itoat qildi"},{"t":"ex","en":"play + er = player","uz":"o'yinchi"}],"quiz":[{"q":"Choose the correct spelling: hope + ing","o":["hopeing","hoping","hopping","hopeng"],"a":1,"e":"Undosh + e, unli bilan boshlanuvchi qo'shimcha: e tushadi."},{"q":"Choose the correct spelling: hope + ful","o":["hopful","hopeful","hoppful","hopefull"],"a":1,"e":"Undosh bilan boshlanuvchi qo'shimchada e saqlanadi."},{"q":"Choose the correct spelling: dye + ing","o":["dying","dyeing","dyieng","dyng"],"a":1,"e":"dye — istisno, e saqlanadi (dying = o'lish so'zi bilan adashmaslik uchun)."},{"q":"Choose the correct spelling: agree + ing","o":["agreing","agreeing","agriing","agrying"],"a":1,"e":"ee bilan tugagan so'zda e tushmaydi."},{"q":"Choose the correct spelling: courage + ous","o":["courageous","couragous","couragious","couraguous"],"a":0,"e":"ge + o bilan boshlanuvchi qo'shimcha: e saqlanadi."},{"q":"Choose the correct spelling: grace + ous","o":["graceous","gracous","gracious","graceious"],"a":2,"e":"-ce + ous: e harfi i ga aylanadi."},{"q":"Choose the correct spelling: true + ly","o":["truely","truly","truley","truelly"],"a":1,"e":"true — istisno: truly."},{"q":"Choose the correct spelling: comfortable → adverb","o":["comfortablely","comfortably","comfortabley","comfortablly"],"a":1,"e":"-able → -ably: e tushadi."},{"q":"Choose the correct spelling: carry + ing","o":["carriing","carring","carrying","carreing"],"a":2,"e":"-ing qo'shilganda y o'zgarmaydi."},{"q":"Choose the correct spelling: obey + ed","o":["obeied","obeyed","obied","obeyd"],"a":1,"e":"Unli + y: hech qanday o'zgarish bo'lmaydi."}]},{"id":"p4-03","en":"Present Perfect Tense: Form and Main Uses","uz":"Hozirgi tugallangan zamon: tuzilishi va asosiy qo'llanishi","emoji":"✅","level":"A2","group":"Fe'l va zamonlar","summary":"Present Perfect zamonining tuzilishi hamda yet, already, ever, never, just ravishlari bilan qo'llanishi.","blocks":[{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Darak: S + have/has + past participle (V3) + C + M"},{"t":"formula","x":"Inkor: S + have/has + not + past participle (V3) + C + M"},{"t":"formula","x":"So'roq: Have/Has + S + past participle (V3) + C + M?"},{"t":"p","x":"Bu yerda <b>S</b> — ega, <b>C</b> — to'ldiruvchi (complement), <b>M</b> — hol (modifier: joy, vaqt, usul)."},{"t":"h","x":"1. O'tgan zamonda noma'lum vaqtda bo'lgan ish-harakat"},{"t":"p","x":"Present Perfect ish-harakat o'tgan zamonda bo'lgan, lekin <b>aniq vaqti aytilmagan / muhim emas</b> bo'lganda ishlatiladi. Vaqt aniq bo'lsa, Past Simple ishlatiladi."},{"t":"ex","en":"Have you had breakfast?","uz":"Nonushta qildingmi? (vaqt muhim emas)"},{"t":"ex","en":"Did you have breakfast at the hotel?","uz":"Mehmonxonada nonushta qildingmi? (aniq vaziyat — Past Simple)"},{"t":"ex","en":"I have read the instructions, but I do not understand them.","uz":"Yo'riqnomani o'qib chiqdim, lekin tushunmadim."},{"t":"ex","en":"I read the instructions last night.","uz":"Yo'riqnomani kecha kechqurun o'qidim. (aniq vaqt — Past Simple)"},{"t":"ex","en":"Jim decided to quit the course because it was getting very difficult.","uz":"Jim kursni tashlashga qaror qildi, chunki u juda qiyinlashib borayotgan edi."},{"t":"h","x":"Yet va Already"},{"t":"p","x":"<b>Yet</b> va <b>already</b> ravishlari o'tgan zamonda noma'lum vaqtda bo'lgan yoki bo'lmagan ish-harakatlarni ifodalaydi va asosan Present Perfect bilan ishlatiladi."},{"t":"ex","en":"We have already written our reports.","uz":"Biz allaqachon hisobotlarimizni yozib bo'ldik."},{"t":"ex","en":"Maria has not called her parents yet.","uz":"Mariya hali ota-onasiga qo'ng'iroq qilmadi."},{"t":"list","items":["<b>Already</b> asosan darak gaplarda, yordamchi fe'l (have/has) va asosiy fe'l <b>orasida</b> keladi; ba'zan gap boshida yoki oxirida ham kelishi mumkin.","<b>Yet</b> inkor va so'roq gaplarda, gapning <b>oxirida</b> keladi."]},{"t":"ex","en":"We have not written our reports yet.","uz":"Biz hali hisobotlarimizni yozmadik."},{"t":"ex","en":"Maria has already called her parents.","uz":"Mariya allaqachon ota-onasiga qo'ng'iroq qildi."},{"t":"h","x":"2. O'tmishdan hozirgacha bo'lgan davr (hayot tajribasi)"},{"t":"p","x":"Present Perfect o'tgan zamondan hozirgacha bo'lgan davr haqida, masalan, inson hayoti va tajribasi haqida gapirganda ishlatiladi."},{"t":"ex","en":"Have you been to London?","uz":"Londonda bo'lganmisan?"},{"t":"ex","en":"I have seen that woman before, but I cannot remember when.","uz":"Bu ayolni oldin ko'rganman, lekin qachonligini eslay olmayman."},{"t":"h","x":"Ever va Never"},{"t":"p","x":"<b>Ever</b> asosan so'roq gaplarda, <b>never</b> esa darak gaplarda ishlatiladi. Ikkalasi ham yordamchi fe'l va asosiy fe'l orasida keladi."},{"t":"ex","en":"Have you ever been to London?","uz":"Hech Londonda bo'lganmisan?"},{"t":"ex","en":"I have never seen such a beautiful car.","uz":"Men hech qachon bunday chiroyli mashinani ko'rmaganman."},{"t":"h","x":"Just — yaqinda tugagan ish-harakat"},{"t":"p","x":"Present Perfect <b>just</b> bilan birga hozirgina tugagan ish-harakatni bildiradi. Just yordamchi va asosiy fe'l orasida keladi; asosan darak gapda, ba'zan so'roq gapda ham ishlatiladi."},{"t":"ex","en":"He has just gone out.","uz":"U hozirgina chiqib ketdi."},{"t":"ex","en":"He went out a few minutes ago.","uz":"U bir necha daqiqa oldin chiqib ketdi. (aniq vaqt — Past Simple)"},{"t":"ex","en":"Has he just gone out?","uz":"U hozirgina chiqib ketdimi?"},{"t":"h","x":"3. Natijasi hozir ko'rinib turgan ish-harakat"},{"t":"p","x":"Ish-harakat o'tmishda bo'lgan, lekin uning <b>natijasi hozir</b> ko'rinib tursa, Present Perfect ishlatiladi."},{"t":"ex","en":"I have washed my car. It looks lovely now.","uz":"Mashinamni yuvdim. Hozir u juda chiroyli ko'rinyapti."},{"t":"ex","en":"I washed my car.","uz":"Mashinamni yuvdim. (shunchaki o'tmishdagi fakt)"},{"t":"ex","en":"The elevator has broken down; we should take the stairs.","uz":"Lift buzilib qoldi, zinadan chiqishimiz kerak."},{"t":"ex","en":"The elevator broke down.","uz":"Lift buzildi. (o'tmishdagi fakt)"},{"t":"rule","x":"Present Perfect + <b>yet</b> bilan tuzilgan gapning odatda hozirgi zamonga ta'siri (natijasi) bo'ladi: <i>He has not come yet, so we are still waiting for him.</i> — U hali kelmadi, shuning uchun hamon kutyapmiz."}],"quiz":[{"q":"Choose the correct form: She ___ her homework.","o":["has finish","have finished","has finished","finished has"],"a":2,"e":"Ega 3-shaxs birlik: has + V3."},{"q":"Choose the correct question: ___ you ever ___ sushi?","o":["Did / eaten","Have / eaten","Have / ate","Has / eat"],"a":1,"e":"So'roq: Have + S + V3; ever so'roq gapda ishlatiladi."},{"q":"Where does 'yet' usually go? 'Maria has not called her parents ___.'","o":["after 'Maria'","after 'has'","at the end of the sentence","before 'Maria'"],"a":2,"e":"Yet odatda gap oxirida keladi."},{"q":"Choose the correct sentence.","o":["We have written already our reports.","We already have written our reports yet.","We have already written our reports.","We have written our reports already yet."],"a":2,"e":"Already yordamchi va asosiy fe'l orasida keladi."},{"q":"Choose the correct sentence.","o":["I have read the instructions last night.","I read the instructions last night.","I has read the instructions last night.","I have reading the instructions last night."],"a":1,"e":"Aniq o'tgan vaqt (last night) bilan Past Simple ishlatiladi."},{"q":"Choose the correct word: 'I have ___ seen such a beautiful car.'","o":["ever","yet","never","ago"],"a":2,"e":"Darak gapda 'hech qachon' ma'nosida never ishlatiladi."},{"q":"Choose the correct sentence.","o":["He has just gone out.","He has gone just out.","He just has went out.","He has gone out just now ago."],"a":0,"e":"Just yordamchi va asosiy fe'l orasida keladi."},{"q":"Which sentence shows a present result? ","o":["I washed my car last week.","I have washed my car. It looks lovely now.","I was washing my car.","I wash my car every Sunday."],"a":1,"e":"Present Perfect natijasi hozir ko'rinayotgan ish-harakatni bildiradi."},{"q":"Choose the correct form: 'The elevator ___, so we should take the stairs.'","o":["has broken down","have broken down","broke down yesterday","is break down"],"a":0,"e":"Hozirgi natija (zinadan chiqish kerak) — Present Perfect."},{"q":"Choose the correct sentence.","o":["He went out a few minutes ago.","He has gone out a few minutes ago.","He has went out a few minutes ago.","He have gone out a few minutes ago."],"a":0,"e":"'ago' aniq o'tgan vaqtni bildiradi — Past Simple."}]},{"id":"p4-04","en":"Present Perfect: For, Since and Present Perfect vs. Past Simple","uz":"Present Perfect: for, since va Past Simple bilan farqi","emoji":"⏳","level":"B1","group":"Fe'l va zamonlar","summary":"for/since, last/the last, tugallanmagan davr, lately/recently bilan Present Perfect va uning Past Simple'dan farqi.","blocks":[{"t":"h","x":"For — davomiylik"},{"t":"p","x":"<b>For</b> vaqt oralig'ini (davrni) bildiradi: <i>for six months, for a month, for two hours</i>."},{"t":"list","items":["<b>For + Past Simple</b> — tugagan davrni bildiradi: <i>He worked there for 40 years.</i> (U yerda 40 yil ishlagan — endi ishlamaydi.)","<b>For + Present Perfect</b> — o'tmishda boshlanib hozirgacha davom etayotgan ish-harakatni bildiradi: <i>He has worked there for 40 years.</i> (40 yildan beri ishlaydi — hozir ham.)"]},{"t":"p","x":"<b>For</b> ba'zan tushirib qoldirilishi mumkin, ayniqsa <b>be, live, wait</b> fe'llaridan keyin:"},{"t":"ex","en":"I have been here (for) an hour / two weeks.","uz":"Men bu yerda bir soatdan / ikki haftadan beriman."},{"t":"rule","x":"<b>All</b> bilan boshlanuvchi vaqt iboralaridan oldin <b>for</b> hech qachon ishlatilmaydi: <i>They have worked all night.</i> (✗ for all night)"},{"t":"h","x":"Since — boshlanish nuqtasi"},{"t":"p","x":"<b>Since</b> ish-harakatning <b>boshlanish nuqtasini</b> bildiradi va \"...dan beri\" (o'sha nuqtadan gapirilayotgan vaqtgacha) ma'nosini beradi: <i>since January, since my birthday</i>."},{"t":"ex","en":"She has been here since 6 a.m.","uz":"U ertalab soat 6 dan beri shu yerda."},{"t":"ex","en":"We have been friends since our schooldays.","uz":"Biz maktab davridan beri do'stmiz."},{"t":"p","x":"<b>Since</b> dan keyin to'liq ergash gap (clause) ham kelishi mumkin:"},{"t":"ex","en":"I have worked there since I left school.","uz":"Maktabni bitirganimdan beri u yerda ishlayman."},{"t":"h","x":"Ever since"},{"t":"p","x":"<b>Ever since</b> — \"o'shandan beri\" ma'nosida, odatda gap oxirida keladi."},{"t":"ex","en":"I saw him at the party last month and have not met him ever since.","uz":"Uni o'tgan oy ziyofatda ko'rdim va o'shandan beri uchratmadim."},{"t":"ex","en":"I haven't seen him since I saw him at the party last month.","uz":"O'tgan oy ziyofatda ko'rganimdan beri uni ko'rmadim."},{"t":"h","x":"Last va The last"},{"t":"ex","en":"I have been here since last week.","uz":"O'tgan haftadan beri shu yerdaman. (month, year va h.k. ham bo'ladi)"},{"t":"ex","en":"I have been here for the last week.","uz":"Oxirgi bir hafta davomida shu yerdaman."},{"t":"list","items":["<b>since last week</b> — ish-harakatning boshlanish nuqtasi (taxminan yetti kun oldin).","<b>for the last week</b> — yetti kunlik davr, ya'ni davomiylik."]},{"t":"h","x":"Tugallanmagan davr: today, this morning..."},{"t":"p","x":"Present Perfect <b>hali tugamagan davrda</b> sodir bo'lgan ish-harakat uchun ishlatiladi. Bunday davr <i>today, this morning / evening / afternoon / week / month / year</i> kabi so'zlar bilan ifodalanadi."},{"t":"ex","en":"(At 10 a.m.) Tom has rung up three times this morning.","uz":"Tom bugun ertalab uch marta qo'ng'iroq qildi. (ertalab hali tugamagan)"},{"t":"ex","en":"(At 2 p.m.) Tom rang up three times this morning.","uz":"Tom bugun ertalab uch marta qo'ng'iroq qilgan edi. (ertalab tugagan — Past Simple)"},{"t":"p","x":"Tugallanmagan davr bilan Present Perfect shu davr ichida <b>noma'lum vaqtda</b> bo'lgan yoki bo'lmagan ish-harakatni bildiradi. Agar vaqt aniq bo'lsa, Past Simple ishlatiladi:"},{"t":"ex","en":"Tom rang up at 8 a.m. this morning.","uz":"Tom bugun ertalab soat 8 da qo'ng'iroq qildi. (aniq vaqt)"},{"t":"ex","en":"Have you seen him today?","uz":"Bugun uni ko'rdingmi?"},{"t":"p","x":"Agar ish-harakat odatda <b>aniq bir vaqtda</b> yoki tugallanmagan davrning aniq bir qismida sodir bo'lishini bilsak, <b>Past Simple</b> ishlatamiz. Masalan, kimningdir budilnigi odatda soat 6 da jiringlasa, nonushta paytida u shunday deydi:"},{"t":"ex","en":"My alarm didn't go off this morning.","uz":"Bugun ertalab budilnigim jiringlamadi."},{"t":"p","x":"Pochtachi odatda soat 9–10 oralig'ida kelsa:"},{"t":"ex","en":"(10 dan oldin) Has the mail carrier come this morning?","uz":"Pochtachi bugun ertalab keldimi? (kelish vaqti hali o'tmagan)"},{"t":"ex","en":"(10 dan keyin) Did the mail carrier come this morning?","uz":"Pochtachi bugun ertalab keldimi? (kelish vaqti o'tib ketgan)"},{"t":"h","x":"Lately va Recently"},{"t":"p","x":"<b>Lately</b> va <b>recently</b> Present Perfect bilan ishlatilganda tugallanmagan davrni (\"so'nggi paytlarda\") bildiradi."},{"t":"ex","en":"Has he been here recently / lately?","uz":"U so'nggi paytlarda shu yerda bo'ldimi?"},{"t":"ex","en":"He has not been here recently / lately.","uz":"U so'nggi paytlarda bu yerda bo'lmadi."},{"t":"p","x":"<b>Recently</b> Past Simple bilan ishlatilsa, \"yaqinda, qisqa vaqt oldin\" ma'nosini beradi:"},{"t":"ex","en":"He left recently.","uz":"U yaqinda ketdi."},{"t":"h","x":"Present Perfect va Past Simple"},{"t":"table","head":["Present Perfect","Past Simple"],"rows":[["O'tmishdan <b>hozirgacha</b> bo'lgan davr haqida (Past → Now)","O'tmishda <b>tugagan</b> davr haqida"],["I have lost my key. (kalit hozir ham yo'q)","I lost my key yesterday. / I was in London in the summer."],["Yangi ma'lumot berilganda: <i>Ow, I have burnt myself.</i>","Shu ma'lumot davom ettirilganda: <i>How did it happen? — I touched a hot pan.</i>"]]},{"t":"rule","x":"<b>When, What time</b> bilan ish-harakat vaqti so'ralganda Past Simple ishlatiladi: <i>What time did you go to sleep?</i>"}],"quiz":[{"q":"Choose the correct word: 'She has been here ___ 6 a.m.'","o":["for","since","during","ago"],"a":1,"e":"6 a.m. — boshlanish nuqtasi, since ishlatiladi."},{"q":"Choose the correct word: 'I have lived here ___ ten years.'","o":["since","for","from","ago"],"a":1,"e":"ten years — davomiylik, for ishlatiladi."},{"q":"Choose the correct sentence.","o":["They have worked for all night.","They have worked all night.","They have worked since all night.","They worked for all the night since."],"a":1,"e":"all bilan boshlanuvchi iboradan oldin for ishlatilmaydi."},{"q":"'He worked there for 40 years.' What does it mean?","o":["He still works there.","He no longer works there.","He will work there for 40 years.","He started working there 40 years from now."],"a":1,"e":"For + Past Simple tugagan davrni bildiradi."},{"q":"Choose the correct sentence.","o":["I have worked there since I have left school.","I have worked there since I left school.","I worked there since I have left school.","I have worked there for I left school."],"a":1,"e":"since + clause: ergash gapda Past Simple ishlatiladi."},{"q":"It is 2 p.m. now. Choose the correct sentence.","o":["Tom has rung up three times this morning.","Tom rang up three times this morning.","Tom rings up three times this morning.","Tom have rung up three times this morning."],"a":1,"e":"Ertalab tugagan — Past Simple."},{"q":"The mail carrier usually comes between 9 and 10. It is 11 a.m. now. Choose the correct question.","o":["Has the mail carrier come this morning?","Did the mail carrier come this morning?","Is the mail carrier come this morning?","Have the mail carrier came this morning?"],"a":1,"e":"Odatiy kelish vaqti o'tib ketgan — Past Simple."},{"q":"Choose the correct sentence.","o":["I have lost my key yesterday.","I lost my key yesterday.","I have losed my key yesterday.","I lose my key yesterday."],"a":1,"e":"yesterday — tugagan vaqt, Past Simple."},{"q":"Choose the correct question.","o":["What time have you gone to bed?","What time did you go to bed?","What time you have gone to bed?","What time has you gone to bed?"],"a":1,"e":"What time / When bilan vaqt so'ralganda Past Simple ishlatiladi."},{"q":"'I have been here for the last week.' What does 'the last week' show?","o":["a starting point","a period of seven days","a future time","a single moment"],"a":1,"e":"the last week — yetti kunlik davr (davomiylik)."}]},{"id":"p4-05","en":"Present Perfect Continuous Tense","uz":"Hozirgi tugallangan davomli zamon","emoji":"🔄","level":"B1","group":"Fe'l va zamonlar","summary":"O'tmishda boshlanib hozir ham davom etayotgan yoki yaqinda tugagan ish-harakatlar uchun Present Perfect Continuous va uning Present Perfect Simple'dan farqi.","blocks":[{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Darak: S + have/has + been + V-ing + C + M"},{"t":"formula","x":"Inkor: S + have/has + not + been + V-ing + C + M"},{"t":"formula","x":"So'roq: Have/Has + S + been + V-ing + C + M?"},{"t":"h","x":"1. O'tmishda boshlanib, hali davom etayotgan yoki yaqinda tugagan ish-harakat"},{"t":"ex","en":"I have been waiting for him. He still hasn't come.","uz":"Men uni kutyapman. U hali ham kelmadi."},{"t":"ex","en":"I am sorry I am late. Have you been waiting long?","uz":"Kechikkanim uchun uzr. Ko'pdan beri kutyapsanmi?"},{"t":"h","x":"2. Ish-harakat qachondan beri davom etayotganini so'rash yoki aytish"},{"t":"p","x":"Bunda asosan <b>how long, for, since</b> ishlatiladi."},{"t":"ex","en":"How long have you been learning English?","uz":"Qachondan beri ingliz tilini o'rganyapsan?"},{"t":"ex","en":"She has been reading a book for two hours.","uz":"U ikki soatdan beri kitob o'qiyapti."},{"t":"h","x":"Ikkala zamonda ham berish mumkin bo'lgan holatlar"},{"t":"p","x":"O'tmishda boshlanib hali davom etayotgan yoki yaqinda tugagan ish-harakatni ko'pincha ikkala zamonda ham ifodalash mumkin:"},{"t":"ex","en":"I have slept for six hours. / I have been sleeping for six hours.","uz":"Olti soat uxladim / olti soatdan beri uxlayapman."},{"t":"ex","en":"How long have you worked? / How long have you been working?","uz":"Qancha vaqtdan beri ishlayapsan?"},{"t":"rule","x":"Diqqat: bu ma'noda Present Perfect Continuous vaqt iborasi bilan ham, vaqt iborasisiz ham ishlatiladi. Present Perfect Simple esa bu ma'noda (davom etayotgan harakat) vaqt iborasisiz ishlatilmaydi. <i>It has been raining.</i> — Yomg'ir yog'ib turgan edi (yer ho'l). <i>It has rained.</i> — Yomg'ir yog'di (shunchaki natija/fakt)."},{"t":"h","x":"Takrorlangan ish-harakat"},{"t":"p","x":"Present Perfect Simple bilan ifodalangan takrorlangan ish-harakatni \"davomli\" harakat sifatida Present Perfect Continuous bilan ham berish mumkin:"},{"t":"ex","en":"I have knocked on the door three times.","uz":"Eshikni uch marta taqillatdim."},{"t":"ex","en":"I have been knocking on the door.","uz":"Eshikni taqillatib turibman."},{"t":"h","x":"Yagona ish-harakatda farq"},{"t":"p","x":"Agar ish-harakat bitta bo'lsa, ikki zamon o'rtasida farq bor: <b>Present Perfect Simple</b> — <b>natijani</b> ta'kidlaydi; <b>Present Perfect Continuous</b> — so'nggi bir soat, ikki soat va h.k. vaqt <b>qanday o'tganini</b> (jarayonni) ta'kidlaydi."},{"t":"table","head":["Present Perfect Simple (natija)","Present Perfect Continuous (jarayon)"],"rows":[["I have cleaned the car. The car is clean now.","I have been cleaning the car for the last two hours."],["She has painted the room. (xona bo'yalgan)","She has been painting the room. (bo'yash bilan band edi, tugamagan bo'lishi mumkin)"]]}],"quiz":[{"q":"Choose the correct form: 'She ___ a book for two hours.'","o":["has been reading","have been reading","has being reading","is been reading"],"a":0,"e":"has + been + V-ing."},{"q":"Choose the correct question.","o":["How long are you learning English?","How long have you been learning English?","How long have you be learning English?","How long did you been learning English?"],"a":1,"e":"Qachondan beri — How long + have + S + been + V-ing."},{"q":"Choose the correct negative form.","o":["He has not been working.","He has been not working.","He not has been working.","He hasn't be working."],"a":0,"e":"S + has + not + been + V-ing."},{"q":"Which sentence emphasizes the RESULT?","o":["I have been cleaning the car.","I have cleaned the car. It is clean now.","I was cleaning the car.","I have been cleaning the car for two hours."],"a":1,"e":"Present Perfect Simple natijani ta'kidlaydi."},{"q":"Which sentence emphasizes how the time was spent?","o":["She has painted the room.","She has been painting the room for the last two hours.","She painted the room.","She paints the room."],"a":1,"e":"Present Perfect Continuous jarayonni ta'kidlaydi."},{"q":"Choose the correct sentence.","o":["I have been knocking on the door three times.","I have knocked on the door three times.","I have been knocked on the door three times.","I knocking on the door three times."],"a":1,"e":"Aniq miqdor (three times) bo'lsa Present Perfect Simple ishlatiladi."},{"q":"'I am sorry I am late. ___ long?'","o":["Have you waited been","Have you been waiting","Are you been waiting","Did you been waiting"],"a":1,"e":"Hozirgacha davom etgan kutish — Present Perfect Continuous."},{"q":"The ground is wet. Which sentence best describes it?","o":["It has been raining.","It is raining tomorrow.","It rains.","It has been rain."],"a":0,"e":"Yaqinda tugagan davomli harakat va uning izi — Present Perfect Continuous."},{"q":"Which pair means almost the same?","o":["I have slept for six hours / I have been sleeping for six hours","I slept / I will sleep","I have slept / I am sleeping tomorrow","I sleep / I slept"],"a":0,"e":"Bunday holatda ikkala zamon ham ishlatilishi mumkin."}]},{"id":"p4-06","en":"Past Perfect Tense and Time Clauses","uz":"O'tgan tugallangan zamon va vaqt ergash gaplari","emoji":"⏪","level":"B1","group":"Fe'l va zamonlar","summary":"O'tmishdagi boshqa bir vaqtdan oldin tugagan ish-harakatlar uchun Past Perfect va uning when, until, before, after bilan qo'llanishi.","blocks":[{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Darak: S + had + past participle (V3) + C + M"},{"t":"formula","x":"Inkor: S + had + not + past participle (V3) + C + M"},{"t":"formula","x":"So'roq: Had + S + past participle (V3) + C + M?"},{"t":"h","x":"Qo'llanishi"},{"t":"p","x":"Past Perfect o'tgan zamondagi bir vaqtdan <b>oldin tugagan</b> ish-harakatni ifodalaydi."},{"t":"ex","en":"When I came, he had gone out.","uz":"Men kelganimda, u chiqib ketgan edi."},{"t":"p","x":"Past Perfect — <b>Present Perfect'ning o'tgan zamondagi ekvivalenti</b>:"},{"t":"ex","en":"Ann has just left the room; if you hurry, you'll catch her.","uz":"Ann hozirgina xonadan chiqdi; shoshilsang, yetib olasan."},{"t":"ex","en":"When I arrived, Ann had just left.","uz":"Men yetib kelganimda, Ann hozirgina chiqib ketgan edi."},{"t":"p","x":"Past Perfect o'tmishdagi biror vaqtdan oldin boshlangan va:"},{"t":"list","items":["<b>A)</b> o'sha boshqa vaqtda ham davom etayotgan;","<b>B)</b> o'sha vaqtda hozirgina tugagan;","<b>C)</b> o'sha vaqtdan ancha oldin tugagan ish-harakatlar uchun ishlatilishi mumkin."]},{"t":"ex","en":"A) Bill was in uniform when I met him. He had been a soldier for ten years and planned to stay in the army until he was 30.","uz":"Men Billni uchratganimda u harbiy kiyimda edi. U o'n yildan beri askar edi va 30 yoshgacha armiyada qolishni rejalashtirgan edi."},{"t":"ex","en":"B) The old oak tree, which had stood in the churchyard since the church was built, suddenly crashed to the ground.","uz":"Cherkov qurilganidan beri cherkov hovlisida turgan qari eman daraxti birdan yerga qulab tushdi."},{"t":"ex","en":"C) He had served in the army for ten years; then he had retired and married. His children were now at school.","uz":"U o'n yil armiyada xizmat qilgan, keyin iste'foga chiqib uylangan edi. Endi uning bolalari maktabda o'qirdi."},{"t":"p","x":"Past Perfect hikoyada <b>Past Simple'ning o'tgan zamondagi ekvivalenti</b> sifatida ham ishlatiladi (hikoya boshlanishidan oldingi voqealar uchun):"},{"t":"ex","en":"Tom was 23 when our story begins. His father had died five years before, and since then Tom had lived alone. His father had advised him not to get married until he was 35, and he intended to follow his advice.","uz":"Hikoyamiz boshlanganda Tom 23 yoshda edi. Otasi besh yil oldin vafot etgan, o'shandan beri Tom yolg'iz yashagan edi..."},{"t":"ex","en":"He arrived at 2 and was told to wait.","uz":"U soat 2 da yetib keldi va unga kutish aytildi. (keyin aytildi)"},{"t":"ex","en":"He arrived at 2 and had been told to wait.","uz":"U soat 2 da yetib keldi; unga kutish (oldinroq) aytilgan edi."},{"t":"h","x":"Vaqt ergash gaplarida Past Perfect"},{"t":"p","x":"O'tgan zamondagi ikki gapni <b>when</b> orqali bog'lasak, Past Simple ikki ish-harakat ketma-ket sodir bo'lganini ko'rsatadi:"},{"t":"ex","en":"I asked a new word. He answered correctly. → When I asked a new word, he answered correctly.","uz":"Men yangi so'z so'raganimda, u to'g'ri javob berdi."},{"t":"p","x":"<b>When + Past Perfect</b> birinchi ish-harakat <b>to'liq tugaganini</b> ta'kidlaydi:"},{"t":"ex","en":"When I opened the window, the birds flew out.","uz":"Derazani ochishim bilan qushlar uchib chiqdi."},{"t":"ex","en":"When I had opened the window, the birds flew out.","uz":"Derazani ochib bo'lganimdan keyin qushlar uchib chiqdi."},{"t":"ex","en":"When he swore at her, she slapped his face. / When he had sworn at her, she slapped his face.","uz":"U uni so'kkanida, ayol uning yuziga shapaloq urdi."},{"t":"rule","x":"Bu holatda <b>when</b> o'rnida <b>as soon as, immediately, the moment</b> so'zlari ham kelishi mumkin."},{"t":"p","x":"<b>Till / until</b> va <b>before</b> bilan, ish-harakat to'liq tugaganini (yoki tugamaganini) ta'kidlamoqchi bo'lsak, Past Perfect ishlatiladi:"},{"t":"ex","en":"He refused to go until he had seen all the pictures.","uz":"U hamma rasmlarni ko'rib bo'lmaguncha ketishdan bosh tortdi."},{"t":"ex","en":"Before we had walked ten miles, he complained of sore feet.","uz":"O'n mil yurib ulgurmasimizdan oldin u oyog'i og'riyotganidan shikoyat qildi."},{"t":"p","x":"<b>After</b> bilan ham ish-harakat to'liq tugaganini ta'kidlash uchun Past Perfect ishlatiladi:"},{"t":"ex","en":"After the will had been read, there were angry exclamations.","uz":"Vasiyatnoma o'qib bo'linganidan keyin g'azabli hayqiriqlar yangradi."}],"quiz":[{"q":"Choose the correct form: 'When I came, he ___ out.'","o":["has gone","had gone","goes","had go"],"a":1,"e":"Kelishdan oldin tugagan harakat — had + V3."},{"q":"Choose the correct question form.","o":["Had you finished before he came?","Did you had finished before he came?","Have you had finish before he came?","Had you finish before he came?"],"a":0,"e":"So'roq: Had + S + V3?"},{"q":"Choose the correct negative form.","o":["She hadn't seen the film.","She didn't had seen the film.","She had not see the film.","She not had seen the film."],"a":0,"e":"S + had + not + V3."},{"q":"Past Perfect is the past equivalent of which tense?","o":["Present Simple","Present Perfect","Future Simple","Present Continuous"],"a":1,"e":"Past Perfect — Present Perfect'ning o'tgan zamondagi ekvivalenti."},{"q":"'When I arrived, Ann ___ left.'","o":["has just","had just","just has","was just"],"a":1,"e":"Past Perfect + just: o'tmishdagi vaqtdan hozirgina oldin."},{"q":"Which sentence stresses that the first action was completely finished?","o":["When I opened the window, the birds flew out.","When I had opened the window, the birds flew out.","When I open the window, the birds fly out.","When I was opening the window, the birds flew out."],"a":1,"e":"when + Past Perfect birinchi harakat to'liq tugaganini ta'kidlaydi."},{"q":"Choose the correct sentence.","o":["He refused to go until he has seen all the pictures.","He refused to go until he had seen all the pictures.","He refused to go until he sees all the pictures.","He refused to go until he had see all the pictures."],"a":1,"e":"until + Past Perfect — harakat to'liq tugaguncha."},{"q":"Which word can replace 'when' in 'When I had opened the window, the birds flew out'?","o":["as soon as","because","although","unless"],"a":0,"e":"when o'rnida as soon as, immediately, the moment kelishi mumkin."},{"q":"Choose the correct sentence.","o":["After the will had been read, there were angry exclamations.","After the will has been read, there were angry exclamations.","After the will had been reading, there were angry exclamations.","After the will was been read, there were angry exclamations."],"a":0,"e":"after + Past Perfect (majhul: had been + V3)."},{"q":"'His father ___ five years before, and since then Tom had lived alone.'","o":["has died","had died","dies","was dying"],"a":1,"e":"Hikoyadagi o'tmishdan oldingi voqea — Past Perfect."}]},{"id":"p4-07","en":"Past Perfect Continuous Tense","uz":"O'tgan tugallangan davomli zamon","emoji":"🕰️","level":"B2","group":"Fe'l va zamonlar","summary":"O'tmishdagi bir vaqtgacha davom etgan yoki undan sal oldin tugagan ish-harakatlar uchun Past Perfect Continuous va uning Past Perfect Simple'dan farqi.","blocks":[{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"Darak: S + had + been + V-ing + C + M"},{"t":"formula","x":"Inkor: S + had + not + been + V-ing + C + M"},{"t":"formula","x":"So'roq: Had + S + been + V-ing + C + M?"},{"t":"h","x":"Qo'llanishi"},{"t":"p","x":"O'tgan zamonda gapirilayotgan vaqtdan <b>oldin boshlanib</b>, o'sha vaqtgacha <b>davom etgan</b> yoki undan <b>sal oldin tugagan</b> ish-harakatlar uchun Past Perfect Continuous ishlatiladi. Bu holatda Past Perfect Simple ham noto'g'ri emas:"},{"t":"ex","en":"It was now six and he was tired because he had been working since dawn.","uz":"Soat olti edi, u charchagan edi, chunki tongdan beri ishlab kelayotgan edi."},{"t":"ex","en":"It was now six and he was tired because he had worked since dawn.","uz":"Soat olti edi, u charchagan edi, chunki tongdan beri ishlagan edi."},{"t":"rule","x":"Bunday holatlarda Past Perfect Simple albatta vaqt iborasi (since dawn, for two hours...) bilan kelishi shart."},{"t":"h","x":"Takrorlangan ish-harakat"},{"t":"p","x":"Past Perfect Simple bilan ifodalangan takrorlangan ish-harakatni davomli harakat sifatida Past Perfect Continuous bilan berish mumkin:"},{"t":"ex","en":"He had tried five times to get her on the phone.","uz":"U besh marta unga telefon orqali bog'lanishga uringan edi."},{"t":"ex","en":"He had been trying to get her on the phone.","uz":"U unga telefon orqali bog'lanishga urinib kelayotgan edi."},{"t":"h","x":"Yagona ish-harakatda farq"},{"t":"ex","en":"He had repaired the engine by six.","uz":"U soat oltigacha motorni ta'mirlab bo'lgan edi. (ish tugagan)"},{"t":"ex","en":"He had been repairing the engine by six.","uz":"U soat oltigacha motorni ta'mirlash bilan band edi. (tugaganmi — noma'lum)"},{"t":"p","x":"Past Perfect Continuous bilan berilgan ish-harakat o'tmishdagi gapirilayotgan vaqtgacha <b>davom etadi</b> yoki undan <b>sal oldin</b> tugaydi. Past Perfect Simple bilan berilgan ish-harakat esa o'sha vaqtgacha davom etgan, sal oldin tugagan yoki hatto <b>ancha oldin</b> tugagan bo'lishi mumkin."},{"t":"ex","en":"I had been painting the door.","uz":"Men eshikni bo'yayotgan edim. (bo'yoq hali qurimagani aniq)"},{"t":"ex","en":"I had painted the door.","uz":"Men eshikni bo'yab bo'lgan edim. (bo'yoq qurigan ham, qurimagan ham bo'lishi mumkin)"},{"t":"h","x":"Qancha vaqtdan beri davom etgani"},{"t":"p","x":"Biror ish-harakat sodir bo'lgunicha ikkinchi ish-harakat <b>qancha vaqtdan beri</b> davom etayotganini ko'rsatish uchun Past Perfect Continuous ishlatiladi:"},{"t":"ex","en":"The football match had to be stopped. They had been playing for half an hour when there was a terrible storm.","uz":"Futbol o'yinini to'xtatishga to'g'ri keldi. Kuchli bo'ron boshlanganda ular yarim soatdan beri o'ynayotgan edi."}],"quiz":[{"q":"Choose the correct form: 'He was tired because he ___ since dawn.'","o":["had been working","has been working","had been worked","was been working"],"a":0,"e":"had + been + V-ing: o'tmishdagi vaqtgacha davom etgan harakat."},{"q":"Choose the correct question.","o":["Had you been waiting long?","Had you waiting long?","Have you been waited long?","Did you had been waiting long?"],"a":0,"e":"So'roq: Had + S + been + V-ing?"},{"q":"Choose the correct negative form.","o":["They had not been playing.","They had been not playing.","They hadn't being playing.","They not had been playing."],"a":0,"e":"S + had + not + been + V-ing."},{"q":"'They ___ for half an hour when there was a terrible storm.'","o":["have been playing","had been playing","were played","has played"],"a":1,"e":"Bo'ronga qadar qancha vaqt davom etgani — Past Perfect Continuous."},{"q":"'I had been painting the door.' What do we know?","o":["The paint was certainly still wet.","The paint was certainly dry.","I painted it many years ago.","I will paint it later."],"a":0,"e":"Past Perfect Continuous: harakat sal oldin tugagan, bo'yoq hali qurimagan."},{"q":"Which sentence clearly shows the job was finished?","o":["He had been repairing the engine by six.","He had repaired the engine by six.","He was repairing the engine at six.","He repairs the engine at six."],"a":1,"e":"Past Perfect Simple natija — ish tugagan."},{"q":"Choose the correct sentence.","o":["He had been trying five times to get her on the phone.","He had tried five times to get her on the phone.","He has been tried five times to call her.","He had trying five times to call her."],"a":1,"e":"Aniq miqdor (five times) bo'lsa Past Perfect Simple ishlatiladi."},{"q":"When Past Perfect Simple is used instead of the continuous for an action continuing up to a past moment, what must it have?","o":["a time phrase","a question word","a modal verb","the word 'yet'"],"a":0,"e":"Bunday holda Past Perfect Simple vaqt iborasi bilan kelishi shart."},{"q":"Choose the correct form: 'The match had to be ___.'","o":["stop","stopped","stopping","stops"],"a":1,"e":"Majhul: had to be + V3 (stopped)."}]},{"id":"p4-08","en":"To Be Going To","uz":"To be going to tuzilmasi","emoji":"🎯","level":"A2","group":"Fe'l va zamonlar","summary":"Niyat, reja va dalilga asoslangan taxminni ifodalovchi \"to be going to\" va o'tmishdagi amalga oshmagan niyat uchun \"was/were going to\".","blocks":[{"t":"h","x":"Tuzilishi"},{"t":"formula","x":"S + am/is/are + going to + bare infinitive (V1)"},{"t":"h","x":"1. Niyat va istak"},{"t":"p","x":"Biror kishining <b>niyati, istagi, xohishini</b> ifodalash uchun <b>to be going to</b> ishlatiladi. Kelishib qo'yilgan aniq rejalar uchun Present Continuous ham qo'llanadi."},{"t":"ex","en":"I am going to visit my relatives.","uz":"Men qarindoshlarimni ko'rgani bormoqchiman."},{"t":"ex","en":"I am seeing my doctor tomorrow.","uz":"Ertaga shifokorim qabuliga boraman. (kelishilgan reja — Present Continuous)"},{"t":"h","x":"2. Dalilga asoslangan taxmin"},{"t":"p","x":"Hozirgi biror belgiga, dalilga <b>tayanib</b> aytilgan aniq taxmin uchun ham <b>to be going to</b> ishlatiladi."},{"t":"ex","en":"His maths is very poor. If he does not study hard, he is going to fail the final exam.","uz":"Uning matematikasi juda yomon. Qattiq o'qimasa, yakuniy imtihondan yiqiladi."},{"t":"ex","en":"Look at those black clouds! It is going to rain.","uz":"Anavi qora bulutlarga qara! Yomg'ir yog'adi."},{"t":"h","x":"Was / were going to"},{"t":"p","x":"<b>Was / were going to</b> o'tgan zamondagi niyatni bildiradi; ko'pincha bu niyat <b>amalga oshmagan</b> bo'ladi."},{"t":"formula","x":"S + was/were + going to + V1"},{"t":"ex","en":"I was going to phone you last night, but I could not.","uz":"Kecha kechqurun senga qo'ng'iroq qilmoqchi edim, lekin qila olmadim."}],"quiz":[{"q":"Choose the correct form: 'I ___ visit my relatives.'","o":["am going to","going to","am go to","is going to"],"a":0,"e":"S + am/is/are + going to + V1."},{"q":"Look at those black clouds! It ___ rain.","o":["is going to","was going to","goes to","has gone to"],"a":0,"e":"Dalilga (qora bulutlar) asoslangan taxmin — be going to."},{"q":"Choose the correct form after 'going to'.","o":["to visited","visiting","visit","visits"],"a":2,"e":"going to dan keyin bare infinitive (V1) keladi."},{"q":"'I ___ phone you last night, but I could not.'","o":["am going to","was going to","will","have gone to"],"a":1,"e":"O'tmishdagi amalga oshmagan niyat — was going to."},{"q":"What does 'was/were going to' usually show?","o":["a past intention that often did not happen","a present habit","a finished result","a general truth"],"a":0,"e":"Was/were going to — ko'pincha amalga oshmagan o'tmishdagi niyat."},{"q":"Choose the correct sentence.","o":["They is going to buy a car.","They are going to buy a car.","They going to buy a car.","They are going buy a car."],"a":1,"e":"They bilan are ishlatiladi: are going to + V1."},{"q":"'He hasn't studied at all. He ___ the exam.'","o":["is going to fail","was going to fail","fails yesterday","has going to fail"],"a":0,"e":"Hozirgi holatga asoslangan taxmin — is going to."},{"q":"Choose the correct question.","o":["Are you going to stay here?","Do you going to stay here?","You are going to stay here?","Are you go to stay here?"],"a":0,"e":"So'roq: Am/Is/Are + S + going to + V1?"}]},{"id":"p4-09","en":"Future Perfect and Future Perfect Continuous","uz":"Kelasi tugallangan va kelasi tugallangan davomli zamon","emoji":"🔮","level":"B2","group":"Fe'l va zamonlar","summary":"Kelajakdagi ma'lum vaqtgacha tugaydigan yoki davom etadigan ish-harakatlar uchun Future Perfect va Future Perfect Continuous.","blocks":[{"t":"h","x":"Future Perfect: tuzilishi"},{"t":"formula","x":"Darak: S + will/shall + have + past participle (V3) + C + M"},{"t":"formula","x":"Inkor: S + will/shall + not + have + past participle (V3) + C + M"},{"t":"formula","x":"So'roq: Will/Shall + S + have + past participle (V3) + C + M?"},{"t":"h","x":"Qo'llanishi"},{"t":"p","x":"Future Perfect asosan <b>by</b> bilan tuzilgan vaqt iboralari bilan ishlatiladi: <i>by then, by that time, by the end of the week / month / year</i>."},{"t":"ex","en":"By the end of the month, he will have been here for ten years.","uz":"Oy oxiriga kelib u bu yerda o'n yil bo'ladi."},{"t":"p","x":"Future Perfect kelasi zamonda <b>ma'lum bir vaqtgacha tugallangan</b> bo'ladigan ish-harakatlarni ifodalaydi."},{"t":"ex","en":"Now it is 3 December. David is very worried about an exam that he is taking on 13 December. Somebody planning a party may say: \"We had better wait till 14 December. David will have had his exam by then, so he will be able to enjoy himself.\"","uz":"Bugun 3-dekabr. David 13-dekabrdagi imtihonidan xavotirda. Ziyofat rejalashtirayotgan kishi: \"14-dekabrgacha kutganimiz ma'qul. Ungacha David imtihonini topshirib bo'lgan bo'ladi va bemalol dam oladi\", deydi."},{"t":"h","x":"Future Perfect Continuous: tuzilishi"},{"t":"formula","x":"Darak: S + will/shall + have + been + V-ing + C + M"},{"t":"formula","x":"Inkor: S + will/shall + not + have + been + V-ing + C + M"},{"t":"formula","x":"So'roq: Will/Shall + S + have + been + V-ing + C + M?"},{"t":"h","x":"Qo'llanishi"},{"t":"p","x":"Future Perfect Continuous ham <b>by</b> bilan tuzilgan vaqt iboralari bilan ishlatiladi:"},{"t":"ex","en":"By the end of the month, he will have been acting for 30 years.","uz":"Oy oxiriga kelib u 30 yildan beri aktyorlik qilayotgan bo'ladi."},{"t":"p","x":"U kelasi zamonda aniq bir vaqtgacha <b>davom etgan</b> yoki undan <b>sal oldin tugagan</b> ish-harakatlar uchun ishlatiladi; bu holatda Future Perfect Simple ham ishlatilishi mumkin."},{"t":"ex","en":"By then he will have been studying.","uz":"Ungacha u o'qib bo'lgan / o'qiyotgan bo'ladi."},{"t":"p","x":"Kelasi zamondagi ma'lum vaqtgacha ish-harakat <b>qancha vaqtdan beri</b> davom etayotganini aytish yoki so'rash uchun ishlatiladi:"},{"t":"ex","en":"By the end of the month, he will have been living here for 40 years.","uz":"Oy oxiriga kelib u bu yerda 40 yildan beri yashayotgan bo'ladi."},{"t":"rule","x":"Takrorlanuvchi ish-harakatni Future Perfect Continuous bilan davomli harakat sifatida berish mumkin. Ammo <b>miqdor</b> (necha marta, nechta) aytilsa, Future Perfect Continuous ishlatilmaydi — Future Perfect Simple ishlatiladi."},{"t":"ex","en":"By the end of the month, he will have climbed 60 mountains.","uz":"Oy oxiriga kelib u 60 ta tog'ga chiqqan bo'ladi. (miqdor bor — Simple)"},{"t":"ex","en":"By the end of the month, he will have been climbing mountains for ten years.","uz":"Oy oxiriga kelib u o'n yildan beri tog'larga chiqib kelayotgan bo'ladi."}],"quiz":[{"q":"Choose the correct form: 'By then David ___ his exam.'","o":["will have had","will had","will have have","has had"],"a":0,"e":"Future Perfect: will + have + V3."},{"q":"Which time expression is typical for the Future Perfect?","o":["by the end of the month","yesterday","every day","ago"],"a":0,"e":"Future Perfect asosan by ... iboralari bilan ishlatiladi."},{"q":"Choose the correct negative form.","o":["She will not have finished.","She will have not finish.","She not will have finished.","She won't has finished."],"a":0,"e":"S + will + not + have + V3."},{"q":"Choose the correct question.","o":["Will you have finished by six?","Will you finished by six?","Have you will finished by six?","Will you have finish by six?"],"a":0,"e":"So'roq: Will + S + have + V3?"},{"q":"Choose the Future Perfect Continuous form.","o":["he will have been acting","he will be acted","he will have acted been","he has been acting"],"a":0,"e":"will + have + been + V-ing."},{"q":"'By the end of the month, he ___ 60 mountains.'","o":["will have been climbing","will have climbed","will climbing","has been climbing"],"a":1,"e":"Miqdor (60) aytilganda Future Perfect Continuous ishlatilmaydi."},{"q":"'By the end of the month, he ___ here for 40 years.'","o":["will have been living","will be lived","will living","has living"],"a":0,"e":"Qancha vaqtdan beri davom etayotgani — Future Perfect Continuous."},{"q":"What does the Future Perfect express?","o":["an action completed before a certain future time","a habit in the past","an action happening now","a general truth"],"a":0,"e":"Kelajakdagi ma'lum vaqtgacha tugallangan ish-harakat."},{"q":"Choose the correct sentence.","o":["By 2030 I will have been working here for 20 years.","By 2030 I will have been work here for 20 years.","By 2030 I will been working here for 20 years.","By 2030 I have will been working here for 20 years."],"a":0,"e":"will + have + been + V-ing."}]},{"id":"p4-10","en":"Passive Voice","uz":"Majhul nisbat (Passive Voice)","emoji":"🔁","level":"B1","group":"Majhul nisbat va modal fe'llar","summary":"Bajaruvchi noma'lum yoki muhim bo'lmaganda ishlatiladigan majhul nisbat va uning turli zamonlardagi tuzilishi.","blocks":[{"t":"h","x":"Qachon ishlatiladi?"},{"t":"list","items":["Ish-harakatning <b>bajaruvchisi noma'lum</b> bo'lsa;","Bajaruvchi <b>ahamiyatsiz, muhim emas</b> bo'lsa."]},{"t":"ex","en":"Tom cleaned the room.","uz":"Tom xonani tozaladi. (aniq nisbat)"},{"t":"ex","en":"The room was cleaned.","uz":"Xona tozalandi. (majhul nisbat)"},{"t":"h","x":"Bajaruvchini ko'rsatish"},{"t":"p","x":"Bajaruvchini gap oxirida <b>by</b> yordamida ko'rsatish mumkin: <b>by + atoqli ot</b> yoki <b>by + kelishikdagi olmosh</b> (him, her, them...)."},{"t":"ex","en":"The room was cleaned by Tom / by him.","uz":"Xona Tom / u tomonidan tozalandi."},{"t":"h","x":"Majhul nisbat qachon yasalmaydi?"},{"t":"p","x":"Faqat hol (modifier) bor gapdan majhul nisbat yasab bo'lmaydi. Gapni majhulga aylantirish uchun unda kamida bitta <b>to'ldiruvchi (complement)</b> bo'lishi kerak."},{"t":"ex","en":"I build the school. → The school is built.","uz":"Maktab quriladi. ✓"},{"t":"ex","en":"I go to school. → ✗ The school is gone.","uz":"Noto'g'ri — 'to school' bu hol, to'ldiruvchi emas."},{"t":"h","x":"Zamonlar bo'yicha tuzilishi"},{"t":"p","x":"Belgilar: <b>Sc</b> — majhul gapning egasi (aniq gapdagi to'ldiruvchi), <b>Viii</b> — fe'lning 3-shakli (past participle), <b>Vp.s.</b> — o'tgan zamon shakli."},{"t":"table","head":["Zamon","Aniq nisbat","Majhul nisbat"],"rows":[["Present Simple","S + V1 + C + M","Sc + am/is/are + V3 + M"],["Present Continuous","S + am/is/are + V-ing + C + M","Sc + am/is/are + being + V3 + M"],["Past Simple","S + V2 + C + M","Sc + was/were + V3 + M"],["Past Continuous","S + was/were + V-ing + C + M","Sc + was/were + being + V3 + M"],["Future Simple","S + will/shall + V1 + C + M","Sc + will/shall + be + V3 + M"],["Present Perfect","S + have/has + V3 + C + M","Sc + have/has + been + V3 + M"],["Past Perfect","S + had + V3 + C + M","Sc + had + been + V3 + M"],["Future Perfect","S + will/shall + have + V3 + C + M","Sc + will/shall + have + been + V3 + M"]]},{"t":"h","x":"Misollar"},{"t":"ex","en":"I read English books in the library. → English books are read in the library.","uz":"Kutubxonada ingliz tilidagi kitoblar o'qiladi."},{"t":"ex","en":"He is driving a car on the highway. → A car is being driven by him on the highway.","uz":"Avtomobil u tomonidan katta yo'lda haydalmoqda."},{"t":"ex","en":"She sang a song. → A song was sung by her.","uz":"Qo'shiq u tomonidan kuylandi."},{"t":"ex","en":"I was speaking to Tom. → Tom was being spoken to.","uz":"Tom bilan gaplashilayotgan edi. (predlog 'to' saqlanadi)"},{"t":"ex","en":"She will hit the ball. → The ball will be hit.","uz":"To'pga zarba beriladi."},{"t":"ex","en":"She has lost the key. → The key has been lost.","uz":"Kalit yo'qolib qoldi."},{"t":"ex","en":"They had cancelled the party. → The party had been cancelled.","uz":"Ziyofat bekor qilingan edi."},{"t":"ex","en":"They will have drunk all the beer. → All the beer will have been drunk.","uz":"Hamma pivo ichib bo'lingan bo'ladi."},{"t":"rule","x":"Diqqat: <b>Future Continuous, Present Perfect Continuous, Past Perfect Continuous</b> va <b>Future Perfect Continuous</b> zamonlarining majhul nisbat shakli ishlatilmaydi."}],"quiz":[{"q":"Choose the passive: 'Tom cleaned the room.'","o":["The room is cleaned by Tom.","The room was cleaned by Tom.","The room was clean by Tom.","The room has cleaning by Tom."],"a":1,"e":"Past Simple → was/were + V3."},{"q":"Choose the passive: 'He is driving a car.'","o":["A car is driven by him.","A car is being driven by him.","A car was being drive by him.","A car is been driven by him."],"a":1,"e":"Present Continuous → am/is/are + being + V3."},{"q":"Choose the passive: 'She has lost the key.'","o":["The key has been lost.","The key has lost.","The key was been lost.","The key have been lost."],"a":0,"e":"Present Perfect → have/has + been + V3."},{"q":"Choose the passive: 'She will hit the ball.'","o":["The ball will hit.","The ball will be hit.","The ball will been hit.","The ball is will be hit."],"a":1,"e":"Future Simple → will + be + V3."},{"q":"Choose the passive: 'They had cancelled the party.'","o":["The party had cancelled.","The party had been cancelled.","The party has been cancelled.","The party was had cancelled."],"a":1,"e":"Past Perfect → had + been + V3."},{"q":"Which sentence CANNOT be changed into the passive?","o":["I build the school.","She sang a song.","I go to school.","They cancelled the party."],"a":2,"e":"Gapda to'ldiruvchi yo'q (to school — hol), majhul yasab bo'lmaydi."},{"q":"Choose the correct passive: 'I read English books in the library.'","o":["English books are read in the library.","English books is read in the library.","English books are reading in the library.","English books were readed in the library."],"a":0,"e":"Present Simple → are + V3 (read)."},{"q":"How do we show the doer with a pronoun?","o":["by he","by him","from him","with he"],"a":1,"e":"by + kelishikdagi olmosh: by him."},{"q":"Which tense has no commonly used passive form?","o":["Present Perfect","Past Simple","Present Perfect Continuous","Future Simple"],"a":2,"e":"Perfect Continuous zamonlar va Future Continuous'ning majhul shakli ishlatilmaydi."},{"q":"Choose the passive: 'They will have drunk all the beer.'","o":["All the beer will have been drunk.","All the beer will been drunk.","All the beer will have drunk.","All the beer will be have drunk."],"a":0,"e":"Future Perfect → will + have + been + V3."}]},{"id":"p5-01","en":"Modal Verbs: Can, Could, May, Might","uz":"Modal fe'llar: can, could, may, might","emoji":"🔑","level":"A2","group":"Majhul nisbat va modal fe'llar","summary":"Modal fe'llar yordamchi fe'l vazifasida keladi va ulardan keyin doim to'siz infinitiv ishlatiladi. Bu darsda qobiliyat, iltimos, ruxsat va ehtimollikni bildiruvchi can/could va may/might o'rganiladi.","blocks":[{"t":"h","x":"Modal fe'llar haqida umumiy qoida"},{"t":"p","x":"Modal fe'llar (<i>modal verbs</i>) gapda <b>yordamchi fe'l</b> (auxiliary) vazifasida keladi. Ulardan keyin har doim <b>bare infinitive</b> — <code>to</code>siz fe'lning birinchi shakli ishlatiladi."},{"t":"formula","x":"S + modal verb + V (bare infinitive) + ..."},{"t":"ex","en":"I should help him with his maths.","uz":"Men unga matematikadan yordam berishim kerak."},{"t":"ex","en":"He can drive any means of transport.","uz":"U har qanday transport vositasini haydashi mumkin (haydashni biladi)."},{"t":"rule","x":"Diqqat: modal fe'ldan keyin <code>to</code> qo'yilmaydi va 3-shaxs birlikda -s qo'shilmaydi: <i>He can swim</i> (<i>He cans to swim</i> emas)."},{"t":"h","x":"Can / could"},{"t":"p","x":"<b>Can</b> hozirgi va kelasi zamon uchun ishlatiladi va «qo'lidan kelmoq, qila olmoq, qobiliyatga ega bo'lmoq» ma'nolarini beradi."},{"t":"ex","en":"I can swim.","uz":"Men suza olaman."},{"t":"ex","en":"He can sing.","uz":"U qo'shiq aytishni biladi."},{"t":"ex","en":"We are going to the river. Can you swim?","uz":"Biz daryoga ketyapmiz. Suza olasanmi?"},{"t":"p","x":"<b>Could</b> — <b>can</b> ning o'tgan zamon shakli."},{"t":"ex","en":"When I was young, I could ride a horse.","uz":"Yoshligimda ot mina olardim."},{"t":"h","x":"Can / could bilan iltimos, ruxsat va so'rash"},{"t":"list","items":["<b>Can you …? / Could you …?</b> — kimdandir biror ish qilishni so'raganda (iltimos). <i>Could</i> biroz muloyimroq.","<b>Can I …?</b> — ruxsat so'raganda.","<b>Can I have …?</b> — biror narsani so'raganda."]},{"t":"ex","en":"Can you help me?","uz":"Menga yordam bera olasizmi?"},{"t":"ex","en":"Could you open the window, please?","uz":"Iltimos, derazani ochib bera olasizmi?"},{"t":"ex","en":"Can I attend the meeting?","uz":"Yig'ilishda qatnashsam bo'ladimi?"},{"t":"ex","en":"Can I have some cheese, please?","uz":"Menga ozgina pishloq bera olasizmi?"},{"t":"h","x":"May / might"},{"t":"p","x":"<b>May</b> hozirgi va kelasi zamon uchun ikki holatda ishlatiladi:"},{"t":"list","items":["<b>ruxsat</b> — «mumkin, ruxsat» ma'nosida;","<b>ehtimollik, taxmin</b> — «balki, ehtimol» ma'nosida."]},{"t":"ex","en":"It may rain.","uz":"Yomg'ir yog'ishi mumkin."},{"t":"ex","en":"You may attend the meeting.","uz":"Siz yig'ilishda qatnashishingiz mumkin (ruxsat)."},{"t":"p","x":"<b>Might</b> — <b>may</b> ning o'tgan zamon shakli (ko'pincha ko'chirma gap va shart gaplarda)."},{"t":"ex","en":"He said that he might come.","uz":"U kelishi mumkinligini aytdi."},{"t":"ex","en":"If you came tomorrow, you might join us.","uz":"Agar ertaga kelsang, bizga qo'shilishing mumkin edi."},{"t":"p","x":"<b>Might</b> ni hozirgi zamonda <b>may</b> ning sinonimi sifatida ham ishlatish mumkin. Bunda ish-harakat sodir bo'lish <b>ehtimoli ancha past</b> bo'ladi."},{"t":"ex","en":"Barcelona may beat Real Madrid.","uz":"Barselona Real Madridni yutishi mumkin (ehtimoli bor)."},{"t":"ex","en":"Navbahor might beat Real Madrid.","uz":"Navbahor Real Madridni yutishi mumkin (lekin ehtimoli juda past)."},{"t":"table","head":["Modal fe'l","Ma'nosi","Misol"],"rows":[["can","qobiliyat, iltimos, ruxsat (hozirgi/kelasi)","I can swim."],["could","can ning o'tgan zamoni; muloyim iltimos","I could ride a horse."],["may","ruxsat; ehtimollik","It may rain."],["might","may ning o'tgan zamoni; past ehtimollik","He might win."]]}],"quiz":[{"q":"Choose the correct sentence.","o":["He can to drive a car.","He cans drive a car.","He can drive a car.","He can driving a car."],"a":2,"e":"Modal fe'ldan keyin to'siz infinitiv keladi va -s qo'shilmaydi."},{"q":"When I was young, I ___ ride a horse.","o":["can","could","may","must"],"a":1,"e":"Could — can ning o'tgan zamon shakli, o'tmishdagi qobiliyatni bildiradi."},{"q":"Which form is used to ask permission?","o":["Can I go out?","Can you go out?","Could you go out?","You can go out."],"a":0,"e":"Can I …? shakli ruxsat so'rash uchun ishlatiladi."},{"q":"___ you open the window, please? (polite request)","o":["May","Must","Could","Should"],"a":2,"e":"Could you …? — kimdandir muloyim iltimos qilish shakli."},{"q":"___ I have some cheese, please?","o":["Can","Must","Should","Ought"],"a":0,"e":"Can I have …? — biror narsani so'rash uchun ishlatiladi."},{"q":"Look at the clouds! It ___ rain.","o":["can","may","must to","could to"],"a":1,"e":"May bu yerda ehtimollik, taxminni bildiradi."},{"q":"In 'You may attend the meeting', 'may' means:","o":["obligation","ability","permission","advice"],"a":2,"e":"May ruxsat ma'nosida ham keladi."},{"q":"Which sentence shows the LOWEST probability?","o":["Navbahor will beat Real Madrid.","Navbahor might beat Real Madrid.","Navbahor may beat Real Madrid.","Navbahor is going to beat Real Madrid."],"a":1,"e":"Might hozirgi zamonda may ga qaraganda pastroq ehtimollikni bildiradi."},{"q":"Might is the past form of:","o":["must","can","may","will"],"a":2,"e":"Might — may ning o'tgan zamon shakli."},{"q":"Choose the correct sentence.","o":["Can I attend to the meeting?","Can I to attend the meeting?","Can I attend the meeting?","Can I attending the meeting?"],"a":2,"e":"Modal fe'ldan keyin to'siz fe'l keladi; attend fe'li predlogsiz ishlatiladi."}]},{"id":"p5-02","en":"Modal Verbs: Must, Have to, Should, Ought to, Had better","uz":"Modal fe'llar: must, have to, should, ought to, had better","emoji":"⚖️","level":"A2","group":"Majhul nisbat va modal fe'llar","summary":"Majburiyat (must, have to), taqiq (mustn't), zarurat yo'qligi (don't have to, needn't), maslahat (should, ought to, had better) va taklif (Would you like…?) shakllari.","blocks":[{"t":"h","x":"Must"},{"t":"p","x":"<b>Must</b> hozirgi va kelasi zamon uchun ishlatiladi va «qilinishi kerak, shart, lozim» deb tarjima qilinadi."},{"t":"ex","en":"I must go right now.","uz":"Men hoziroq ketishim kerak."},{"t":"ex","en":"Must he stay here till noon?","uz":"U shu yerda tushgacha qolishi shartmi?"},{"t":"ex","en":"I must leave tomorrow.","uz":"Men ertaga ketishim shart."},{"t":"h","x":"Have to"},{"t":"p","x":"<b>Have to</b> ham hozirgi va kelasi zamon uchun ishlatiladi va «qilinishi kerak, shart, lozim» ma'nosini beradi. 3-shaxs birlikda <b>has to</b>."},{"t":"ex","en":"Tom has to do this job.","uz":"Tom bu ishni bajarishi kerak."},{"t":"rule","x":"Have to bilan inkor yoki so'roq gap tuzishda <b>do / does</b> (o'tgan zamonda <b>did</b>) yordamchi fe'llari ishlatilishi shart."},{"t":"ex","en":"Does Tom have to do this job?","uz":"Tom bu ishni bajarishi shartmi?"},{"t":"ex","en":"Tom does not have to do this job.","uz":"Tom bu ishni bajarishi shart emas."},{"t":"p","x":"<b>Must</b> va <b>have to</b> ning o'tgan zamon shakli — <b>had to</b>."},{"t":"ex","en":"Yesterday I had to go to work earlier.","uz":"Kecha ishga ertaroq borishimga to'g'ri keldi."},{"t":"h","x":"Must va have to farqi"},{"t":"p","x":"<b>Must</b> so'zlovchining <b>shaxsiy fikri</b>ni (o'zi zarur deb hisoblashini) ifodalaydi. <b>Have to</b> esa <b>ko'pchilik, jamoat fikri</b>, qoida yoki tashqi majburiyatni ifodalaydi."},{"t":"ex","en":"Everyone has to go to military service in our country.","uz":"Mamlakatimizda hamma harbiy xizmatga borishi shart (qonun)."},{"t":"ex","en":"You must sleep earlier.","uz":"Sen ertaroq uxlashing kerak (mening fikrim)."},{"t":"ex","en":"You must see the movie.","uz":"Sen bu filmni albatta ko'rishing kerak (men shunday deb o'ylayman)."},{"t":"ex","en":"You have to see the movie.","uz":"Bu filmni ko'rishing kerak (hamma shunday deydi / majbursan)."},{"t":"h","x":"Mustn't va don't have to"},{"t":"p","x":"<b>Mustn't</b> qat'iy <b>taqiqni</b> bildiradi: «qilmaslik shart, mumkin emas». <b>Don't have to / doesn't have to</b> esa «qilishing shart emas, bunga ehtiyoj yo'q» degan ma'noni beradi."},{"t":"ex","en":"You don't have to drive so fast. We have enough time.","uz":"Bunchalik tez haydashing shart emas. Vaqtimiz yetarli."},{"t":"ex","en":"You mustn't drive so fast.","uz":"Bunchalik tez haydamasliging kerak (mumkin emas)."},{"t":"ex","en":"You mustn't clean the car.","uz":"Mashinani tozalamasliging kerak (taqiq)."},{"t":"ex","en":"You don't have to clean the car.","uz":"Mashinani tozalashing shart emas."},{"t":"p","x":"<b>Don't have to / doesn't have to</b> o'rnida sinonim sifatida <b>don't need to / doesn't need to</b> va <b>needn't</b> ni ishlatish mumkin."},{"t":"ex","en":"You needn't hurry.","uz":"Shoshilishing shart emas."},{"t":"ex","en":"You don't need to hurry.","uz":"Shoshilishingga hojat yo'q."},{"t":"ex","en":"You don't have to hurry.","uz":"Shoshilishing shart emas."},{"t":"h","x":"Should"},{"t":"p","x":"<b>Should</b> maslahat yoki taklif bildirish uchun ishlatiladi va «qilish kerak, lozim, yaxshi bo'ladi» deb tarjima qilinadi."},{"t":"ex","en":"You should try very hard in order to achieve something.","uz":"Biror narsaga erishish uchun juda qattiq harakat qilishing kerak."},{"t":"h","x":"Ought to"},{"t":"p","x":"<b>Should</b> ning sinonimi sifatida <b>ought</b> ishlatiladi; undan keyin <b>to</b> talab qilinadi."},{"t":"ex","en":"You ought to wear warm clothes.","uz":"Issiq kiyim kiyishing kerak."},{"t":"rule","x":"Inkor gapda <b>not</b> ought ga qo'shiladi (<i>ought not to</i>). So'roq gapda <b>ought</b> egadan oldinga o'tadi."},{"t":"ex","en":"Ought I to do like this?","uz":"Men shunday qilishim kerakmi?"},{"t":"ex","en":"You ought not to enter this room.","uz":"Bu xonaga kirmasliging kerak."},{"t":"h","x":"Had better"},{"t":"p","x":"<b>Should</b> ning sinonimi sifatida <b>had better</b> ham ishlatiladi. Undan keyin <b>to'siz infinitiv</b> keladi. Inkor gapda <b>not</b> had better dan keyin qo'yiladi."},{"t":"formula","x":"S + had better (not) + V"},{"t":"ex","en":"You had better go with me.","uz":"Men bilan borganing yaxshiroq."},{"t":"ex","en":"You had better not go with me.","uz":"Men bilan bormaganing ma'qul."},{"t":"h","x":"Would you like something / to do something?"},{"t":"p","x":"Bu shakl biror narsani taklif qilish yoki biror ish-harakatni bajarishni taklif qilish uchun ishlatiladi. Ma'nosi <b>Do you want something / to do something?</b> ga teng, lekin muloyimroq."},{"t":"formula","x":"Would you like + noun? | Would you like + to + V?"},{"t":"ex","en":"Would you like a cup of tea?","uz":"Bir piyola choy ichasizmi?"},{"t":"ex","en":"Would you like to drink a cup of tea?","uz":"Bir piyola choy ichishni xohlaysizmi?"},{"t":"ex","en":"Would you like an apple? = Do you want an apple?","uz":"Olma yeysizmi? = Olma xohlaysizmi?"},{"t":"table","head":["Shakl","Ma'nosi"],"rows":[["must","shart, kerak (shaxsiy fikr)"],["have to / has to","shart, kerak (qoida, jamoat fikri)"],["had to","must / have to ning o'tgan zamoni"],["mustn't","qat'iy taqiq — mumkin emas"],["don't have to / needn't / don't need to","shart emas, ehtiyoj yo'q"],["should / ought to / had better","maslahat, tavsiya"]]}],"quiz":[{"q":"Yesterday I ___ go to work earlier.","o":["must","had to","have to","must to"],"a":1,"e":"Must va have to ning o'tgan zamon shakli — had to."},{"q":"___ Tom have to do this job?","o":["Has","Is","Does","Must"],"a":2,"e":"Have to bilan so'roq gap do/does yordamida tuziladi."},{"q":"You ___ drive so fast. We have enough time.","o":["mustn't","don't have to","must","had better"],"a":1,"e":"Don't have to — «shart emas, ehtiyoj yo'q» ma'nosini beradi."},{"q":"You ___ smoke here. It's forbidden.","o":["don't have to","needn't","mustn't","don't need to"],"a":2,"e":"Mustn't qat'iy taqiqni bildiradi."},{"q":"Which is NOT a synonym of 'You don't have to hurry'?","o":["You needn't hurry.","You don't need to hurry.","You mustn't hurry.","There is no need for you to hurry."],"a":2,"e":"Mustn't taqiqni bildiradi, qolganlari «shart emas» ma'nosida."},{"q":"Everyone ___ go to military service in our country. (a law)","o":["has to","must to","ought","had better to"],"a":0,"e":"Have to qoida, jamoat fikri yoki tashqi majburiyatni bildiradi."},{"q":"You ought ___ warm clothes.","o":["wear","to wear","wearing","wears"],"a":1,"e":"Ought dan keyin to qo'yiladi: ought to wear."},{"q":"Choose the correct negative form.","o":["You had not better go.","You had better not go.","You not had better go.","You had better don't go."],"a":1,"e":"Had better ning inkorida not had better dan keyin qo'yiladi."},{"q":"Choose the correct question with 'ought'.","o":["Do I ought to do like this?","Ought I to do like this?","Ought I do like this?","Am I ought to do like this?"],"a":1,"e":"So'roq gapda ought egadan oldinga o'tadi va to saqlanadi."},{"q":"___ like a cup of tea?","o":["Would you","Do you would","Will you to","Should you"],"a":0,"e":"Would you like …? — muloyim taklif shakli."}]},{"id":"p5-03","en":"Command, Advice, Request","uz":"Buyruq, maslahat va iltimos gaplar","emoji":"📣","level":"A1","group":"Savollar va gap turlari","summary":"Buyruq gaplar egasiz tuziladi, inkori don't bilan yasaladi. Let's, let him/her/them shakllari va ularning zamonaviy muqobillari ham o'rganiladi.","blocks":[{"t":"h","x":"Buyruq gap"},{"t":"p","x":"Buyruq gap ikkinchi shaxsga (tinglovchiga) qaratiladi va unda <b>ega berilmaydi</b>. Fe'lning birinchi shakli ishlatiladi."},{"t":"ex","en":"Stop! Hurry! Shut up!","uz":"To'xta! Shoshil! Jim bo'l!"},{"t":"p","x":"Inkor shakli <b>don't</b> yordamida yasaladi."},{"t":"formula","x":"Don't + V"},{"t":"ex","en":"Don't stop! Don't be late!","uz":"To'xtama! Kechikma!"},{"t":"h","x":"Buyruq kimga qaratilganini ko'rsatish"},{"t":"p","x":"Buyruq kimga qaratilganini ko'rsatish uchun gap oxiriga <b>ot</b> qo'yiladi va u vergul bilan ajratiladi. Bu ot gap boshida juda kam keladi."},{"t":"ex","en":"Eat your dinner, boys.","uz":"Bolalar, kechki ovqatingizni yenglar."},{"t":"ex","en":"Be careful, Tom.","uz":"Ehtiyot bo'l, Tom."},{"t":"ex","en":"Boys, eat your dinner.","uz":"Bolalar, ovqatingizni yenglar (kam uchraydigan tartib)."},{"t":"p","x":"Gap boshida <b>you</b> ham kelishi mumkin. Bu so'zlovchi tinglovchini ajratib ko'rsatayotganini yoki jahli chiqqanini bildiradi."},{"t":"ex","en":"You go on.","uz":"Sen davom et."},{"t":"ex","en":"You shut up and listen to my words.","uz":"Sen jim bo'l va gaplarimni eshit!"},{"t":"h","x":"Let's + bare infinitive"},{"t":"p","x":"<b>Let's (let us) + to'siz infinitiv</b> tinglovchini (va so'zlovchining o'zini) biror ishga chorlash uchun ishlatiladi."},{"t":"ex","en":"Let's go.","uz":"Ketdik."},{"t":"ex","en":"Let's travel on foot.","uz":"Piyoda sayohat qilaylik."},{"t":"p","x":"Inkor shakli to'siz infinitiv oldiga <b>not</b> qo'yish orqali yasaladi."},{"t":"formula","x":"Let's not + V"},{"t":"ex","en":"Let's not swim in the river.","uz":"Daryoda suzmaylik."},{"t":"h","x":"Let him / her / it / them + bare infinitive"},{"t":"p","x":"Bu shakl ma'no jihatidan uchinchi shaxsga qaratilgan <b>buyruq</b> hisoblanadi."},{"t":"ex","en":"Let him go.","uz":"U ketaversin."},{"t":"ex","en":"Let him not go.","uz":"U bormasin."},{"t":"ex","en":"Let them eat it.","uz":"Ular uni yeyishsin."},{"t":"rule","x":"Zamonaviy ingliz tilida bu tuzilma o'rnida 3-shaxs uchun ko'proq <b>S + must + V</b> yoki <b>S + be to + V</b> shakli ishlatiladi."},{"t":"ex","en":"He must go.","uz":"U ketishi kerak."},{"t":"ex","en":"They are to eat it.","uz":"Ular uni yeyishlari kerak."},{"t":"ex","en":"They are not to eat it.","uz":"Ular uni yemasliklari kerak."}],"quiz":[{"q":"Choose the correct negative command.","o":["Not be late!","Don't be late!","Be not late!","Doesn't be late!"],"a":1,"e":"Buyruq gapning inkori don't bilan yasaladi."},{"q":"In a command, the subject is usually:","o":["always given","not given","given at the end with 'too'","replaced by 'it'"],"a":1,"e":"Buyruq gapda ega berilmaydi."},{"q":"Choose the most usual word order.","o":["Tom be careful.","Be careful, Tom.","Careful be, Tom.","Tom, careful be."],"a":1,"e":"Kimga qaratilgani odatda gap oxirida vergul bilan beriladi."},{"q":"'You shut up and listen!' Here 'you' shows:","o":["politeness","a question","anger or emphasis","the past tense"],"a":2,"e":"Gap boshidagi you jahl yoki ajratib ko'rsatishni bildiradi."},{"q":"___ travel on foot.","o":["Let's","Let's to","Lets us to","Let we"],"a":0,"e":"Let's + to'siz infinitiv — chorlash."},{"q":"Choose the correct negative of 'Let's swim in the river'.","o":["Don't let's to swim.","Let's not swim in the river.","Let's swim not in the river.","Let not us swim."],"a":1,"e":"Inkor: Let's not + V."},{"q":"'Let them eat it.' In modern English this is more often expressed as:","o":["They are to eat it.","They eat it, let's.","They let to eat it.","Let's they eat it."],"a":0,"e":"Zamonaviy tilda S + be to / must + V ko'proq ishlatiladi."},{"q":"Choose the correct sentence.","o":["Let him to go.","Let him goes.","Let him go.","Let he go."],"a":2,"e":"Let + object pronoun (him) + to'siz infinitiv."},{"q":"Choose the correct negative form.","o":["Let him not go.","Let him don't go.","Let not him to go.","Let him no go."],"a":0,"e":"Not to'siz infinitiv oldiga qo'yiladi: Let him not go."}]},{"id":"p5-04","en":"Addition to Remarks (So / Neither / Too / Either)","uz":"Fikrga qo'shimcha: so, neither, too, either","emoji":"🤝","level":"A2","group":"Savollar va gap turlari","summary":"Boshqa birovning gapiga qo'shilish yoki qarshi chiqish: too / also / so (tasdiq), either / neither / nor (inkor) va but bilan qarama-qarshi qo'shimcha.","blocks":[{"t":"h","x":"Tasdiq gapga tasdiq qo'shimcha"},{"t":"p","x":"Tasdiq gapga tasdiq qo'shimcha («men ham») <b>3 xil usulda</b> yasaladi:"},{"t":"formula","x":"1) S + auxiliary + asosiy fe'l + C + M + too.<br>2) S + auxiliary + too / also.<br>3) So + auxiliary + S."},{"t":"p","x":"Yordamchi fe'l asosiy gapdagi zamonga mos bo'lishi kerak; agar asosiy gapda yordamchi fe'l bo'lmasa, <b>do / does / did</b> ishlatiladi."},{"t":"ex","en":"Bill will enjoy the game. — I will enjoy the game too. / I will too. / So will I.","uz":"Bill o'yindan zavqlanadi. — Men ham."},{"t":"ex","en":"Ann has been learning English. — They have been learning English too. / They have too. / So have they.","uz":"Ann ingliz tilini o'rganib kelmoqda. — Ular ham."},{"t":"ex","en":"Tom likes pop music. — I like pop music too. / I do too. / So do I.","uz":"Tom pop musiqani yoqtiradi. — Men ham."},{"t":"ex","en":"Girls usually sing. — Boys sing too. / Boys do too. / So do boys.","uz":"Qizlar odatda qo'shiq aytishadi. — O'g'il bolalar ham."},{"t":"rule","x":"Diqqat: <b>So + auxiliary + S</b> tuzilmasida so'z tartibi teskari: <i>So do I</i> (<i>So I do</i> emas)."},{"t":"h","x":"Inkor gapga inkor qo'shimcha"},{"t":"p","x":"Inkor gapga inkor qo'shimcha («men ham … emas») ham <b>3 xil usulda</b> yasaladi:"},{"t":"formula","x":"1) S + negative auxiliary + asosiy fe'l + C + M + either.<br>2) S + negative auxiliary + either.<br>3) Neither / Nor + auxiliary + S."},{"t":"ex","en":"We don't smoke. — Tom doesn't smoke either. / Tom doesn't either. / Nor does Tom. (Neither does Tom.)","uz":"Biz chekmaymiz. — Tom ham chekmaydi."},{"t":"rule","x":"<b>Neither / Nor</b> dan keyin yordamchi fe'l <b>tasdiq</b> shaklda keladi: <i>Neither does Tom</i> (<i>Neither doesn't Tom</i> emas)."},{"t":"h","x":"Tasdiq gapga inkor qo'shimcha"},{"t":"formula","x":"But + S + negative auxiliary."},{"t":"ex","en":"A: I will phone you. B: But he won't.","uz":"A: Men senga qo'ng'iroq qilaman. B: Lekin u qilmaydi."},{"t":"ex","en":"He likes swimming but I don't.","uz":"U suzishni yoqtiradi, lekin men yoqtirmayman."},{"t":"h","x":"Inkor gapga tasdiq qo'shimcha"},{"t":"formula","x":"But + S + auxiliary."},{"t":"ex","en":"A: Bill hasn't got a licence. B: But Donald has.","uz":"A: Billning guvohnomasi yo'q. B: Lekin Donaldda bor."},{"t":"ex","en":"She doesn't eat meat but her children do.","uz":"U go'sht yemaydi, lekin bolalari yeydi."},{"t":"p","x":"Gap qanchalik uzun va murakkab zamonda bo'lmasin, qisqa javobda faqat birinchi yordamchi fe'l olinadi:"},{"t":"ex","en":"John will have been cutting several pine trees in the new forest by the end of this month by himself. — So will I.","uz":"Jon oy oxirigacha yangi o'rmonda bir nechta qarag'ayni o'zi kesib bo'lgan bo'ladi. — Men ham."}],"quiz":[{"q":"Tom likes pop music. — So ___ I.","o":["am","do","like","does"],"a":1,"e":"Present Simple gapda do yordamchi fe'li ishlatiladi: So do I."},{"q":"Ann has been learning English. — So ___ they.","o":["have","has","do","are"],"a":0,"e":"Asosiy gapdagi yordamchi fe'l (have) olinadi, ega they bo'lgani uchun have."},{"q":"We don't smoke. — Tom doesn't smoke ___.","o":["too","also","either","neither"],"a":2,"e":"Inkor gapga inkor qo'shimchada either ishlatiladi."},{"q":"We don't smoke. — ___ does Tom.","o":["So","Nor","Either","Too"],"a":1,"e":"Neither / Nor + tasdiq auxiliary + S."},{"q":"Choose the correct sentence.","o":["So I will.","So will I.","I will so.","Will so I."],"a":1,"e":"So + auxiliary + S — teskari so'z tartibi."},{"q":"Choose the correct reply to 'I can't swim.'","o":["Neither can't I.","Neither can I.","So can I.","I can't too."],"a":1,"e":"Neither dan keyin auxiliary tasdiq shaklda keladi."},{"q":"He likes swimming but I ___.","o":["do","don't","doesn't","am not"],"a":1,"e":"Tasdiq gapga inkor qo'shimcha: But + S + negative auxiliary."},{"q":"She doesn't eat meat but her children ___.","o":["don't","does","do","eat not"],"a":2,"e":"Inkor gapga tasdiq qo'shimcha: But + S + auxiliary."},{"q":"Bill will enjoy the game. — I will ___.","o":["either","too","neither","so"],"a":1,"e":"Tasdiq gapga tasdiq qo'shimcha: S + auxiliary + too / also."},{"q":"Bill hasn't got a licence. — But Donald ___.","o":["has","hasn't","does","is"],"a":0,"e":"Inkor gapga tasdiq javob: But + S + auxiliary (has)."}]},{"id":"p5-05","en":"Questions: General, Special and Subject Questions","uz":"So'roq gaplar: umumiy, maxsus va egaga beriladigan savollar","emoji":"❓","level":"A1","group":"Savollar va gap turlari","summary":"Ingliz tilida 3 xil so'roq gap bor: umumiy (ha/yo'q), maxsus (WH) va tag savollar. Bu darsda umumiy, maxsus savollar, so'roq so'zlari va egaga beriladigan savol o'rganiladi.","blocks":[{"t":"h","x":"So'roq gap turlari"},{"t":"list","items":["<b>General questions</b> (yes / no questions) — umumiy savollar;","<b>Special questions</b> (WH questions) — maxsus savollar;","<b>Tag questions</b> — ajratilgan (dumli) savollar."]},{"t":"h","x":"General questions (umumiy savollar)"},{"t":"p","x":"Umumiy savollarga <b>ha</b> yoki <b>yo'q</b> deb javob berish mumkin. Yordamchi fe'l (yoki <i>to be</i>) egadan oldinga chiqadi."},{"t":"formula","x":"Auxiliary / do / does / did / to be + S + V + C + M ?"},{"t":"ex","en":"Can you speak English? — Yes, I can.","uz":"Inglizcha gapira olasizmi? — Ha, olaman."},{"t":"ex","en":"Are they playing football? — No, they aren't.","uz":"Ular futbol o'ynayaptimi? — Yo'q."},{"t":"ex","en":"He is a student. → Is he a student?","uz":"U talaba. → U talabami?"},{"t":"ex","en":"Mary is going to school. → Is Mary going to school?","uz":"Meri maktabga ketyapti. → Meri maktabga ketyaptimi?"},{"t":"ex","en":"I cleaned the car. → Did you clean the car?","uz":"Men mashinani tozaladim. → Sen mashinani tozaladingmi?"},{"t":"ex","en":"Tom usually does his homework late. → Does Tom usually do his homework late?","uz":"Tom odatda uy vazifasini kech qiladimi?"},{"t":"h","x":"Special questions (maxsus savollar)"},{"t":"p","x":"Maxsus savollarga ha yoki yo'q deb javob berib bo'lmaydi; javob sifatida biror <b>ma'lumot</b> berish kerak bo'ladi."},{"t":"formula","x":"WH-word + auxiliary / do / does / did / to be + S + V + C + M ?"},{"t":"ex","en":"What did he buy?","uz":"U nima sotib oldi?"},{"t":"ex","en":"Who are you?","uz":"Siz kimsiz?"},{"t":"table","head":["So'roq so'zi","Tarjimasi","Misol"],"rows":[["What","nima, nimani (asosan to'ldiruvchini so'raydi)","I learnt new rules. — What did you learn?"],["Whom","kimni (to'ldiruvchini so'raydi)","He knows a scholar from Venezuela. — Whom does he know from Venezuela?"],["When","qachon","When did you come?"],["Where","qayerda, qayerga","Where are you going? Where does he live?"],["Why","nega, nima uchun (sabab)","Why are you crying?"],["How","qanday, qay tarzda","How did you get here?"],["Which","qaysi (tanlov)","Which person is your groupmate?"],["Whose","kimniki, kimlarniki","Whose book is it?"],["Who","kim","Who are you?"]]},{"t":"rule","x":"Diqqat: sabab so'ralganda <b>Why</b> ishlatiladi; <b>How</b> esa «qanday, qay usulda» degan ma'noni beradi."},{"t":"h","x":"Subject questions (egaga beriladigan savol)"},{"t":"p","x":"Subject question — ish-harakatni <b>bajaruvchisi (ega)</b> so'ralganda ishlatiladigan savol. Bunda <b>do / does / did</b> ishlatilmaydi va so'z tartibi darak gapdagidek qoladi."},{"t":"formula","x":"Who / What + V + C + M ?"},{"t":"ex","en":"Who cleaned the room? — Tom cleaned the room.","uz":"Xonani kim tozaladi? — Tom tozaladi."},{"t":"ex","en":"What dug this hole? — A rat dug this hole.","uz":"Bu chuqurni nima kavladi? — Kalamush kavladi."},{"t":"rule","x":"Egaga beriladigan savolda <b>Who / What</b> 3-shaxs birlik hisoblanadi: <i>Who is absent?</i> (<i>Who are absent?</i> emas)."}],"quiz":[{"q":"Which question can be answered with 'yes' or 'no'?","o":["Where does he live?","Does he live in Tashkent?","Who lives here?","Why does he live here?"],"a":1,"e":"Umumiy savollar yordamchi fe'l bilan boshlanadi va ha/yo'q javobini talab qiladi."},{"q":"Tom usually does his homework late. → ___ Tom usually do his homework late?","o":["Do","Is","Does","Did"],"a":2,"e":"Present Simple, 3-shaxs birlik — does."},{"q":"I cleaned the car. → ___ you clean the car?","o":["Do","Did","Were","Have"],"a":1,"e":"Past Simple gapda did ishlatiladi."},{"q":"___ are you crying? — Because I'm sad.","o":["How","Why","What","Which"],"a":1,"e":"Sabab so'ralganda Why ishlatiladi."},{"q":"___ book is it? — It's Ann's.","o":["Who","Whom","Whose","Which"],"a":2,"e":"Whose — kimniki degan ma'noni beradi."},{"q":"He knows a scholar. ___ does he know?","o":["Who's","Whose","Whom","What's"],"a":2,"e":"Whom — kimni, to'ldiruvchini so'raydi."},{"q":"Choose the correct subject question.","o":["Who did clean the room?","Who cleaned the room?","Who does cleaned the room?","Whom cleaned the room?"],"a":1,"e":"Egaga beriladigan savolda do/does/did ishlatilmaydi."},{"q":"Choose the correct question.","o":["Who are absent?","Who is absent?","Who do absent?","Who be absent?"],"a":1,"e":"Who egaga savol bo'lganda 3-shaxs birlik hisoblanadi."},{"q":"___ person is your groupmate? (choosing from a group)","o":["Which","Whose","Whom","Why"],"a":0,"e":"Which — tanlovni ko'rsatadi."},{"q":"How many types of questions does the book name?","o":["two","three","four","five"],"a":1,"e":"General, special va tag questions — 3 xil."}]},{"id":"p5-06","en":"Tag Questions and Command Tags","uz":"Tag (dumli) savollar va qisqa javob-savollar","emoji":"🏷️","level":"B1","group":"Savollar va gap turlari","summary":"Tag savollar tinglovchining fikrini so'rash uchun ishlatiladi: tasdiq gapga inkor tag, inkor gapga tasdiq tag. Maxsus holatlar (I am, let's, nobody, hardly) va so'zlovchi munosabatini bildiruvchi qisqa savollar.","blocks":[{"t":"h","x":"Question tag nima?"},{"t":"p","x":"Question tag aytilgan gapga tinglovchining fikrini so'rash (tasdiqlatish) uchun ishlatiladi."},{"t":"ex","en":"You are a good student, aren't you?","uz":"Sen yaxshi o'quvchisan, shunday emasmi?"},{"t":"ex","en":"Ann can't swim, can she?","uz":"Ann suza olmaydi, shundaymi?"},{"t":"h","x":"Asosiy qoida"},{"t":"p","x":"<b>Inkor gapga tasdiq tag</b>, <b>tasdiq gapga inkor tag</b> qo'shiladi. Tagdagi ega har doim <b>olmosh</b> bo'lishi kerak."},{"t":"formula","x":"Negative sentence, auxiliary + pronoun?<br>Positive sentence, negative auxiliary + pronoun?"},{"t":"ex","en":"Mary was there, wasn't she?","uz":"Meri u yerda edi, shunday emasmi?"},{"t":"h","x":"I am"},{"t":"p","x":"Agar gapda <b>I am</b> kelsa, tagda <b>aren't I</b> (rasmiyroq: <i>am I not</i>) ishlatiladi."},{"t":"ex","en":"I am doing well, aren't I? (or: am I not?)","uz":"Men yaxshi ishlayapman, to'g'rimi?"},{"t":"ex","en":"I am not doing well, am I?","uz":"Men yaxshi ishlamayapman, shundaymi?"},{"t":"h","x":"Let's + V"},{"t":"p","x":"Agar gapda <b>let's + V</b> kelsa, tagda yordamchi fe'l sifatida <b>shall</b> ishlatiladi."},{"t":"ex","en":"Let's go, shall we?","uz":"Ketdik, bo'ladimi?"},{"t":"h","x":"Inkor ma'noli so'zlar"},{"t":"p","x":"Agar gapda <b>neither, no, none, no one, nobody, nothing, scarcely, barely, hardly, hardly ever, seldom</b> kabi so'zlar bo'lsa, gap ma'no jihatidan inkor hisoblanadi, shuning uchun tag <b>tasdiq</b> shaklda bo'ladi."},{"t":"ex","en":"No salt is allowed, is it?","uz":"Tuz mumkin emas, shundaymi?"},{"t":"ex","en":"Peter hardly ever managed this job, did he?","uz":"Piter bu ishni deyarli hech qachon uddalamagan, shundaymi?"},{"t":"h","x":"Anyone, nobody va boshqalar ega bo'lganda"},{"t":"p","x":"Agar gapda <b>anyone, anybody, no one, nobody, none, neither</b> ega bo'lib kelsa, tagda ega sifatida <b>they</b> ishlatiladi. Nobody/no one/none/neither bilan tag doim <b>tasdiq</b> shaklda bo'ladi."},{"t":"ex","en":"Nobody could enter the room, could they?","uz":"Hech kim xonaga kira olmadi, shundaymi?"},{"t":"h","x":"Command tag (munosabat bildiruvchi qisqa savol)"},{"t":"p","x":"Bu qisqa savollar so'zlovchining aytilgan gapga <b>munosabatini</b> ko'rsatish uchun ishlatiladi. Bunda gap qanday bo'lsa, savol ham shunday bo'ladi:"},{"t":"formula","x":"Positive sentence → positive tag?<br>Negative sentence → negative tag?"},{"t":"ex","en":"I saw him. — Did you?","uz":"Men uni ko'rdim. — Rostdanmi?"},{"t":"ex","en":"I did not pay Paul. — Oh, didn't you?","uz":"Men Polga pul to'lamadim. — E, to'lamadingmi?"},{"t":"p","x":"So'zlovchining ohangidan uning qiziqqani yoki qiziqmagani, hayron qolgani, xursand bo'lgani, jahli chiqqani, shubha bilan qarayotgani yoki ishonmayotgani va hokazolarni bilib olish mumkin."}],"quiz":[{"q":"Mary was there, ___?","o":["was she","wasn't she","didn't she","isn't she"],"a":1,"e":"Tasdiq gapga inkor tag; yordamchi fe'l was."},{"q":"Ann can't swim, ___?","o":["can't she","can she","does she","can Ann"],"a":1,"e":"Inkor gapga tasdiq tag; tagdagi ega olmosh bo'ladi."},{"q":"I am doing well, ___?","o":["amn't I","aren't I","don't I","isn't I"],"a":1,"e":"I am bo'lsa, tagda aren't I (yoki am I not) ishlatiladi."},{"q":"Let's go, ___?","o":["will we","don't we","shall we","let we"],"a":2,"e":"Let's bilan tagda shall we ishlatiladi."},{"q":"No salt is allowed, ___?","o":["isn't it","is it","doesn't it","is salt"],"a":1,"e":"No kabi inkor ma'noli so'zlar bilan tag tasdiq bo'ladi."},{"q":"Peter hardly ever managed this job, ___?","o":["didn't he","did he","hasn't he","does he"],"a":1,"e":"Hardly ever gapni inkor ma'noli qiladi, shuning uchun tag tasdiq."},{"q":"Nobody could enter the room, ___?","o":["couldn't they","could he","could they","couldn't he"],"a":2,"e":"Nobody ega bo'lsa, tagda they va tasdiq shakl ishlatiladi."},{"q":"The subject of a question tag must always be:","o":["a noun","a pronoun","a name","an adjective"],"a":1,"e":"Tagdagi ega har doim olmosh bo'lishi kerak."},{"q":"A: I saw him. B: ___ (showing surprise)","o":["Didn't you?","Did you?","Saw you?","Do you?"],"a":1,"e":"Munosabat bildiruvchi qisqa savolda tasdiq gapga tasdiq savol beriladi."},{"q":"A: I did not pay Paul. B: Oh, ___?","o":["did you","didn't you","paid you","don't you"],"a":1,"e":"Inkor gapga inkor qisqa savol — munosabat bildiradi."}]},{"id":"p5-07","en":"Embedded Questions","uz":"Gap ichidagi so'roq gap (embedded question)","emoji":"🪆","level":"B1","group":"Ko'chirma gap va murakkab gaplar","summary":"Darak yoki so'roq gap ichida kelgan so'roq gapda so'z tartibi darak gapdagidek bo'ladi; umumiy savollar if/whether bilan bog'lanadi, o'tgan zamonda zamonlar moslashadi.","blocks":[{"t":"h","x":"Embedded sentence nima?"},{"t":"p","x":"Embedded sentence — darak yoki so'roq gap <b>ichida</b> qatnashayotgan so'roq gap. Ichki qismda so'z tartibi <b>darak gapdagidek</b> bo'ladi: avval ega, keyin fe'l; <b>do / does / did</b> ishlatilmaydi."},{"t":"formula","x":"S + V + question word + S + V.<br>Auxiliary + S + V + question word + S + V ?"},{"t":"ex","en":"Could you tell me where the station is?","uz":"Vokzal qayerdaligini ayta olasizmi?"},{"t":"ex","en":"I do not know what his name is.","uz":"Uning ismi nimaligini bilmayman."},{"t":"ex","en":"He asks where the meeting will take place.","uz":"U yig'ilish qayerda bo'lishini so'rayapti."},{"t":"ex","en":"I have no idea how long the interview will take.","uz":"Suhbat qancha davom etishini bilmayman."},{"t":"ex","en":"Do they know how often the bus runs at night?","uz":"Ular tunda avtobus qanchalik tez-tez qatnashini bilishadimi?"},{"t":"rule","x":"Diqqat: <i>Where is the station?</i> → <i>Could you tell me where the station <b>is</b>?</i> (<i>where is the station</i> emas)."},{"t":"h","x":"Subject question bilan"},{"t":"p","x":"Egaga beriladigan savol (subject question) gap ichiga kirganda hech qanday o'zgarish bo'lmaydi, chunki uning tartibi allaqachon darak gapdagidek."},{"t":"ex","en":"They cannot decide who will paint that room.","uz":"Ular u xonani kim bo'yashini hal qila olmayapti."},{"t":"h","x":"General question bilan: if / whether"},{"t":"p","x":"Agar umumiy (ha/yo'q) savol gap ichiga kiritilsa, <b>if</b> yoki <b>whether</b> ishlatiladi."},{"t":"ex","en":"Does he go to school? → Do you know whether (or if) he goes to school?","uz":"U maktabga boradimi? → U maktabga borish-bormasligini bilasanmi?"},{"t":"ex","en":"Have you been to London? → I cannot tell if you have been to London.","uz":"Londonda bo'lganmisan? → Londonda bo'lgan-bo'lmaganingni ayta olmayman."},{"t":"h","x":"O'tgan zamonda zamonlar moslashuvi"},{"t":"p","x":"Agar asosiy gap <b>o'tgan zamonda</b> bo'lsa, ichki gapning zamoni bir pog'ona o'tmishga suriladi (Present → Past, Past → Past Perfect)."},{"t":"ex","en":"What do you do? → He asked what I did.","uz":"Nima ish qilasan? → U nima ish qilishimni so'radi."},{"t":"ex","en":"Did he come? → She asked if he had come.","uz":"U keldimi? → U kelgan-kelmaganini so'radi."}],"quiz":[{"q":"Could you tell me where ___?","o":["is the station","the station is","does the station be","the station does"],"a":1,"e":"Gap ichidagi savolda so'z tartibi darak gapdagidek: ega + fe'l."},{"q":"I don't know what ___.","o":["is his name","his name is","does his name","his name does be"],"a":1,"e":"Ichki savolda ega fe'ldan oldin keladi."},{"q":"Do they know how often ___ at night?","o":["does the bus run","the bus runs","runs the bus","the bus does run"],"a":1,"e":"Ichki savolda do/does ishlatilmaydi."},{"q":"'Does he go to school?' → Do you know ___ he goes to school?","o":["that","what","whether","which"],"a":2,"e":"Umumiy savol gap ichiga if yoki whether bilan kiritiladi."},{"q":"'Who will paint the room?' → They can't decide ___.","o":["who will paint the room","who the room will paint","who does paint the room","whom will paint the room"],"a":0,"e":"Subject question gap ichiga kirganda o'zgarmaydi."},{"q":"'What do you do?' → He asked what I ___.","o":["do","did","does","am doing"],"a":1,"e":"Asosiy gap o'tgan zamonda — ichki gap Present Simple → Past Simple."},{"q":"'Did he come?' → She asked if he ___.","o":["came","comes","had come","has come"],"a":2,"e":"Past Simple → Past Perfect."},{"q":"Choose the correct sentence.","o":["He asks where will the meeting take place.","He asks where the meeting will take place.","He asks where does the meeting take place.","He asks where take place the meeting."],"a":1,"e":"Ichki savolda: question word + S + V."},{"q":"I cannot tell ___ you have been to London.","o":["if","what","that","who"],"a":0,"e":"Ha/yo'q savoli ichki gapga if bilan kiradi."}]},{"id":"p5-08","en":"The Indefinite Article A / An and One","uz":"Noaniq artikl a / an va one","emoji":"🅰️","level":"A2","group":"Artikl va son","summary":"A/an ning qo'shimcha qo'llanishlari: butun turni bildirish, miqdor iboralari, «har bir» ma'nosi, undov gaplar, Mr/Mrs bilan; one va a/an farqi, one day iborasi.","blocks":[{"t":"h","x":"A/an butun guruh nomi sifatida"},{"t":"p","x":"Noaniq artikl <b>a/an</b> birlikdagi ot oldidan kelib, <b>butun bir guruh (tur)</b>ni anglatishi mumkin. Bunda fe'l <b>birlikda</b> ishlatiladi. Ma'nosi <i>all / any</i> bilan bir xil."},{"t":"ex","en":"A child needs love. = All children need love. = Any child needs love.","uz":"Har qanday bolaga mehr kerak."},{"t":"ex","en":"A car must be insured. = All cars must be insured. = Any car must be insured.","uz":"Har qanday mashina sug'urtalangan bo'lishi kerak."},{"t":"h","x":"Miqdor iboralari"},{"t":"p","x":"Miqdorni bildiruvchi ba'zi iboralar oldidan <b>a</b> artikli ishlatiladi: <b>a lot of, a few, a little, a great many</b>; shuningdek kasrlarda: <b>a third</b> = 1/3."},{"t":"ex","en":"I have got a lot of friends.","uz":"Mening do'stlarim ko'p."},{"t":"h","x":"A/an «har bir» (for each / per) ma'nosida"},{"t":"ex","en":"One pound a metre.","uz":"Metri bir funt."},{"t":"ex","en":"50 sums a kilo.","uz":"Kilosi 50 so'm."},{"t":"ex","en":"Four times a day.","uz":"Kuniga to'rt marta."},{"t":"ex","en":"Sixty kilometres an hour.","uz":"Soatiga oltmish kilometr."},{"t":"h","x":"Undov gaplarda"},{"t":"p","x":"Undov gaplarda (<b>What a …! / Such a …!</b>) birlikdagi sanaladigan ot oldidan <b>a/an</b> ishlatiladi. Ot ko'plikda bo'lsa, artikl ishlatilmaydi."},{"t":"ex","en":"Such a long queue! — Such long queues!","uz":"Qanday uzun navbat! — Qanday uzun navbatlar!"},{"t":"ex","en":"What a pretty girl! — What pretty girls!","uz":"Qanday chiroyli qiz! — Qanday chiroyli qizlar!"},{"t":"h","x":"A + Mr / Mrs / Miss + familiya"},{"t":"p","x":"<b>A</b> artikli <b>Mr / Mrs / Miss + familiya</b> oldidan kelishi mumkin. Bu so'zlovchi bu odamni tanimasligini yoki uni birinchi marta tilga olayotganini bildiradi."},{"t":"ex","en":"Who is that person? — A Mr Smith.","uz":"U kim? — Qandaydir Smit degan kishi."},{"t":"h","x":"One va a/an"},{"t":"p","x":"Vaqt, masofa, og'irlik va hokazolarni <b>sanash yoki hisoblashda</b> <b>one</b> va <b>a/an</b> ishlatiladi va ular o'rtasida farq yo'q."},{"t":"table","head":["one","a / an"],"rows":[["one pound","a pound"],["one week","a week"],["one million sums","a million sums"]]},{"t":"rule","x":"Lekin «har bir» ma'nosidagi iboralarda <b>one</b> ishlatib bo'lmaydi: <i>A room is 100 pounds a week</i> (<i>100 pounds one week</i> emas)."},{"t":"p","x":"Sanash-hisoblashda emas, balki umumiy bayon gaplarda <b>one</b> bilan <b>a/an</b> orasida katta farq bor:"},{"t":"ex","en":"A shotgun is no good. (= it is the wrong sort of thing)","uz":"Ov miltig'i yaramaydi (bu umuman noto'g'ri narsa)."},{"t":"ex","en":"One shotgun is no good. (= I need more than one)","uz":"Bitta miltiq yetmaydi (menga bittadan ko'p kerak)."},{"t":"h","x":"One day / one night ..."},{"t":"p","x":"<b>One</b> so'zi <b>day / week / month / year / summer</b> kabi so'zlar bilan kelsa, o'tmishda biror ish-harakat sodir bo'lgan kunni ifodalaydi: <b>one day</b> — bir kuni."},{"t":"ex","en":"One night there was a terrible storm.","uz":"Bir kechasi dahshatli bo'ron bo'ldi."},{"t":"p","x":"Shu bilan birga <b>one day</b> kelajakdagi noma'lum bir kunni ifodalash uchun ham keng qo'llaniladi."},{"t":"ex","en":"One day you will understand what I am saying.","uz":"Bir kun kelib aytayotganlarimni tushunasan."}],"quiz":[{"q":"'A child needs love' means:","o":["One particular child needs love.","Any child needs love.","Only one child needs love.","The child needed love."],"a":1,"e":"A/an birlikdagi ot oldida butun turni bildirishi mumkin."},{"q":"Choose the correct phrase.","o":["Four times the day","Four times a day","Four times one day","Four times day"],"a":1,"e":"A/an «har bir» (per) ma'nosida ishlatiladi."},{"q":"Sixty kilometres ___ hour.","o":["a","an","the","one"],"a":1,"e":"Hour unli tovush bilan boshlanadi va «har bir» ma'nosida an ishlatiladi."},{"q":"What ___ pretty girls!","o":["a","an","the","— (no article)"],"a":3,"e":"Undov gapda ko'plikdagi ot oldidan artikl ishlatilmaydi."},{"q":"Such ___ long queue!","o":["a","the","one","— (no article)"],"a":0,"e":"Undov gapda birlikdagi sanaladigan ot oldidan a ishlatiladi."},{"q":"'A Mr Smith phoned.' This shows that the speaker:","o":["knows Mr Smith well","does not know Mr Smith","is Mr Smith","has met him many times"],"a":1,"e":"A + Mr/Mrs + familiya — so'zlovchi bu odamni tanimaydi."},{"q":"A room is 100 pounds ___ week.","o":["one","a","the","an"],"a":1,"e":"«Har bir» ma'nosidagi iboralarda one ishlatilmaydi."},{"q":"'One shotgun is no good' means:","o":["A shotgun is the wrong thing.","I need more than one.","Shotguns are bad.","I have no shotgun."],"a":1,"e":"One son ma'nosini beradi — bitta yetarli emas."},{"q":"___ day you will understand what I am saying.","o":["A","The","One","An"],"a":2,"e":"One day kelajakdagi noma'lum kunni ham ifodalaydi."},{"q":"Which phrase does NOT take 'a'?","o":["a lot of","a few","a great many","a much"],"a":3,"e":"Kitobdagi iboralar: a lot of, a few, a little, a great many."}]},{"id":"p5-09","en":"Other / Another, Little / Few","uz":"Other / another va little / few","emoji":"🔢","level":"A2","group":"Olmosh, sifat, ravish","summary":"Another, other, the other va the others farqi; one/ones bilan qo'llash. Little va few ning olmosh, ravish sifatida ishlatilishi, quite a few, only a few va boshqa qoidalar.","blocks":[{"t":"h","x":"Another / other / the other"},{"t":"p","x":"<b>Another = an + other</b>. Qo'shilishi bo'yicha qoidalar:"},{"t":"table","head":["Shakl","Ma'nosi","Misol"],"rows":[["another + birlikdagi ot","yana bitta (one more)","another pencil = yana bitta qalam"],["the other + birlikdagi ot","oxirgi, qolgan bittasi","the other pencil = qolgan oxirgi qalam"],["other + ko'plikdagi ot","yana bir nechta, boshqa","other pencils = yana bir nechta qalam"],["the other + ko'plikdagi ot","qolgan barchasi (the rest)","the other pencils = qolgan barcha qalamlar"]]},{"t":"ex","en":"There were three people. One of them was Uzbek, another one was French, and the other one was English.","uz":"Uch kishi bor edi. Biri o'zbek, yana biri fransuz, qolgani esa ingliz edi."},{"t":"h","x":"One / ones bilan"},{"t":"p","x":"<b>Another, other, the other</b> dan keyin oldin aytilgan otni takrorlamasdan, uning o'rniga <b>one / ones</b> ishlatish mumkin."},{"t":"ex","en":"Do you like this suit? — It is OK, but can you show me another one?","uz":"Bu kostyum yoqdimi? — Yomon emas, lekin boshqasini ko'rsata olasizmi?"},{"t":"ex","en":"Two of them refused, but the other ones agreed.","uz":"Ulardan ikkitasi rad etdi, qolganlari esa rozi bo'ldi."},{"t":"h","x":"Yolg'iz holda olmosh sifatida"},{"t":"p","x":"<b>Another, other</b> yoki <b>the other</b> o'zi yolg'iz holda birlik yoki ko'plikdagi otni ifodalab kelishi mumkin. Bu holatda ko'plik qo'shimchasi <b>-s</b> other ga qo'shiladi: <b>others, the others</b>."},{"t":"ex","en":"You have not met Bill's sister, have you? — I have met one, but I did not know he had another.","uz":"Billning singlisi bilan tanishmagansan, a? — Bittasi bilan tanishganman, lekin uning yana biri borligini bilmasdim."},{"t":"ex","en":"Emily preferred that one but did not pay attention to the others.","uz":"Emili o'shanisini afzal ko'rdi, qolganlariga e'tibor bermadi."},{"t":"rule","x":"Diqqat: ot oldida <b>other</b> ko'plik qo'shimchasini olmaydi: <i>other pencils</i> (<i>others pencils</i> emas)."},{"t":"h","x":"Little va few"},{"t":"p","x":"<b>Little</b> (sanalmaydigan otlar bilan) va <b>few</b> (sanaladigan otlar bilan) <b>olmosh</b> sifatida ham ishlatilishi mumkin."},{"t":"ex","en":"Would you like some sugar? — A little, please.","uz":"Shakar olasizmi? — Ozgina, iltimos."},{"t":"list","items":["<b>Only a few / only a little</b> — miqdorning juda ozligini ta'kidlaydi.","<b>Quite a few / quite a little</b> — miqdorning ancha ko'pligini bildiradi."]},{"t":"ex","en":"Only a few customers have accounts.","uz":"Faqat bir nechta mijozning hisob raqami bor."},{"t":"ex","en":"I have quite a few books on art.","uz":"Menda san'at haqida ancha ko'p kitob bor."},{"t":"h","x":"Og'zaki nutqda: not much / not many"},{"t":"p","x":"Og'zaki nutqda <b>little / few</b> ni <b>a little / a few</b> bilan adashtirish mumkinligi sababli, ularning o'rniga <b>inkor yordamchi fe'l + much / many</b> ishlatiladi."},{"t":"ex","en":"They have little money. = They do not have much money.","uz":"Ularning puli kam."},{"t":"ex","en":"I bought few cars. = I did not buy many cars.","uz":"Men ko'p mashina sotib olmadim."},{"t":"h","x":"Darajalovchi so'zlar"},{"t":"p","x":"<b>Little, few</b> oldidan <b>so, too, extremely, relatively, comparatively</b> so'zlari kelib, ularning darajasini kuchaytiradi."},{"t":"ex","en":"I am unwilling to take this drug. I know so little about it.","uz":"Bu dorini ichishni istamayman. Men u haqida juda kam bilaman."},{"t":"ex","en":"They have too many technicians; we have too few.","uz":"Ularda texniklar haddan tashqari ko'p, bizda esa juda kam."},{"t":"h","x":"A little ravish sifatida"},{"t":"p","x":"<b>A little</b> gapda <b>ravish</b> bo'lib kelishi mumkin («biroz, ozgina»)."},{"t":"ex","en":"It rained a little during the night.","uz":"Kechasi biroz yomg'ir yog'di."},{"t":"p","x":"<b>A little</b> ni <b>salbiy ma'noli</b> sifat va ravishlar bilan ishlatish mumkin, lekin ijobiy ma'noli sifat va ravishlar bilan ishlatilmaydi. Shu holatda a little o'rnida <b>rather</b> so'zini ham ishlatsa bo'ladi."},{"t":"table","head":["a little + salbiy","rather + salbiy"],"rows":[["a little annoyed","rather annoyed"],["a little anxious","rather anxious"],["a little impatiently","rather impatiently"]]},{"t":"p","x":"<b>Qiyosiy daraja</b>dagi sifat va ravishlar oldidan ham <b>a little</b> ishlatiladi."},{"t":"ex","en":"The paper should be a little thicker.","uz":"Qog'oz biroz qalinroq bo'lishi kerak."},{"t":"ex","en":"Can you walk a little faster?","uz":"Biroz tezroq yura olasizmi?"}],"quiz":[{"q":"I've broken my pencil. Can I have ___ one?","o":["other","another","the others","others"],"a":1,"e":"Another + birlikdagi ot = yana bitta."},{"q":"There are two pens. One is red and ___ is blue.","o":["another","other","the other","others"],"a":2,"e":"The other + birlik — qolgan oxirgi bittasi."},{"q":"Some students passed; ___ students failed.","o":["another","other","the another","others"],"a":1,"e":"Other + ko'plikdagi ot — boshqa, yana bir nechta."},{"q":"Emily liked that one but ignored ___.","o":["the other","the others","the others ones","another"],"a":1,"e":"Yolg'iz ishlatilganda ko'plik -s other ga qo'shiladi: the others."},{"q":"Choose the correct phrase.","o":["others pencils","other pencils","another pencils","an other pencil"],"a":1,"e":"Ot oldida other ko'plik qo'shimchasini olmaydi."},{"q":"I have ___ books on art — about a hundred!","o":["only a few","quite a few","few","a little"],"a":1,"e":"Quite a few miqdorning ancha ko'pligini bildiradi."},{"q":"'They have little money' is often said in speech as:","o":["They have a little money.","They don't have much money.","They have many money.","They don't have little money."],"a":1,"e":"Og'zaki nutqda little o'rnida not much ishlatiladi."},{"q":"Which is correct?","o":["a little happy","a little annoyed","a little delighted","a little wonderful"],"a":1,"e":"A little salbiy ma'noli sifatlar bilan ishlatiladi."},{"q":"Can you walk ___ faster?","o":["a few","few","a little","little of"],"a":2,"e":"Qiyosiy daraja oldidan a little ishlatiladi."},{"q":"They have too many technicians; we have too ___.","o":["little","few","much","a few"],"a":1,"e":"Technicians sanaladigan ot — few; too darajani kuchaytiradi."}]},{"id":"p5-10","en":"The Definite Article: General Uses and Geographical Names","uz":"Aniq artikl the: umumiy qoidalar va geografik nomlar","emoji":"🌍","level":"B1","group":"Artikl va son","summary":"The ning yagona narsa, tur va guruhni bildirishi, the + sifat; geografik nomlar, davlatlar, sayyoralar, qutblar va yo'nalishlar bilan the ishlatilishi va ishlatilmasligi.","blocks":[{"t":"h","x":"Yagona narsa"},{"t":"p","x":"<b>The</b> joylashuviga ko'ra faqat <b>bitta</b> narsa nazarda tutilganda (tinglovchi qaysi biri ekanini biladi) ishlatiladi."},{"t":"ex","en":"Where is Ann? — Ann is in the garden.","uz":"Ann qayerda? — Bog'da."},{"t":"ex","en":"Please, pass me the salt.","uz":"Iltimos, tuzni uzatib yuboring."},{"t":"ex","en":"Has the mail carrier come?","uz":"Pochtachi keldimi?"},{"t":"h","x":"The + birlikdagi ot — tur yoki guruh"},{"t":"p","x":"<b>The + birlikdagi ot</b> narsalar yoki hayvonlarning butun bir turini (guruhini) ifodalashi mumkin."},{"t":"ex","en":"The whale is in danger of becoming extinct.","uz":"Kitlar yo'qolib ketish xavfi ostida."},{"t":"ex","en":"The deep-freeze has made life easier for housewives.","uz":"Muzlatgich uy bekalarining hayotini osonlashtirdi."},{"t":"rule","x":"Istisno: <b>man</b> so'zi butun insoniyatni yoki irqni nazarda tutsa, <b>the</b> ishlatilmaydi."},{"t":"ex","en":"If oil supplies run out, man may have to fall back on the horse.","uz":"Agar neft zaxiralari tugasa, insoniyat yana otga qaytishiga to'g'ri kelishi mumkin."},{"t":"p","x":"Biror <b>odamlar guruhini</b> ifodalash uchun ham <b>the + birlikdagi ot</b> ishlatiladi. Bunday otlar bilan <b>birlikdagi fe'l</b> va <b>he, she, it</b> olmoshlari ishlatiladi."},{"t":"ex","en":"The small shopkeeper is finding life difficult.","uz":"Kichik do'kondorlar uchun hayot og'irlashmoqda."},{"t":"h","x":"The + sifat"},{"t":"p","x":"<b>The + sifat</b> biror o'ziga xos jihati bilan ajralib turuvchi odamlar guruhini ifodalaydi (fe'l ko'plikda)."},{"t":"ex","en":"The old have to live alone in many countries.","uz":"Ko'p mamlakatlarda qariyalar yolg'iz yashashga majbur."},{"t":"h","x":"Geografik nomlar"},{"t":"table","head":["THE ishlatiladi","THE ishlatilmaydi"],"rows":[["Okean, daryo, dengiz, ko'rfaz nomlari: <i>the Pacific Ocean, the Thames</i>","Birlikdagi ko'llar: <i>Baikal, Geneva</i>"],["Ko'plikdagi orollar: <i>the Azores</i>","Birlikdagi orollar: <i>Madagascar, Greenland</i>"],["Tog' tizmalari: <i>the Andes, the Rocky Mountains</i>","Cho'qqilar, birlikdagi tog'lar: <i>Everest, Mount McKinley</i>"],["Earth (bizning sayyora) va moon: <i>the Earth, the moon</i>","Sayyoralar va yulduz turkumlari nomi: <i>Mars, Earth, Mercury, Ursa Major (Big Bear)</i>"],["Ko'plikdagi davlat nomlari: <i>the Philippines, the Netherlands</i>","Yakka davlatlar: <i>Uzbekistan, Russia, England</i>"],["Republic, Kingdom, States so'zli nomlar: <i>the Irish Republic, the United Kingdom</i>","Shtat nomlari: <i>Texas, New York</i>"],["Cho'l nomlari: <i>the Sahara, the Kyzylkum</i>","Shaharlar: <i>Namangan, London</i>"],["OF tuzilmali nomlar: <i>the United States of America, the Bay of Biscay</i>","Qit'a nomlari: <i>Africa, Europe</i>"],["Region, hududlar: <i>the Baltic, the Balkans</i>","—"],["Qutblar: <i>the South Pole, the North Pole</i>","—"]]},{"t":"rule","x":"Istisnolar (davlatlar): <i>the Ukraine, the Sudan, the Yemen</i> (eski uslubda; hozir ko'pincha <i>Ukraine, Sudan, Yemen</i>). Istisnolar (shahar va joylar): <i>the Hague; the Mall, the City, the Strand</i> (Londondagi joylar)."},{"t":"h","x":"East, west, south, north"},{"t":"table","head":["THE ishlatiladi","THE ishlatilmaydi"],"rows":[["Ot vazifasida kelsa: <i>the north of Spain, the West, the Middle East</i>","Sifat vazifasida kelsa: <i>South Africa, West Germany</i>"],["—","Yo'nalishni bildirsa: <i>Go north, then turn east.</i>"]]},{"t":"rule","x":"Istisno: <i>the West Indies, the East End, the West End</i>."},{"t":"h","x":"Space so'zi"},{"t":"list","items":["<b>the space</b> — bo'sh joy ma'nosida: <i>He tried to park his car, but the space was not big enough.</i> (Mashinasini qo'ymoqchi bo'ldi, lekin joy yetarli emas edi.)","<b>space</b> (artiklsiz) — koinot ma'nosida: <i>There are a lot of stars in space.</i> (Koinotda yulduzlar juda ko'p.)"]}],"quiz":[{"q":"Please pass me ___ salt.","o":["a","an","the","— (no article)"],"a":2,"e":"Vaziyatdan qaysi narsa ekani aniq — the."},{"q":"___ whale is in danger of becoming extinct.","o":["A","The","An","— (no article)"],"a":1,"e":"The + birlikdagi ot butun turni ifodalaydi."},{"q":"Which sentence is correct when talking about all humanity?","o":["The man may have to fall back on the horse.","Man may have to fall back on the horse.","A men may have to fall back on the horse.","The men may fall back on horse."],"a":1,"e":"Man insoniyat ma'nosida the siz ishlatiladi."},{"q":"___ old have to live alone in many countries.","o":["An","— (no article)","The","A"],"a":2,"e":"The + sifat — odamlar guruhini bildiradi."},{"q":"Choose the correct option.","o":["the Lake Baikal","the Everest","the Andes","the Madagascar"],"a":2,"e":"Tog' tizmalari oldidan the ishlatiladi."},{"q":"Choose the correct option.","o":["the Uzbekistan","the Philippines","the Texas","the Africa"],"a":1,"e":"Ko'plikdagi davlat nomlari oldidan the ishlatiladi."},{"q":"He lives in ___ United Kingdom.","o":["a","the","— (no article)","an"],"a":1,"e":"Kingdom, Republic, States so'zli nomlar the bilan."},{"q":"Go ___ north, then turn east.","o":["the","a","— (no article)","an"],"a":2,"e":"Yo'nalishni bildirganda the ishlatilmaydi."},{"q":"They live in ___ north of Spain.","o":["— (no article)","a","the","an"],"a":2,"e":"North ot vazifasida kelganda the ishlatiladi."},{"q":"There are a lot of stars in ___ space.","o":["the","a","— (no article)","an"],"a":2,"e":"Space koinot ma'nosida artiklsiz ishlatiladi."}]},{"id":"p5-11","en":"The Definite Article: Institutions, Places and Special Cases","uz":"Aniq artikl the: muassasalar, joylar va maxsus holatlar","emoji":"🏛️","level":"B1","group":"Artikl va son","summary":"Universitet, mehmonxona, gazeta, musiqa asboblari, tarixiy hujjatlar, bayramlar, ko'chalar bilan the; school/hospital/home/work/town kabi so'zlarning artiklli va artiklsiz qo'llanishi; a number of va the number of.","blocks":[{"t":"h","x":"Nomlar, tadbirlar va sohalar"},{"t":"table","head":["THE ishlatiladi","THE ishlatilmaydi"],"rows":[["Musiqa asboblari: <i>the guitar, the piano</i>","Bayram nomlari: <i>Hayit, Navruz, Thanksgiving</i>"],["University, school, college + of + nom: <i>the University of Connecticut, the School of Business</i>","University, school, college atoqli otdan keyin kelsa: <i>Cambridge University, Business School</i>"],["Tarixiy hujjatlar: <i>the Constitution, the Bill of Rights</i>","Sport o'yinlari: <i>basketball, football</i>"],["Urush nomlari: <i>the Civil War, the Great War</i>","Jahon urushlari (raqam bilan): <i>World War I, World War II</i>"],["Gazeta va jurnal nomlari: <i>The Times, the Xalq So'zi</i>","Fan va soha nomlari: <i>mathematics, sociology</i>"],["Mehmonxona, restoran, pab, muzey, galereya, kino, teatr nomlari: <i>the Red Lion (pub), the National Museum</i>","Do'kon, restoran, mehmonxona, bank nomi kishi ismi bilan kelsa: <i>Lloyds Bank, Luigi's Italian Restaurant</i>"],["—","Ko'cha, shoh ko'cha va maydon nomlari: <i>The Prime Minister lives in Downing Street.</i>"],["—","Airport, station, castle, zoo, park, palace oldidan kishi yoki joy nomi kelsa: <i>Namangan Station, Birmingham Castle</i>"],["—","Musiqa yo'nalishlari: <i>jazz, rock, pop</i>"]]},{"t":"h","x":"Radio va television"},{"t":"list","items":["<b>the radio</b> — doim the bilan: <i>I listen to the radio.</i>","<b>the television</b> — qurilma ma'nosida: <i>Can you turn off the television?</i> (Televizorni o'chira olasanmi?)","<b>television</b> (artiklsiz) — ommaviy axborot vositasi ma'nosida: <i>I am watching television.</i> (Televizor ko'ryapman.)"]},{"t":"h","x":"Mavhum otlar"},{"t":"p","x":"Mavhum otlar umumiy ma'noda artiklsiz ishlatiladi, lekin <b>aniqlashtirilgan</b> (maxsuslashtirilgan) bo'lsa, <b>the</b> oladi."},{"t":"ex","en":"People fear death.","uz":"Odamlar o'limdan qo'rqadi."},{"t":"ex","en":"The death of the great artist upset everyone.","uz":"Buyuk rassomning o'limi hammani qayg'uga soldi."},{"t":"h","x":"Home"},{"t":"p","x":"<b>Home</b> odatda artiklsiz ishlatiladi; lekin aniqlashtirilib, ajratib aytilsa, <b>the</b> oladi."},{"t":"ex","en":"He is at home. I arrived home at 5 p.m.","uz":"U uyda. Men uyga soat 5 da keldim."},{"t":"ex","en":"We arrived at the bride's home.","uz":"Biz kelinning uyiga yetib keldik."},{"t":"ex","en":"For some years, this was the home of your queen.","uz":"Bir necha yil bu qirolichangizning uyi bo'lgan."},{"t":"h","x":"Bed, church, court, hospital, prison, school, college, university"},{"t":"p","x":"Bu so'zlar <b>asosiy maqsadida</b> ishlatilsa (masalan, kasal davolanish uchun kasalxonaga, o'qish uchun maktabga), <b>the</b> ishlatilmaydi. Agar boshqa maqsadda borilsa, <b>the</b> ishlatiladi."},{"t":"ex","en":"He was ill, that is why he went to hospital.","uz":"U kasal edi, shuning uchun kasalxonaga yotdi."},{"t":"ex","en":"He goes to the prison, sometimes to give lectures.","uz":"U qamoqxonaga ba'zan ma'ruza o'qish uchun boradi."},{"t":"ex","en":"My dad went to the school to meet my teacher.","uz":"Dadam o'qituvchim bilan uchrashish uchun maktabga bordi."},{"t":"h","x":"Sea, work, office, town"},{"t":"table","head":["THE bilan","THE siz"],"rows":[["<b>go / be at the sea</b> — dengiz bo'yida, sohilda: <i>He is at the sea.</i>","<b>go / be at sea</b> — kemada, dengizda (suzishda): <i>He is at sea.</i>"],["<b>the work</b> — buyurilgan aniq (jismoniy) ish: <i>Have you finished the work which I ordered?</i>","<b>work</b> — ishda, ishxonaga: <i>He went to work.</i>"],["<b>the office</b>: <i>He went to the office.</i>","—"],["<b>the town</b> — so'zlovchining ona shahri emas, boshqa aniq shahar: <i>Can you remember the name of the town which we visited last year?</i>","<b>town</b> — so'zlovchining o'z shahri: <i>Bobur is out of town on a business trip.</i>"],["Shahar ichidagi mavjud muassasalar (airport, fire brigade, police station): <i>Can you tell me where the airport is?</i>","—"]]},{"t":"h","x":"A number of / the number of"},{"t":"formula","x":"A number of + plural noun + plural verb<br>The number of + plural noun + singular verb"},{"t":"ex","en":"A number of people in this room are single.","uz":"Bu xonadagi bir qancha odamlar bo'ydoq."},{"t":"ex","en":"The number of days in a week is seven.","uz":"Haftadagi kunlar soni yettita."},{"t":"rule","x":"<b>A number of</b> = «bir qancha» (fe'l ko'plikda); <b>the number of</b> = «… soni» (fe'l birlikda)."}],"quiz":[{"q":"She plays ___ piano very well.","o":["a","the","— (no article)","an"],"a":1,"e":"Musiqa asboblari oldidan the ishlatiladi."},{"q":"He likes playing ___ football.","o":["the","a","— (no article)","an"],"a":2,"e":"Sport o'yinlari oldidan artikl ishlatilmaydi."},{"q":"Choose the correct option.","o":["the World War II","World War II","a World War II","the World War"],"a":1,"e":"Raqamli jahon urushlari nomlari the siz."},{"q":"The Prime Minister lives in ___ Downing Street.","o":["the","a","— (no article)","an"],"a":2,"e":"Ko'cha nomlari oldidan the ishlatilmaydi."},{"q":"He was ill, so he went to ___ hospital.","o":["the","a","— (no article)","an"],"a":2,"e":"Hospital asosiy maqsadida (davolanish) ishlatilsa, the siz."},{"q":"My dad went to ___ school to meet my teacher.","o":["the","— (no article)","a","an"],"a":0,"e":"Maktabga o'qish uchun emas, boshqa maqsadda borilganda the ishlatiladi."},{"q":"'He is at sea' means:","o":["He is on the beach.","He is on a ship.","He is near the sea in a hotel.","He is swimming in a pool."],"a":1,"e":"At sea — kemada, dengizda; at the sea — dengiz bo'yida."},{"q":"Can you turn off ___ television?","o":["the","— (no article)","a","an"],"a":0,"e":"Television qurilma ma'nosida the bilan."},{"q":"A number of people in this room ___ single.","o":["is","are","was","be"],"a":1,"e":"A number of + ko'plikdagi ot + ko'plikdagi fe'l."},{"q":"The number of days in a week ___ seven.","o":["are","is","were","have"],"a":1,"e":"The number of + ko'plikdagi ot + birlikdagi fe'l."}]},{"id":"p6-01","en":"Prepositions of Time: at, on, in, by, before","uz":"Vaqt predloglari: at, on, in, by, before","emoji":"⏰","level":"A1","group":"Predloglar","summary":"Vaqt, kun, sana, oy va yil oldidan qaysi predlog ishlatilishi, hamda by, till, before, on time va in time farqlari.","blocks":[{"t":"rule","x":"Predlogdan keyin faqat <b>ot</b> (noun) keladi. Agar predlogdan keyin fe'l kelsa, u fe'lning <b>gerund</b> (-ing) shakli ishlatiladi: <i>before starting</i>, <i>after eating</i>."},{"t":"h","x":"At + soat (vaqt)"},{"t":"ex","en":"I got up at 6.","uz":"Men soat 6 da turdim."},{"t":"h","x":"At + yosh"},{"t":"p","x":"Yoshni aytishda <b>at seventeen / eighteen</b> yoki <b>at the age of seventeen / eighteen</b> deyiladi."},{"t":"ex","en":"He started running his own business at the age of seventeen.","uz":"U o'z biznesini 17 yoshida yurita boshladi."},{"t":"h","x":"On + kun / sana"},{"t":"p","x":"<b>On</b> aniq bir kunni ifodalash uchun ishlatiladi: <i>on Monday, on Friday, on 4th of May, on Christmas Day</i>."},{"t":"ex","en":"She comes here on Mondays.","uz":"U bu yerga dushanba kunlari keladi."},{"t":"ex","en":"We finish our course on the 30th of June.","uz":"Biz kursimizni 30-iyunda tugatamiz."},{"t":"ex","en":"On Christmas Day, everyone receives presents.","uz":"Rojdestvo kuni hamma sovg'a oladi."},{"t":"rule","x":"Lekin: <b>at Christmas, at Easter, at night</b> — bu yerda faqat bitta kun emas, balki <b>davr</b> nazarda tutiladi."},{"t":"p","x":"<b>At the weekend</b> — aniq bir kun emas, balki davr nazarda tutiladi, shuning uchun bu birikmada <b>at</b> ishlatiladi (amerikacha: <i>on the weekend</i>)."},{"t":"ex","en":"I'll visit your home on Sunday.","uz":"Men uyingizga yakshanba kuni boraman."},{"t":"ex","en":"I'll visit your home at the weekend.","uz":"Men uyingizga dam olish kunlari boraman."},{"t":"h","x":"In + hafta / oy / yil"},{"t":"p","x":"<i>in April, in August, in a week, in 2009</i>."},{"t":"ex","en":"We start our studies in September.","uz":"Biz o'qishni sentabrda boshlaymiz."},{"t":"ex","en":"I'll complete my essay in a week.","uz":"Insholimni bir haftada tugataman."},{"t":"ex","en":"I'll complete my essay this week.","uz":"Insholimni shu hafta tugataman."},{"t":"h","x":"Istisno iboralar"},{"t":"p","x":"Kun qismlari bilan <b>in</b> ishlatiladi: <i>in the morning, in the afternoon, in the evening</i>."},{"t":"ex","en":"I usually get up at 6 in the morning.","uz":"Men odatda ertalab soat 6 da turaman."},{"t":"ex","en":"Do you usually watch TV in the evening?","uz":"Siz odatda kechqurun televizor ko'rasizmi?"},{"t":"rule","x":"Istisno qoida: kun qismi aniq kunga bog'lansa, <b>on</b> ishlatiladi: <i>on Monday morning, on Friday evening, on the morning of April 7</i>. Ammo <i>tomorrow evening</i> oldidan predlog qo'yilmaydi."},{"t":"ex","en":"On the morning of April 7, we left the city.","uz":"7-aprel kuni ertalab biz shahardan chiqdik."},{"t":"ex","en":"I'll call you tomorrow evening.","uz":"Ertaga kechqurun senga qo'ng'iroq qilaman."},{"t":"ex","en":"I'll call you in the evening.","uz":"Kechqurun qo'ng'iroq qilaman."},{"t":"table","head":["Ifoda","Predlog"],"rows":[["August 1995 (oy + yil)","in August 1995"],["1 August 1995 (aniq sana)","on 1 August 1995"]]},{"t":"h","x":"this / next / every / following / upcoming"},{"t":"rule","x":"<b>this, next, last, every, following, upcoming</b> so'zlari kelgan vaqt iboralari oldidan <b>in / on / at</b> ishlatilmaydi."},{"t":"ex","en":"I go to church every Sunday. / I go to church on Sunday.","uz":"Men har yakshanba cherkovga boraman."},{"t":"ex","en":"We start our studies in September. / We start our studies next September.","uz":"Biz o'qishni sentabrda / kelasi sentabrda boshlaymiz."},{"t":"h","x":"By + vaqt"},{"t":"p","x":"<b>By</b> — kelishilgan vaqtdan oldin yoki aynan o'sha vaqtda, lekin undan kech emas («...gacha, ...dan kechiktirmay»)."},{"t":"ex","en":"I'll arrive by five.","uz":"Men soat beshgacha (kechi bilan beshda) yetib kelaman."},{"t":"rule","x":"Farq: <i>You should register your book <b>by</b> Friday.</i> — juma kuni ham kiradi (eng kechi juma). <i>You should keep your book <b>till</b> Friday.</i> — <b>till/until</b> davom etadigan harakat bilan ishlatiladi va juma kuni chegara hisoblanadi."},{"t":"h","x":"Before"},{"t":"p","x":"<b>Before</b> predlog, bog'lovchi va ravish bo'lib kela oladi."},{"t":"ex","en":"Before starting the match, we should do warm-up exercises.","uz":"O'yinni boshlashdan oldin badan qizdirish mashqlarini qilishimiz kerak. (predlog + gerund)"},{"t":"ex","en":"Before we start the match, we should do warm-up exercises.","uz":"O'yinni boshlashimizdan oldin... (bog'lovchi)"},{"t":"ex","en":"We should do warm-up exercises before we start the match.","uz":"O'yinni boshlashdan oldin mashq qilishimiz kerak."},{"t":"ex","en":"I haven't tried to ride a horse before.","uz":"Men ilgari otga minib ko'rmaganman. (ravish)"},{"t":"h","x":"On time / in time / in good time"},{"t":"list","items":["<b>On time</b> — aynan kelishilgan vaqtda, erta ham emas, kech ham emas.","<b>In time</b> — kelishilgan vaqtdan oldin, kechikmay (ulgurib). <b>In time for + ot</b>.","<b>In good time</b> — kelishilgan vaqtdan ancha oldin."]},{"t":"ex","en":"We started the meeting on time.","uz":"Yig'ilishni o'z vaqtida boshladik."},{"t":"ex","en":"I arrived at the theatre in time.","uz":"Teatrga ulgurib keldim."},{"t":"ex","en":"They came in time for their train.","uz":"Ular poyezdlariga ulgurib kelishdi."},{"t":"ex","en":"I came to our course in good time. Until they came, I even slept a little.","uz":"Kursga ancha erta keldim. Ular kelguncha hatto biroz uxlab oldim."},{"t":"h","x":"On + V-ing = When + S + P"},{"t":"formula","x":"On + V-ing = When + Subject + Predicate"},{"t":"ex","en":"On arriving home, I called my mother.","uz":"Uyga kelishim bilan onamga qo'ng'iroq qildim."},{"t":"ex","en":"On teaching, I gained a lot of experience. = When I taught, I gained a lot of experience.","uz":"Dars berganimda ko'p tajriba orttirdim."}],"quiz":[{"q":"I got up ___ 6 o'clock.","o":["in","on","at","by"],"a":2,"e":"Soat (aniq vaqt) oldidan at ishlatiladi."},{"q":"She comes here ___ Mondays.","o":["at","on","in","to"],"a":1,"e":"Hafta kunlari oldidan on ishlatiladi."},{"q":"We start our studies ___ September.","o":["on","at","in","by"],"a":2,"e":"Oy nomlari oldidan in ishlatiladi."},{"q":"Children get presents ___ Christmas (the holiday period).","o":["on","in","at","by"],"a":2,"e":"Bayram davri nazarda tutilsa: at Christmas. Aniq kun bo'lsa: on Christmas Day."},{"q":"I'll see you ___ Friday evening.","o":["in","on","at","—"],"a":1,"e":"Kun qismi aniq kunga bog'lansa on ishlatiladi: on Friday evening."},{"q":"Choose the correct sentence.","o":["I go to church on every Sunday.","I go to church at every Sunday.","I go to church every Sunday.","I go to church in every Sunday."],"a":2,"e":"every, next, this, last oldidan predlog ishlatilmaydi."},{"q":"Please send the report ___ Friday at the latest.","o":["by","till","since","during"],"a":0,"e":"By — belgilangan vaqtdan kech emas degan ma'noni beradi."},{"q":"The film started exactly at 7 — it started ___.","o":["in time","on time","in good time","by time"],"a":1,"e":"On time — aynan kelishilgan vaqtda."},{"q":"We got to the station ___ for our train.","o":["on time","in time","at time","by time"],"a":1,"e":"In time for + ot — ulgurib, kechikmay."},{"q":"___ the door, she screamed. (= When she opened the door)","o":["On open","On opening","In opening","At opened"],"a":1,"e":"On + V-ing = When + S + P. Predlogdan keyin gerund keladi."}]},{"id":"p6-02","en":"Prepositions of Time: beginning/end, from…to, since, during, for, after, while","uz":"Vaqt predloglari: boshi/oxiri, from…to, since, during, for, after, while","emoji":"⌛","level":"A2","group":"Predloglar","summary":"At/in the beginning va end, in + davr, from…to/till, since, during va for, after va afterwards hamda while farqlari.","blocks":[{"t":"h","x":"At the beginning / at the end"},{"t":"p","x":"Biror joy yoki narsaning boshi yoki oxirini ko'rsatish uchun qo'llaniladi (<b>at the beginning of / at the end of</b>)."},{"t":"ex","en":"At the end, you can find a list of irregular verbs.","uz":"Oxirida noto'g'ri fe'llar ro'yxatini topishingiz mumkin."},{"t":"ex","en":"At the beginning of the book, there are contents.","uz":"Kitobning boshida mundarija bor."},{"t":"h","x":"In the beginning / in the end"},{"t":"p","x":"Biror ish-harakatning boshi yoki yakunini bildiradi."},{"t":"table","head":["Ibora","Ma'nosi"],"rows":[["In the beginning = at first","avvaliga, dastlab"],["In the end = at last","va nihoyat, oxir-oqibat"]]},{"t":"ex","en":"At first, he opposed the bargain, but in the end, he agreed.","uz":"Avvaliga u bitimga qarshi chiqdi, lekin oxir-oqibat rozi bo'ldi."},{"t":"ex","en":"In the beginning, we had some problems with understanding each other.","uz":"Dastlab bir-birimizni tushunishda muammolarimiz bor edi."},{"t":"h","x":"In + vaqt davri (kelasi zamon)"},{"t":"p","x":"Kelasi zamonda <b>in + davr</b> «shu davr oxirida, ...dan keyin» deb tushuniladi."},{"t":"ex","en":"I should finish the lesson in 21 minutes.","uz":"Men darsni 21 daqiqadan keyin tugatishim kerak."},{"t":"h","x":"From … to / till / until"},{"t":"p","x":"Vaqt oralig'ini ko'rsatish uchun <b>from … to / till / until</b> ishlatiladi."},{"t":"ex","en":"Most people work from 8:30 to / till 7.","uz":"Ko'pchilik 8:30 dan 7 gacha ishlaydi."},{"t":"rule","x":"Masofa oralig'ini ko'rsatish uchun faqat <b>from … to</b> ishlatiladi (till/until emas)."},{"t":"ex","en":"It is 10 km from my home to Chorsu.","uz":"Uyimdan Chorsugacha 10 km."},{"t":"h","x":"Since — uch xil vazifa"},{"t":"list","items":["<b>Bog'lovchi</b> (conjunction): <i>He has worked since I left.</i> — Men ketganimdan beri u ishlab kelmoqda.","<b>Predlog</b> (preposition): <i>He has worked since my departure.</i> — Ketishimdan beri u ishlamoqda.","<b>Ravish</b> (adverb): <i>He left school in 1997. I have not seen him since.</i> — O'shandan beri uni ko'rmadim."]},{"t":"h","x":"During va for"},{"t":"p","x":"<b>During</b> — «davomida, paytida» ma'nosida biror vaqt oralig'ini ifodalaydi va <b>faqat otlar oldidan</b> keladi: <i>during the summer, during the Middle Ages</i>."},{"t":"p","x":"During bilan berilgan gaplarda ish-harakat shu vaqt davomida yoki shu vaqt oralig'ining bir qismida sodir bo'lgan bo'lishi mumkin."},{"t":"ex","en":"During the night, it stopped raining.","uz":"Tun davomida (tunda bir payt) yomg'ir to'xtadi."},{"t":"ex","en":"During the last century, Japanese people worked very hard.","uz":"O'tgan asr davomida yaponlar juda qattiq mehnat qilishdi."},{"t":"p","x":"<b>For</b> asosan miqdor (qancha vaqt) bilan beriladi: <i>for three years, for a week</i>. Solishtiring: <b>for a week</b> (bir hafta mobaynida) — <b>during the week</b> (o'sha hafta davomida)."},{"t":"ex","en":"I lived there for three years.","uz":"Men u yerda uch yil yashadim."},{"t":"ex","en":"I shouldn't work for a week. During the week, I hope I will rest enough.","uz":"Bir hafta ishlamasligim kerak. O'sha hafta davomida yetarlicha dam olaman deb umid qilaman."},{"t":"p","x":"<b>For</b> boshqa ma'nolarda ham ishlatiladi:"},{"t":"ex","en":"He asked for fifty pounds.","uz":"U ellik funt so'radi."},{"t":"ex","en":"It is for you.","uz":"Bu siz uchun."},{"t":"p","x":"<b>For</b> bog'lovchi sifatida <b>because</b> (chunki) ma'nosida keladi:"},{"t":"ex","en":"I told them to postpone the meeting, for I was tired.","uz":"Ularga yig'ilishni keyinga qoldirishni aytdim, chunki charchagan edim."},{"t":"h","x":"After va afterwards"},{"t":"p","x":"<b>After</b> ot yoki gerunddan oldin kelib «keyin, so'ng» ma'nosini bildiradi."},{"t":"ex","en":"Don't have a bathe after a meal / after eating.","uz":"Ovqatdan keyin cho'milmang."},{"t":"p","x":"<b>Afterwards</b> o'zidan keyin ot talab qilmaydi; u ham «keyin» ma'nosini beradi va <b>after that / then</b> ga teng."},{"t":"ex","en":"Don't have a big meal and bathe afterwards.","uz":"Ko'p ovqat yeb, keyin cho'milmang."},{"t":"ex","en":"Don't have a big meal. If you do so, don't have a bathe afterwards.","uz":"Ko'p ovqat yemang. Agar yesangiz, keyin cho'milmang."},{"t":"p","x":"<b>Afterwards</b> so'zi <b>soon, not long, immediately</b> bilan kelib ma'noni kuchaytiradi."},{"t":"ex","en":"Soon afterwards, we got a letter.","uz":"Ko'p o'tmay biz xat oldik."},{"t":"ex","en":"We got a letter not long afterwards.","uz":"Oradan ko'p vaqt o'tmay xat oldik."},{"t":"h","x":"While"},{"t":"rule","x":"<b>While</b> — «davomida, paytida, mobaynida» deb tarjima qilinadi, lekin <b>faqat gap (ega + kesim) bilan</b> keladi. <b>During</b> esa faqat ot bilan."},{"t":"ex","en":"We did not speak during the meal.","uz":"Ovqat paytida gaplashmadik."},{"t":"ex","en":"We did not speak while we were eating.","uz":"Ovqatlanayotganimizda gaplashmadik."}],"quiz":[{"q":"___, he refused, but finally he agreed. (= At first)","o":["At the beginning","In the beginning","On the beginning","By the beginning"],"a":1,"e":"In the beginning = at first — avvaliga (harakatning boshi)."},{"q":"You can find the answers ___ of the book.","o":["in the end","at the end","on the end","by the end"],"a":1,"e":"Narsa yoki joyning oxirini ko'rsatish uchun at the end (of) ishlatiladi."},{"q":"It is 10 km ___ my home to the city centre.","o":["from … till","from … until","from … to","since … to"],"a":2,"e":"Masofa uchun faqat from … to ishlatiladi."},{"q":"I'll be ready ___ ten minutes. (= after ten minutes)","o":["in","for","during","since"],"a":0,"e":"Kelasi zamonda in + davr «shu davr oxirida» ma'nosini beradi."},{"q":"He left school in 1997. I haven't seen him ___.","o":["for","since","during","while"],"a":1,"e":"Since bu yerda ravish: o'shandan beri."},{"q":"I lived in London ___ three years.","o":["during","since","for","while"],"a":2,"e":"Miqdor (qancha vaqt) bilan for ishlatiladi."},{"q":"It stopped raining ___ the night.","o":["while","during","for","since"],"a":1,"e":"During ot oldidan keladi va davr ichidagi bir payti ham bo'lishi mumkin."},{"q":"We didn't speak ___ we were eating.","o":["during","for","while","after"],"a":2,"e":"While dan keyin to'liq gap (ega + kesim) keladi."},{"q":"Choose the correct sentence.","o":["Don't swim after eat.","Don't swim afterwards a meal.","Don't swim after eating.","Don't swim after to eat."],"a":2,"e":"After dan keyin ot yoki gerund keladi; afterwards ot olmaydi."},{"q":"In 'I postponed it, for I was tired', 'for' means:","o":["during","because","since","instead of"],"a":1,"e":"For bog'lovchi sifatida because (chunki) ma'nosida keladi."}]},{"id":"p6-03","en":"Prepositions of Place: at, in, into, on, onto","uz":"O'rin predloglari: at, in, into, on, onto","emoji":"📍","level":"A1","group":"Predloglar","summary":"At (yonida, nuqtada) va in (ichida) farqi, qaysi so'zlar bilan qaysi predlog ishlatilishi, hamda in/into va on/onto farqlari.","blocks":[{"t":"h","x":"At va in"},{"t":"p","x":"<b>At</b> predlogi «yonida» deb tarjima qilinadi va biror aniq <b>nuqtada</b> ekanligimizni ko'rsatadi. At bilan biz hudud ichida, chegarasida yoki yonida bo'lishimiz mumkin."},{"t":"ex","en":"I am at the blackboard.","uz":"Men doska yonidaman."},{"t":"p","x":"Bundan tashqari <b>at</b> quyidagi so'zlar oldidan keladi:"},{"t":"list","items":["home, work, the office, school, university","an address, the bus stop, the end, the station, the airport","a concert, a conference, a party","the dentist's, the doctor's va h.k."]},{"t":"ex","en":"He is at the bus stop.","uz":"U avtobus bekatida."},{"t":"p","x":"<b>In</b> predlogi «ichida» deb tarjima qilinadi. U aniq chegarasi bor yoki biror narsa bilan o'ralgan joylar bilan qo'llaniladi."},{"t":"ex","en":"We are in the room.","uz":"Biz xonadamiz."},{"t":"p","x":"<b>In</b> quyidagi so'zlar bilan keladi:"},{"t":"list","items":["a country, a town, a village, a square, a street","a room, a forest, a field","bed, hospital, prison","the sky, the world","a newspaper, a magazine, a book, a photograph, a picture","a car, the middle of"]},{"t":"h","x":"Sea / river / lake"},{"t":"table","head":["Ibora","Ma'nosi"],"rows":[["in the sea / river / lake","suv ichida"],["at the sea / river / lake","dengiz/daryo/ko'l yonida (bo'yida)"],["at sea","kemada, dengiz ustida (suzib yurib)"]]},{"t":"ex","en":"Children are swimming in the lake.","uz":"Bolalar ko'lda suzishyapti."},{"t":"ex","en":"They have a hotel at the sea.","uz":"Ularning dengiz bo'yida mehmonxonasi bor."},{"t":"ex","en":"The ships of the navy are at sea.","uz":"Harbiy-dengiz flotining kemalari dengizda (suzib yuribdi)."},{"t":"h","x":"In va into"},{"t":"list","items":["<b>In</b> — biror narsa ichida joylashganlikni (holatni) ifodalaydi.","<b>Into</b> — biror narsa ichiga qarab harakatni ifodalaydi."]},{"t":"ex","en":"We were in the hall.","uz":"Biz zalda edik."},{"t":"ex","en":"We were running into the hall.","uz":"Biz zalga yugurib kirayotgan edik."},{"t":"rule","x":"<b>Put</b> fe'li bilan <b>in</b> ham, <b>into</b> ham ishlatilishi mumkin: <i>He put his hand in / into his pocket.</i>"},{"t":"p","x":"<b>In</b> ravish vazifasida ham kela oladi: <i>Come in.</i> — Kiring."},{"t":"h","x":"On va onto"},{"t":"p","x":"<b>On</b> — «ustida» deb tarjima qilinadi va ham joylashuv, ham harakat uchun ishlatiladi."},{"t":"ex","en":"The book is on the table.","uz":"Kitob stol ustida."},{"t":"ex","en":"Snow fell on the hills.","uz":"Tepaliklarga qor yog'di."},{"t":"p","x":"<b>Onto</b> esa faqat harakat uchun ishlatiladi (biror narsa ustiga)."},{"t":"ex","en":"We lifted him onto the table.","uz":"Biz uni stol ustiga ko'tardik."},{"t":"ex","en":"The cat jumped onto the chair.","uz":"Mushuk stul ustiga sakradi."},{"t":"p","x":"<b>On</b> ham ravish bo'lib kela oladi: <i>Come on.</i> — Qani, kel(ing)."},{"t":"h","x":"Solishtiring: on / at / in the door"},{"t":"ex","en":"His name is on the door.","uz":"Uning ismi eshik ustiga yopishtirilgan."},{"t":"ex","en":"His name is at the door.","uz":"Uning ismi eshik yonida yozilgan."},{"t":"rule","x":"<i>His name is in the door.</i> — mantiqan noto'g'ri. Joylashuv uchun <b>to</b> (yo'nalish) va <b>into</b> (ichiga harakat) farqini ham yodda tuting."}],"quiz":[{"q":"I'll meet you ___ the bus stop.","o":["in","at","on","into"],"a":1,"e":"Bus stop, station, airport kabi aniq nuqtalar bilan at ishlatiladi."},{"q":"She lives ___ a small village.","o":["at","on","in","onto"],"a":2,"e":"Country, town, village bilan in ishlatiladi."},{"q":"He is ill and stays ___ bed.","o":["in","at","on","into"],"a":0,"e":"Bed, hospital, prison bilan in ishlatiladi."},{"q":"I read about it ___ a magazine.","o":["at","on","in","onto"],"a":2,"e":"Newspaper, magazine, book bilan in ishlatiladi."},{"q":"The children are swimming ___ the lake.","o":["at","in","on","onto"],"a":1,"e":"Suv ichida bo'lsa: in the lake."},{"q":"The sailors have been ___ sea for two months.","o":["in","at","on","into"],"a":1,"e":"At sea — kemada, dengizda suzib yurib."},{"q":"She ran ___ the kitchen.","o":["in","at","into","onto"],"a":2,"e":"Ichkariga harakat bo'lsa into ishlatiladi."},{"q":"The cat jumped ___ the chair.","o":["on to the","onto","into","at"],"a":1,"e":"Narsa ustiga harakat uchun onto ishlatiladi."},{"q":"Which sentence is illogical?","o":["His name is on the door.","His name is at the door.","His name is in the door.","The key is in the door."],"a":2,"e":"Ism eshik ichida bo'la olmaydi — in the door bu holatda mantiqsiz."},{"q":"Which verb can be used with both 'in' and 'into' with the same meaning?","o":["be","stay","put","live"],"a":2,"e":"Put bilan in ham, into ham ishlatiladi: put his hand in/into his pocket."}]},{"id":"p6-04","en":"Above, Over, Below, Under, Between, Among and Other Place Prepositions","uz":"Above, over, below, under, between, among va boshqa o'rin predloglari","emoji":"↕️","level":"A2","group":"Predloglar","summary":"Above/over, below/under, beneath, beside/besides, between/among, in front of, opposite, behind predloglarining ma'nolari va farqlari.","blocks":[{"t":"h","x":"Above va over"},{"t":"p","x":"<b>Above</b> va <b>over</b> «yuqorida, yuqoriroqda» ma'nosini beradi va ko'pincha bir-birining o'rnida ishlatiladi."},{"t":"ex","en":"The helicopter hovered over / above us.","uz":"Vertolyot tepamizda muallaq turdi."},{"t":"ex","en":"The flag moved over / above our heads.","uz":"Bayroq boshimiz uzra hilpiradi."},{"t":"list","items":["<b>Over</b> — to'g'ridan-to'g'ri «tepasida», tegib turishi ham mumkin.","<b>Above</b> — «tepasida», ammo orada to'siq yoki bo'shliq bor."]},{"t":"ex","en":"The book is over the notebook.","uz":"Kitob daftar ustida (ustma-ust turibdi)."},{"t":"ex","en":"The book is above the notebook.","uz":"Kitob daftardan yuqorida (orada nimadir bor)."},{"t":"ex","en":"Mary lives above me.","uz":"Meri mendan yuqori qavatda yashaydi."},{"t":"ex","en":"Tom was lying over John when they had fallen into the hole.","uz":"Chuqurga yiqilishganda Tom Jonning ustida yotgan edi."},{"t":"h","x":"Lavozimda yuqori"},{"t":"p","x":"<b>Over</b> va <b>above</b> «lavozimda yuqori» ma'nosida kelishi mumkin. Bunda <b>over</b> bir pog'ona yuqorini, <b>above</b> bir necha pog'ona yuqorini nazarda tutadi."},{"t":"ex","en":"He is over me.","uz":"U mendan bir pog'ona yuqori (bevosita boshlig'im)."},{"t":"ex","en":"He is above me.","uz":"U mendan (bir necha pog'ona) yuqori lavozimda."},{"t":"h","x":"Over ning boshqa ma'nolari"},{"t":"p","x":"<b>All over + ot / olmosh</b> = in every part of — «hamma joyida»."},{"t":"ex","en":"He has friends all over the world.","uz":"Uning butun dunyoda do'stlari bor."},{"t":"p","x":"<b>Over</b> — narigi tomonida, bir tomondan ikkinchi tomonga, orqali (across), ustini yopib ma'nolarida:"},{"t":"ex","en":"He lives over the mountains.","uz":"U tog'larning narigi tomonida yashaydi."},{"t":"ex","en":"The bird flew over the lake.","uz":"Qush ko'l ustidan uchib o'tdi."},{"t":"ex","en":"There is a bridge over the river.","uz":"Daryo ustida ko'prik bor."},{"t":"ex","en":"She put a blanket over him.","uz":"U uning ustiga ko'rpa yopdi."},{"t":"p","x":"<b>Over = more than</b> (...dan ko'p):"},{"t":"ex","en":"Over fifty people came to the meeting.","uz":"Yig'ilishga ellikdan ortiq odam keldi."},{"t":"p","x":"<b>Over + ovqat / ichimlik</b> — «...ustida, ...paytida»:"},{"t":"ex","en":"We had a chat over a cup of tea.","uz":"Bir piyola choy ustida suhbatlashdik."},{"t":"ex","en":"We discussed the issue over lunch.","uz":"Masalani tushlik paytida muhokama qildik."},{"t":"formula","x":"take + vaqt + over + ot / olmosh — biror ishni tugatishga vaqt sarflash"},{"t":"ex","en":"He took two years over his invention.","uz":"U ixtirosiga ikki yil sarfladi."},{"t":"ex","en":"They usually don't take long over lunch.","uz":"Ular odatda tushlikka ko'p vaqt sarflashmaydi."},{"t":"p","x":"<b>Above</b> sifat yoki ravish sifatida «yuqorida keltirilgan, avval aytilgan» ma'nosini beradi: <i>the above address</i> (= the aforementioned address)."},{"t":"h","x":"Below va under"},{"t":"p","x":"Ikkalasi ham «pastida, pastroqda» ma'nosini beradi. Orada to'siq yoki bo'shliq bo'lsa <b>below</b>, hech narsa bo'lmasa (bevosita ostida) <b>under</b> ishlatiladi."},{"t":"ex","en":"They live below us.","uz":"Ular bizdan pastki qavatda yashashadi."},{"t":"ex","en":"The ice cracked under his feet.","uz":"Muz uning oyog'i ostida yorildi."},{"t":"p","x":"Lavozimda past ma'nosida: <b>under</b> — bir pog'ona past, <b>below</b> — bir necha pog'ona past."},{"t":"ex","en":"He is under me. / He is below me.","uz":"U mendan bir pog'ona past. / U mendan bir necha pog'ona past."},{"t":"h","x":"Beneath"},{"t":"p","x":"<b>Beneath</b> ba'zan <b>under</b> o'rnida ishlatiladi, ammo uni ko'chma (majoziy) ma'noda ishlatgan ma'qulroq («...ga loyiq emas, ...dan past»)."},{"t":"ex","en":"He would think it beneath him to tell a lie.","uz":"U yolg'on gapirishni o'ziga ep ko'rmaydi."},{"t":"ex","en":"She married beneath her.","uz":"U o'zidan past mavqedagi odamga turmushga chiqdi."},{"t":"h","x":"Beside, between, in front of, opposite, behind"},{"t":"table","head":["Predlog","Ma'nosi"],"rows":[["beside","yonida"],["between","orasida (ikkisi orasida)"],["in front of","oldida"],["opposite","qarshisida"],["behind","orqasida"]]},{"t":"table","head":["","Chap","O'rta","O'ng"],"rows":[["Sahna","","",""],["A qator","Tom","John","Ann"],["B qator","Tim","Mary","Bob"]]},{"t":"ex","en":"John is between Tom and Ann.","uz":"Jon Tom bilan Ann orasida."},{"t":"ex","en":"Ann is in front of Bob.","uz":"Ann Bobning oldida."},{"t":"ex","en":"Tim is behind Tom.","uz":"Tim Tomning orqasida."},{"t":"p","x":"Agar stol atrofida Ann va Tim bir-biriga qarab o'tirgan bo'lsa, <b>opposite</b> ishlatiladi:"},{"t":"ex","en":"Tim is sitting opposite Ann.","uz":"Tim Annning qarshisida o'tiribdi."},{"t":"h","x":"Beside va besides"},{"t":"rule","x":"<b>Beside</b> — yonida. <b>Besides</b> — «bundan tashqari, ...dan tashqari, yana» va «baribir, nima bo'lganda ham» (anyway, in any case) ma'nolarini beradi."},{"t":"ex","en":"Besides helping Tom, I cooked the whole meal.","uz":"Tomga yordam berganimdan tashqari, men butun taomni pishirdim."},{"t":"ex","en":"We can't afford this dog. Besides, Tom doesn't like dogs.","uz":"Bu itni sotib ololmaymiz. Qolaversa, Tom itlarni yoqtirmaydi."},{"t":"h","x":"Between va among"},{"t":"p","x":"<b>Between</b> — ikkita narsa yoki kishi orasida joylashgan uchinchi narsani ko'rsatadi. Ammo ikkitadan ko'p narsa aniq, nomma-nom sanalsa ham <b>between</b> ishlatilishi mumkin."},{"t":"ex","en":"Luxembourg lies between Belgium, Germany and France.","uz":"Lyuksemburg Belgiya, Germaniya va Fransiya orasida joylashgan."},{"t":"p","x":"<b>Among</b> — ko'p sonli narsalar yoki kishilar orasida bo'lishni ko'rsatadi."},{"t":"ex","en":"He was very happy to be among his friends.","uz":"U do'stlari orasida bo'lganidan juda xursand edi."}],"quiz":[{"q":"There is a bridge ___ the river.","o":["under","over","below","among"],"a":1,"e":"Over — bir tomondan ikkinchi tomonga, ustidan ma'nosida."},{"q":"___ fifty people came to the party. (= more than)","o":["Above of","Over","Beneath","Upon"],"a":1,"e":"Over = more than."},{"q":"We discussed the plan ___ a cup of coffee.","o":["above","over","on","beside"],"a":1,"e":"Over + ovqat/ichimlik — ...ustida, ...paytida."},{"q":"The ice cracked ___ his feet.","o":["below","under","beneath of","over"],"a":1,"e":"Bevosita ostida, orada hech narsa yo'q bo'lsa under ishlatiladi."},{"q":"He has friends ___ the world.","o":["all above","all over","all on","over all of"],"a":1,"e":"All over = in every part of — hamma joyida."},{"q":"Luxembourg lies ___ Belgium, Germany and France.","o":["among","between","beside","besides"],"a":1,"e":"Aniq, nomma-nom sanalgan narsalar orasida between ishlatilishi mumkin."},{"q":"She felt happy ___ her old friends.","o":["between","among","besides","opposite"],"a":1,"e":"Ko'p kishilar orasida among ishlatiladi."},{"q":"We can't go today. ___, it's raining. (= anyway)","o":["Beside","Besides","Between","Beneath"],"a":1,"e":"Besides — bundan tashqari, baribir ma'nosida."},{"q":"Ann and Tim sit at a table facing each other. Tim is sitting ___ Ann.","o":["behind","beside","opposite","between"],"a":2,"e":"Bir-biriga qarab o'tirsa opposite (qarshisida) ishlatiladi."},{"q":"He took three years ___ his book.","o":["for","over","above","during"],"a":1,"e":"Take + vaqt + over + ot — biror ishga vaqt sarflash."}]},{"id":"p6-05","en":"But/Except, By, Arrive, Home, Transport, Corner, Front/Back","uz":"But/except, by, arrive, home, transport, corner, front/back","emoji":"🚌","level":"A2","group":"Predloglar","summary":"But va except, by va via, arrive in/at, home bilan predlog, transport bilan predloglar, in/at the corner va in/at/on the front/back qoidalari.","blocks":[{"t":"h","x":"But va except"},{"t":"p","x":"Ikkalasi ham «...dan tashqari» ma'nosida ishlatiladi. Ammo <b>nobody, no one, nothing, nowhere</b> dan keyin ko'proq <b>but</b> qo'llaniladi."},{"t":"ex","en":"Nobody but Tom knew the answer.","uz":"Tomdan boshqa hech kim javobni bilmasdi."},{"t":"ex","en":"Everyone knows the answer except Tom.","uz":"Tomdan tashqari hamma javobni biladi."},{"t":"rule","x":"<b>But</b> va <b>except</b> dan keyin fe'l kelsa, faqat <b>bare infinitive</b> (to siz) shakli ishlatiladi."},{"t":"ex","en":"She did nothing during the day but sleep.","uz":"U kun bo'yi uxlashdan boshqa hech narsa qilmadi."},{"t":"h","x":"By"},{"t":"list","items":["<b>With the help of</b> — yordamida, vositasida.","<b>Through</b> — orqali, bo'ylab."]},{"t":"ex","en":"I came here by train.","uz":"Bu yerga poyezdda keldim."},{"t":"ex","en":"We reached the city by the forest road.","uz":"Shaharga o'rmon yo'li orqali yetib keldik."},{"t":"p","x":"<b>Through</b> o'rnida <b>via</b> ishlatilishi mumkin:"},{"t":"ex","en":"I sent him the pictures through / via Bluetooth.","uz":"Unga rasmlarni Bluetooth orqali yubordim."},{"t":"h","x":"Arrive in / arrive at"},{"t":"list","items":["<b>arrive in</b> — shahar, mamlakat.","<b>arrive at</b> — boshqa joylar (mehmonxona, restoran, bekat va h.k.).","<b>Qishloq</b> bilan ikkalasi ham ishlatiladi: <i>arrive at / in her village</i>."]},{"t":"ex","en":"He arrived in Madrid / Spain.","uz":"U Madridga / Ispaniyaga yetib keldi."},{"t":"ex","en":"We arrived at a hotel / hostel / restaurant.","uz":"Biz mehmonxonaga / restoranga yetib keldik."},{"t":"ex","en":"She arrived at / in her village.","uz":"U qishlog'iga yetib keldi."},{"t":"p","x":"<b>Arrive at / in</b> o'rnida <b>get to</b> yoki <b>reach</b> istalgan joy bilan ishlatilishi mumkin (reach dan keyin predlog qo'yilmaydi)."},{"t":"ex","en":"He got to the station just in time.","uz":"U bekatga zo'rg'a ulgurdi."},{"t":"ex","en":"I want to reach Berlin before dark.","uz":"Qorong'i tushmasdan Berlinga yetib olmoqchiman."},{"t":"p","x":"<b>Get in</b> ham shu ma'noda ishlatilishi mumkin, lekin asosan poyezdlar bilan keladi: <i>What time does the train get in?</i>"},{"t":"h","x":"Home"},{"t":"rule","x":"Agar <b>home</b> ga qarab harakat bo'lsa (go, come, get, return home), uning oldidan predlog <b>ishlatilmaydi</b>."},{"t":"ex","en":"It took us an hour to get home.","uz":"Uyga yetib borishimizga bir soat ketdi."},{"t":"ex","en":"She went home by bus.","uz":"U uyga avtobusda ketdi."},{"t":"ex","en":"I returned home.","uz":"Men uyga qaytdim."},{"t":"p","x":"Ammo <b>home</b> dan oldin boshqa so'z kelsa, predlog ishlatiladi:"},{"t":"ex","en":"She returned to her parents' home.","uz":"U ota-onasining uyiga qaytdi."},{"t":"p","x":"Home ga nisbatan harakat bo'lmasa (joylashuv), predlog ishlatiladi:"},{"t":"list","items":["<b>at home</b>","<b>at + ... + home</b> (at her home)","<b>in + ... + home</b> — in bilan home orasida albatta biror so'z bo'lishi kerak (<i>in my home</i>; <i>in home</i> emas)."]},{"t":"ex","en":"I was at home.","uz":"Men uyda edim."},{"t":"ex","en":"She stayed at her home.","uz":"U o'z uyida qoldi."},{"t":"ex","en":"They lived in my home.","uz":"Ular mening uyimda yashashdi."},{"t":"h","x":"Transport"},{"t":"table","head":["Ibora","Qo'llanilishi"],"rows":[["get in / into","shaxsiy va jamoat transporti (mashinaga) chiqmoq"],["get on / onto","jamoat transporti hamda ot, velosiped, tuya va h.k."],["go on board","bortga (kema, samolyot) chiqmoq"],["get out / out of","shaxsiy transportdan (mashinadan) tushmoq"],["get off","jamoat transporti hamda ot, velosiped, tuyadan tushmoq"],["in","shaxsiy transport: in my car"],["on","jamoat transporti: on a bus"],["by (artiklsiz)","har qanday transport: by car, by bus"],["on foot","piyoda"]]},{"t":"ex","en":"I came here by car / on foot.","uz":"Bu yerga mashinada / piyoda keldim."},{"t":"rule","x":"<b>Get in / into / out / out of</b> bino, tashkilot yoki mamlakatga kirish yoki chiqishni ifodalashda ham ishlatiladi — faqat kirish yoki chiqishda <b>qiyinchilik</b> bo'lsa."},{"t":"ex","en":"The house is on fire! We had better get out.","uz":"Uy yonyapti! Chiqib ketganimiz ma'qul."},{"t":"ex","en":"I've lost my keys! How are we going to get into the flat?","uz":"Kalitlarimni yo'qotdim! Kvartiraga qanday kiramiz?"},{"t":"ex","en":"Nowadays it's difficult to get into university.","uz":"Hozirgi kunda universitetga kirish qiyin."},{"t":"h","x":"In / at / on the corner"},{"t":"list","items":["<b>in the corner</b> — ichki burchak (xonaning burchagi).","<b>at / on the corner</b> — tashqi burchak (ko'chaning muyulishi)."]},{"t":"ex","en":"There is a table in the corner of the room.","uz":"Xonaning burchagida stol bor."},{"t":"ex","en":"I'm standing at / on the corner of the street.","uz":"Men ko'chaning muyulishida turibman."},{"t":"h","x":"In / at / on the front, the back"},{"t":"list","items":["<b>in the front / back</b> — mashinaning old yoki orqa o'rindig'ida o'tirish.","<b>at the front / back</b> — bino yoki predmetning old yoki orqa tomonida.","<b>on the front / back</b> — qog'ozning old yoki orqa betida; xatning boshi yoki oxirida."]},{"t":"ex","en":"I was sitting in the back when we crashed.","uz":"To'qnashganimizda men orqa o'rindiqda o'tirgan edim."},{"t":"ex","en":"The garden is at the front of the house.","uz":"Bog' uyning old tomonida."},{"t":"ex","en":"Please write on the back of this piece of paper.","uz":"Iltimos, bu qog'ozning orqa betiga yozing."}],"quiz":[{"q":"Nobody ___ Tom knew the answer.","o":["but","besides","by","beside"],"a":0,"e":"Nobody, nothing, nowhere dan keyin ko'pincha but (…dan boshqa) ishlatiladi."},{"q":"She did nothing all day but ___.","o":["to sleep","sleeping","sleep","slept"],"a":2,"e":"But/except dan keyin fe'l bare infinitive shaklida keladi."},{"q":"He arrived ___ Madrid last night.","o":["at","in","to","on"],"a":1,"e":"Shahar va mamlakat bilan arrive in ishlatiladi."},{"q":"We arrived ___ the hotel at midnight.","o":["in","to","at","on"],"a":2,"e":"Boshqa joylar (mehmonxona, restoran) bilan arrive at."},{"q":"Choose the correct sentence.","o":["She went to home by bus.","She went at home by bus.","She went home by bus.","She went in home by bus."],"a":2,"e":"Home ga qarab harakatda predlog ishlatilmaydi."},{"q":"They lived ___ my home for a year.","o":["in","to","—","into"],"a":0,"e":"In bilan home orasida so'z bo'lsa (my) in ishlatiladi."},{"q":"I went to work ___ bus.","o":["on a","in","by","with"],"a":2,"e":"By + transport (artiklsiz): by bus, by car."},{"q":"He got ___ his bicycle and rode away.","o":["in","into","on","out"],"a":2,"e":"Ot, velosiped, tuya va jamoat transporti bilan get on."},{"q":"There is a lamp ___ the corner of the room.","o":["at","on","in","by"],"a":2,"e":"Ichki burchak (xona) uchun in the corner."},{"q":"Please sign ___ the back of the cheque.","o":["in","at","on","by"],"a":2,"e":"Qog'ozning orqa beti uchun on the back."}]},{"id":"p6-06","en":"Prepositions & Adverbs; Like, As, As if","uz":"Predlog va ravish; like, as, as if","emoji":"🔁","level":"B1","group":"Predloglar","summary":"Ham predlog, ham ravish bo'la oladigan so'zlar; like va as farqi; as if / as though ishlatilishi.","blocks":[{"t":"h","x":"Predlog va ravish"},{"t":"p","x":"Ba'zi so'zlar ham predlog (ot bilan), ham ravish (ot siz) bo'lib kela oladi."},{"t":"ex","en":"Peter is behind us.","uz":"Piter bizning orqamizda. (predlog)"},{"t":"ex","en":"He's a long way behind.","uz":"U ancha orqada qoldi. (ravish)"},{"t":"ex","en":"She climbed over the wall.","uz":"U devordan oshib o'tdi. (predlog)"},{"t":"ex","en":"You'll have to climb over too.","uz":"Sen ham oshib o'tishing kerak. (ravish)"},{"t":"p","x":"Eng ko'p uchraydigan bunday so'zlar: <i>above, about, across, along, before, behind, besides, below, by, down, in, near, off, on, over, past, round, since, through, under, up</i>."},{"t":"ex","en":"Come round to my home any evening.","uz":"Biror kuni kechqurun uyimga aylanib kel. (ravish)"},{"t":"ex","en":"The shop is just round the corner.","uz":"Do'kon muyulishning naryog'ida. (predlog)"},{"t":"ex","en":"See the table below.","uz":"Quyidagi jadvalga qarang. (ravish)"},{"t":"h","x":"Like"},{"t":"p","x":"<b>Like</b> — «similar to, the same as» (...ga o'xshash, ...dek) ma'nosini beradi va predlog vazifasida keladi."},{"t":"formula","x":"like + ot / olmosh / gerund"},{"t":"ex","en":"What a beautiful house! It's like a palace.","uz":"Qanday chiroyli uy! U saroyga o'xshaydi."},{"t":"ex","en":"He is a simple teacher, like me.","uz":"U ham men kabi oddiy o'qituvchi."},{"t":"ex","en":"What's that noise? It sounds like a baby crying.","uz":"Bu qanday ovoz? Go'dak yig'layotganga o'xshaydi."},{"t":"h","x":"As"},{"t":"p","x":"<b>As</b> ham «...dek, ...ganidek» ma'nosini beradi, lekin o'zidan keyin <b>gap</b> (ega + kesim) talab qiladi."},{"t":"formula","x":"as + gap (S + V)"},{"t":"ex","en":"You should do it as I showed you.","uz":"Buni men ko'rsatganimdek qilishing kerak."},{"t":"ex","en":"You should do it like this.","uz":"Buni mana bunday qilishing kerak."},{"t":"p","x":"<b>Such as</b> — «shu kabi, ...kabi» deb tarjima qilinadi va o'zidan keyin fe'l (gap) talab qilmaydi."},{"t":"ex","en":"Some sports, such as motor racing, can be dangerous.","uz":"Avtopoyga kabi ba'zi sport turlari xavfli bo'lishi mumkin."},{"t":"p","x":"<b>As usual</b> — odatdagidek:"},{"t":"ex","en":"You got five minuses, as usual.","uz":"Odatdagidek beshta minus olding."},{"t":"p","x":"<b>As + gap</b> boshqa ma'nolarda ham keladi:"},{"t":"ex","en":"Do as you are told. (= Do what you are told.)","uz":"Senga aytilganidek bajar."},{"t":"ex","en":"They did as they promised.","uz":"Ular va'da qilganlaridek qilishdi."},{"t":"p","x":"As bilan iboralar: <i>as you know, as we expected, as I told you, as I said</i>."},{"t":"ex","en":"As you know, I'm a student.","uz":"Bilganingizdek, men talabaman."},{"t":"ex","en":"He failed his exam, as we expected.","uz":"Biz kutganimizdek, u imtihondan yiqildi."},{"t":"h","x":"As «sifatida» va like farqi"},{"t":"rule","x":"<b>As</b> predlog bo'lib kelsa «<b>sifatida</b>» ma'nosini beradi — biror narsa haqiqatda qanday ekanini yoki bo'lganini aytadi. <b>Like</b> esa narsalarni <b>solishtirish</b> uchun ishlatiladi (aslida unday emas, faqat o'xshaydi)."},{"t":"ex","en":"Everyone is ill at home. Our home is like a hospital.","uz":"Uyda hamma kasal. Uyimiz kasalxonaga o'xshaydi."},{"t":"ex","en":"During the war, our house was used as a hospital.","uz":"Urush paytida uyimiz kasalxona sifatida ishlatilgan."},{"t":"ex","en":"In the 1960s, John worked in the USA as a teacher.","uz":"1960-yillarda Jon AQShda o'qituvchi bo'lib ishlagan."},{"t":"ex","en":"Last week I worked at my grandparents' house like a slave.","uz":"O'tgan hafta bobomlarnikida quldek ishladim."},{"t":"h","x":"As if / as though"},{"t":"p","x":"<b>As if</b> — «xuddi, go'yo» deb tarjima qilinadi va kishi yoki narsa qanday tuyulishini, ko'rinishini ko'rsatadi. <b>As if = as though</b>."},{"t":"ex","en":"The house looked as if nobody was living in it.","uz":"Uy xuddi unda hech kim yashamayotgandek ko'rinardi."},{"t":"ex","en":"Ann sounded as if she had a cold.","uz":"Annning ovozidan u shamollagandek tuyulardi."},{"t":"ex","en":"You look tired. You look as if / as though you haven't slept.","uz":"Charchagan ko'rinasan. Xuddi uxlamagandek ko'rinasan."},{"t":"formula","x":"It + link verb (looks / seems / sounds) + as if / as though = ...ga o'xshaydi"},{"t":"ex","en":"It's late. It looks as if Tom isn't coming.","uz":"Kech bo'ldi. Tom kelmaydiganga o'xshaydi."},{"t":"p","x":"Og'zaki nutqda <b>as if / as though</b> o'rnida ko'pincha <b>like</b> ishlatiladi:"},{"t":"ex","en":"It's late. It looks like Tom isn't coming.","uz":"Kech bo'ldi. Tom kelmaydiganga o'xshaydi."},{"t":"p","x":"<b>As if</b> boshqa fe'llar bilan ham kelib, kishi harakatni qanday bajarayotganini ko'rsatadi:"},{"t":"ex","en":"He ran as if he was running for his life.","uz":"U xuddi jonini saqlab qolish uchun yugurayotgandek yugurdi."},{"t":"ex","en":"They looked at me as if I was mad.","uz":"Ular menga xuddi aqldan ozgandek qarashdi."},{"t":"rule","x":"Hozirgi zamon haqida gapirganda ba'zan <b>as if</b> dan keyin <b>o'tgan zamon</b> ishlatiladi — bu aytilayotgan narsa haqiqatga to'g'ri kelmasligini ta'kidlaydi. Bu holatda <b>was</b> o'rnida <b>were</b> ishlatilgani ma'qulroq, lekin was ham xato emas."},{"t":"ex","en":"I don't like Tom. He speaks as if he knew everything.","uz":"Tomni yoqtirmayman. U xuddi hamma narsani biladigandek gapiradi."},{"t":"ex","en":"They behave as if they were princesses.","uz":"Ular o'zlarini xuddi malikalardek tutishadi."},{"t":"ex","en":"They treat me as if I were their son.","uz":"Ular menga xuddi o'z o'g'illaridek munosabatda bo'lishadi."}],"quiz":[{"q":"In which sentence is 'behind' an adverb?","o":["Peter is behind us.","He's a long way behind.","The cat is behind the sofa.","She hid behind the tree."],"a":1,"e":"O'zidan keyin ot kelmasa so'z ravish vazifasida bo'ladi."},{"q":"It's a beautiful house. It's ___ a palace.","o":["as","like","as if","such as"],"a":1,"e":"Like + ot — solishtirish (…ga o'xshaydi)."},{"q":"You should do it ___ I showed you.","o":["like","as","such as","as usual"],"a":1,"e":"As dan keyin gap (S + V) keladi."},{"q":"Some sports, ___ motor racing, can be dangerous.","o":["like as","as if","such as","as though"],"a":2,"e":"Such as — …kabi; undan keyin fe'l kelmaydi."},{"q":"During the war, the school was used ___ a hospital.","o":["like","as","as if","such as"],"a":1,"e":"As — «sifatida», haqiqiy vazifani bildiradi."},{"q":"I worked all day ___ a slave. (I am not really a slave.)","o":["as","like","as though","such as"],"a":1,"e":"Solishtirish (aslida unday emas) uchun like ishlatiladi."},{"q":"You look ___ you haven't slept.","o":["as","such as","as if","like as"],"a":2,"e":"As if — xuddi …gandek; tashqi ko'rinishni ifodalaydi."},{"q":"He talks as if he ___ everything. (but he doesn't)","o":["knows","knew","has known","will know"],"a":1,"e":"Haqiqatga to'g'ri kelmaydigan holatda as if dan keyin o'tgan zamon ishlatiladi."},{"q":"Which is the preferred form? 'They treat me as if I ___ their son.'","o":["am","were","be","have been"],"a":1,"e":"Bunday holatlarda was o'rniga were ishlatilgani ma'qulroq."},{"q":"___ you know, I'm a student.","o":["Like","As","Such as","As if"],"a":1,"e":"As you know — bilganingizdek (as bilan ibora)."}]},{"id":"p6-07","en":"Some, Any, No, None","uz":"Some, any, no va none","emoji":"🧺","level":"A2","group":"Olmosh, sifat, ravish","summary":"Some va any qaysi gaplarda ishlatilishi, no va none farqi, some/any/none + of qolipi va birlikdagi ot bilan some/any ma'nolari.","blocks":[{"t":"h","x":"Some"},{"t":"p","x":"<b>Some</b> — «ozgina, biroz, bir nechta» deb tarjima qilinadi. Ko'plikdagi yoki sanalmaydigan otlar oldidan sifat sifatida yoki ular o'rnida olmosh bo'lib ishlatiladi."},{"t":"ex","en":"I have some money, but I need some more.","uz":"Menda biroz pul bor, lekin yana biroz kerak."},{"t":"p","x":"<b>Some</b> — <b>a, an</b> va <b>one</b> ning ko'plik shakli hisoblanadi."},{"t":"ex","en":"Kate ate a date. / Kate ate some dates.","uz":"Keyt bitta xurmo yedi. / Keyt bir nechta xurmo yedi."},{"t":"p","x":"Some asosan <b>darak (tasdiq)</b> gaplarda ishlatiladi."},{"t":"ex","en":"They bought some honey.","uz":"Ular biroz asal sotib olishdi."},{"t":"rule","x":"Some so'roq gaplarda ham ishlatiladi: (1) javob «ha» ekani oldindan ma'lum bo'lsa; (2) biror narsani <b>taklif qilish</b> yoki <b>so'rash</b> uchun."},{"t":"ex","en":"Did some of you sleep on the floor?","uz":"Ba'zilaringiz polda uxladingizmi?"},{"t":"ex","en":"Would you like some wine?","uz":"Biroz vino ichasizmi? (taklif)"},{"t":"ex","en":"Could you do some typing for me?","uz":"Men uchun biroz matn terib bera olasizmi? (iltimos)"},{"t":"h","x":"Any"},{"t":"p","x":"<b>Any</b> ko'plikdagi yoki sanalmaydigan otlar oldidan <b>inkor</b> gaplarda ishlatiladi."},{"t":"ex","en":"I don't have any mistakes.","uz":"Menda hech qanday xato yo'q."},{"t":"p","x":"<b>Hardly, barely, scarcely</b> so'zlari bilan ham <b>any</b> ishlatiladi (ular inkor ma'nosiga ega)."},{"t":"ex","en":"There is hardly any milk left.","uz":"Sut deyarli qolmagan."},{"t":"formula","x":"without any = with no"},{"t":"ex","en":"I finished my assignment without any difficulty. = I finished my assignment with no difficulty.","uz":"Topshiriqni hech qanday qiyinchiliksiz bajardim."},{"t":"p","x":"Any yuqoridagi (some) holatlardan tashqari <b>so'roq</b> gaplarda ishlatiladi."},{"t":"ex","en":"Have you got any money?","uz":"Pulingiz bormi?"},{"t":"ex","en":"Did he catch any fish?","uz":"U baliq tutdimi?"},{"t":"p","x":"<b>If</b> va <b>whether</b> dan keyin <b>any</b> ishlatiladi."},{"t":"ex","en":"I don't know whether there is any petrol left in the tank.","uz":"Bakda benzin qolgan-qolmaganini bilmayman."},{"t":"ex","en":"If you need any money, let me know.","uz":"Agar pul kerak bo'lsa, menga ayt."},{"t":"h","x":"No va none"},{"t":"p","x":"<b>No</b> — sifat (ot oldidan keladi), <b>none</b> — olmosh (o'zi yolg'iz keladi). Ular tasdiq shaklidagi gaplarda inkor ma'nosini beradi."},{"t":"ex","en":"I have no friends. I had some last year, but I have none now.","uz":"Mening do'stlarim yo'q. O'tgan yili bor edi, hozir birortasi ham yo'q."},{"t":"p","x":"<b>No + ot</b> gapda ega bo'lishi mumkin:"},{"t":"ex","en":"No work was done.","uz":"Hech qanday ish qilinmadi."},{"t":"ex","en":"No letters arrived.","uz":"Hech qanday xat kelmadi."},{"t":"p","x":"<b>None</b> ham gapda ega bo'lib kelishi mumkin, ammo bu kamdan-kam uchraydi."},{"t":"ex","en":"We expected some letters, but none came.","uz":"Biz xatlar kutgan edik, lekin birortasi ham kelmadi."},{"t":"h","x":"Some / any / none + of"},{"t":"formula","x":"some / any / none + of + the / this / that / these / those / egalik sifati / kishilik olmoshi"},{"t":"ex","en":"None of us has visited Europe.","uz":"Hech birimiz Yevropada bo'lmaganmiz."},{"t":"ex","en":"Some of the staff can speak Japanese.","uz":"Xodimlarning ba'zilari yaponcha gapira oladi."},{"t":"ex","en":"Some of my friends are older than me.","uz":"Do'stlarimning ba'zilari mendan katta."},{"t":"h","x":"Birlikdagi sanaladigan ot bilan some va any"},{"t":"p","x":"<b>Some</b> birlikdagi sanaladigan ot oldidan kelganda noma'lum narsa yoki kishini ko'rsatadi: «qandaydir bir, allaqaysi»."},{"t":"ex","en":"Some idiot parked his car in front of my garage.","uz":"Qandaydir bir ahmoq mashinasini garajim oldiga qo'yib ketibdi."},{"t":"p","x":"<b>Any</b> birlikdagi sanaladigan ot oldidan kelsa «har qanday, istalgan» ma'nosini beradi."},{"t":"ex","en":"Any dictionary will give you the meaning of this word.","uz":"Istalgan lug'at sizga bu so'zning ma'nosini beradi."}],"quiz":[{"q":"They bought ___ honey yesterday.","o":["any","some","no any","none"],"a":1,"e":"Darak gaplarda odatda some ishlatiladi."},{"q":"I don't have ___ mistakes in my test.","o":["some","any","no","none"],"a":1,"e":"Inkor gaplarda any ishlatiladi."},{"q":"Would you like ___ tea?","o":["any","some","no","none"],"a":1,"e":"Taklif qilishda so'roq gapda ham some ishlatiladi."},{"q":"Did he catch ___ fish?","o":["any","no","none","a"],"a":0,"e":"Oddiy so'roq gaplarda any ishlatiladi."},{"q":"If you need ___ help, call me.","o":["some","no","any","none"],"a":2,"e":"If va whether dan keyin any ishlatiladi."},{"q":"There is hardly ___ sugar left.","o":["no","some","any","none"],"a":2,"e":"Hardly, barely, scarcely bilan any ishlatiladi."},{"q":"I had some friends last year, but I have ___ now.","o":["no","none","any","not"],"a":1,"e":"None — olmosh, o'zidan keyin ot kelmaydi."},{"q":"___ letters arrived this morning.","o":["None","No","Any","Not"],"a":1,"e":"No + ot gapda ega bo'la oladi."},{"q":"___ dictionary will give you this word. (= whichever one)","o":["Some","Any","No","None"],"a":1,"e":"Any + birlikdagi ot — har qanday, istalgan."},{"q":"___ idiot has parked in front of my garage. (= an unknown person)","o":["Any","Some","No","None"],"a":1,"e":"Some + birlikdagi ot — qandaydir bir (noma'lum)."}]},{"id":"p6-08","en":"Someone, Anyone, No one, Something… and Else","uz":"Someone, anyone, no one, something... va else","emoji":"👤","level":"A2","group":"Olmosh, sifat, ravish","summary":"Some/any/no/every bilan yasalgan qo'shma olmoshlar va ravishlar, ularning moslashuvi, egalik shakli va else bilan qo'llanilishi.","blocks":[{"t":"h","x":"Qo'shma so'zlar"},{"t":"p","x":"<b>Someone, somebody, something, anyone, anybody, anything, no one, nobody, nothing</b> — qo'shma so'zlar bo'lib, <b>some, any, no</b> ishlatiladigan holatlarda (darak, so'roq, inkor, taklif) ishlatiladi."},{"t":"ex","en":"Someone wants to speak to you on the phone.","uz":"Kimdir siz bilan telefonda gaplashmoqchi."},{"t":"ex","en":"Nobody has ever given me a free ticket.","uz":"Hech kim menga hech qachon tekin chipta bermagan."},{"t":"ex","en":"Is there anyone you know?","uz":"Taniydigan biror kishingiz bormi?"},{"t":"ex","en":"Would anyone like some water?","uz":"Kimdir suv ichadimi?"},{"t":"ex","en":"Would you like something?","uz":"Biror narsa xohlaysizmi? (taklif)"},{"t":"ex","en":"He drinks anything.","uz":"U nima bo'lsa ham ichaveradi."},{"t":"ex","en":"He drank something. / He drank nothing.","uz":"U nimadir ichdi. / U hech narsa ichmadi."},{"t":"table","head":["Sinonimlar",""],"rows":[["someone","somebody"],["no one (no-one)","nobody"],["anyone","anybody"]]},{"t":"h","x":"Egalik shakli"},{"t":"p","x":"<b>Someone, somebody, anyone, anybody, no one, nobody</b> bilan egalik shakli ('s) yasash mumkin."},{"t":"ex","en":"Somebody's passport has been stolen.","uz":"Kimningdir pasporti o'g'irlangan."},{"t":"ex","en":"I don't want to waste anyone's time.","uz":"Hech kimning vaqtini olmoqchi emasman."},{"t":"h","x":"Moslashuv: doim birlik"},{"t":"rule","x":"Bu so'zlar har doim <b>birlik</b> hisoblanadi va o'zidan keyin <b>birlikdagi fe'l</b> talab qiladi."},{"t":"ex","en":"Somebody is crying.","uz":"Kimdir yig'layapti."},{"t":"ex","en":"Has anyone come yet?","uz":"Hali hech kim keldimi?"},{"t":"ex","en":"Nobody wants to be alone.","uz":"Hech kim yolg'iz qolishni xohlamaydi."},{"t":"rule","x":"Ammo <b>someone, anyone, no one</b> kabi kishilarga oid so'zlar birlik bo'lishiga qaramay, ularga ishora qiluvchi olmosh sifatida <b>they, them, their</b> ishlatiladi. <b>he/his, she/her</b> ham xato emas."},{"t":"ex","en":"Has anyone left their luggage on the train?","uz":"Kimdir yuklarini poyezdda qoldirdimi?"},{"t":"ex","en":"No one saw Tom go out, did they?","uz":"Hech kim Tomning chiqib ketganini ko'rmadi, shundaymi?"},{"t":"p","x":"<b>Something, anything, nothing</b> ga ishora qiluvchi olmosh — <b>it</b>."},{"t":"ex","en":"Something went wrong, didn't it?","uz":"Nimadir noto'g'ri ketdi, shundaymi?"},{"t":"h","x":"Somewhere, anywhere, nowhere"},{"t":"p","x":"<b>Anywhere, somewhere, nowhere</b> gapda ravish hisoblanadi."},{"t":"ex","en":"Do you have anywhere to go?","uz":"Boradigan biror joying bormi?"},{"t":"ex","en":"He went somewhere.","uz":"U qayergadir ketdi."},{"t":"h","x":"Else"},{"t":"p","x":"Bu so'zlardan keyin <b>else</b> (boshqa) ishlatilishi mumkin:"},{"t":"table","head":["Ibora","Ma'nosi"],"rows":[["someone else","some other person — boshqa kimdir"],["anyone else","any other person — boshqa biror kishi"],["no one else","no other person — boshqa hech kim"],["somewhere else","in / at / to some other place — boshqa biror joyda/joyga"],["anywhere else","in / at / to any other place — boshqa istalgan joyda/joyga"],["nowhere else","in / at / to no other place — boshqa hech qayerda"]]},{"t":"ex","en":"I'm afraid I can't help you. You will have to ask someone else.","uz":"Afsuski, yordam berolmayman. Boshqa birovdan so'rashingizga to'g'ri keladi."},{"t":"ex","en":"There isn't anyone else.","uz":"Boshqa hech kim yo'q."},{"t":"ex","en":"There is no one else to ask.","uz":"So'raydigan boshqa hech kim yo'q."},{"t":"ex","en":"Are you going anywhere else?","uz":"Yana boshqa biror joyga borasanmi?"},{"t":"p","x":"<b>someone / somebody / anyone / anybody / no one / nobody + else</b> bilan ham egalik shakli yasaladi — <b>'s</b> else ga qo'shiladi."},{"t":"ex","en":"I took someone else's coat.","uz":"Men boshqa birovning paltosini olib qo'ydim."},{"t":"ex","en":"No one else's luggage was opened.","uz":"Boshqa hech kimning yuki ochilmadi."}],"quiz":[{"q":"Somebody ___ crying in the next room.","o":["are","is","were","be"],"a":1,"e":"Somebody, anyone, nobody doim birlik — birlikdagi fe'l talab qiladi."},{"q":"Nobody ___ to be alone.","o":["want","wants","are wanting","have wanted"],"a":1,"e":"Nobody birlik hisoblanadi: wants."},{"q":"Has anyone left ___ umbrella here?","o":["its","their","theirs","them"],"a":1,"e":"Kishilarga oid someone/anyone uchun odatda their ishlatiladi."},{"q":"Something went wrong, didn't ___?","o":["they","he","it","there"],"a":2,"e":"Something, anything, nothing ga ishora olmoshi it."},{"q":"No one saw him leave, did ___?","o":["it","he","they","one"],"a":2,"e":"No one ga savol qo'shimchasida they ishlatiladi."},{"q":"I can't help you. Ask ___.","o":["someone else","else someone","someone's else","other someone"],"a":0,"e":"Else qo'shma so'zdan keyin keladi: someone else."},{"q":"I took ___ coat by mistake.","o":["someone's else","someone else's","someone elses","else someone's"],"a":1,"e":"Egalik 's else ga qo'shiladi: someone else's."},{"q":"Do you have ___ to stay tonight?","o":["anywhere","anyone","anything","any"],"a":0,"e":"Joy haqida so'ralganda anywhere (ravish) ishlatiladi."},{"q":"Would you like ___ to drink? (offer)","o":["anything","something","nothing","everything"],"a":1,"e":"Taklifda some va uning qo'shma so'zlari ishlatiladi."},{"q":"'Nowhere else' means:","o":["in some other place","in any other place","in no other place","in every place"],"a":2,"e":"Nowhere else = in / at / to no other place."}]},{"id":"p6-09","en":"Every, Each, All and Whole","uz":"Every, each, all va whole","emoji":"🌐","level":"B1","group":"Olmosh, sifat, ravish","summary":"Every va each farqi, everyone/everything, all va whole ishlatilishi, all + of va all ning gapdagi o'rni.","blocks":[{"t":"h","x":"Every va each"},{"t":"p","x":"<b>Every</b> va <b>each</b> — «har bir» ma'nosini beradi va o'zidan keyin <b>birlikdagi ot</b> va <b>birlikdagi fe'l</b> talab qiladi."},{"t":"ex","en":"Every house is blue.","uz":"Har bir uy ko'k rangda."},{"t":"ex","en":"Every boy likes football.","uz":"Har bir bola futbolni yaxshi ko'radi."},{"t":"ex","en":"Each door has a doorknob except ours.","uz":"Biznikidan boshqa har bir eshikning tutqichi bor."},{"t":"rule","x":"<b>Each</b> gapda ham sifat (ot oldidan), ham olmosh (o'zi yolg'iz) bo'lib kela oladi, ammo <b>every</b> faqat sifat bo'lib keladi."},{"t":"ex","en":"Every man had a weapon. / Each man had a weapon. / Each had a weapon.","uz":"Har bir kishining quroli bor edi. (<i>Every had...</i> deyilmaydi)"},{"t":"p","x":"<b>Each</b> asosan kichik miqdorlar (har birini alohida) uchun, <b>every</b> esa katta miqdorlar (hammasini umumlashtirib) uchun ishlatiladi."},{"t":"p","x":"Each va every ga ishora qilish uchun <b>he / she / it</b> ning egalik shakllari (his, her, its) ishlatiladi."},{"t":"ex","en":"Every man has his house.","uz":"Har bir erkakning o'z uyi bor."},{"t":"ex","en":"Each dog is loyal to its owner.","uz":"Har bir it o'z egasiga sodiq."},{"t":"ex","en":"Every mother is kind to her child.","uz":"Har bir ona o'z farzandiga mehribon."},{"t":"h","x":"Everyone, everybody, everything"},{"t":"p","x":"<b>Everyone = everybody</b> — birlik hisoblanadi, o'zidan keyin birlikdagi fe'l talab qiladi va <b>all the people</b> o'rnida ishlatiladi."},{"t":"ex","en":"Everyone is ready. = All the people are ready.","uz":"Hamma tayyor."},{"t":"p","x":"<b>Everything</b> — «har bir narsa, hamma narsa», birlikdagi fe'l talab qiladi va <b>all the things</b> o'rnida ishlatiladi."},{"t":"ex","en":"Everything has been wasted. = All the things have been wasted.","uz":"Hamma narsa isrof bo'ldi."},{"t":"p","x":"<b>All the people, all the things</b> ni ergash gap yoki iboralardan oldin ishlatgan ma'qulroq."},{"t":"ex","en":"All the people in the room clapped.","uz":"Xonadagi hamma odamlar qarsak chalishdi."},{"t":"ex","en":"I got all the things you asked for.","uz":"So'ragan hamma narsalaringni oldim."},{"t":"h","x":"All"},{"t":"p","x":"<b>All</b> birlik, sanalmaydigan va ko'plikdagi otlar oldidan kelishi mumkin. Ko'plik va sanalmaydigan otlar oldidan «<b>hamma, barcha</b>», birlikdagi ot oldidan esa «<b>whole</b>», ya'ni «butun, boshidan oxirigacha» ma'nosini beradi."},{"t":"ex","en":"All the people were running.","uz":"Hamma odamlar yugurayotgan edi."},{"t":"ex","en":"I got all the money.","uz":"Men hamma pulni oldim."},{"t":"ex","en":"Has she read all the book?","uz":"U kitobni boshdan-oxir o'qidimi?"},{"t":"p","x":"<b>All</b> «the only thing / things» (yagona narsa) ma'nosida ham keladi."},{"t":"ex","en":"All I've eaten today is a sandwich.","uz":"Bugun yegan narsam faqat bitta sendvich."},{"t":"h","x":"All va whole"},{"t":"p","x":"<b>Whole</b> — «butun, boshidan oxirigacha», asosan <b>birlikdagi</b> otlar bilan ishlatiladi. <b>The / his / her / my</b> va h.k. whole dan oldin keladi."},{"t":"ex","en":"Have you read the whole book? = Have you read all the book?","uz":"Kitobni to'liq o'qidingmi?"},{"t":"ex","en":"her whole life = all her life","uz":"butun hayoti"},{"t":"rule","x":"Sanalmaydigan otlar bilan <b>whole</b> ishlatilmaydi: <i>He drank all the water in the bottle.</i> (<i>the whole water</i> emas)"},{"t":"h","x":"Every / all / whole + vaqt"},{"t":"p","x":"<b>Every + vaqt</b> — harakat qanday chastota (takrorlanish) bilan sodir bo'lishini ko'rsatadi."},{"t":"ex","en":"He gets a minus every lesson.","uz":"U har darsda minus oladi."},{"t":"ex","en":"Ann goes to see her mother every three weeks.","uz":"Ann har uch haftada onasini ko'rgani boradi."},{"t":"p","x":"<b>All / the whole + vaqt</b> — harakat shu vaqtning boshidan oxirigacha davom etganini ko'rsatadi. Bunda <b>all</b> artiklsiz, <b>whole</b> esa artikl bilan keladi."},{"t":"ex","en":"We tried to solve that tough problem the whole evening.","uz":"Biz o'sha qiyin masalani butun oqshom yechishga urindik."},{"t":"ex","en":"I played computer games all day.","uz":"Kun bo'yi kompyuter o'yinlari o'ynadim."},{"t":"h","x":"All + of"},{"t":"formula","x":"all + of + the / this / that / these / those / egalik sifati / kishilik olmoshi"},{"t":"ex","en":"All of the people were running. / All of my friends. / All of them.","uz":"Odamlarning hammasi... / Do'stlarimning hammasi. / Ularning hammasi."},{"t":"p","x":"Bu qolipda <b>of</b> ni tushirib qoldirish mumkin. Birlikdagi otlar oldidan tushirib qoldirgan, ko'plikdagi otlar oldidan qoldirish ixtiyoriy."},{"t":"ex","en":"all the town, all the book, all (of) Tom's boys, all (of) these guys","uz":"butun shahar, butun kitob, Tomning hamma o'g'illari, bu yigitlarning hammasi"},{"t":"rule","x":"<b>All of + kishilik olmoshi</b> da <b>of</b> ni tushirib bo'lmaydi. Uning o'rniga muqobil shakl bor:"},{"t":"table","head":["All of ...","Muqobil shakl"],"rows":[["all of us","we all (ega), us all (to'ldiruvchi)"],["all of you","you all"],["all of them","they all (ega), them all (to'ldiruvchi)"]]},{"t":"ex","en":"We all went. = All of us went.","uz":"Hammamiz bordik."},{"t":"ex","en":"We ate all of them. = We ate them all.","uz":"Ularning hammasini yedik."},{"t":"h","x":"All ning yordamchi fe'l bilan o'rni"},{"t":"rule","x":"Gapda yordamchi fe'l bo'lsa, <b>all</b> olmosh (ega) va yordamchi fe'ldan keyin keladi. Yordamchi fe'l bittadan ko'p bo'lsa — birinchisidan keyin. <b>to be</b> asosiy fe'l bo'lsa ham all undan keyin qo'yiladi."},{"t":"ex","en":"We are all waiting.","uz":"Hammamiz kutyapmiz."},{"t":"ex","en":"You must all help me.","uz":"Hammangiz menga yordam berishingiz kerak."},{"t":"ex","en":"They have all been waiting.","uz":"Ularning hammasi kutib turishibdi."},{"t":"ex","en":"We have all known the answer.","uz":"Hammamiz javobni bilganmiz."},{"t":"ex","en":"We are all ready.","uz":"Hammamiz tayyormiz."},{"t":"rule","x":"Istisno: <b>qisqa javoblarda</b> yordamchi fe'l (to be) <b>all</b> dan keyin keladi. Oddiy fe'l bo'lsa all fe'ldan oldin keladi: <i>We all have maps.</i>"},{"t":"ex","en":"Who is ready? — We all are.","uz":"Kim tayyor? — Hammamiz."}],"quiz":[{"q":"Every student ___ a dictionary.","o":["have","has","are having","were"],"a":1,"e":"Every dan keyin birlikdagi ot va birlikdagi fe'l keladi."},{"q":"Which word can be used alone as a pronoun?","o":["every","each","whole","no"],"a":1,"e":"Each olmosh bo'lib kela oladi (Each had a weapon), every esa faqat sifat."},{"q":"Each dog is loyal to ___ owner.","o":["their","its","it's","his own's"],"a":1,"e":"Each/every ga he/she/it ning egalik shakli ishlatiladi: its."},{"q":"Everyone ___ ready for the trip.","o":["are","is","were","have"],"a":1,"e":"Everyone birlik hisoblanadi."},{"q":"He drank ___ water in the bottle.","o":["the whole","all the","whole the","the all"],"a":1,"e":"Sanalmaydigan otlar bilan whole ishlatilmaydi."},{"q":"Have you read ___ book?","o":["whole the","the whole","all of whole","the all"],"a":1,"e":"The / my / his whole dan oldin keladi: the whole book."},{"q":"She goes to see her mother ___ three weeks.","o":["all","whole","every","each of"],"a":2,"e":"Every + vaqt — takrorlanish chastotasi."},{"q":"Choose the correct form: 'We ate ___.'","o":["all them","them all","all they","they all"],"a":1,"e":"All of them = them all (to'ldiruvchi)."},{"q":"Choose the correct word order.","o":["They all have been waiting.","They have been all waiting.","They have all been waiting.","All they have been waiting."],"a":2,"e":"All birinchi yordamchi fe'ldan keyin keladi."},{"q":"Who is ready? — We all ___.","o":["is","are","be","do"],"a":1,"e":"Qisqa javobda to be all dan keyin keladi: We all are."}]},{"id":"p6-10","en":"Each of, Both, Neither, Either","uz":"Each of, both, neither va either","emoji":"✌️","level":"B1","group":"Olmosh, sifat, ravish","summary":"Each of va muqobil shakllar, both, neither, either ning moslashuvi hamda both…and, neither…nor, either…or juft bog'lovchilari.","blocks":[{"t":"h","x":"Each of"},{"t":"formula","x":"each + of + the / these / those / egalik sifati / kishilik olmoshi + ko'plikdagi ot"},{"t":"ex","en":"each of the boys / each of them","uz":"bolalarning har biri / ularning har biri"},{"t":"rule","x":"Bu yerda <b>of</b> ni tushirib bo'lmaydi. Uning o'rniga muqobil shakl ishlatiladi:"},{"t":"table","head":["Each of ...","Muqobil shakl"],"rows":[["each of you","you each"],["each of us","we each (ega), us each (to'ldiruvchi)"],["each of them","they each (ega), them each (to'ldiruvchi)"]]},{"t":"ex","en":"We each sent them letters.","uz":"Har birimiz ularga xat yubordik."},{"t":"ex","en":"They gave us each an ice cream.","uz":"Ular har birimizga bittadan muzqaymoq berishdi."},{"t":"rule","x":"<b>Each of you / us / them</b> — <b>birlik</b> hisoblanadi. <b>We / you / they each</b> — <b>ko'plik</b> hisoblanadi."},{"t":"ex","en":"Each of us has a map.","uz":"Har birimizda xarita bor."},{"t":"ex","en":"We each have a map.","uz":"Har birimizda xarita bor."},{"t":"p","x":"<b>Each</b> fe'l bilan kelganda <b>all</b> dagi qoidalar o'rinli bo'ladi (birinchi yordamchi fe'ldan keyin)."},{"t":"ex","en":"They have each been questioned.","uz":"Ularning har biri so'roq qilingan."},{"t":"h","x":"Both"},{"t":"p","x":"<b>Both</b> — «har ikkalasi, ikkalasi ham», o'zidan keyin <b>ko'plikdagi ot</b> va <b>ko'plikdagi fe'l</b> talab qiladi. U o'zi yolg'iz yoki ot bilan kelishi mumkin."},{"t":"ex","en":"Both doors were open.","uz":"Ikkala eshik ham ochiq edi."},{"t":"ex","en":"I gave him both, but he didn't let me in.","uz":"Unga ikkalasini ham berdim, lekin u meni ichkariga kiritmadi."},{"t":"p","x":"<b>Both of + the / these / those / egalik sifati / kishilik olmoshi</b>. Bu holatda (olmoshdan tashqari) <b>of</b> ni tushirib qoldirish mumkin."},{"t":"ex","en":"both of the wheels = both the wheels","uz":"ikkala g'ildirak ham"},{"t":"table","head":["Both of ...","Muqobil shakl"],"rows":[["both of you","you both"],["both of us","we both (ega), us both (to'ldiruvchi)"],["both of them","they both (ega), them both (to'ldiruvchi)"]]},{"t":"ex","en":"Both of us knew him. = We both knew him.","uz":"Ikkalamiz ham uni tanirdik."},{"t":"p","x":"Both fe'l bilan kelsa, <b>all</b> va <b>each</b> dagi o'rin qoidalari amal qiladi: <i>They have both left.</i>"},{"t":"h","x":"Neither"},{"t":"p","x":"<b>Neither</b> — «(ikkalasidan) birortasi ham ... emas» ma'nosini beradi va o'zidan keyin <b>birlikdagi ot</b> hamda <b>tasdiq shaklidagi birlik fe'l</b> talab qiladi. U yolg'iz yoki ot bilan kelishi mumkin."},{"t":"ex","en":"I tried both keys, but neither worked.","uz":"Ikkala kalitni ham sinab ko'rdim, lekin birortasi ham ishlamadi."},{"t":"ex","en":"Neither boy knew the way.","uz":"Ikkala boladan birortasi ham yo'lni bilmasdi."},{"t":"p","x":"<b>Neither of + the / these / those / egalik sifati / kishilik olmoshi</b> bilan kelishi mumkin; of dan keyin doim <b>ko'plikdagi</b> ot yoki olmosh keladi."},{"t":"h","x":"Either"},{"t":"p","x":"<b>Either</b> — «ikkalasidan biri (qaysi biri bo'lsa ham)», <b>birlikdagi ot va fe'l</b> talab qiladi. U yolg'iz ham kela oladi. <b>Either of + the / these / those / egalik sifati / kishilik olmoshi</b>."},{"t":"ex","en":"Either student should know the answer.","uz":"Ikkala o'quvchidan istalgani javobni bilishi kerak."},{"t":"ex","en":"Either of you has to stay.","uz":"Ikkalangizdan biringiz qolishingiz kerak."},{"t":"table","head":["Qolip","Misol"],"rows":[["either + inkor fe'l","I haven't read either of these books."],["neither + tasdiq fe'l","I have read neither of these books."]]},{"t":"rule","x":"<b>Neither</b> va <b>either</b> ga ishora qiluvchi olmosh yoki egalik sifati kerak bo'lsa, <b>they, their, them</b> ishlatiladi. <b>NB!</b> Faqat odamlar uchun."},{"t":"ex","en":"Neither of them knows the way, do they?","uz":"Ularning hech biri yo'lni bilmaydi, shundaymi?"},{"t":"ex","en":"Either of them can bring their passport.","uz":"Ularning istalgan biri pasportini olib kelishi mumkin."},{"t":"h","x":"Juft bog'lovchilar"},{"t":"table","head":["Bog'lovchi","Ma'nosi"],"rows":[["both … and …","ham … ham …"],["neither … nor …","na … na …"],["either … or …","yo … yo …"]]},{"t":"ex","en":"It was both cold and wet.","uz":"Ham sovuq, ham nam edi."},{"t":"ex","en":"She neither wrote nor phoned.","uz":"U na yozdi, na qo'ng'iroq qildi."},{"t":"ex","en":"Could you either phone or send a fax?","uz":"Yo telefon qila olasizmi, yo faks yubora olasizmi?"}],"quiz":[{"q":"Each of us ___ a map.","o":["have","has","are having","were"],"a":1,"e":"Each of us/you/them birlik hisoblanadi."},{"q":"We each ___ a map.","o":["has","have","is having","was"],"a":1,"e":"We/you/they each ko'plik hisoblanadi."},{"q":"Choose the correct sentence.","o":["Each them got a prize.","Each of them got a prize.","Each they got a prize.","Them each of got a prize."],"a":1,"e":"Each + kishilik olmoshi bilan of tushirilmaydi: each of them."},{"q":"Both doors ___ open.","o":["was","were","is","has"],"a":1,"e":"Both ko'plikdagi ot va fe'l talab qiladi."},{"q":"Which is correct?","o":["Both of us knew him.","Both us knew him.","Us both knew him.","Both we knew him."],"a":0,"e":"Both of us yoki we both (ega) — to'g'ri shakllar."},{"q":"I tried both keys, but ___ worked.","o":["either","neither","both","none of both"],"a":1,"e":"Neither + tasdiq fe'l — birortasi ham ... emas."},{"q":"I haven't read ___ of these books.","o":["neither","either","both","none"],"a":1,"e":"Inkor fe'l bilan either ishlatiladi."},{"q":"___ of you has to stay here.","o":["Both","Either","All","We"],"a":1,"e":"Either of you — ikkalangizdan biri; birlik fe'l (has) bilan."},{"q":"She ___ wrote nor phoned.","o":["either","neither","both","not"],"a":1,"e":"Neither … nor … — na … na …"},{"q":"It was ___ cold and wet.","o":["either","neither","both","so"],"a":2,"e":"Both … and … — ham … ham …"}]},{"id":"p6-11","en":"Adjectives: -ing / -ed, Link Verbs and Using 'and'","uz":"Sifatlar: -ing / -ed, bog'lovchi fe'llar va and qo'yilishi","emoji":"🎨","level":"A2","group":"Olmosh, sifat, ravish","summary":"Sifat vazifasidagi present va past participle farqi, link verb dan keyin sifat yoki ravish tanlash hamda bir nechta sifat orasida and qo'yish qoidalari.","blocks":[{"t":"h","x":"-ing va -ed sifatlar"},{"t":"p","x":"<b>Present participle</b> (-ing) ham, <b>past participle</b> (-ed) ham gapda sifat bo'lib kela oladi."},{"t":"list","items":["<b>-ing sifat</b> (present participle) — <b>aktiv</b>: «shunday ta'sir ko'rsatadigan» (having this effect). Masalan: <i>boring</i> — zeriktiradigan.","<b>-ed sifat</b> (past participle) — <b>passiv</b>: «shunday ta'sirlangan» (affected in this way). Masalan: <i>bored</i> — zerikkan."]},{"t":"ex","en":"She was boring.","uz":"U zerikarli edi (boshqalarni zeriktirardi)."},{"t":"ex","en":"She was bored.","uz":"U zerikkan edi."},{"t":"ex","en":"The job was tiring.","uz":"Ish charchatadigan edi."},{"t":"ex","en":"I was tired.","uz":"Men charchagan edim."},{"t":"table","head":["-ed (passiv)","-ing (aktiv)"],"rows":[["a tired woman — charchagan ayol","a tiring woman — charchatadigan ayol"],["bored — zerikkan","boring — zerikarli"]]},{"t":"h","x":"Link verb: sifat yoki ravish?"},{"t":"p","x":"Ba'zi fe'llar (look, turn, feel, sound, taste, grow va h.k.) ham <b>link verb</b> (bog'lovchi fe'l), ham oddiy (harakat) fe'l bo'lib kela oladi."},{"t":"list","items":["<b>Link verb</b> bo'lsa, undan keyin <b>sifat</b> ishlatiladi; u holatni bildiradi, bunda ish-harakat sodir bo'lmaydi. Link verb o'rniga <b>to be</b> qo'yilsa ma'no deyarli o'zgarmaydi.","Boshqa hollarda, ya'ni fe'l harakatni bildirsa, sifat emas, balki <b>ravish</b> ishlatiladi."]},{"t":"ex","en":"He looked calm.","uz":"U xotirjam ko'rinardi. (= He was calm.)"},{"t":"ex","en":"He looked calmly at the angry crowd.","uz":"U g'azablangan olomonga xotirjam qaradi."},{"t":"ex","en":"She turned pale.","uz":"Uning rangi oqarib ketdi."},{"t":"ex","en":"She turned angrily to the man behind her.","uz":"U orqasidagi odamga jahl bilan o'girildi."},{"t":"h","x":"Bir nechta sifat va and"},{"t":"p","x":"Ot oldidan (attributive) bir nechta sifat kelsa, <b>and</b> qo'yish shart emas. Ammo <b>rang</b> sifatlari kelsa, oxirgi ikki sifat orasiga <b>and</b> qo'yiladi."},{"t":"ex","en":"a green and brown carpet","uz":"yashil va jigarrang gilam"},{"t":"ex","en":"a red, white and blue flag","uz":"qizil, oq va ko'k bayroq"},{"t":"p","x":"Kesim tarkibida (predicative, fe'ldan keyin) bir nechta sifat kelsa, oxirgi ikki sifat orasiga <b>and</b> qo'yiladi."},{"t":"ex","en":"The day was cold, wet and windy.","uz":"Kun sovuq, nam va shamolli edi."}],"quiz":[{"q":"The lecture was very long and ___.","o":["bored","boring","bore","boringly"],"a":1,"e":"-ing sifat — ta'sir ko'rsatadigan (zeriktiradigan)."},{"q":"After the long trip, I was very ___.","o":["tiring","tired","tire","tiringly"],"a":1,"e":"-ed sifat — ta'sirlangan (charchagan)."},{"q":"'A tiring woman' means a woman who:","o":["is tired","makes others tired","is retired","feels sleepy"],"a":1,"e":"-ing sifat aktiv: boshqalarni charchatadigan."},{"q":"He looked ___. (= He was calm.)","o":["calmly","calm","calmness","calming"],"a":1,"e":"Link verb dan keyin sifat ishlatiladi."},{"q":"He looked ___ at the angry crowd.","o":["calm","calmly","calmed","calmer"],"a":1,"e":"Look at — harakat fe'li, shuning uchun ravish ishlatiladi."},{"q":"She turned ___ when she heard the news.","o":["palely","pale","paleness","to pale"],"a":1,"e":"Turn bu yerda link verb (= became), undan keyin sifat."},{"q":"Which phrase is correct?","o":["a red, white, blue flag","a red, white and blue flag","a red and white and and blue flag","a red white blue flag"],"a":1,"e":"Rang sifatlarida oxirgi ikkisi orasiga and qo'yiladi."},{"q":"Which sentence is correct?","o":["The day was cold, wet, windy.","The day was cold, wet and windy.","The day was cold and, wet windy.","The day was and cold wet windy."],"a":1,"e":"Kesim tarkibidagi sifatlarda oxirgi ikkisi orasiga and qo'yiladi."},{"q":"Which phrase is correct without 'and'?","o":["a big old house","a green brown carpet","The day was cold wet.","a black white cat"],"a":0,"e":"Ot oldidagi oddiy sifatlar orasiga and shart emas; ranglarda esa and kerak."},{"q":"The film was ___; we all felt ___.","o":["frightened / frightening","frightening / frightened","frightening / frightening","frightened / frightened"],"a":1,"e":"Film qo'rqitadigan (-ing), biz qo'rqib ketgan (-ed)."}]},{"id":"p6-12","en":"Comparison of Adjectives: as…as, than, the…the","uz":"Sifatlarni qiyoslash: as…as, than, the…the","emoji":"⚖️","level":"B1","group":"Olmosh, sifat, ravish","summary":"As…as va so…as, qiyosiy daraja qoliplari, mantiqsiz qiyoslashlar, karrali qiyoslash, the more…the more, the superlative…ever va darker and darker shakllari.","blocks":[{"t":"h","x":"As … as"},{"t":"p","x":"<b>As … as</b> — «...dek, ...singari» deb tarjima qilinadi va tasdiq hamda inkor gaplarda ishlatiladi. Bu qolipda sifatning <b>oddiy (positive) darajasi</b> ishlatiladi."},{"t":"ex","en":"A boy of sixteen is often as tall as his father.","uz":"16 yoshli bola ko'pincha otasidek baland bo'ladi."},{"t":"ex","en":"He isn't as snobbish as you.","uz":"U sendek manman emas."},{"t":"h","x":"So … as"},{"t":"p","x":"<b>So … as</b> — <b>as … as</b> ga ekvivalent. Yagona farqi: <b>so … as</b> faqat <b>inkor</b> gaplarda ishlatiladi."},{"t":"ex","en":"Your coffee isn't so good as mine.","uz":"Sizning qahvangiz menikidek yaxshi emas."},{"t":"h","x":"Most = very"},{"t":"p","x":"<b>Most</b> so'zi sifat bilan <b>the</b> artiklisiz ishlatilishi mumkin va bunda <b>very</b> (juda) ma'nosini beradi."},{"t":"ex","en":"It was a most interesting lecture.","uz":"Bu juda qiziqarli ma'ruza edi."},{"t":"h","x":"Qiyosiy daraja qoliplari"},{"t":"formula","x":"S + V + comparative adjective + than + noun / pronoun"},{"t":"ex","en":"He is taller than her.","uz":"U qizdan balandroq."},{"t":"ex","en":"This book is more interesting than that book.","uz":"Bu kitob u kitobdan qiziqarliroq."},{"t":"formula","x":"S + V + far / much / a bit / a little + comparative adjective + than + noun / pronoun"},{"t":"ex","en":"The movie we saw in the cinema was far more interesting than the one we saw at home.","uz":"Kinoteatrda ko'rgan filmimiz uyda ko'rganimizdan ancha qiziqarliroq edi."},{"t":"formula","x":"S + V + as + much / many / little / few + noun + as + noun / pronoun"},{"t":"ex","en":"She hasn't got as much patience as Tom.","uz":"Uning sabri Tomnikichalik emas."},{"t":"formula","x":"S + V + more / fewer / less + noun + than + noun / pronoun"},{"t":"ex","en":"He ate fewer apples than you.","uz":"U sendan kamroq olma yedi."},{"t":"h","x":"Mantiqsiz qiyoslashlar (illogical comparisons)"},{"t":"p","x":"Ikki narsani solishtirganda ular bir-biriga mantiqan mos, ya'ni bir turga mansub bo'lishi kerak. To'g'ri qiyoslashning 3 yo'li bor:"},{"t":"list","items":["<b>Egalik shakli (possessive)</b>: <i>His drawings are as perfect as his instructor's.</i> (instructor emas) — <i>Jack's car runs better than Mary's.</i> (Mary emas)","<b>That of</b> (birlik uchun): <i>The salary of a professor is higher than that of a secretary.</i>","<b>Those of</b> (ko'plik uchun): <i>The duties of policemen are as difficult as those of doctors.</i>"]},{"t":"ex","en":"Jack's car runs better than Mary's.","uz":"Jekning mashinasi Merinikidan yaxshiroq yuradi."},{"t":"ex","en":"The salary of a professor is higher than that of a secretary.","uz":"Professorning maoshi kotibnikidan yuqori."},{"t":"h","x":"Karrali qiyoslash (multiple numbers)"},{"t":"p","x":"<i>half, twice, three times</i> va h.k."},{"t":"formula","x":"S + V + multiple number + as + much / many (+ noun) / adjective + as + noun / pronoun"},{"t":"ex","en":"This book costs twice as much as yours.","uz":"Bu kitob siznikidan ikki baravar qimmat turadi."},{"t":"ex","en":"This book is twice as expensive as yours.","uz":"Bu kitob siznikidan ikki baravar qimmat."},{"t":"h","x":"The …, the … (parallel o'zgarish)"},{"t":"formula","x":"The + comparative …, the + comparative …"},{"t":"ex","en":"The higher we flew, the worse she felt.","uz":"Qancha baland uchganimiz sari, u o'zini shuncha yomonroq his qildi."},{"t":"ex","en":"The bigger they are, the harder they fall.","uz":"Qancha katta bo'lsa, shuncha qattiq yiqiladi."},{"t":"formula","x":"The more …, the + comparative …"},{"t":"ex","en":"The more you study, the smarter you become.","uz":"Qancha ko'p o'qisang, shuncha aqlliroq bo'lasan."},{"t":"h","x":"The superlative … + perfect + ever"},{"t":"formula","x":"the + superlative + noun + (that) + S + have/has + ever + V3"},{"t":"ex","en":"It's the most beautiful bridge I've ever seen.","uz":"Bu men ko'rgan eng chiroyli ko'prik."},{"t":"ex","en":"This work is the most difficult one I've ever done.","uz":"Bu men qilgan eng qiyin ish."},{"t":"h","x":"Comparative and comparative"},{"t":"p","x":"Asta-sekin o'zgarayotgan holat yoki harakat <b>comparative and comparative</b> shakli orqali ifodalanadi."},{"t":"ex","en":"It was becoming darker and darker.","uz":"Borgan sari qorong'ilashib borardi."},{"t":"ex","en":"I was becoming more and more impatient.","uz":"Men tobora sabrsizlanib borardim."}],"quiz":[{"q":"A boy of sixteen is often as ___ as his father.","o":["taller","tall","tallest","more tall"],"a":1,"e":"As … as qolipida sifatning oddiy darajasi ishlatiladi."},{"q":"In which sentence can 'so … as' be used?","o":["She is so clever as her sister.","She isn't so clever as her sister.","Is she so clever as her sister than?","She is so cleverer as her sister."],"a":1,"e":"So … as faqat inkor gaplarda ishlatiladi."},{"q":"This film was ___ more interesting than the last one.","o":["very","far","most","so"],"a":1,"e":"Qiyosiy darajani kuchaytirish: far / much / a bit / a little + comparative."},{"q":"She hasn't got as ___ patience as Tom.","o":["many","much","more","few"],"a":1,"e":"Patience sanalmaydigan ot — as much … as."},{"q":"He ate ___ apples than you.","o":["less","fewer","little","few"],"a":1,"e":"Sanaladigan ko'plik ot (apples) bilan fewer ishlatiladi."},{"q":"Jack's car runs better than ___.","o":["Mary","Mary's","that Mary","those of Mary"],"a":1,"e":"Mantiqiy qiyoslash: mashina mashina bilan — Mary's."},{"q":"The salary of a professor is higher than ___ of a secretary.","o":["this","that","those","it"],"a":1,"e":"Birlikdagi otni takrorlamaslik uchun that of ishlatiladi."},{"q":"This book costs ___ as yours.","o":["twice as much","twice much","as twice much","twice more as"],"a":0,"e":"Karrali qiyoslash: twice / three times + as much + as."},{"q":"The more you practise, ___ you get.","o":["the better","better","the best","more better"],"a":0,"e":"The more …, the + comparative … — parallel o'zgarish."},{"q":"It was getting ___ .","o":["dark and dark","darker and darker","darkest and darkest","more dark and dark"],"a":1,"e":"Asta-sekin o'zgarish comparative and comparative bilan ifodalanadi."}]},{"id":"p7-01","en":"Position of Adverbs: Manner, Character and Place","uz":"Ravishlarning o'rni: holat, xarakter va o'rin ravishlari","emoji":"📍","level":"B1","group":"Olmosh, sifat, ravish","summary":"Holat ravishlari (beautifully, well), xarakter ravishlari (kindly, foolishly) va o'rin ravishlari (here, away, everywhere) gapda qayerda turishi va o'rni o'zgarsa ma'no qanday o'zgarishi.","blocks":[{"t":"h","x":"1. Holat ravishlari (Adverbs of manner)"},{"t":"p","x":"Holat ravishlari harakat <b>qanday</b> bajarilishini bildiradi. Ular odatda <b>fe'ldan keyin</b> keladi."},{"t":"ex","en":"She dances beautifully.","uz":"U chiroyli raqs tushadi."},{"t":"ex","en":"He runs fast.","uz":"U tez yuguradi."},{"t":"p","x":"Agar fe'ldan keyin <b>to'ldiruvchi (object)</b> bo'lsa, holat ravishi to'ldiruvchidan keyin keladi."},{"t":"rule","x":"Diqqat: ravishni fe'l bilan to'ldiruvchi orasiga qo'yib bo'lmaydi! <i>He speaks well English</i> ❌ → <b>He speaks English well</b> ✅"},{"t":"formula","x":"S + V + O + adverb of manner"},{"t":"ex","en":"He gave her money reluctantly.","uz":"U unga pulni istar-istamas berdi."},{"t":"ex","en":"He speaks English well.","uz":"U ingliz tilida yaxshi gapiradi."},{"t":"h","x":"Fe'l + predlog + to'ldiruvchi"},{"t":"p","x":"<b>Fe'l + predlog + to'ldiruvchi</b> bo'lganda ravish predlogdan oldin ham, to'ldiruvchidan keyin ham kelishi mumkin. Ma'no o'zgarmaydi."},{"t":"ex","en":"He looked at me suspiciously.","uz":"U menga shubha bilan qaradi."},{"t":"ex","en":"He looked suspiciously at me.","uz":"U menga shubha bilan qaradi."},{"t":"p","x":"Agar to'ldiruvchi tarkibida ibora yoki ergash gap bo'lsa (ya'ni u uzun bo'lsa), ravish <b>predlogdan oldin</b> qo'yiladi."},{"t":"ex","en":"He looked suspiciously at everyone who got off the plane.","uz":"U samolyotdan tushgan har bir kishiga shubha bilan qaradi."},{"t":"h","x":"To'ldiruvchining uzunligi"},{"t":"p","x":"Fe'l + to'ldiruvchi gaplarda ham to'ldiruvchining uzunligi muhim: to'ldiruvchi qisqa bo'lsa — ravish undan keyin; uzun bo'lsa (ibora/ergash gap) — ravish <b>fe'ldan oldin</b> keladi."},{"t":"ex","en":"He angrily denied that he had stolen the money.","uz":"U pulni o'g'irlaganini jahl bilan rad etdi."},{"t":"rule","x":"Agar ravish ergash gap yoki iboradan keyin qo'yilsa, u o'sha ergash gap/iboradagi fe'lga tegishli bo'lib qoladi va ma'no o'zgaradi."},{"t":"ex","en":"He denied that he had stolen the money angrily.","uz":"U pulni jahl bilan o'g'irlaganini rad etdi (angrily → stolen ga tegishli)."},{"t":"ex","en":"They secretly decided to leave the town.","uz":"Ular shaharni tark etishga yashirincha qaror qilishdi (qaror yashirin)."},{"t":"ex","en":"They decided to leave the town secretly.","uz":"Ular shaharni yashirincha tark etishga qaror qilishdi (ketish yashirin)."},{"t":"h","x":"2. Xarakter va aql ravishlari"},{"t":"p","x":"<b>foolishly, generously, kindly, stupidly</b> va hokazo ravishlar <b>fe'ldan oldin</b> kelsa, harakatni bajarishning o'zi ahmoqona, saxiylik, mehribonlik ekanini bildiradi (ega haqida baho)."},{"t":"ex","en":"He generously paid for us.","uz":"U saxiylik qilib biz uchun pul to'ladi."},{"t":"ex","en":"He kindly waited for us. (= It was kind of him to wait.)","uz":"U mehribonlik qilib bizni kutdi."},{"t":"p","x":"Bu ravishlar fe'ldan yoki fe'l + to'ldiruvchidan <b>keyin</b> ham kelishi mumkin, lekin ma'no boshqacha bo'ladi — endi ular harakatning <b>qanday bajarilganini</b> (holat) bildiradi."},{"t":"table","head":["Fe'ldan oldin","Fe'ldan keyin"],"rows":[["He kindly waited for us. — kutishning o'zi mehribonlik","He spoke kindly. — uning ovozi va so'zlari mehribon edi"],["He generously paid for us. — to'lagani saxiylik","He paid us generously. — kerakligidan ko'p to'ladi"],["He foolishly answered the questions. — javob berishning o'zi ahmoqlik edi","He answered the questions foolishly. — javoblari ahmoqona edi"]]},{"t":"h","x":"3. O'rin ravishlari (Adverbs of place)"},{"t":"p","x":"<b>away, everywhere, here, nowhere, somewhere, there, off</b> va boshqalar."},{"t":"p","x":"To'ldiruvchi bo'lmasa, ular odatda fe'ldan keyin keladi. To'ldiruvchi bo'lsa — fe'l + to'ldiruvchidan yoki fe'l + predlog + to'ldiruvchidan keyin keladi."},{"t":"formula","x":"V + adverb<br>V + object + adverb<br>V + preposition + object + adverb"},{"t":"ex","en":"She went away.","uz":"U ketib qoldi."},{"t":"ex","en":"I looked everywhere.","uz":"Men hamma joyni qaradim."},{"t":"ex","en":"I sent her abroad.","uz":"Men uni chet elga jo'natdim."},{"t":"ex","en":"They looked for it everywhere.","uz":"Ular uni hamma joydan qidirishdi."},{"t":"p","x":"<b>Ravishdosh iboralar</b> (predlog + ot/olmosh) ham xuddi shu qoidalarga bo'ysunadi."},{"t":"ex","en":"The parrot sat on the table.","uz":"To'tiqush stol ustida o'tirdi."},{"t":"ex","en":"They live near me.","uz":"Ular menga yaqin joyda yashaydi."},{"t":"h","x":"Here / there + go / come / be + ega"},{"t":"formula","x":"Here / There + come / go / be + noun subject"},{"t":"table","head":["Inversiya (urg'uli)","Oddiy tartib"],"rows":[["Here comes Tom. — Ana, Tom kelyapti (hozir kelib qoldi).","Tom comes here. — Tom bu yerga keladi (odati)."],["Here is Tom. — Ana Tom! (hozir paydo bo'ldi / topildi)","Tom is here. — Tom shu yerda (xonada, binoda)."]]},{"t":"p","x":"Gap boshida kelgan here/there fe'ldan keyin kelgandagidan ko'ra kuchliroq urg'u oladi va odatda ma'no farq qiladi."},{"t":"rule","x":"Bu tuzilmada ega <b>ot</b> bo'lishi kerak. Agar ega <b>kishilik olmoshi</b> bo'lsa, u fe'ldan oldin keladi: <b>Here he is.</b> / <b>Here he comes.</b> (<i>Here comes he</i> ❌)."},{"t":"ex","en":"Here is an ambulance.","uz":"Ana tez yordam mashinasi."},{"t":"ex","en":"An ambulance comes here.","uz":"Bu yerga tez yordam mashinasi keladi."}],"quiz":[{"q":"Choose the correct sentence.","o":["He speaks well English.","He well speaks English.","He speaks English well.","Well he speaks English."],"a":2,"e":"Holat ravishi fe'l bilan to'ldiruvchi orasiga qo'yilmaydi — to'ldiruvchidan keyin keladi."},{"q":"Which sentence is correct?","o":["He looked suspiciously at everyone who got off the plane.","He looked at everyone suspiciously who got off the plane.","He looked at everyone who suspiciously got off the plane.","He suspiciously looked everyone at who got off the plane."],"a":0,"e":"To'ldiruvchi ergash gapli (uzun) bo'lsa, ravish predlogdan oldin qo'yiladi."},{"q":"In \"They decided to leave the town secretly\", what was secret?","o":["The decision","The leaving","Both equally","Nothing"],"a":1,"e":"Ravish iboradan keyin kelsa, o'sha iboradagi fe'lga (leave) tegishli bo'ladi."},{"q":"\"He kindly waited for us\" means:","o":["His voice was kind.","It was kind of him to wait.","He waited for a short time.","He waited angrily."],"a":1,"e":"Xarakter ravishi fe'ldan oldin kelsa, harakatning o'zi mehribonlik ekanini bildiradi."},{"q":"\"He paid us generously\" means:","o":["It was generous of him to pay at all.","He paid more than enough.","He paid only a little.","He refused to pay."],"a":1,"e":"Fe'l + to'ldiruvchidan keyin kelgan generously harakatning qanday bajarilganini bildiradi — ko'p to'ladi."},{"q":"Choose the correct sentence.","o":["Here comes he.","Here he comes.","He here comes.","Comes here he."],"a":1,"e":"Ega kishilik olmoshi bo'lsa, u fe'ldan oldin keladi: Here he comes."},{"q":"\"Here comes Tom\" means:","o":["Tom usually comes to this place.","Tom is arriving right now.","Tom never comes here.","Tom lives here."],"a":1,"e":"Here comes Tom — Tom hozir kelyapti / kelib qoldi. Tom comes here — odat."},{"q":"Choose the correct word order.","o":["They looked for it everywhere.","They everywhere looked for it.","They looked for everywhere it.","Everywhere they for it looked."],"a":0,"e":"O'rin ravishi V + predlog + to'ldiruvchidan keyin keladi: They looked for it everywhere."},{"q":"Choose the correct sentence.","o":["He angrily denied that he had stolen the money.","He denied angrily that he had stolen the money angrily.","He denied that angrily he had stolen.","Angrily he denied stolen the money."],"a":0,"e":"To'ldiruvchi uzun (ergash gap) bo'lsa, ravish fe'ldan oldin qo'yiladi."}]},{"id":"p7-02","en":"Adverbs of Time and Frequency; Order of Adverbs","uz":"Payt va takror ravishlari; ravishlar tartibi","emoji":"⏰","level":"B1","group":"Olmosh, sifat, ravish","summary":"Payt ravishlari (soon, yesterday) va takror ravishlari (always, never) gapdagi o'rni hamda bir gapda holat, o'rin va payt ravishlari kelganda ularning tartibi.","blocks":[{"t":"h","x":"1. Payt ravishlari (Adverbs of time)"},{"t":"p","x":"<b>afterwards, eventually, lately, now, recently, soon, then, today, tomorrow, yesterday, last year, next year</b>; shuningdek <b>at once, since then, till</b>."},{"t":"p","x":"Payt ravishlari odatda gapning (sodda gapning) <b>eng boshida</b> yoki <b>eng oxirida</b> keladi."},{"t":"ex","en":"Eventually I gave up.","uz":"Oxir-oqibat men taslim bo'ldim."},{"t":"ex","en":"I gave up eventually. I was fed up with it.","uz":"Oxiri taslim bo'ldim. Undan jonimga tegib ketgandi."},{"t":"p","x":"Buyruq gaplarda va <b>till</b> bilan kelgan iboralarda oxirgi o'rin odatiy."},{"t":"ex","en":"Write today.","uz":"Bugun yoz."},{"t":"ex","en":"I'll wait till night.","uz":"Men kechgacha kutaman."},{"t":"p","x":"Murakkab (yordamchi fe'lli) zamonlarda <b>afterwards, eventually, today, now, recently, soon</b> yordamchi fe'ldan keyin ham kelishi mumkin."},{"t":"ex","en":"We will soon be there.","uz":"Biz tez orada u yerda bo'lamiz."},{"t":"p","x":"<b>before, immediately, early, late</b> gap oxirida keladi."},{"t":"ex","en":"I'll go there immediately.","uz":"Men u yerga darhol boraman."},{"t":"ex","en":"I came late.","uz":"Men kech keldim."},{"t":"rule","x":"<b>before</b> va <b>immediately</b> bog'lovchi bo'lib kelsa, gap (ergash gap) boshida turadi."},{"t":"table","head":["Gap","Vazifasi"],"rows":[["I've seen him before.","ravish (oxirida)"],["Before you eat, clean your hands.","bog'lovchi (boshida)"]]},{"t":"h","x":"2. Takror ravishlari (Adverbs of frequency)"},{"t":"list","items":["a) <b>always, continually, frequently, occasionally, often, once, twice, periodically, repeatedly, sometimes, usually</b>","b) <b>ever, never, rarely, seldom, hardly ever, scarcely ever</b>"]},{"t":"p","x":"<b>to be</b> asosiy fe'l bo'lib kelsa, takror ravishi undan <b>keyin</b> keladi."},{"t":"ex","en":"I am always happy.","uz":"Men doim xursandman."},{"t":"ex","en":"She is usually late.","uz":"U odatda kechikadi."},{"t":"p","x":"Oddiy zamonlarda takror ravishi asosiy fe'ldan <b>oldin</b> keladi."},{"t":"ex","en":"They sometimes stay up during the night.","uz":"Ular ba'zan tunda uxlamay o'tirishadi."},{"t":"p","x":"Murakkab zamonlarda ravish <b>birinchi yordamchi fe'ldan keyin</b> keladi. So'roq gaplarda esa <b>yordamchi fe'l + ega</b>dan keyin keladi."},{"t":"ex","en":"He can never lie to me.","uz":"U menga hech qachon yolg'on gapira olmaydi."},{"t":"ex","en":"I have often been told not to believe him.","uz":"Menga unga ishonmaslikni ko'p marta aytishgan."},{"t":"ex","en":"Have you ever been to the USA?","uz":"Siz hech AQShda bo'lganmisiz?"},{"t":"p","x":"<b>used to</b> va <b>have to</b> ravishni o'zidan <b>oldin</b> olishni afzal ko'radi."},{"t":"ex","en":"You hardly ever have to remind him.","uz":"Unga deyarli hech qachon eslatishingizga to'g'ri kelmaydi."},{"t":"ex","en":"He always used to sit there.","uz":"U doim u yerda o'tirardi."},{"t":"p","x":"Qo'shimcha izoh yoki qisqa javoblarda takror ravishi ko'pincha <b>yordamchi fe'ldan oldin</b> qo'yiladi."},{"t":"ex","en":"I know I should take exercise, but I never do.","uz":"Mashq qilishim kerakligini bilaman, lekin hech qachon qilmayman."},{"t":"ex","en":"Do you smoke? — No, I never do.","uz":"Chekasizmi? — Yo'q, hech qachon."},{"t":"p","x":"Yordamchi fe'l urg'u olganda ham ravish undan oldin kelishi mumkin."},{"t":"ex","en":"I can never remember. / I never can remember.","uz":"Hech eslay olmayman."},{"t":"h","x":"3. Holat, o'rin va payt ravishlarining tartibi"},{"t":"formula","x":"holat (manner) → o'rin (place) → payt (time)"},{"t":"p","x":"Holat ifodalari odatda o'rin ifodalaridan <b>oldin</b> keladi."},{"t":"ex","en":"He climbed hurriedly out of the window.","uz":"U shosha-pisha derazadan chiqdi."},{"t":"ex","en":"He would study happily anywhere.","uz":"U istalgan joyda mamnuniyat bilan o'qirdi."},{"t":"rule","x":"Lekin <b>away, back, down, forward, home, in, on, off, out, round, up</b> odatda holat ravishidan <b>oldin</b> keladi."},{"t":"ex","en":"She looked back anxiously.","uz":"U xavotir bilan orqasiga qaradi."},{"t":"ex","en":"I went home quietly.","uz":"Men uyga jimgina ketdim."},{"t":"p","x":"Ba'zan bu so'zlarning ayrimlari ta'kid uchun gapning eng boshiga chiqadi (inversiya bilan)."},{"t":"ex","en":"Round and round flew the plane.","uz":"Samolyot aylanib-aylanib uchdi."},{"t":"ex","en":"Away went the runners.","uz":"Yuguruvchilar yugurib ketishdi."},{"t":"rule","x":"<b>here</b> va <b>there</b> ham holat ravishidan oldin keladi, lekin holat ravishi <b>hard, well, badly</b> bo'lsa, here/there ulardan <b>keyin</b> keladi."},{"t":"ex","en":"He stood there silently.","uz":"U u yerda jim turdi."},{"t":"ex","en":"He worked hard there.","uz":"U u yerda qattiq ishladi."},{"t":"p","x":"Payt ravishlari gapning eng boshida yoki eng oxirida keladi."},{"t":"ex","en":"Every day he queued patiently at the bus stop.","uz":"Har kuni u avtobus bekatida sabr bilan navbatda turardi."},{"t":"ex","en":"He worked hard in the garden today.","uz":"U bugun bog'da qattiq ishladi."}],"quiz":[{"q":"Choose the correct sentence.","o":["She usually is late.","She is usually late.","Usually late she is.","She is late usually always."],"a":1,"e":"to be asosiy fe'l bo'lsa, takror ravishi undan keyin keladi."},{"q":"Choose the correct sentence.","o":["They stay sometimes up at night.","They stay up sometimes at night sometimes.","They sometimes stay up at night.","Sometimes stay they up at night."],"a":2,"e":"Oddiy zamonda takror ravishi asosiy fe'ldan oldin keladi."},{"q":"Choose the correct question.","o":["Have ever you been to the USA?","Ever have you been to the USA?","Have you ever been to the USA?","Have you been ever to the USA?"],"a":2,"e":"So'roq gapda takror ravishi yordamchi fe'l + egadan keyin keladi."},{"q":"Choose the correct sentence.","o":["You have hardly ever to remind him.","You hardly ever have to remind him.","You have to hardly ever remind him.","Hardly you ever have to remind him."],"a":1,"e":"have to va used to ravishni o'zidan oldin olishni afzal ko'radi."},{"q":"Where does \"immediately\" (as an adverb) normally go?","o":["At the beginning","Before the verb","At the end of the clause","After the subject"],"a":2,"e":"before, immediately, early, late ravish sifatida gap oxirida keladi."},{"q":"In \"Before you eat, clean your hands\", \"before\" is:","o":["an adverb","a conjunction","a preposition of place","an adjective"],"a":1,"e":"Bog'lovchi bo'lib kelgan before ergash gap boshida turadi."},{"q":"Choose the correct word order.","o":["I went quietly home.","I quietly home went.","I went home quietly.","Home quietly I went."],"a":2,"e":"home, back, away kabi so'zlar holat ravishidan oldin keladi."},{"q":"Choose the correct sentence.","o":["He worked there hard.","He worked hard there.","He there worked hard.","There hard he worked."],"a":1,"e":"Holat ravishi hard/well/badly bo'lsa, here/there undan keyin keladi."},{"q":"Choose the correct sentence.","o":["I know I should exercise, but I do never.","I know I should exercise, but I never do.","I know I should exercise, but never I do.","I know I should exercise, but do I never."],"a":1,"e":"Qisqa javob/izohlarda takror ravishi yordamchi fe'ldan oldin keladi."},{"q":"Choose the correct sentence.","o":["He climbed out of the window hurriedly out.","He climbed hurriedly out of the window.","Hurriedly he out climbed of the window.","He hurriedly out of the window climbed."],"a":1,"e":"Holat ifodasi odatda o'rin ifodasidan oldin keladi."}]},{"id":"p7-03","en":"Sentence Adverbs","uz":"Butun gapga oid ravishlar (Sentence adverbs)","emoji":"💬","level":"B2","group":"Olmosh, sifat, ravish","summary":"Butun gapni o'zgartirib, so'zlovchining fikrini bildiruvchi ravishlar (certainly, probably, perhaps, surely, fortunately) va ularning gapdagi o'rni.","blocks":[{"t":"p","x":"Sentence adverbs butun gap yoki sodda gapni o'zgartiradi va odatda <b>so'zlovchining fikri yoki munosabatini</b> bildiradi."},{"t":"ex","en":"Honestly, he told the truth.","uz":"Rostini aytsam, u haqiqatni aytdi."},{"t":"ex","en":"Unfortunately, I was late.","uz":"Afsuski, men kechikdim."},{"t":"h","x":"Uch guruh"},{"t":"list","items":["<b>A guruh:</b> actually, apparently, certainly, clearly, evidently, obviously, presumably, probably, undoubtedly","<b>B guruh:</b> definitely","<b>C guruh:</b> perhaps, possibly, surely"]},{"t":"h","x":"A guruh ravishlarining o'rni"},{"t":"list","items":["<b>to be</b> asosiy fe'l bo'lsa — undan keyin: <i>He is obviously smart.</i>","Oddiy zamonda — asosiy fe'ldan oldin: <i>They certainly work hard. He actually lives next door.</i>","Murakkab zamonda — birinchi yordamchi fe'ldan keyin: <i>They have presumably sold their house.</i>","Gap boshida yoki oxirida ham kelishi mumkin: <i>Apparently he knew the town well. / He knew the town well, apparently.</i>"]},{"t":"ex","en":"He is obviously smart.","uz":"U aniq aqlli."},{"t":"ex","en":"They have presumably sold their house.","uz":"Ehtimol, ular uylarini sotib bo'lishgan."},{"t":"h","x":"Definitely"},{"t":"p","x":"<b>definitely</b> ham shu o'rinlarda keladi, lekin gap boshida kamroq ishlatiladi."},{"t":"ex","en":"He will definitely be a big name.","uz":"U albatta mashhur bo'ladi."},{"t":"h","x":"Perhaps, possibly, surely"},{"t":"p","x":"<b>perhaps</b> va <b>possibly</b> asosan gap boshida keladi. Gap oxirida kelishi ham mumkin, lekin juda kam."},{"t":"ex","en":"Perhaps we should finish.","uz":"Balki, tugatishimiz kerakdir."},{"t":"p","x":"<b>surely</b> odatda gap boshida yoki oxirida turadi (fe'l yonida juda kam). U asosan <b>so'roq gaplarda</b> ishlatiladi."},{"t":"ex","en":"Surely you paid $1?","uz":"Ishonchim komilki, 1 dollar to'lagandirsiz?"},{"t":"ex","en":"You paid $1, surely?","uz":"1 dollar to'lagandirsiz, a?"},{"t":"rule","x":"<b>sure</b> va <b>certain</b> sifatlari deyarli bir xil ma'noni beradi (<i>I am sure. = I am certain.</i>), lekin <b>certainly</b> va <b>surely</b> ravishlari farq qiladi: <b>certainly</b> = aniq, albatta; <b>surely</b> — so'zlovchi bu fikr to'g'ri ekaniga to'liq ishonch hosil qilmaganini bildiradi."},{"t":"table","head":["Gap","Ma'nosi"],"rows":[["He certainly paid $1.","U aniq 1 dollar to'ladi."],["He paid $1, surely?","U 1 dollar to'lagandir, shundaymi? (ishonch to'liq emas)"]]},{"t":"h","x":"Boshqa sentence adverbs"},{"t":"list","items":["admittedly, fortunately, unfortunately, frankly, likely","* honestly, * unlikely, * naturally, * officially"]},{"t":"p","x":"Ular odatda <b>gap boshida</b> keladi (oxirida ham mumkin, lekin kam) va gapning qolgan qismidan <b>vergul</b> bilan ajratiladi."},{"t":"ex","en":"Fortunately, I missed the class.","uz":"Baxtimga, men darsni qoldirdim."},{"t":"ex","en":"Honestly, he didn't take the money.","uz":"Rostini aytsam, u pulni olmadi."},{"t":"rule","x":"Yulduzcha (*) qo'yilgan ravishlar holat ravishi bo'lib ham kelishi mumkin — unda ma'no o'zgaradi."},{"t":"table","head":["Gap","Ma'nosi"],"rows":[["Honestly, he didn't take the money.","Rostini aytsam, u pulni olmadi (so'zlovchi fikri)."],["Tom didn't take the money honestly.","Tom pulni halol yo'l bilan olmadi (holat)."]]},{"t":"h","x":"Probably va inkor"},{"t":"p","x":"Yordamchi fe'l bo'lsa, <b>probably</b> birinchi yordamchi fe'ldan keyin keladi; lekin qisqartirilgan inkor yordamchi fe'l (won't, doesn't) undan <b>keyin</b> keladi, ya'ni probably oldinda turadi."},{"t":"ex","en":"He will probably not go.","uz":"U ehtimol bormaydi."},{"t":"ex","en":"He probably won't go.","uz":"U ehtimol bormaydi."}],"quiz":[{"q":"Choose the correct sentence.","o":["He won't probably go.","He probably won't go.","He won't go probably not.","Probably he won't not go."],"a":1,"e":"Qisqartirilgan inkor yordamchi fe'l (won't) probably dan keyin keladi."},{"q":"Choose the correct sentence.","o":["They have presumably sold their house.","They presumably have sold their house presumably.","They have sold presumably their house.","Presumably sold they have their house."],"a":0,"e":"A guruh ravishlari murakkab zamonda birinchi yordamchi fe'ldan keyin keladi."},{"q":"Which adverb shows that the speaker is NOT completely sure?","o":["certainly","definitely","surely","obviously"],"a":2,"e":"surely so'zlovchining to'liq ishonchi yo'qligini bildiradi; certainly = aniq."},{"q":"Choose the correct sentence.","o":["He is obviously smart.","He obviously is smart obviously.","Obviously is he smart.","He smart is obviously."],"a":0,"e":"to be asosiy fe'l bo'lsa, A guruh ravishi undan keyin keladi."},{"q":"Choose the correct sentence.","o":["They work certainly hard.","They certainly work hard.","They work hard certainly not.","Certainly work they hard."],"a":1,"e":"Oddiy zamonda A guruh ravishi asosiy fe'ldan oldin keladi."},{"q":"Where are \"perhaps\" and \"possibly\" chiefly used?","o":["After the main verb","In front position","Between verb and object","Only at the end"],"a":1,"e":"perhaps va possibly asosan gap boshida keladi."},{"q":"\"Surely\" is used mainly in:","o":["questions","commands","exclamations only","passive sentences"],"a":0,"e":"surely asosan so'roq gaplarda ishlatiladi: Surely you paid $1?"},{"q":"In \"Tom didn't take the money honestly\", \"honestly\" is:","o":["a sentence adverb (speaker's opinion)","an adverb of manner","an adverb of time","an adverb of degree"],"a":1,"e":"Fe'l + to'ldiruvchidan keyin kelgan honestly harakatning qanday bajarilganini bildiradi — holat ravishi."},{"q":"Which sentence uses correct punctuation?","o":["Fortunately I, was late.","Fortunately, I was late.","Fortunately I was, late.","I, fortunately was late."],"a":1,"e":"Bunday ravishlar gap boshida keladi va vergul bilan ajratiladi."}]},{"id":"p7-04","en":"Adverbs of Degree; Quite and Rather","uz":"Daraja ravishlari; quite va rather","emoji":"📏","level":"B1","group":"Olmosh, sifat, ravish","summary":"Sifat yoki boshqa ravishni kuchaytiruvchi daraja ravishlari (very, too, enough, far, much) va quite hamda rather ning farqi.","blocks":[{"t":"p","x":"Daraja ravishlari <b>sifat</b> yoki <b>boshqa ravish</b>ni o'zgartiradi va odatda ulardan <b>oldin</b> keladi."},{"t":"list","items":["absolutely, almost, barely, completely, enough, entirely, extremely, fairly, far, hardly, just, much, nearly, only, quite, rather, rarely, scarcely, so, too, very va h.k."]},{"t":"ex","en":"He is very intelligent.","uz":"U juda aqlli."},{"t":"ex","en":"You are absolutely right.","uz":"Siz mutlaqo haqsiz."},{"t":"ex","en":"He drives too fast.","uz":"U haddan tashqari tez haydaydi."},{"t":"rule","x":"<b>enough</b> sifat yoki ravishdan <b>keyin</b> keladi."},{"t":"ex","en":"This box isn't big enough.","uz":"Bu quti yetarlicha katta emas."},{"t":"ex","en":"He didn't work quickly enough.","uz":"U yetarlicha tez ishlamadi."},{"t":"rule","x":"<b>far</b> qiyosiy darajadagi sifat/ravish bilan yoki <b>too</b> + oddiy darajadagi sifat/ravish bilan ishlatiladi."},{"t":"ex","en":"It is far better to say nothing.","uz":"Hech narsa demagan ancha yaxshi."},{"t":"ex","en":"He drives far too fast.","uz":"U haddan ziyod tez haydaydi."},{"t":"h","x":"Fe'lni o'zgartiradigan daraja ravishlari"},{"t":"p","x":"<b>almost, barely, enough, hardly, just, little, a little, much, nearly, quite, rather, really, scarcely</b> fe'lni ham o'zgartira oladi."},{"t":"ex","en":"I almost finished.","uz":"Men deyarli tugatdim."},{"t":"ex","en":"I am almost ready.","uz":"Men deyarli tayyorman."},{"t":"rule","x":"<b>much</b>dan boshqa hammasi takror ravishlari kabi asosiy fe'ldan oldin keladi. <b>much</b> esa gap yoki sodda gap <b>oxirida</b> keladi."},{"t":"ex","en":"I don't know much about him.","uz":"Men u haqida ko'p narsa bilmayman."},{"t":"h","x":"Quite"},{"t":"p","x":"<b>quite</b> = «very» dan kamroq, lekin «a little» dan ko'proq (ancha, anchagina)."},{"t":"ex","en":"He's quite famous.","uz":"U ancha mashhur."},{"t":"ex","en":"She's quite beautiful.","uz":"U ancha chiroyli."},{"t":"rule","x":"<b>quite</b> a / an artikldan <b>oldin</b> keladi: <b>quite a nice day</b>, <b>quite an old house</b>."},{"t":"h","x":"Rather"},{"t":"p","x":"<b>rather</b> quite ga o'xshaydi, lekin asosan <b>salbiy</b> so'zlar va salbiy fikrlar bilan ishlatiladi."},{"t":"ex","en":"He is rather rude.","uz":"U ancha qo'pol."},{"t":"ex","en":"It is rather cold.","uz":"Ancha sovuq."},{"t":"p","x":"Ko'pincha quite ijobiy, rather salbiy fikr bilan keladi:"},{"t":"ex","en":"She's quite intelligent but rather lazy.","uz":"U ancha aqlli, lekin ancha dangasa."},{"t":"p","x":"<b>rather</b> ijobiy so'zlar bilan kelsa, «g'ayrioddiy darajada, kutilmaganda» ma'nosini beradi."},{"t":"ex","en":"a rather interesting book = an unusually interesting book","uz":"g'ayrioddiy darajada qiziqarli kitob"},{"t":"ex","en":"a rather nice orange = a surprisingly nice orange","uz":"kutilmaganda mazali apelsin"},{"t":"rule","x":"<b>rather</b> a / an dan oldin ham, keyin ham kelishi mumkin: <b>a rather interesting book</b> = <b>rather an interesting book</b>."},{"t":"h","x":"Quite = completely (butunlay)"},{"t":"p","x":"Quyidagi sifatlar bilan quite «butunlay, mutlaqo» ma'nosini beradi: <b>sure, certain, right, wrong, true, safe, unnecessary, extraordinary, different, impossible, amazing, amazed</b>."},{"t":"ex","en":"Are you sure? — Yes, quite sure.","uz":"Ishonchingiz komilmi? — Ha, mutlaqo."},{"t":"p","x":"Ba'zi fe'llar bilan ham quite «butunlay» ma'nosida keladi:"},{"t":"ex","en":"I quite agree with you.","uz":"Men siz bilan to'liq qo'shilaman."}],"quiz":[{"q":"Choose the correct sentence.","o":["This box isn't enough big.","This box isn't big enough.","This box enough isn't big.","This box isn't enough bigger."],"a":1,"e":"enough sifat yoki ravishdan keyin keladi."},{"q":"Choose the correct phrase.","o":["a quite nice day","quite a nice day","a nice quite day","nice a quite day"],"a":1,"e":"quite a / an dan oldin keladi."},{"q":"Which is correct?","o":["It is far good to say nothing.","It is far better to say nothing.","It is far best to say nothing.","It is better far to say nothing."],"a":1,"e":"far qiyosiy daraja (better) yoki too + sifat bilan ishlatiladi."},{"q":"Choose the correct sentence.","o":["I don't much know about him.","I much don't know about him.","I don't know much about him.","Much I don't know about him."],"a":2,"e":"much fe'lni o'zgartirganda gap oxirida keladi."},{"q":"Which word is mainly used with negative ideas?","o":["quite","rather","very","completely"],"a":1,"e":"rather asosan salbiy so'z va fikrlar bilan ishlatiladi."},{"q":"\"A rather interesting book\" means:","o":["a slightly boring book","an unusually interesting book","a completely interesting book","a book that is not interesting"],"a":1,"e":"rather ijobiy so'z bilan kelsa «g'ayrioddiy, kutilmaganda» ma'nosini beradi."},{"q":"In \"Yes, quite sure\", \"quite\" means:","o":["a little","completely","not very","rather"],"a":1,"e":"sure, right, wrong, impossible kabi sifatlar bilan quite = completely."},{"q":"Which phrase is NOT correct?","o":["a rather old house","rather an old house","quite an old house","an quite old house"],"a":3,"e":"quite a/an dan oldin keladi; rather esa oldin ham, keyin ham kelishi mumkin."},{"q":"Choose the best sentence.","o":["She's rather intelligent but quite lazy.","She's quite intelligent but rather lazy.","She's quite intelligent but quite lazy rather.","She's intelligent rather but lazy quite."],"a":1,"e":"Odatda quite ijobiy fikr bilan, rather salbiy fikr bilan keladi."}]},{"id":"p7-05","en":"Inversion after Negative and Restrictive Adverbs","uz":"Inversiya (ta'kid uchun so'z tartibining o'zgarishi)","emoji":"🔄","level":"C1","group":"Savollar va gap turlari","summary":"never, seldom, not only, no sooner kabi ravish va iboralar gap boshiga chiqqanda darak gapda so'roq gap tartibi (inversiya) qo'llanishi.","blocks":[{"t":"p","x":"Ba'zi ravish va ravishdosh iboralar <b>qo'shimcha ta'kid</b> berish uchun gap yoki sodda gapning eng boshiga qo'yilishi mumkin. Bunda gap <b>darak gap</b> bo'lib qoladi, lekin so'z tartibi <b>so'roq gapdagidek</b> bo'ladi (yordamchi fe'l egadan oldin). Bu so'zlarning ko'pchiligi inkor yoki cheklov ma'nosiga ega."},{"t":"formula","x":"Adverb (phrase) + auxiliary + subject + main verb ..."},{"t":"h","x":"Inversiya talab qiladigan so'zlar"},{"t":"list","items":["hardly ever, hardly … when","in no circumstances, on no account","neither, nor","never, seldom, scarcely ever","no sooner … than","not only, not till","nowhere","only by, only in this way, only then, only when","scarcely … when","so"]},{"t":"h","x":"Misollar"},{"t":"table","head":["Oddiy tartib","Inversiya"],"rows":[["I have never before been asked to accept a bribe.","Never before have I been asked to accept a bribe."],["He didn't realize that he had lost it till he got home.","Not till he got home did he realize that he had lost it."],["He became so suspicious that he checked everyone.","So suspicious did he become that he checked everyone."]]},{"t":"ex","en":"Never before have I been asked to accept a bribe.","uz":"Hech qachon mendan pora olishni so'rashmagan edi."},{"t":"ex","en":"Not till he got home did he realize that he had lost it.","uz":"U uni yo'qotganini faqat uyga kelgandagina angladi."},{"t":"rule","x":"Oddiy zamonda (Present/Past Simple) inversiya uchun <b>do / does / did</b> qo'shiladi: <i>Not till he got home <b>did</b> he realize...</i>"}],"quiz":[{"q":"Choose the correct sentence.","o":["Never before I have been asked to accept a bribe.","Never before have I been asked to accept a bribe.","Never before I was asked have.","Never have before been I asked."],"a":1,"e":"Never gap boshida kelsa, yordamchi fe'l egadan oldin keladi."},{"q":"Choose the correct sentence.","o":["Not till he got home he realized it.","Not till he got home did he realize it.","Not till he got home realized he it.","Not till did he get home he realized it."],"a":1,"e":"Oddiy o'tgan zamonda inversiya uchun did qo'shiladi va asosiy (bosh) gapda inversiya bo'ladi."},{"q":"Which word requires inversion when placed at the beginning?","o":["Usually","Seldom","Today","Happily"],"a":1,"e":"seldom inversiya talab qiladigan so'zlar ro'yxatida bor."},{"q":"Complete: No sooner had he arrived ___ the phone rang.","o":["then","when","than","that"],"a":2,"e":"To'g'ri juftlik: no sooner … than."},{"q":"Complete: Hardly had I sat down ___ the bell rang.","o":["than","when","then","so"],"a":1,"e":"hardly … when / scarcely … when."},{"q":"Choose the correct sentence.","o":["So suspicious he became that he checked everyone.","So suspicious did he become that he checked everyone.","So did suspicious he become that he checked everyone.","So suspicious became did he that he checked everyone."],"a":1,"e":"So + sifat gap boshida kelsa, did + ega + fe'l tartibi ishlatiladi."},{"q":"Choose the correct sentence.","o":["On no account you should open this door.","On no account should you open this door.","On no account should open you this door.","On no account you open should this door."],"a":1,"e":"On no account dan keyin yordamchi fe'l (should) egadan oldin keladi."},{"q":"Why do we use inversion after these adverbs?","o":["To make a question","To give extra emphasis","To make the sentence passive","To show future time"],"a":1,"e":"Bu ravishlar qo'shimcha ta'kid berish uchun gap boshiga chiqariladi; gap so'roq emas, darak gap bo'lib qoladi."}]},{"id":"p7-06","en":"Sentences, Clauses, Conjunctions and Linkers","uz":"Gap, sodda gap (clause), bog'lovchilar va linkerlar","emoji":"🔗","level":"A2","group":"Ko'chirma gap va murakkab gaplar","summary":"Mustaqil va ergash gaplar, sodda, qo'shma (compound) va murakkab (complex) gaplar hamda and, but, or, so, because bog'lovchilari va if/when farqi.","blocks":[{"t":"h","x":"Gap va clause"},{"t":"p","x":"To'liq fikr — bu <b>gap (sentence)</b>; gap esa <b>clause</b>lardan tashkil topadi. <b>Clause</b> — ega va kesimi bo'lgan so'zlar guruhi."},{"t":"ex","en":"He jumps.","uz":"U sakraydi."},{"t":"ex","en":"John, who is your teacher, can jump high.","uz":"Sizning o'qituvchingiz bo'lgan Jon baland sakray oladi."},{"t":"h","x":"Mustaqil va ergash clause"},{"t":"list","items":["<b>Independent clause</b> (mustaqil gap) — ega va kesimga ega, o'zi to'liq gap bo'la oladi, bitta to'liq fikr beradi: <i>He jumps.</i>","<b>Dependent clause</b> (ergash gap) — ega va kesimi bor, lekin to'liq gap hosil qilmaydi; mustaqil gapga bog'lanishi shart va to'liq fikr bermaydi."]},{"t":"ex","en":"The TV program that I saw was very interesting.","uz":"Men ko'rgan teleko'rsatuv juda qiziqarli edi."},{"t":"p","x":"Bu gapda ergash gap <i>«that I saw»</i> mustaqil gap <i>«The TV program was very interesting»</i> ga bog'langan va qo'shimcha ma'lumot beradi — ko'rsatuvni kim ko'rganini aytadi."},{"t":"ex","en":"The toy was torn into pieces as a dog played with it.","uz":"It o'ynayotganda o'yinchoq parcha-parcha bo'lib yirtildi."},{"t":"p","x":"Bu yerda ergash gap <i>«as a dog played with it»</i> o'yinchoqni kim va qanday yirtgani haqida qo'shimcha ma'lumot beradi."},{"t":"ex","en":"When I leave, I will send you a message.","uz":"Ketganimda sizga xabar yuboraman."},{"t":"p","x":"Gapning asosiy fikrini beruvchi mustaqil qism <b>main clause</b> (bosh gap) deyiladi."},{"t":"h","x":"Gap turlari"},{"t":"list","items":["1) <b>Simple</b> (sodda) — bitta mustaqil clause: <i>The cat ran. / Last night the fat black cat swiftly ran under the speeding blue sports car.</i>","2) <b>Compound</b> (qo'shma, teng bog'lovchili) — ikki yoki undan ortiq mustaqil clause: <i>The cat ran and the dog chased it.</i>","3) <b>Complex</b> (ergash gapli) — bir yoki bir nechta mustaqil va bir yoki bir nechta ergash clause: <i>The cat that I saw ran.</i>"]},{"t":"p","x":"Compound gapdagi mustaqil gaplar <b>and, but, or, nor, yet</b> bog'lovchilari bilan bog'lanadi."},{"t":"ex","en":"We could trade in our old car or we could keep it as a second car.","uz":"Eski mashinamizni almashtirishimiz yoki uni ikkinchi mashina sifatida saqlashimiz mumkin."},{"t":"ex","en":"Last night the fat black cat that I saw in the street swiftly ran under the speeding blue sports car as a big shaggy dog chased after it.","uz":"Kecha kechqurun ko'chada ko'rgan semiz qora mushugim katta paxmoq it quvlaganda tez ketayotgan ko'k sport mashinasi tagiga yugurib kirdi."},{"t":"h","x":"Bog'lovchilar (Conjunctions)"},{"t":"p","x":"Bog'lovchilar ikki sodda gapni bitta qo'shma gapga birlashtiradi."},{"t":"ex","en":"The car stopped. The driver got out. → The car stopped and the driver got out.","uz":"Mashina to'xtadi va haydovchi tushdi."},{"t":"table","head":["Bog'lovchi","Vazifasi","Misol"],"rows":[["and","bir xil turdagi gaplarni bog'laydi (ikkalasi ham bo'lishli yoki ikkalasi ham inkor)","The car didn't stop and the driver didn't get out."],["but","har xil gaplarni bog'laydi (biri bo'lishli, biri inkor)","I phoned but he didn't answer."],["or","ikki tanlovni ko'rsatadi; asosan so'roq gaplarda","Do you want to play tennis or are you tired? / I could play tennis or I could sleep."],["so","natijani ko'rsatadi","It was too hot so I opened the window."],["because","sababni ko'rsatadi","I opened the window because it was too hot."]]},{"t":"rule","x":"<b>and, but, or, so</b> doim gapning o'rtasida keladi. <b>because</b> — istisno: u gap boshida ham kelishi mumkin, bunda ikki gap orasiga albatta <b>vergul</b> qo'yiladi: <b>Because it was too hot, I opened the window.</b>"},{"t":"h","x":"Linkerlar"},{"t":"p","x":"Linkerlar bitta ergash va bitta mustaqil gapni bitta murakkab (complex) gapga birlashtiradi."},{"t":"ex","en":"When I came, he wasn't at home.","uz":"Men kelganimda u uyda yo'q edi."},{"t":"h","x":"If va when farqi"},{"t":"table","head":["Gap","Ma'nosi"],"rows":[["If I see him, I will tell him.","Uni ko'rishim mumkin, lekin aniq emas."],["When I see him, I will tell him.","Uni albatta ko'raman (ko'rganimda aytaman)."]]}],"quiz":[{"q":"What is a clause?","o":["Any group of words","A group of words with a subject and a verb","Only a full sentence","A word that joins sentences"],"a":1,"e":"Clause — ega va kesimi bo'lgan so'zlar guruhi."},{"q":"\"The cat ran and the dog chased it\" is a ___ sentence.","o":["simple","compound","complex","dependent"],"a":1,"e":"Ikki mustaqil gap and bilan bog'langan — compound."},{"q":"\"The cat that I saw ran\" is a ___ sentence.","o":["simple","compound","complex","imperative"],"a":2,"e":"Mustaqil gap + ergash gap (that I saw) — complex."},{"q":"Choose the correct conjunction: I phoned ___ he didn't answer.","o":["and","but","so","or"],"a":1,"e":"but bo'lishli va inkor gapni (har xil gaplarni) bog'laydi."},{"q":"Choose the correct conjunction: It was too hot ___ I opened the window.","o":["because","but","so","or"],"a":2,"e":"so natijani ko'rsatadi."},{"q":"Which conjunction can begin a sentence (followed by a comma between clauses)?","o":["and","so","because","but"],"a":2,"e":"because istisno: gap boshida kelishi mumkin, ikki gap orasiga vergul qo'yiladi."},{"q":"\"When I see him, I will tell him\" means:","o":["I may possibly see him.","I will definitely see him.","I saw him yesterday.","I will never see him."],"a":1,"e":"when — albatta ko'raman; if — ko'rishim mumkin, aniq emas."},{"q":"Which is a dependent clause?","o":["He jumps.","The program was interesting.","that I saw","I opened the window."],"a":2,"e":"Ergash gap to'liq fikr bermaydi va mustaqil gapga bog'lanishi kerak."},{"q":"Choose the correct conjunction: Do you want tea ___ coffee?","o":["but","so","or","because"],"a":2,"e":"or ikki tanlovni ko'rsatadi, asosan so'roq gaplarda."}]},{"id":"p7-07","en":"Reported Speech: Statements and Sequence of Tenses","uz":"O'zlashtirma gap: darak gaplar va zamonlar moslashuvi","emoji":"🗣️","level":"B1","group":"Ko'chirma gap va murakkab gaplar","summary":"Ko'chirma gapni o'zlashtirma gapga aylantirishda olmosh, this/these, zamon, payt va o'rin ifodalarining o'zgarishi hamda zamonlar moslashuvi qoidasi.","blocks":[{"t":"h","x":"Ko'chirma va o'zlashtirma gap"},{"t":"list","items":["<b>Direct speech</b> (ko'chirma gap) — so'zlovchining aynan o'z so'zlari keltiriladi.","<b>Indirect / reported speech</b> (o'zlashtirma gap) — so'zlovchining aynan so'zlari emas, aytgan fikrining aniq mazmuni beriladi."]},{"t":"ex","en":"He said: “I have lost my phone.”","uz":"U dedi: «Men telefonimni yo'qotdim.»"},{"t":"ex","en":"He said he had lost his phone.","uz":"U telefonini yo'qotganini aytdi."},{"t":"rule","x":"Ko'chirma gapda keltirilgan so'zlar <b>qo'shtirnoq</b> ichiga olinadi; ulardan bevosita oldin <b>vergul</b> yoki <b>ikki nuqta</b> qo'yiladi."},{"t":"h","x":"1. Olmosh va egalik sifatlari"},{"t":"p","x":"Olmoshlar va egalik sifatlari (my, your...) odatda o'zgaradi."},{"t":"ex","en":"He said, “I forgot where I put my phone.” → He said he had forgotten where he had put his phone.","uz":"U telefonini qayerga qo'yganini unutganini aytdi."},{"t":"p","x":"Agar so'zlovchi <b>o'z so'zlarini</b> o'zi yetkazsa, olmoshlar o'zgarmaydi."},{"t":"ex","en":"I said, “I like my house.” → I said I liked my house.","uz":"Men uyimni yoqtirishimni aytdim."},{"t":"p","x":"Ba'zan chalkashlik bo'lmasligi uchun olmosh o'rniga <b>ot</b> ishlatish kerak."},{"t":"ex","en":"Tom said, “He came in through the window.” → Tom said the thief had come in through the window.","uz":"Tom o'g'ri derazadan kirganini aytdi."},{"t":"h","x":"2. This / these"},{"t":"list","items":["Payt ifodalaridagi <b>this/these</b> → <b>that/those</b>: <i>“I'll go this week.” → She said she would go that week.</i>","Sifat sifatida kelgan <b>this/that/these/those</b> odatda → <b>the</b>: <i>“I bought this flower / these flowers for my mother.” → He said he had bought the flower / the flowers for his mother.</i>","Olmosh sifatida kelgan <b>this</b> → <b>it</b>, <b>these</b> → <b>they / them</b>."]},{"t":"ex","en":"He showed two books and said, “I found these on your shelf.” → He showed two books and said he had found them on my shelf.","uz":"U ikki kitobni ko'rsatib, ularni mening javonimdan topganini aytdi."},{"t":"ex","en":"He said, “We'll discuss this tomorrow.” → He said they would discuss it the next day.","uz":"U buni ertasi kuni muhokama qilishlarini aytdi."},{"t":"h","x":"3. Zamon"},{"t":"p","x":"Kirish fe'li <b>hozirgi zamonda</b> (says, tells) bo'lsa, zamon o'zgarmaydi."},{"t":"ex","en":"Tom says, “I'll never give up.” → Tom says he'll never give up.","uz":"Tom hech qachon taslim bo'lmasligini aytyapti."},{"t":"p","x":"Lekin o'zlashtirma gap odatda <b>o'tgan zamondagi</b> fe'l bilan kiritiladi (said, told). Bunda ko'chirma gapdagi fe'llar mos o'tgan zamonga o'tadi:"},{"t":"table","head":["Ko'chirma gap","O'zlashtirma gap"],"rows":[["Present Simple","Past Simple"],["Present Continuous","Past Continuous"],["Present Perfect","Past Perfect"],["Present Perfect Continuous","Past Perfect Continuous"],["Past Simple","Past Perfect"],["Past Perfect","Past Perfect (o'zgarmaydi)"],["Past Perfect Continuous","Past Perfect Continuous (o'zgarmaydi)"],["will","would"]]},{"t":"ex","en":"Tom said, “I never eat meat.” → Tom said he never ate meat.","uz":"Tom hech qachon go'sht yemasligini aytdi."},{"t":"ex","en":"He said, “I've seen it before.” → He said he had seen it before.","uz":"U buni avval ko'rganini aytdi."},{"t":"rule","x":"Agar aytilgan fikr hozir ham <b>haqiqat</b> bo'lsa, zamonni o'zgartirish shart emas: <i>She said, “New York is bigger than London.” → She said New York <b>is</b> bigger than London.</i>"},{"t":"h","x":"Zamonlar moslashuvi (Sequence of tenses)"},{"t":"p","x":"Bosh gap <b>o'tgan zamonda</b> bo'lsa, ergash gap ham <b>o'tgan zamonda</b> bo'lishi kerak."},{"t":"table","head":["Bosh gap hozirgi zamonda","Bosh gap o'tgan zamonda"],"rows":[["He thinks that it will rain.","He thought that it would rain."],["He sees that he has made mistakes.","He saw that he had made mistakes."]]},{"t":"h","x":"4. Payt ifodalari"},{"t":"table","head":["Ko'chirma gap","O'zlashtirma gap"],"rows":[["now","then"],["today","that day"],["yesterday","the day before"],["the day before yesterday","two days before"],["tomorrow","the next day / the following day"],["the day after tomorrow","in two days' time"],["next week / month / year","the following week / month / year"],["last week / month / year","the previous week / month / year"],["a year ago","a year before / the previous year"]]},{"t":"ex","en":"She said, “I've seen it today.” → She said she had seen it that day.","uz":"U buni o'sha kuni ko'rganini aytdi."},{"t":"rule","x":"Agar gap aytilgan va yetkazilgan kun bir xil bo'lsa, payt ifodasini o'zgartirish shart emas: <i>At breakfast this morning he said, “I'll be very busy today.” → At breakfast this morning he said he would be very busy today.</i>"},{"t":"h","x":"5. O'rin ravishlari"},{"t":"p","x":"Qaysi joy nazarda tutilgani aniq bo'lsa, <b>here → there</b>."},{"t":"ex","en":"At the airport he said, “I'll be here tomorrow.” → At the airport he said he would be there the next day.","uz":"Aeroportda u ertasi kuni u yerda bo'lishini aytdi."},{"t":"p","x":"Joy aniq bo'lmasa, here mos ibora bilan almashtiriladi."},{"t":"ex","en":"She said, “You can sit here.” → She said I could sit beside her.","uz":"U uning yonida o'tirishim mumkinligini aytdi."}],"quiz":[{"q":"He said, “I am tired.” → He said he ___ tired.","o":["is","was","has been","will be"],"a":1,"e":"Present Simple → Past Simple."},{"q":"She said, “I have finished.” → She said she ___.","o":["has finished","finished","had finished","was finishing"],"a":2,"e":"Present Perfect → Past Perfect."},{"q":"He said, “I saw her.” → He said he ___ her.","o":["saw","had seen","has seen","sees"],"a":1,"e":"Past Simple → Past Perfect."},{"q":"They said, “We will come.” → They said they ___ come.","o":["will","would","shall","are going"],"a":1,"e":"will → would."},{"q":"“tomorrow” in reported speech usually becomes:","o":["yesterday","the day before","the next day","that day"],"a":2,"e":"tomorrow → the next day / the following day."},{"q":"“yesterday” in reported speech usually becomes:","o":["the day before","the next day","two days before","that day"],"a":0,"e":"yesterday → the day before."},{"q":"She said, “New York is bigger than London.” Which report is acceptable?","o":["She said New York is bigger than London.","She said New York had been bigger.","She said New York will be bigger.","She said New York has been bigger than London."],"a":0,"e":"Fikr hozir ham haqiqat bo'lsa, zamon o'zgarmasligi mumkin."},{"q":"Tom says, “I'll never give up.” → Tom says he ___ never give up.","o":["would","will","had","did"],"a":1,"e":"Kirish fe'li hozirgi zamonda (says) bo'lsa, zamon o'zgarmaydi."},{"q":"He said, “We'll discuss this tomorrow.” → He said they would discuss ___ the next day.","o":["this","these","it","that one here"],"a":2,"e":"Olmosh sifatida kelgan this → it."},{"q":"Sequence of tenses: He thought that it ___ rain.","o":["will","would","is going","rains"],"a":1,"e":"Bosh gap o'tgan zamonda bo'lsa, ergash gap ham o'tgan zamonga o'tadi: will → would."}]},{"id":"p7-08","en":"Say and Tell; Reporting Verbs","uz":"Say va tell; o'zlashtirma gap fe'llari","emoji":"🗨️","level":"B1","group":"Ko'chirma gap va murakkab gaplar","summary":"Ko'chirma va o'zlashtirma gapda say va tell ning ishlatilishi, inversiya imkoniyati, that ni tushirib qoldirish va admit, explain, promise kabi fe'llar.","blocks":[{"t":"h","x":"Say — ko'chirma gap bilan"},{"t":"p","x":"Ko'chirma gapda <b>say</b> keltirilgan so'zlardan oldin ham, keyin ham kelishi mumkin."},{"t":"ex","en":"Tom said, “I've just heard it.”","uz":"Tom dedi: «Men buni hozirgina eshitdim.»"},{"t":"ex","en":"“I've just heard it,” Tom said.","uz":"«Men buni hozirgina eshitdim», — dedi Tom."},{"t":"p","x":"Say keltirilgan so'zlardan keyin kelsa, <b>inversiya</b> mumkin — lekin ega <b>ot</b> bo'lishi shart."},{"t":"ex","en":"“I've just heard it,” said Tom.","uz":"«Men buni hozirgina eshitdim», — dedi Tom."},{"t":"p","x":"<b>say + to + kimga</b> tuzilmasi faqat keltirilgan so'zlardan keyin kelganda mumkin; bunda inversiya <b>mumkin emas</b>."},{"t":"ex","en":"“I have just heard it,” Tom said to me.","uz":"«Men buni hozirgina eshitdim», — dedi Tom menga."},{"t":"h","x":"Tell — ko'chirma gap bilan"},{"t":"p","x":"<b>tell</b> doim <b>kimga</b> aytilayotganini (shaxsni) talab qiladi."},{"t":"ex","en":"Tell me. / He told us. / I will tell him.","uz":"Menga ayt. / U bizga aytdi. / Men unga aytaman."},{"t":"rule","x":"Istisno: <b>tell the truth</b>, <b>tell a lie / lies</b>, <b>tell a story</b> — shaxssiz ishlatiladi: <i>He told the truth. She tells lies. They tell a story.</i>"},{"t":"p","x":"Tell ko'chirma gap bilan ishlatilsa, doim keltirilgan so'zlardan <b>keyin</b> qo'yiladi; tell bilan <b>inversiya mumkin emas</b>."},{"t":"ex","en":"“I am leaving at once,” Tom told me.","uz":"«Men hoziroq ketyapman», — dedi Tom menga."},{"t":"h","x":"Say va tell — o'zlashtirma gap bilan"},{"t":"p","x":"O'zlashtirma darak gapni kiritish uchun <b>say</b> va <b>tell + kimga</b> ishlatiladi. <b>say + to + kimga</b> ham mumkin, lekin <b>tell + kimga</b> ancha ko'p uchraydi."},{"t":"ex","en":"Tom told me he had just heard it.","uz":"Tom menga buni hozirgina eshitganini aytdi."},{"t":"ex","en":"He said he had just heard it.","uz":"U buni hozirgina eshitganini aytdi."},{"t":"ex","en":"He said to me that he had just heard it.","uz":"U menga buni hozirgina eshitganini aytdi."},{"t":"rule","x":"<b>say</b> va <b>tell + kimga</b> dan keyin <b>that</b> tushirib qoldirilishi mumkin. <b>say + to + kimga</b> dan keyin esa <b>that</b>ni tushirib bo'lmaydi."},{"t":"ex","en":"Tom told me (that) he had heard it. / He said (that) he had just heard it.","uz":"that ixtiyoriy"},{"t":"h","x":"Boshqa kirish fe'llari"},{"t":"list","items":["add*, admit*, answer*, argue*, boast*, complain*, deny*, explain*, grumble*, object*, observe*, promise*, protest*, remark*, reply*","assure + kimni, point out, remind + kimni"]},{"t":"p","x":"Ular ko'chirma gap bilan ishlatilsa, keltirilgan so'zlardan <b>keyin</b> qo'yiladi."},{"t":"ex","en":"“It will cost a lot,” Tom assured us.","uz":"«Bu qimmatga tushadi», — deb Tom bizni ishontirdi."},{"t":"p","x":"Yulduzcha qo'yilgan fe'llarda inversiya faqat ega <b>ot</b> bo'lsa mumkin."},{"t":"ex","en":"“But it will take longer,” Bill objected. / “But it will take longer,” objected Bill.","uz":"«Lekin bu ko'proq vaqt oladi», — deb e'tiroz bildirdi Bill."},{"t":"p","x":"Bu fe'llar o'zlashtirma gapni ham kiritadi; bunda fe'ldan keyin <b>that</b> qo'yiladi."},{"t":"ex","en":"Tom assured us that it would cost a lot, but Bill objected that it would take longer.","uz":"Tom bu qimmatga tushishiga ishontirdi, lekin Bill bu ko'proq vaqt olishini aytib e'tiroz bildirdi."}],"quiz":[{"q":"Choose the correct sentence.","o":["“I've just heard it,” said he.","“I've just heard it,” said Tom.","“I've just heard it,” told Tom.","“I've just heard it,” told he me."],"a":1,"e":"say bilan inversiya faqat ega ot bo'lganda mumkin; tell bilan inversiya umuman mumkin emas."},{"q":"Choose the correct sentence.","o":["He told that he was tired.","He said me that he was tired.","He told me that he was tired.","He said me he was tired."],"a":2,"e":"tell doim kimga aytilganini talab qiladi: told me."},{"q":"Which expression does NOT need a person after \"tell\"?","o":["tell the truth","tell about the trip","tell that he left","tell if he came"],"a":0,"e":"Istisnolar: tell the truth, tell a lie, tell a story."},{"q":"Choose the correct sentence.","o":["“I'm leaving,” told Tom me.","Tom told me, “I'm leaving.”","“I'm leaving,” Tom told me.","Told Tom me, “I'm leaving.”"],"a":2,"e":"tell ko'chirma gap bilan doim keltirilgan so'zlardan keyin keladi va inversiya bo'lmaydi."},{"q":"In which sentence can \"that\" NOT be omitted?","o":["He said that he was ill.","He told me that he was ill.","He said to me that he was ill.","She told us that she was busy."],"a":2,"e":"say + to + kimga dan keyin that tushirib qoldirilmaydi."},{"q":"Choose the correct sentence.","o":["“I have just heard it,” said Tom to me.","“I have just heard it,” Tom said to me.","Tom said to me, “I have just heard it,” said.","“I have just heard it,” said to me Tom."],"a":1,"e":"say + to + kimga keltirilgan so'zlardan keyin keladi, inversiyasiz."},{"q":"Choose the correct sentence.","o":["“But it will take longer,” objected he.","“But it will take longer,” objected Bill.","“But it will take longer,” Bill objected that.","Bill objected, that “it will take longer.”"],"a":1,"e":"Yulduzli fe'llarda (object) inversiya faqat ega ot bo'lganda mumkin."},{"q":"Which is more usual for reporting statements?","o":["say to + object","tell + object","tell to + object","say + object"],"a":1,"e":"say + to + kimga ham mumkin, lekin tell + kimga ancha ko'p uchraydi."}]},{"id":"p7-09","en":"Questions in Reported Speech","uz":"O'zlashtirma gapda so'roq gaplar","emoji":"❓","level":"B1","group":"Ko'chirma gap va murakkab gaplar","summary":"So'roq gaplarni o'zlashtirma gapga aylantirish: darak so'z tartibi, ask/inquire/wonder fe'llari, so'roq so'zi takrorlanishi va if/whether.","blocks":[{"t":"p","x":"So'roq gapni o'zlashtirma gapga aylantirishda <b>zamon, olmosh, egalik sifati, payt va o'rin ravishlari</b> darak gaplardagidek o'zgaradi. Bundan tashqari fe'lning <b>so'roq shakli darak shakliga</b> o'tadi, shuning uchun gap oxirida so'roq belgisi qo'yilmaydi."},{"t":"ex","en":"He said, “Where is she going?” → He asked where she was going.","uz":"U (ayol) qayerga ketayotganini so'radi."},{"t":"rule","x":"Ega haqidagi so'roqda (who, what ega bo'lsa) so'z tartibini o'zgartirish shart emas: <i>“Who lives next door?” he said. → He asked who lived next door.</i>"},{"t":"h","x":"So'roq fe'llari"},{"t":"p","x":"O'zlashtirma so'roq gapdagi asosiy fe'l doim so'rash fe'li bo'ladi: <b>ask, inquire, wonder, want to know</b>."},{"t":"ex","en":"He said, “Where are you from?” → He asked where I was from.","uz":"U qayerdan ekanligimni so'radi."},{"t":"p","x":"<b>inquire, ask, wonder</b> ko'chirma gapda ham ishlatiladi va keltirilgan so'zlardan keyin qo'yiladi."},{"t":"ex","en":"“Where is the station?” he inquired.","uz":"«Vokzal qayerda?» — deb so'radi u."},{"t":"rule","x":"<b>ask</b> bilan kimdan so'ralgani ko'rsatilishi mumkin (He asked <b>me</b>...), lekin <b>inquire, wonder, want to know</b> shaxsni olmaydi."},{"t":"ex","en":"He said, “What have you got in your bag?” → He asked me what I had got in my bag.","uz":"U sumkamda nima borligini mendan so'radi."},{"t":"h","x":"So'roq so'zli savollar"},{"t":"p","x":"Ko'chirma savol <b>when, where, who, how, why</b> kabi so'roq so'zi bilan boshlansa, so'roq so'zi o'zlashtirma gapda takrorlanadi."},{"t":"ex","en":"She said, “What do you want?” → She asked what they wanted.","uz":"U ular nima xohlashini so'radi."},{"t":"h","x":"Umumiy savollar: if / whether"},{"t":"p","x":"So'roq so'zi bo'lmasa, <b>if</b> yoki <b>whether</b> ishlatiladi."},{"t":"ex","en":"“Is anyone there?” he said. → He asked if / whether anyone was there.","uz":"U u yerda birov bor-yo'qligini so'radi."},{"t":"p","x":"Aslida if va whether o'rtasida farq yo'q, lekin <b>whether</b> ikki holatda ko'proq ishlatiladi:"},{"t":"list","items":["1a) <b>Tanlov savoli</b> bo'lsa: <i>“Do you want to go by air or by sea?” he asked. → He asked whether I wanted to go by air or by sea.</i>","1b) <b>whether or not</b>: <i>“Do you want to insure your luggage or not?” he asked. → He asked whether or not I wanted to insure my luggage.</i>","2) Savolda <b>shart gap</b> (if) bo'lsa — ikkinchi if o'rniga whether yaxshiroq: <i>“If you get the job, will you move to York?” he asked. → He asked whether, if I got the job, I would move to York.</i>"]}],"quiz":[{"q":"He said, “Where is she going?” → He asked ___.","o":["where is she going","where she was going","where was she going?","where she is going?"],"a":1,"e":"O'zlashtirma so'roqda darak so'z tartibi va zamon o'zgarishi: where she was going."},{"q":"“Is anyone there?” he said. → He asked ___ anyone was there.","o":["that","what","if","which"],"a":2,"e":"So'roq so'zi bo'lmasa if / whether ishlatiladi."},{"q":"“Who lives next door?” → He asked ___.","o":["who did live next door","who lived next door","who does live next door","who next door lived"],"a":1,"e":"Ega haqidagi so'roqda so'z tartibi o'zgarmaydi, faqat zamon o'zgaradi."},{"q":"Which verb can take the person asked as an object?","o":["inquire","wonder","want to know","ask"],"a":3,"e":"Faqat ask kimdan so'ralganini ko'rsata oladi: He asked me..."},{"q":"“Do you want to go by air or by sea?” → He asked ___ I wanted to go by air or by sea.","o":["that","whether","what","which"],"a":1,"e":"Tanlov savollarida whether ko'proq ishlatiladi."},{"q":"She said, “What do you want?” → She asked ___.","o":["what did they want","what they wanted","that they wanted","if what they wanted"],"a":1,"e":"So'roq so'zi takrorlanadi, tartib darak gapdagidek bo'ladi."},{"q":"Choose the correct sentence.","o":["He wondered me where the station was.","He inquired me where the station was.","He asked me where the station was.","He wanted to know me where the station was."],"a":2,"e":"inquire, wonder, want to know shaxsni olmaydi; ask oladi."},{"q":"“If you get the job, will you move to York?” → He asked ___, if I got the job, I would move to York.","o":["if","that","whether","what"],"a":2,"e":"Savolda shart gap (if) bo'lsa, ikkinchi if o'rniga whether ishlatish yaxshiroq."},{"q":"Choose the correct reported question.","o":["He asked where was I from.","He asked where I was from.","He asked where am I from?","He asked me that where I was from."],"a":1,"e":"O'zlashtirma so'roqda darak tartib, so'roq belgisi qo'yilmaydi."}]},{"id":"p7-10","en":"Commands, Requests, Advice and Suggestions in Reported Speech","uz":"O'zlashtirma gapda buyruq, iltimos, maslahat va taklif","emoji":"📢","level":"B2","group":"Ko'chirma gap va murakkab gaplar","summary":"Buyruq, iltimos va maslahatlarni fe'l + kimga + to-infinitiv bilan yetkazish, inkor shakli, be to tuzilmasi va Let's / let him / let ni o'zlashtirma gapda ifodalash.","blocks":[{"t":"h","x":"Asosiy tuzilma"},{"t":"p","x":"O'zlashtirma buyruq, iltimos va maslahat odatda quyidagicha ifodalanadi:"},{"t":"formula","x":"verb (command / request / advice) + object + to-infinitive"},{"t":"ex","en":"“Speak quietly, Tom,” she said. → She told Tom to speak quietly.","uz":"U Tomga sekin gapirishni aytdi."},{"t":"p","x":"Ishlatiladigan fe'llar: <b>advise, ask, beg, command, encourage, entreat, forbid, implore, invite, order, recommend, remind, request, tell, urge, warn</b>."},{"t":"ex","en":"“Get your coat, Tom,” he said. → He urged Tom to get his coat.","uz":"U Tomni paltosini olishga undadi."},{"t":"ex","en":"“You had better sleep,” she said. → She advised Tom to sleep.","uz":"U Tomga uxlashni maslahat berdi."},{"t":"h","x":"Inkor shakl"},{"t":"formula","x":"verb + object + not + to-infinitive"},{"t":"ex","en":"“Don't go too far, boys,” she said. → She warned the boys not to go too far.","uz":"U bolalarni uzoqqa ketmaslikka ogohlantirdi."},{"t":"h","x":"Kimga aytilgani albatta ko'rsatiladi"},{"t":"p","x":"O'zlashtirma buyruq, iltimos, maslahatda <b>kimga</b> aytilgani doim bo'lishi kerak. Ko'chirma gapda u ko'pincha aytilmaydi — shuning uchun yetkazishda ot yoki olmosh qo'shamiz."},{"t":"ex","en":"He said, “Go away.” → He told me / him / her / them / us / the children to go away.","uz":"U menga (unga, ularga...) ketishni aytdi."},{"t":"rule","x":"Istisno: <b>ask</b> dan keyin <b>see, speak to, talk to</b> kabi fe'llar kelsa, shaxs tushib qolishi mumkin: <i>He said, “Can I speak to the manager?” → He asked to speak to the manager.</i>"},{"t":"h","x":"tell / say + (that) + ega + be to + infinitiv"},{"t":"formula","x":"tell / say + that + subject + be to + infinitive"},{"t":"ex","en":"He said, “Wait.” → He told me that I was to wait. = He told me to wait.","uz":"U menga kutishimni aytdi."},{"t":"p","x":"Inkor buyruqda <b>not</b> be dan keyin qo'yiladi."},{"t":"ex","en":"He said, “Don't speak.” → He told me that I was not to speak. = He told me not to speak.","uz":"U menga gapirmasligimni aytdi."},{"t":"p","x":"Ikki tuzilma o'rtasida farq yo'q, lekin <b>be to</b> tuzilmasi ikki holatda ko'proq ishlatiladi:"},{"t":"list","items":["1) Kirish fe'li <b>hozirgi zamonda</b> bo'lsa: <i>He says, “Meet me at the station.” → He says that we are to meet him at the station.</i>","2) Buyruqdan oldin <b>ergash gap</b> bo'lsa: <i>He said, “If you see Ann, tell her to ring me.” → He told me that if I saw Ann I was to tell her to ring him. / He told me to tell Ann to ring him if I saw her.</i>"]},{"t":"h","x":"Let's + infinitiv → suggest"},{"t":"p","x":"<b>Let's</b> taklifni bildiradi, shuning uchun o'zlashtirma gapda <b>suggest + gerund</b> yoki <b>suggest that + ega + should + infinitiv</b> ishlatiladi."},{"t":"ex","en":"He said, “Let's go there.” → He suggested going there. / He suggested that we / they should go there.","uz":"U u yerga borishni taklif qildi."},{"t":"ex","en":"He said, “Let's stop now and finish it later.” → He suggested stopping then and finishing it later. / He suggested that we should stop then and finish it later.","uz":"U hozir to'xtab, keyinroq tugatishni taklif qildi."},{"t":"p","x":"Inkorda <b>not + gerund</b> yoki <b>should not</b> ishlatiladi."},{"t":"ex","en":"He said, “Let's not sleep.” → He suggested not sleeping. / He suggested that we should not sleep.","uz":"U uxlamaslikni taklif qildi."},{"t":"h","x":"Let him / her / them → ought to / should"},{"t":"p","x":"<b>let him / her / them</b> majburiyat yoki burchni bildiradi, shuning uchun o'zlashtirma gapda <b>ought to / should</b> ishlatiladi."},{"t":"ex","en":"“It's not my business,” said the postman, “let the government do something about it.” → The postman said it wasn't his business and that the government ought to / should do something about it.","uz":"Pochtachi bu uning ishi emasligini va bu bilan hukumat shug'ullanishi kerakligini aytdi."},{"t":"h","x":"Let = allow / permit (ruxsat bermoq)"},{"t":"p","x":"<b>let</b> oddiy fe'l sifatida «ruxsat bermoq» ma'nosida kelsa, iltimosni bildiradi — shuning uchun o'zlashtirma gapda iltimos shakli ishlatiladi."},{"t":"ex","en":"“Let him come with us, Mother,” I said. → I asked my mother to let him come with us.","uz":"Men onamdan uning biz bilan kelishiga ruxsat berishini so'radim."}],"quiz":[{"q":"“Speak quietly, Tom,” she said. → She told Tom ___ quietly.","o":["speak","to speak","speaking","that speak"],"a":1,"e":"Buyruq: tell + kimga + to-infinitiv."},{"q":"“Don't go too far, boys,” she said. → She warned the boys ___ too far.","o":["don't go","to not going","not to go","not go"],"a":2,"e":"Inkor buyruq: not + to-infinitiv."},{"q":"He said, “Go away.” Which report is correct?","o":["He told to go away.","He told me to go away.","He said me to go away.","He told me go away."],"a":1,"e":"O'zlashtirma buyruqda kimga aytilgani albatta bo'lishi kerak."},{"q":"He said, “Let's go there.” → He ___.","o":["suggested to go there","suggested going there","told us go there","suggested us to go there"],"a":1,"e":"Let's taklifni bildiradi: suggest + gerund."},{"q":"He said, “Let's go there.” → He suggested that we ___ go there.","o":["should","would","must to","will"],"a":0,"e":"suggest that + ega + should + infinitiv."},{"q":"He said, “Don't speak.” → He told me that I ___ to speak.","o":["am not","was not","did not","not was"],"a":1,"e":"be to tuzilmasida not be dan keyin keladi va zamon moslashadi: was not to speak."},{"q":"“Let the government do something,” said the postman. → He said the government ___ do something.","o":["let","ought to","was let","would let"],"a":1,"e":"let him/her/them majburiyatni bildiradi: ought to / should."},{"q":"“Let him come with us, Mother,” I said. → I asked my mother ___ him come with us.","o":["to let","let","letting","that let"],"a":0,"e":"let = ruxsat bermoq bo'lsa, iltimos shakli: ask + kimdan + to let."},{"q":"He says, “Meet me at the station.” Which report is more usual?","o":["He says that we are to meet him at the station.","He says that we were to meet him at the station.","He says us meet him.","He said meet him at the station."],"a":0,"e":"Kirish fe'li hozirgi zamonda bo'lsa, be to tuzilmasi ko'proq ishlatiladi; zamon o'zgarmaydi."},{"q":"He said, “Let's not sleep.” → He suggested ___.","o":["to not sleep","not sleeping","sleeping not","don't sleep"],"a":1,"e":"Inkor taklif: not + gerund."}]},{"id":"p7-11","en":"Direct and Indirect Objects","uz":"Vositasiz va vositali to'ldiruvchilar","emoji":"🎁","level":"A2","group":"Gap va ot","summary":"Ikki to'ldiruvchili gaplarda vositali to'ldiruvchining o'rni, to va for bilan ishlatiladigan fe'llar va it/them bilan bog'liq cheklov.","blocks":[{"t":"p","x":"To'ldiruvchilar ikki xil: <b>vositasiz (direct)</b> — nimani? (the book) va <b>vositali (indirect)</b> — kimga? kim uchun? (Tom). Vositali to'ldiruvchi vositasizdan <b>oldin</b> qo'yilishi mumkin — bunda predlog (to / for) tushib qoladi."},{"t":"table","head":["Predlog bilan","Predlogsiz"],"rows":[["I gave the book to Tom.","I gave Tom the book."],["I ordered flowers for my mother.","I ordered my mother flowers."]]},{"t":"formula","x":"V + direct object + to/for + person = V + person + direct object"},{"t":"h","x":"«to» bilan keladigan fe'llar"},{"t":"p","x":"<b>bring, give, hand, leave (vasiyatda qoldirmoq), offer, pass (uzatmoq), pay, play, promise, sell, send, show, sing, take, tell</b>"},{"t":"ex","en":"I showed the map to Bill. → I showed Bill the map.","uz":"Men Billga xaritani ko'rsatdim."},{"t":"ex","en":"He sent $5 to John. → He sent John $5.","uz":"U Jonga 5 dollar yubordi."},{"t":"h","x":"«for» bilan keladigan fe'llar"},{"t":"p","x":"<b>book, build, buy, cook (bake, boil, fry va h.k.), fetch, find, get, keep, leave, make, order, reserve</b>"},{"t":"ex","en":"I bought a book for Bill. → I bought Bill a book.","uz":"Men Bill uchun kitob sotib oldim."},{"t":"ex","en":"He'll get a drink for you. → He'll get you a drink.","uz":"U sizga ichimlik olib keladi."},{"t":"h","x":"Qaysi tartib yaxshiroq?"},{"t":"list","items":["Vositasiz to'ldiruvchi <b>ibora yoki ergash gap</b> (uzun) bo'lsa — vositali to'ldiruvchini <b>oldin</b> qo'yish yaxshiroq: <i>He told me the whole story. Show me what you've got in your hand.</i>","Vositali to'ldiruvchi <b>ibora yoki ergash gap</b> bo'lsa — uni vositasizdan <b>keyin</b> (predlog bilan) qo'yish yaxshiroq: <i>We kept seats for everyone who had paid. I had to show my ID to the man at the door.</i>"]},{"t":"rule","x":"Vositasiz to'ldiruvchi <b>it / them</b> bo'lsa, vositali to'ldiruvchini undan oldin qo'yib bo'lmaydi: <b>They kept it for Mary.</b> ✅ (<i>They kept Mary it</i> ❌), <b>She made them for Bill.</b> ✅"}],"quiz":[{"q":"I gave the book to Tom. = I gave ___.","o":["to Tom the book","Tom the book","the book Tom","Tom to the book"],"a":1,"e":"Vositali to'ldiruvchi oldin kelsa, to tushib qoladi."},{"q":"Complete: I bought a book ___ Bill.","o":["to","for","at","with"],"a":1,"e":"buy fe'li for bilan ishlatiladi."},{"q":"Complete: He sent $5 ___ John.","o":["for","to","at","by"],"a":1,"e":"send fe'li to bilan ishlatiladi."},{"q":"Choose the correct sentence.","o":["They kept Mary it.","They kept it for Mary.","They kept for Mary it.","They kept it Mary."],"a":1,"e":"Vositasiz to'ldiruvchi it/them bo'lsa, vositali to'ldiruvchi undan oldin kelmaydi."},{"q":"Which verb uses \"for\" (not \"to\")?","o":["give","show","cook","sell"],"a":2,"e":"cook (bake, fry...) for bilan keladi."},{"q":"Which verb uses \"to\" (not \"for\")?","o":["buy","reserve","promise","fetch"],"a":2,"e":"promise to bilan keladi: promise something to someone."},{"q":"Choose the better sentence.","o":["We kept everyone who had paid seats.","We kept seats for everyone who had paid.","We kept for everyone seats who had paid.","We kept seats everyone who had paid."],"a":1,"e":"Vositali to'ldiruvchi uzun (ergash gapli) bo'lsa, u vositasizdan keyin keladi."},{"q":"Choose the better sentence.","o":["Show what you've got in your hand to me.","Show me what you've got in your hand.","Show to me what you've got in your hand me.","Show what me you've got in your hand."],"a":1,"e":"Vositasiz to'ldiruvchi ergash gap bo'lsa, vositali to'ldiruvchi oldin qo'yiladi."},{"q":"He'll get a drink for you. = He'll get ___.","o":["for you a drink","you a drink","a drink you","to you a drink"],"a":1,"e":"for tushib qoladi: get you a drink."}]},{"id":"p7-12","en":"Transitive and Intransitive Verbs: rise/raise, lie/lay, sit/set","uz":"O'timli va o'timsiz fe'llar: rise/raise, lie/lay, sit/set","emoji":"↕️","level":"B1","group":"Fe'l va zamonlar","summary":"O'timli va o'timsiz fe'llar farqi hamda ko'p adashtiriladigan rise–raise, lie–lay va sit–set juftliklari.","blocks":[{"t":"p","x":"Fe'llar ikki xil bo'ladi:"},{"t":"list","items":["1) <b>Transitive</b> (o'timli) — o'zidan keyin to'ldiruvchi (complement) oladi.","2) <b>Intransitive</b> (o'timsiz) — o'zidan keyin to'ldiruvchi olmaydi."]},{"t":"table","head":["O'timsiz (to'ldiruvchisiz)","O'timli (to'ldiruvchi bilan)"],"rows":[["rise – rose – risen","raise – raised – raised"],["lie – lay – lain","lay – laid – laid"],["sit – sat – sat","set – set – set"]]},{"t":"ex","en":"The sun rises in the east.","uz":"Quyosh sharqdan chiqadi."},{"t":"ex","en":"The students raised their hands.","uz":"O'quvchilar qo'llarini ko'tarishdi."},{"t":"h","x":"Raise va rise"},{"t":"p","x":"<b>raise</b> — biror narsani ko'tarmoq yoki oshirmoq. Undan keyin albatta to'ldiruvchi bo'ladi."},{"t":"ex","en":"The weightlifter raises the barbell over his head.","uz":"Og'ir atlet shtangani boshidan yuqori ko'taradi."},{"t":"ex","en":"John raised his grades substantially.","uz":"Jon baholarini ancha oshirdi."},{"t":"p","x":"<b>rise</b> — turmoq, o'z kuchi bilan ko'tarilmoq, oshmoq. Undan keyin to'ldiruvchi kelmaydi."},{"t":"ex","en":"When the bell rings, the students rise from their seats.","uz":"Qo'ng'iroq chalinganda o'quvchilar o'rinlaridan turishadi."},{"t":"ex","en":"John rose early so that he could play tennis.","uz":"Jon tennis o'ynash uchun erta turdi."},{"t":"ex","en":"Prices have risen more than 10 percent.","uz":"Narxlar 10 foizdan ko'proq oshdi."},{"t":"h","x":"Lay va lie"},{"t":"p","x":"<b>lay – laid – laid</b> — biror narsa yoki kishini biror sirtga qo'ymoq, yotqizmoq. Undan keyin to'ldiruvchi bo'lishi shart."},{"t":"ex","en":"Don't lay your clothes on the bed.","uz":"Kiyimlaringni karavotga qo'yma."},{"t":"ex","en":"She laid her baby in the crib.","uz":"U chaqalog'ini beshikka yotqizdi."},{"t":"p","x":"<b>lie – lay – lain</b> — yotmoq, dam olmoq yoki biror joyda joylashmoq. Ko'pincha <b>down</b> bilan ishlatiladi."},{"t":"ex","en":"The university lies in the western section of town.","uz":"Universitet shaharning g'arbiy qismida joylashgan."},{"t":"ex","en":"If the children are tired, they should lie down for a nap.","uz":"Bolalar charchagan bo'lsa, biroz uxlab olish uchun yotishlari kerak."},{"t":"ex","en":"Don't disturb Mary; she has lain down for a rest.","uz":"Meriyani bezovta qilma, u dam olish uchun yotgan."},{"t":"rule","x":"Diqqat: <b>lie – lay – lain</b> (yotmoq) ni <b>lie – lied – lied</b> (yolg'on gapirmoq) bilan adashtirmang!"},{"t":"h","x":"Set va sit"},{"t":"p","x":"<b>set</b> — biror narsa yoki kishini biror sirtga yoki joyga qo'ymoq. U <b>lay</b> va <b>put</b> bilan almashinishi mumkin. Istisno: <b>set the table</b> = dasturxon tuzamoq."},{"t":"ex","en":"The carpenters set their tools in the box.","uz":"Duradgorlar asboblarini qutiga qo'yishdi."},{"t":"ex","en":"The mother set the baby in the cradle.","uz":"Ona chaqaloqni beshikka qo'ydi."},{"t":"ex","en":"The little girl helps her father set the table.","uz":"Qizcha otasiga dasturxon tuzashga yordam beradi."},{"t":"p","x":"<b>sit</b> — o'tirmoq; undan keyin to'ldiruvchi ishlatilmaydi."},{"t":"ex","en":"We're going to sit in the fifth row.","uz":"Biz beshinchi qatorda o'tiramiz."}],"quiz":[{"q":"The sun ___ in the east.","o":["raises","rises","lays","sets up"],"a":1,"e":"rise o'timsiz — to'ldiruvchi olmaydi."},{"q":"The students ___ their hands.","o":["rose","raised","risen","lay"],"a":1,"e":"raise o'timli — to'ldiruvchi (their hands) oladi."},{"q":"Don't ___ your clothes on the bed.","o":["lie","lay","lain","lied"],"a":1,"e":"lay — biror narsani qo'ymoq; to'ldiruvchi talab qiladi."},{"q":"If you are tired, you should ___ down.","o":["lay","lie","laid","raise"],"a":1,"e":"lie (down) — yotmoq, o'timsiz."},{"q":"What is the past participle of \"lie\" (to rest)?","o":["lied","laid","lain","lay"],"a":2,"e":"lie – lay – lain; lied esa «yolg'on gapirmoq» ma'nosidagi lie dan."},{"q":"Prices have ___ more than 10 percent.","o":["raised","risen","rose","raise"],"a":1,"e":"rise – rose – risen; to'ldiruvchi yo'q, shuning uchun risen."},{"q":"She ___ her baby in the crib yesterday.","o":["lay","laid","lied","lain"],"a":1,"e":"lay ning o'tgan zamon shakli — laid."},{"q":"\"Set the table\" means:","o":["to sit at the table","to prepare the table for a meal","to buy a table","to lie on the table"],"a":1,"e":"set the table — dasturxon tuzamoq."},{"q":"We're going to ___ in the fifth row.","o":["set","sit","seat","lay"],"a":1,"e":"sit — o'tirmoq, o'timsiz."},{"q":"The university ___ in the western section of town.","o":["lays","lies","laid","raises"],"a":1,"e":"lie — joylashmoq ma'nosida, o'timsiz."}]},{"id":"p7-13","en":"Passive Voice: Special Points","uz":"Majhul nisbat: alohida holatlar","emoji":"🔁","level":"B2","group":"Majhul nisbat va modal fe'llar","summary":"get bilan majhul nisbat, majhul so'roq gaplar, by va with, predlogli fe'llar, ikki to'ldiruvchili gaplar, It is said / He is said to be va be supposed to.","blocks":[{"t":"h","x":"Be o'rniga get"},{"t":"p","x":"Majhul nisbatda <b>be</b> o'rniga <b>get</b> ishlatish mumkin. <b>get</b> — norasmiy, <b>be</b> — rasmiy."},{"t":"ex","en":"The eggs got sold. / The eggs were sold.","uz":"Tuxumlar sotildi."},{"t":"h","x":"Majhul so'roq gaplar"},{"t":"p","x":"Faol (aniq) nisbatdagi <b>to'ldiruvchi haqidagi so'roq</b> majhul nisbatda <b>ega haqidagi so'roq</b>ga aylanadi (yordamchi did kerak bo'lmaydi)."},{"t":"ex","en":"They stole a car. → What did they steal? → What was stolen?","uz":"Nima o'g'irlandi?"},{"t":"p","x":"Faol nisbatdagi <b>ega haqidagi so'roq</b> majhul nisbatda <b>to'ldiruvchi turidagi so'roq</b>ga aylanadi va oxirida albatta <b>by</b> bo'ladi."},{"t":"ex","en":"Who stole the car? → Who was the car stolen by?","uz":"Mashina kim tomonidan o'g'irlandi?"},{"t":"h","x":"By va with"},{"t":"p","x":"Harakat bajaruvchisi odatda <b>by</b> bilan ko'rsatiladi. Agar bajaruvchi <b>jonsiz narsa</b> (modda, material, vosita) bo'lsa, <b>with</b> ishlatiladi."},{"t":"table","head":["Faol nisbat","Majhul nisbat"],"rows":[["Daniel painted this picture.","This picture was painted by Daniel."],["Smoke filled the room.","The room was filled with smoke."],["Paint covered the lock.","The lock was covered with paint."]]},{"t":"h","x":"Fe'l + predlog + to'ldiruvchi"},{"t":"p","x":"Fe'l + predlog + to'ldiruvchi majhul nisbatga o'tganda predlog <b>fe'ldan darhol keyin</b> qoladi."},{"t":"ex","en":"You must write to him. → He must be written to.","uz":"Unga xat yozish kerak."},{"t":"h","x":"Ikki to'ldiruvchili gaplar"},{"t":"p","x":"Faol gapda ikkita to'ldiruvchi bo'lsa, ikki xil majhul gap tuzish mumkin."},{"t":"ex","en":"I offered Ann some flowers. → Ann was offered some flowers. / Some flowers were offered to Ann.","uz":"Annaga gullar taklif qilindi."},{"t":"rule","x":"Majhul gapda egani <b>jonli</b> to'ldiruvchidan (shaxsdan) qilish yaxshiroq: <b>Ann was offered some flowers.</b>"},{"t":"h","x":"People say that... → It is said / He is said to..."},{"t":"p","x":"«People say that he is rich» turidagi gaplarning ikki xil majhul shakli bor:"},{"t":"formula","x":"It is said that + clause<br>Subject + is said + to-infinitive"},{"t":"ex","en":"It is said that he is rich. / He is said to be rich.","uz":"Aytishlaricha, u boy."},{"t":"p","x":"Bu tuzilmalar quyidagi fe'llar bilan ishlatiladi: <b>acknowledge, allege, assume, believe, claim, consider, estimate, feel, find, know, presume, report, say, think, understand</b>."},{"t":"ex","en":"People believe that he eats ten eggs a day. → It is believed that he eats ten eggs a day. / He is believed to eat ten eggs a day.","uz":"Uning kuniga o'nta tuxum yeyishiga ishonishadi."},{"t":"h","x":"Be supposed to"},{"t":"list","items":["<b>be supposed to</b> = <b>be said to</b> (aytishlaricha): <i>People suppose that it's delicious. → It's supposed to be delicious.</i>","<b>be supposed to</b> = <b>be expected to</b> (kutiladi, lozim): <i>People suppose that you know how to drive. → You're supposed to know how to drive.</i>","<b>be not supposed to</b> = <b>be not allowed to</b> (mumkin emas): <i>You're not supposed to walk on the grass.</i>"]},{"t":"ex","en":"You're not supposed to walk on the grass.","uz":"Maysa ustida yurish mumkin emas."}],"quiz":[{"q":"Which is informal?","o":["The eggs were sold.","The eggs got sold.","The eggs are being sold.","The eggs had been sold."],"a":1,"e":"get bilan majhul nisbat norasmiy, be bilan — rasmiy."},{"q":"Active: What did they steal? → Passive:","o":["What was stolen?","What did be stolen?","What was they stolen?","What did stolen?"],"a":0,"e":"To'ldiruvchi haqidagi so'roq majhulda ega haqidagi so'roqqa aylanadi: What was stolen?"},{"q":"Active: Who stole the car? → Passive:","o":["Who was the car stolen?","Who was the car stolen by?","By who stole the car?","Who did the car stolen by?"],"a":1,"e":"Ega haqidagi so'roq majhulda by bilan tugaydi."},{"q":"The room was filled ___ smoke.","o":["by","with","of","from"],"a":1,"e":"Bajaruvchi jonsiz narsa (modda) bo'lsa, with ishlatiladi."},{"q":"You must write to him. → He must ___.","o":["be written","be written to","written to be","be to written"],"a":1,"e":"Predlog majhul nisbatda fe'ldan darhol keyin qoladi."},{"q":"I offered Ann some flowers. Which passive is preferred?","o":["Ann was offered some flowers.","Some flowers were offered Ann by.","Ann offered some flowers.","Flowers was offered to Ann."],"a":0,"e":"Majhul gapda egani jonli to'ldiruvchidan qilish yaxshiroq."},{"q":"People say that he is rich. → He is said ___ rich.","o":["be","to be","being","that he is"],"a":1,"e":"Subject + is said + to-infinitive."},{"q":"\"You're not supposed to walk on the grass\" means:","o":["You are expected to walk on the grass.","You are not allowed to walk on the grass.","People say you walk on the grass.","You will walk on the grass."],"a":1,"e":"be not supposed to = be not allowed to."},{"q":"People believe that he eats ten eggs a day. → It ___ that he eats ten eggs a day.","o":["believes","is believed","was believing","believed"],"a":1,"e":"It is + V3 + that... tuzilmasi."},{"q":"\"You're supposed to know how to drive\" means:","o":["You are expected to know how to drive.","You are not allowed to drive.","People say you can't drive.","You want to drive."],"a":0,"e":"Bu yerda be supposed to = be expected to."}]},{"id":"p8-01","en":"See Somebody Do / See Somebody Doing","uz":"See somebody do va see somebody doing","emoji":"👀","level":"B1","group":"Infinitiv, gerund va ergash gaplar","summary":"Sezgi fe'llari (see, hear, watch, feel, notice) dan keyin to'liq harakat uchun «to»siz infinitiv, jarayon uchun -ing shakli ishlatiladi.","blocks":[{"t":"h","x":"See + kimdir + bare infinitive (to'liq harakat)"},{"t":"p","x":"Agar biz harakatni <b>boshidan oxirigacha to'liq</b> ko'rgan bo'lsak, <i>see somebody</i> dan keyin <b>to</b>siz infinitiv (bare infinitive) ishlatiladi."},{"t":"ex","en":"Tom got into his car and drove away. I saw this. → I saw Tom get into his car and drive away.","uz":"Tom mashinasiga o'tirib, haydab ketganini ko'rdim."},{"t":"ex","en":"Ann watched TV. I saw this. → I saw Ann watch TV.","uz":"Annaning televizor ko'rganini ko'rdim."},{"t":"rule","x":"Diqqat: majhul (passiv) gapda esa <b>to</b> li to'liq infinitiv ishlatiladi."},{"t":"ex","en":"Ann went out. I saw this. → I saw Ann go out. → Ann was seen to go out.","uz":"Annaning chiqib ketgani ko'rildi."},{"t":"h","x":"See + kimdir + -ing (jarayon)"},{"t":"p","x":"Agar kimnidir harakatning <b>o'rtasida</b>, ya'ni u biror ishni qilayotgan paytda ko'rgan bo'lsak va harakatni to'liq ko'rmagan bo'lsak, <b>-ing</b> shakli (gerund/sifatdosh) ishlatiladi."},{"t":"formula","x":"Somebody was doing something + I saw this → I saw somebody doing something"},{"t":"ex","en":"I saw Ann. She was waiting for a bus. → I saw Ann waiting for a bus.","uz":"Annani avtobus kutib turganida ko'rdim."},{"t":"ex","en":"He was walking along the street. I saw this when I drove past him. → I saw him walking along the street.","uz":"Uni ko'chada ketayotganida ko'rdim."},{"t":"h","x":"Boshqa sezgi fe'llari"},{"t":"p","x":"<b>see</b> o'rniga <b>hear, watch, listen to, feel, notice</b> fe'llarini ham xuddi shu qoida bilan ishlatish mumkin."},{"t":"ex","en":"I didn't hear you come in.","uz":"Kirib kelganingizni eshitmadim."},{"t":"ex","en":"I felt somebody touch me.","uz":"Kimdir menga tegib ketganini sezdim."},{"t":"ex","en":"I heard it raining.","uz":"Yomg'ir yog'ayotganini eshitdim."},{"t":"rule","x":"<b>smell</b> va <b>find</b> fe'llaridan keyin faqat <b>-ing</b> shakli ishlatiladi."},{"t":"ex","en":"Can you smell something burning?","uz":"Nimadir kuyayotganini hidlayapsanmi?"},{"t":"ex","en":"She found him reading her letters.","uz":"U uni o'z xatlarini o'qiyotgan holda topdi."}],"quiz":[{"q":"I saw Tom ___ into his car and drive away. (whole action)","o":["got","get","to get","gets"],"a":1,"e":"Harakat to'liq ko'rilgan — to'siz infinitiv: get."},{"q":"I saw Ann ___ for a bus. (she was in the middle of it)","o":["wait","to wait","waiting","waited"],"a":2,"e":"Harakat jarayonda ko'rilgan — -ing shakli."},{"q":"Ann was seen ___ out.","o":["go","going","to go","went"],"a":2,"e":"Majhul gapda to'liq infinitiv (to go) ishlatiladi."},{"q":"Can you smell something ___?","o":["burn","to burn","burning","burnt"],"a":2,"e":"smell dan keyin faqat -ing shakli."},{"q":"She found him ___ her letters.","o":["read","to read","reading","reads"],"a":2,"e":"find dan keyin faqat -ing shakli."},{"q":"I didn't hear you ___ in.","o":["come","to come","came","comes"],"a":0,"e":"hear + obyekt + to'siz infinitiv."},{"q":"Which verb can NOT be followed by object + bare infinitive?","o":["hear","feel","notice","smell"],"a":3,"e":"smell faqat -ing shakli bilan ishlatiladi."},{"q":"I felt somebody ___ me.","o":["to touch","touch","touched","touches"],"a":1,"e":"feel + obyekt + to'siz infinitiv."},{"q":"He was heard ___ the song.","o":["sing","to sing","sang","sung"],"a":1,"e":"Sezgi fe'li majhul nisbatda bo'lsa, to li infinitiv keladi."}]},{"id":"p8-02","en":"The Infinitive: Forms and Verb + Infinitive","uz":"Infinitiv: shakllari va fe'l + infinitiv","emoji":"🔤","level":"B1","group":"Infinitiv, gerund va ergash gaplar","summary":"Infinitivning olti shakli, uning ega va to'ldiruvchi vazifasida kelishi, infinitiv oladigan fe'llar va «fe'l + so'roq so'zi + infinitiv» qurilmasi.","blocks":[{"t":"h","x":"Infinitivning olti shakli"},{"t":"table","head":["Shakl","Misol"],"rows":[["Present infinitive (oddiy)","to work, to do"],["Present continuous infinitive (davomli)","to be working, to be doing"],["Perfect infinitive (tugallangan)","to have worked, to have done"],["Perfect continuous infinitive","to have been working, to have been doing"],["Present infinitive passive (majhul)","to be done"],["Perfect infinitive passive","to have been done"]]},{"t":"h","x":"Infinitiv ega vazifasida"},{"t":"p","x":"Infinitiv <b>appear, be, seem</b> fe'llari bilan kelgan gapda ega bo'lishi mumkin."},{"t":"ex","en":"To compromise appears advisable.","uz":"Murosaga kelish maqsadga muvofiq ko'rinadi."},{"t":"ex","en":"To save money now seems impossible.","uz":"Hozir pul tejash imkonsiz tuyuladi."},{"t":"p","x":"Lekin ko'proq gap boshiga <b>it</b> qo'yilib, infinitiv gap oxiriga ko'chiriladi."},{"t":"ex","en":"It appears advisable to compromise.","uz":"Murosaga kelish maqsadga muvofiq ko'rinadi."},{"t":"ex","en":"It now seems impossible to save money.","uz":"Hozir pul tejash imkonsiz ko'rinadi."},{"t":"p","x":"<b>it</b> qurilmasida bog'lovchi fe'ldan keyin odatda sifat keladi, ammo ba'zan sifat o'rniga <b>ot</b> ham kelishi mumkin."},{"t":"ex","en":"It would be a crime / a mistake to cut down any more trees.","uz":"Yana daraxt kesish jinoyat / xato bo'lardi."},{"t":"ex","en":"It would be an offence to drop litter in the street.","uz":"Ko'chaga axlat tashlash huquqbuzarlik bo'lardi."},{"t":"p","x":"Bog'lovchi fe'l o'rnida <b>cost / take + obyekt</b> ham kelishi mumkin."},{"t":"ex","en":"It would cost millions / take years to rebuild this castle.","uz":"Bu qal'ani qayta qurish millionlarga tushardi / yillar olardi."},{"t":"p","x":"Perfect infinitiv ham ega bo'la oladi."},{"t":"ex","en":"To have made the same mistake twice was unforgivable.","uz":"Bir xil xatoni ikki marta qilganlik kechirib bo'lmas edi."},{"t":"h","x":"Infinitiv to'ldiruvchi vazifasida"},{"t":"ex","en":"I agreed to pay. / She refused to come.","uz":"Men to'lashga rozi bo'ldim. / U kelishdan bosh tortdi."},{"t":"p","x":"Bevosita infinitiv oladigan fe'llar (yulduzchalar keyingi qoidalar uchun):"},{"t":"list","items":["<b>** (ikki yulduzli):</b> agree, arrange, ask, claim, decide, demand, determine, be determined, resolve","<b>* (bir yulduzli):</b> appear, forget, guarantee, happen, learn, pretend, promise, prove, remember, seem, swear, threaten","<b>Yulduzsiz:</b> aim, attempt, bother, care, choose, condescend, consent, decline, endeavour, fail, hesitate, hope, long, manage, neglect, offer, plan, prepare, be prepared, proceed, refuse, tend, trouble, pray, undertake, volunteer, vow"]},{"t":"p","x":"Infinitiv oladigan iboralar: <b>make up one's mind*, turn out*</b>, <b>be about, can afford, do one's best, do what one can, make every effort, it occurs to + obyekt, set out, take the trouble</b>."},{"t":"ex","en":"He is just about to leave.","uz":"U endi ketmoqchi bo'lib turibdi."},{"t":"ex","en":"We can't afford to live in the centre.","uz":"Biz markazda yashashga qurbimiz yetmaydi."},{"t":"ex","en":"He managed to put out the fire.","uz":"U olovni o'chirishga muvaffaq bo'ldi."},{"t":"h","x":"that + ergash gap bilan almashtirish"},{"t":"p","x":"Bir yulduzli (*) fe'llar va iboralar <b>that + ergash gap</b> bilan ham ishlatilishi mumkin."},{"t":"ex","en":"I promise to wait. = I promise that I'll wait.","uz":"Kutishga va'da beraman."},{"t":"rule","x":"<b>appear, happen, seem, turn out</b> that qurilmasi bilan ishlatilganda, gap boshida kirish so'zi <b>it</b> bo'lishi shart."},{"t":"ex","en":"His mansion turned out to be an enormous bungalow. = It turned out that his mansion was an enormous bungalow.","uz":"Uning saroyi katta bir qavatli uy bo'lib chiqdi."},{"t":"p","x":"Ikki yulduzli (**) fe'llar <b>that ... should</b> qurilmasi bilan ishlatilishi mumkin, ayniqsa majhul nisbatda."},{"t":"ex","en":"They decided to divide the profit equally. = They decided that the profit should be divided equally.","uz":"Ular foydani teng bo'lishga qaror qilishdi."},{"t":"h","x":"Davomli infinitiv"},{"t":"p","x":"Davomli infinitiv ko'pincha <b>appear, happen, pretend, seem</b> dan keyin ishlatiladi. Uni <b>agree, arrange, decide, determine, hope, manage, plan</b> dan keyin ham qo'llash mumkin."},{"t":"ex","en":"I happened to be looking out of the window when they arrived.","uz":"Ular kelganida tasodifan derazadan qarab turgan edim."},{"t":"ex","en":"He seems to be following us.","uz":"U bizni kuzatib kelayotganga o'xshaydi."},{"t":"h","x":"Fe'l + how / what / when / where / which / why + infinitiv"},{"t":"p","x":"Bu qurilma quyidagi fe'llardan keyin keladi: <b>ask, decide, discover, find out, forget, know, learn, remember, see, show + obyekt, think, understand, want to know, wonder</b>."},{"t":"ex","en":"He discovered how to open the safe.","uz":"U seyfni qanday ochishni aniqladi."},{"t":"ex","en":"She found out where to buy fruit cheaply.","uz":"U mevani qayerdan arzon olishni bilib oldi."},{"t":"p","x":"<b>whether + infinitiv</b> <i>want to know</i> va <i>wonder</i> dan keyin ishlatiladi."},{"t":"ex","en":"He wondered whether to write or phone.","uz":"U xat yozsamikan yoki qo'ng'iroq qilsamikan deb o'yladi."},{"t":"rule","x":"<b>know, decide, think, remember</b> dan keyin <b>whether + infinitiv</b> faqat inkor va so'roq gaplarda ishlatiladi."},{"t":"ex","en":"He needn't decide yet whether to study science or arts.","uz":"U hali aniq fanlarni yoki gumanitar fanlarni o'qishni hal qilishi shart emas."},{"t":"p","x":"<b>ask, decide, forget, learn, remember</b> bevosita infinitiv bilan ham kelishi mumkin, lekin ma'no o'zgaradi. <b>learn how</b> = ko'nikma egallamoq."},{"t":"ex","en":"She learned how to drive.","uz":"U mashina haydashni o'rgandi (ko'nikma)."},{"t":"ex","en":"She learned to trust nobody.","uz":"U hech kimga ishonmaslikka o'rgandi (xulq)."}],"quiz":[{"q":"Which is the perfect continuous infinitive of 'work'?","o":["to be working","to have worked","to have been working","to be worked"],"a":2,"e":"Perfect continuous infinitiv: to have been + V-ing."},{"q":"It would ___ years to rebuild this castle.","o":["make","take","do","have"],"a":1,"e":"Bog'lovchi fe'l o'rnida take/cost + obyekt ishlatiladi."},{"q":"He managed ___ out the fire.","o":["put","putting","to put","to putting"],"a":2,"e":"manage dan keyin infinitiv keladi."},{"q":"Which sentence is correct?","o":["His mansion turned out that it was a bungalow.","It turned out that his mansion was a bungalow.","Turned out that his mansion was a bungalow.","His mansion turned out be a bungalow."],"a":1,"e":"turn out + that qurilmasida kirish so'zi it majburiy."},{"q":"They decided that the profit ___ divided equally.","o":["should be","should","be to","to be"],"a":0,"e":"Ikki yulduzli fe'llar that ... should qurilmasini oladi, ko'pincha majhulda."},{"q":"He seems ___ us.","o":["to follow be","be following","to be following","following to"],"a":2,"e":"seem dan keyin davomli infinitiv: to be + V-ing."},{"q":"He wondered ___ to write or phone.","o":["that","whether","if","what"],"a":1,"e":"wonder dan keyin whether + infinitiv ishlatiladi; if + infinitiv bo'lmaydi."},{"q":"She learned ___ to drive. (acquired a skill)","o":["how","what","whether","that"],"a":0,"e":"learn how = ko'nikma egallash."},{"q":"We can't afford ___ in the centre.","o":["living","to live","live","lived"],"a":1,"e":"can afford iborasidan keyin infinitiv keladi."},{"q":"___ appears advisable to compromise.","o":["This","It","There","That"],"a":1,"e":"Infinitiv gap oxiriga ko'chganda gap boshida it qo'yiladi."}]},{"id":"p8-03","en":"Verb + Object + Infinitive and the Bare Infinitive","uz":"Fe'l + obyekt + infinitiv va «to»siz infinitiv","emoji":"🎯","level":"B2","group":"Infinitiv, gerund va ergash gaplar","summary":"Obyekt va infinitiv oladigan fe'llar, ask/beg/tell/teach farqlari hamda «to»siz infinitiv qo'llanadigan barcha holatlar.","blocks":[{"t":"h","x":"Fe'l + obyekt + infinitiv"},{"t":"p","x":"Quyidagi fe'llardan keyin obyekt va infinitiv keladi ((b) belgisi = to'siz infinitiv):"},{"t":"list","items":["advise, allow, bribe, command, compel, enable, encourage, entitle, <b>feel (b)</b>, forbid, force, <b>hear (b)</b>, implore, induce, instruct, invite, <b>let (b)</b>, <b>make (b)</b>, oblige, order, permit, persuade, remind, request, <b>see (b)</b>, show how, teach / teach how, tell / tell how, tempt, train, urge, warn, <b>watch (b)</b>"]},{"t":"ex","en":"These glasses will enable you to see in the dark.","uz":"Bu ko'zoynak sizga qorong'ida ko'rish imkonini beradi."},{"t":"ex","en":"She encouraged me to try again.","uz":"U meni yana urinib ko'rishga undadi."},{"t":"rule","x":"<b>show</b> infinitiv bilan kelsa, <b>how</b> talab qiladi: He showed me how to change a fuse."},{"t":"table","head":["Qurilma","Ma'nosi"],"rows":[["tell + how + infinitiv","yo'l-yo'riq bermoq (instruct)"],["tell + obyekt + infinitiv","buyurmoq (order)"],["tell + that","xabar bermoq (inform)"],["teach how","o'rgatmoq (instruct)"],["teach + obyekt + infinitiv","kimnidir ma'lum tarzda o'zini tutishga o'rgatmoq"]]},{"t":"ex","en":"He told me how to replace a fuse.","uz":"U menga saqlagichni qanday almashtirishni tushuntirdi."},{"t":"ex","en":"He taught me how to swim.","uz":"U menga suzishni o'rgatdi."},{"t":"ex","en":"I taught him to obey all the commands without asking questions.","uz":"Men uni barcha buyruqlarni savolsiz bajarishga o'rgatdim."},{"t":"p","x":"<b>remind, show, teach, tell</b> dan keyin <b>that</b> ham kelishi mumkin."},{"t":"ex","en":"He reminded me that the road was dangerous.","uz":"U menga yo'l xavfli ekanini eslatdi."},{"t":"ex","en":"I told him to go. (order) / I told him that he was late. (inform)","uz":"Unga ketishni buyurdim. / Unga kechikkanini aytdim."},{"t":"h","x":"Ikkala qurilmada keladigan fe'llar"},{"t":"p","x":"Quyidagilar ham <i>fe'l + infinitiv</i>, ham <i>fe'l + obyekt + infinitiv</i> bilan keladi: <b>ask, beg, would hate, help, intend, like, would like, would love, mean, prefer, want, wish</b>."},{"t":"ex","en":"I want to drive. / I want you to drive.","uz":"Men haydamoqchiman. / Sizning haydashingizni xohlayman."},{"t":"table","head":["Gap","Ma'nosi"],"rows":[["I asked to speak to Mr. James.","I said, 'Can I speak to Mr. James?'"],["I asked Bill to speak to Mr. James.","I said, 'Bill, can you speak to Mr. James?'"],["I begged to go.","I said, 'Please let me go.'"],["I begged him to go.","I said, 'Please go.'"]]},{"t":"h","x":"Obyekt + to be"},{"t":"p","x":"<b>assume, believe, consider, feel, know, suppose, understand</b> dan keyin <b>obyekt + to be</b> kelishi mumkin, lekin bu kamroq ishlatiladi — odatda that qurilmasi afzal. Majhul gaplarda esa <b>to be</b> qurilmasi ko'proq ishlatiladi."},{"t":"ex","en":"I consider him to be the best student. = I consider that he is the best student.","uz":"Men uni eng yaxshi talaba deb hisoblayman."},{"t":"ex","en":"He is considered to be the best student.","uz":"U eng yaxshi talaba hisoblanadi."},{"t":"h","x":"«To»siz infinitiv (bare infinitive)"},{"t":"list","items":["<b>can, do, may, must, shall, will</b> dan keyin: They can swim. We may win. I do believe.","<b>needn't</b> dan keyin to'siz, <b>need</b> dan keyin to'liq: I needn't go (= I don't need to go). I need to go.","<b>dare</b> dan keyin to'siz; do/did/will/would bilan kelsa to qo'shilishi mumkin: I dared go. I dare not go. I didn't dare (to) go. I wouldn't dare (to) go.","<b>feel, hear, see, watch</b> dan keyin to'siz: I saw him drive off. I heard Tom cry. Majhulda to'liq: He was seen to drive off.","<b>let</b> faol va majhulda ham to'siz: They let me go. I was let go.","<b>make</b> faolda to'siz: He made me move my car. Majhulda to'liq: I was made to move my car.","<b>would rather, would sooner, rather than, sooner than</b> dan keyin to'siz: I would rather wait till Friday.","<b>had better</b> dan keyin to'siz: You had better go.","<b>help</b> dan keyin to'liq yoki to'siz: He helped us (to) carry the luggage."]},{"t":"p","x":"make dan keyingi infinitiv takrorlanmaslik uchun tushirib qoldirilishi mumkin: <i>Why did you tell? — He made me.</i>"},{"t":"rule","x":"Ikki infinitiv <b>and</b> bilan bog'lansa, ikkinchisining <b>to</b> si odatda tushib qoladi: I want to sit in the garden and write some letters."},{"t":"rule","x":"<b>but</b> va <b>except</b> <i>do + anything / nothing / everything</i> dan keyin to'siz infinitiv oladi: He does nothing but complain. My dog does everything except speak."},{"t":"h","x":"Infinitivni faqat «to» bilan ifodalash"},{"t":"p","x":"Takrorlanmaslik uchun infinitiv o'rniga faqat <b>to</b> qoldiriladi. Bu asosan <b>hate, hope, would like, would love, make (majhul), mean, plan, try, want</b> fe'llari va <b>have, need, ought, used to, be able to, be going to</b> dan keyin bo'ladi."},{"t":"ex","en":"Would you like to come with me? — Yes, I would love to.","uz":"Men bilan borasizmi? — Ha, jon deb."},{"t":"ex","en":"Did you get a ticket? — I tried to, but I was late.","uz":"Chipta oldingizmi? — Urindim, lekin kechikdim."},{"t":"h","x":"Bo'lingan infinitiv (split infinitive)"},{"t":"p","x":"So'zlashuvda <b>really</b> ko'pincha <b>to</b> va fe'l orasiga qo'yiladi. Uning o'rnida <b>completely, entirely, duly, unduly</b> ham kelishi mumkin."},{"t":"ex","en":"It would take ages to really master the job.","uz":"Bu ishni chinakam egallash uchun ancha vaqt kerak."},{"t":"ex","en":"It would take ages to completely finish the job. = ...to finish the job completely.","uz":"Ishni butunlay tugatish uchun ko'p vaqt ketadi."}],"quiz":[{"q":"He made me ___ my car.","o":["to move","move","moving","moved"],"a":1,"e":"make faol nisbatda to'siz infinitiv oladi."},{"q":"I was made ___ my car.","o":["move","to move","moving","moved"],"a":1,"e":"make majhulda to'liq infinitiv oladi."},{"q":"They let me go. Passive:","o":["I was let to go.","I was let go.","I was let going.","I let go."],"a":1,"e":"let faol va majhulda ham to'siz infinitiv oladi."},{"q":"He showed me ___ change a fuse.","o":["to","how to","that","for"],"a":1,"e":"show infinitiv bilan how talab qiladi."},{"q":"'I told him to go' means:","o":["I informed him","I ordered him","I asked his permission","I taught him"],"a":1,"e":"tell + obyekt + infinitiv = buyurmoq."},{"q":"I asked Bill to speak to Mr. James. This means:","o":["I wanted to speak to Mr. James myself","I wanted Bill to speak to Mr. James","Bill asked me","Mr. James asked Bill"],"a":1,"e":"ask + obyekt + infinitiv — boshqa odamdan iltimos."},{"q":"You needn't ___ now.","o":["to go","go","going","gone"],"a":1,"e":"needn't dan keyin to'siz infinitiv."},{"q":"He does nothing but ___.","o":["to complain","complaining","complain","complains"],"a":2,"e":"do nothing but dan keyin to'siz infinitiv."},{"q":"He is considered ___ the best student.","o":["be","being","to be","that he is"],"a":2,"e":"Majhul gaplarda to be qurilmasi odatiy."},{"q":"Would you like to come? — Yes, I'd love ___.","o":["it","to","so","that"],"a":1,"e":"Takrorlanmaslik uchun infinitiv faqat to bilan ifodalanadi."}]},{"id":"p8-04","en":"Infinitive after Nouns, Too / Enough and Perfect Infinitive","uz":"Otdan keyingi infinitiv, too / enough va perfect infinitiv","emoji":"📏","level":"B2","group":"Infinitiv, gerund va ergash gaplar","summary":"Infinitiv oladigan otlar, too / enough / so ... as qurilmalari, kirish iboralari va perfect infinitivning ma'nolari.","blocks":[{"t":"h","x":"Ot + infinitiv"},{"t":"p","x":"Quyidagi otlardan keyin bevosita infinitiv kelishi mumkin: <b>ability, ambition, anxiety, attempt, decision, demand, desire, determination, eagerness, effort, failure, offer, plan, promise, refusal, request, scheme, willingness, wish</b>."},{"t":"ex","en":"His ability to get on with people is his asset.","uz":"Odamlar bilan til topisha olishi — uning boyligi."},{"t":"ex","en":"She made an effort to stand up.","uz":"U o'rnidan turishga harakat qildi."},{"t":"h","x":"Too + infinitiv"},{"t":"formula","x":"too + sifat + infinitiv"},{"t":"ex","en":"You are too young to understand.","uz":"Sen tushunish uchun hali juda yoshsan."},{"t":"p","x":"Ba'zan too + sifatdan keyin majhul infinitiv keladi."},{"t":"ex","en":"This parcel is too heavy to be sent by post.","uz":"Bu posilka pochta orqali yuborish uchun juda og'ir."},{"t":"formula","x":"too + sifat + a/an + ot + infinitiv"},{"t":"ex","en":"He is too shrewd a businessman to accept the first offer.","uz":"U birinchi taklifni qabul qiladigan darajada sodda tadbirkor emas."},{"t":"ex","en":"He is too experienced a conductor to mind what the critics say.","uz":"U tanqidchilar gapiga e'tibor beradigan darajada tajribasiz dirijyor emas."},{"t":"formula","x":"too + ravish + infinitiv"},{"t":"ex","en":"It's too soon to say whether the scheme will succeed or not.","uz":"Reja muvaffaqiyatli bo'ladimi-yo'qmi, aytishga hali erta."},{"t":"ex","en":"She speaks too quickly for me to understand.","uz":"U men tushunolmaydigan darajada tez gapiradi."},{"t":"h","x":"Enough + infinitiv"},{"t":"formula","x":"sifat / ravish + enough + infinitiv"},{"t":"ex","en":"She is old enough to travel by herself.","uz":"U yolg'iz sayohat qilishga yetarlicha katta."},{"t":"ex","en":"He didn't jump high enough to win the prize.","uz":"U sovrin yutish uchun yetarlicha baland sakramadi."},{"t":"p","x":"<b>enough</b> olmosh yoki sifat (ot oldida) sifatida ham kelib, infinitiv olishi mumkin."},{"t":"ex","en":"He doesn't earn enough to live on.","uz":"U kun ko'rishga yetarli pul topmaydi."},{"t":"ex","en":"He hasn't got enough time to finish it.","uz":"Uning buni tugatishga yetarli vaqti yo'q."},{"t":"formula","x":"so + sifat + as + infinitiv"},{"t":"ex","en":"He was so foolish as to leave the car unlocked. = He was foolish enough to leave the car unlocked.","uz":"U mashinani qulflamay qoldiradigan darajada ahmoq edi."},{"t":"h","x":"Kirish iboralari"},{"t":"p","x":"Ba'zi infinitiv iboralar gap boshida yoki oxirida gap ravishi kabi ishlatiladi."},{"t":"ex","en":"To be honest, I just don't like him.","uz":"Rostini aytsam, u menga yoqmaydi."},{"t":"ex","en":"To cut a long story short, we said 'No'.","uz":"Qisqasi, biz «Yo'q» dedik."},{"t":"ex","en":"I've never met him, to tell you the truth.","uz":"Rostini aytsam, u bilan hech uchrashmaganman."},{"t":"h","x":"Perfect infinitiv"},{"t":"p","x":"<b>was / were + perfect infinitiv</b> amalga oshmagan reja yoki kelishuvni bildiradi."},{"t":"ex","en":"This house was to have been ready today.","uz":"Bu uy bugun tayyor bo'lishi kerak edi (lekin bo'lmadi)."},{"t":"p","x":"<b>appear, happen, pretend, seem</b> dan keyin perfect infinitiv asosiy fe'ldan <b>oldin</b> sodir bo'lgan harakatni bildiradi."},{"t":"table","head":["Infinitiv","that qurilmasi"],"rows":[["He seems to be an athlete.","It seems that he is an athlete."],["He seems to have been an athlete.","It seems that he was an athlete."]]}],"quiz":[{"q":"This parcel is too heavy ___ by post.","o":["to send","to be sent","sending","be sent"],"a":1,"e":"too + sifatdan keyin majhul infinitiv ham kelishi mumkin."},{"q":"He is too shrewd ___ to accept the first offer.","o":["businessman","a businessman","the businessman","businessmen"],"a":1,"e":"too + sifat + a/an + ot + infinitiv."},{"q":"She is ___ to travel by herself.","o":["enough old","old enough","too old","so old"],"a":1,"e":"enough sifatdan keyin keladi: old enough."},{"q":"He was so foolish ___ leave the car unlocked.","o":["to","that","as to","enough to"],"a":2,"e":"so + sifat + as + infinitiv."},{"q":"His ability ___ on with people is his asset.","o":["getting","to get","get","of get"],"a":1,"e":"ability otidan keyin infinitiv keladi."},{"q":"'This house was to have been ready today' means:","o":["It is ready","It was planned but is not ready","It will be ready","It was ready yesterday"],"a":1,"e":"was/were + perfect infinitiv — amalga oshmagan reja."},{"q":"He seems to have been an athlete. =","o":["It seems that he is an athlete.","It seems that he was an athlete.","It seemed that he is an athlete.","It seems that he will be an athlete."],"a":1,"e":"Perfect infinitiv oldingi harakatni bildiradi."},{"q":"___, I just don't like him.","o":["To be honest","Being honestly","Honest to be","For honest"],"a":0,"e":"To be honest — kirish ibora."},{"q":"He doesn't earn ___ to live on.","o":["enough","too","so","such"],"a":0,"e":"enough olmosh sifatida infinitiv oladi."}]},{"id":"p8-05","en":"The Gerund","uz":"Gerund (-ing shakl)","emoji":"🏃","level":"B1","group":"Infinitiv, gerund va ergash gaplar","summary":"Gerundning ega, taqiq va to'ldiruvchi vazifalari, gerund oladigan fe'llar, egalik olmoshi + gerund hamda perfect va majhul gerund.","blocks":[{"t":"h","x":"Gerund ega vazifasida"},{"t":"ex","en":"Dancing bored him.","uz":"Raqs uni zeriktirdi."},{"t":"ex","en":"Reading French is easier than speaking it.","uz":"Fransuzcha o'qish gapirishdan osonroq."},{"t":"h","x":"Qisqa taqiqlar"},{"t":"p","x":"Gerund qisqa taqiqlarda ishlatiladi: <b>No fishing. No smoking.</b>"},{"t":"rule","x":"Agar to'ldiruvchi (obyekt) bo'lsa, buyruq mayli ishlatiladi: Don't touch the wires. Don't feed the lions."},{"t":"h","x":"Gerund oladigan fe'llar"},{"t":"list","items":["<b>* (that ham oladigan):</b> admit, deny, fancy (= imagine), imagine, mean, propose, recollect, remember, suggest, understand","<b>Boshqalar:</b> anticipate, appreciate, avoid, consider, defer, delay, detest, dislike, dread, enjoy, escape, excuse, finish, forgive, involve, keep, loathe, mind, miss, pardon, postpone, practise, prevent, resent, resist, risk, save (somebody the trouble of), stop (= cease)","<b>Iboralar:</b> can't stand (= endure), can't help (= prevent/avoid), it's no use / it's no good, worth, look forward to, take to, be accustomed to, be used to"]},{"t":"rule","x":"<b>worth</b> sifatidan keyin gerund ishlatiladi: This book is worth reading."},{"t":"ex","en":"He admitted taking the money.","uz":"U pulni olganini tan oldi."},{"t":"ex","en":"Would you consider selling it?","uz":"Uni sotishni o'ylab ko'rasizmi?"},{"t":"ex","en":"He detests writing letters.","uz":"U xat yozishni juda yomon ko'radi."},{"t":"ex","en":"I couldn't help laughing.","uz":"Kulmasdan turolmadim."},{"t":"ex","en":"I'll look forward to seeing you.","uz":"Siz bilan ko'rishishni intiqlik bilan kutaman."},{"t":"p","x":"Yulduzli fe'llar <b>that</b> ergash gapi bilan ham keladi: <i>He admitted that he had taken the money.</i>"},{"t":"h","x":"Gerund kimga tegishli?"},{"t":"p","x":"Fe'l yoki fe'l + predlogdan keyin bevosita gerund kelsa, u gapning <b>egasiga</b> tegishli bo'ladi."},{"t":"ex","en":"Tom insisted on reading the letter. (Tom read it.)","uz":"Tom xatni o'zi o'qishni talab qildi."},{"t":"p","x":"Orasiga <b>egalik sifati yoki olmosh</b> qo'yilsa, gerund o'sha shaxsga tegishli bo'ladi."},{"t":"ex","en":"Tom insisted on me / my reading the letter.","uz":"Tom xatni men o'qishimni talab qildi."},{"t":"p","x":"Ikkala qurilmani oladigan fe'llar va iboralar: <b>dislike, dread, fancy, involve, like (inkorda), mean, mind, propose, recollect, remember, resent, save, stop, suggest, understand, approve / disapprove of, insist on, it's no good / use, object to, there's no point in, what's the point of</b>."},{"t":"ex","en":"He disliked working late. / He disliked me / my working late.","uz":"U kechgacha ishlashni yoqtirmasdi. / U mening kechgacha ishlashimni yoqtirmasdi."},{"t":"rule","x":"<b>excuse, forgive, pardon, prevent</b> dan keyin har doim egalik sifati yoki olmosh keladi: Excuse my / me ringing you up so early."},{"t":"p","x":"<b>appreciate</b> odatda egalik sifati yoki majhul gerund talab qiladi."},{"t":"ex","en":"I appreciate your giving me so much of your time.","uz":"Menga shuncha vaqt ajratganingizni qadrlayman."},{"t":"ex","en":"I appreciate being given this opportunity.","uz":"Menga bu imkoniyat berilganini qadrlayman."},{"t":"h","x":"Mind"},{"t":"p","x":"<b>mind</b> asosan inkor va so'roq gaplarda ishlatiladi. <b>Would you mind ...?</b> — iltimos qilishning eng keng tarqalgan usullaridan biri."},{"t":"ex","en":"Would you mind waiting a moment? / I don't mind walking.","uz":"Bir oz kutib tura olasizmi? / Piyoda yurishga qarshi emasman."},{"t":"ex","en":"Would you mind not smoking? = Please don't smoke.","uz":"Chekmasangiz bo'ladimi?"},{"t":"ex","en":"Would you mind moving your car? = Please move your car.","uz":"Mashinangizni surib qo'ya olasizmi?"},{"t":"h","x":"Perfect va majhul gerund"},{"t":"p","x":"O'tgan harakat haqida gapirganda <b>perfect gerund</b> (having + V3) ishlatiladi."},{"t":"ex","en":"He was accused of having deserted his ship.","uz":"U kemasini tashlab qochganlikda ayblandi."},{"t":"ex","en":"He denied having been there.","uz":"U u yerda bo'lganini rad etdi."},{"t":"p","x":"Gerundning majhul shakli: <b>being + V3</b>, <b>having been + V3</b>."},{"t":"ex","en":"He was punished by being sent to prison.","uz":"U qamoqqa yuborilish bilan jazolandi."},{"t":"ex","en":"The safe showed no signs of having been touched.","uz":"Seyfga tegilganlik belgisi yo'q edi."}],"quiz":[{"q":"I couldn't help ___.","o":["to laugh","laugh","laughing","laughed"],"a":2,"e":"can't help dan keyin gerund keladi."},{"q":"I look forward to ___ you.","o":["see","seeing","to see","seen"],"a":1,"e":"look forward to — bu yerda to predlog, gerund oladi."},{"q":"Which notice is correct?","o":["No touch the wires.","Don't touching the wires.","Don't touch the wires.","No touching wires the."],"a":2,"e":"Obyekt bo'lsa, buyruq mayli ishlatiladi."},{"q":"Tom insisted on ___ the letter. (I read it)","o":["reading","my reading","to read","me to read"],"a":1,"e":"Egalik sifati gerundni o'sha shaxsga bog'laydi."},{"q":"Excuse ___ you up so early.","o":["ringing","to ring","my ringing","ring"],"a":2,"e":"excuse dan keyin egalik sifati/olmosh + gerund keladi."},{"q":"He denied ___ there.","o":["to have been","having been","have been","to be"],"a":1,"e":"O'tgan harakat uchun perfect gerund."},{"q":"Would you mind ___ a moment?","o":["to wait","wait","waiting","waited"],"a":2,"e":"mind dan keyin gerund."},{"q":"The safe showed no signs of ___.","o":["having touched","having been touched","been touched","to be touched"],"a":1,"e":"Majhul perfect gerund: having been + V3."},{"q":"I appreciate ___ this opportunity.","o":["to be given","being given","give","to give"],"a":1,"e":"appreciate egalik sifati yoki majhul gerund talab qiladi."},{"q":"This book is worth ___.","o":["to read","read","reading","to be read"],"a":2,"e":"worth dan keyin gerund keladi."}]},{"id":"p8-06","en":"Verb + Gerund or Infinitive","uz":"Gerund yoki infinitiv oladigan fe'llar","emoji":"⚖️","level":"B2","group":"Infinitiv, gerund va ergash gaplar","summary":"Ham gerund, ham infinitiv oladigan fe'llar: ma'no o'zgarmaydigan va o'zgaradigan holatlar (remember, regret, forget, mean, be afraid, be sorry, be ashamed).","blocks":[{"t":"p","x":"Quyidagi fe'llar infinitiv yoki gerund olishi mumkin: <b>advise, agree, allow, begin, can/could bear, cease, continue, forget, hate, intend, like, love, mean, need, permit, prefer, propose, recommend, regret, remember, require, start, stop, try, used to, want</b>. Iboralar: <b>be ashamed of, be afraid (of), be sorry (for), care for, go on</b>."},{"t":"h","x":"Ma'no o'zgarmaydigan fe'llar"},{"t":"p","x":"<b>begin, start, continue, cease</b> infinitiv ham, gerund ham oladi, ma'no farq qilmaydi."},{"t":"ex","en":"I began working. = I began to work.","uz":"Men ishlashni boshladim."},{"t":"rule","x":"Bilish, tushunish fe'llari va <b>matter</b> fe'li bilan infinitiv ko'proq ishlatiladi: I'm beginning to understand why he acted so strangely."},{"t":"p","x":"<b>can / could bear</b> ikkalasini ham oladi, asosan inkor gaplarda ishlatiladi."},{"t":"ex","en":"I can't bear waiting. = I can't bear to wait.","uz":"Kutishga toqatim yo'q."},{"t":"p","x":"<b>intend</b> ikkalasini ham oladi, infinitiv ko'proq ishlatiladi. Lekin <b>intend + obyekt</b> dan keyin faqat infinitiv."},{"t":"ex","en":"I intend to sell it. = I intend selling it.","uz":"Men uni sotmoqchiman."},{"t":"ex","en":"I intend you to take over the department.","uz":"Bo'limni sizga topshirmoqchiman."},{"t":"p","x":"<b>allow, advise, permit, recommend, encourage</b> dan keyin bevosita gerund yoki <b>obyekt + infinitiv</b> keladi."},{"t":"ex","en":"I advised sleeping. / I advised him to sleep.","uz":"Uxlashni maslahat berdim. / Unga uxlashni maslahat berdim."},{"t":"p","x":"<b>it needs / requires / wants</b> dan keyin gerund yoki majhul infinitiv keladi."},{"t":"ex","en":"The grass wants cutting. = The grass needs to be cut.","uz":"Maysani o'rish kerak."},{"t":"h","x":"Remember, regret, forget"},{"t":"p","x":"Gerund harakat <b>oldin</b> sodir bo'lganini bildiradi (eslash/afsuslanishdan avval)."},{"t":"ex","en":"I regret spending so much money.","uz":"Shuncha pul sarflaganimdan afsusdaman."},{"t":"ex","en":"I remember reading about the earthquake.","uz":"Zilzila haqida o'qiganimni eslayman."},{"t":"rule","x":"forget + gerund faqat forget inkorda bo'lganda ishlatiladi: I'll never forget waiting for the bombs to fall."},{"t":"p","x":"Agar <b>remember, regret, forget</b> ning o'zi oldingi harakat bo'lsa (ya'ni harakat keyin bajariladi), infinitiv keladi."},{"t":"ex","en":"I'll remember to ring Bill.","uz":"Billga qo'ng'iroq qilishni unutmayman."},{"t":"ex","en":"I regret to say that you have failed the exam.","uz":"Afsus bilan aytamanki, imtihondan o'tolmadingiz."},{"t":"h","x":"Agree, mean"},{"t":"p","x":"<b>agree</b> dan keyin infinitiv: <i>Tom agreed to wait.</i> <b>agree to</b> esa egalik sifati + gerund olishi mumkin: <i>He agreed to my leaving early on Friday.</i>"},{"t":"table","head":["Qurilma","Ma'nosi","Misol"],"rows":[["mean + infinitiv","niyat qilmoq (intend)","I mean to get to the top by sunrise."],["mean + gerund","anglatmoq, talab qilmoq (involve)","This job means getting up early."]]},{"t":"h","x":"Be afraid (of), be sorry (for), be ashamed (of)"},{"t":"table","head":["Qurilma","Ma'nosi","Misol"],"rows":[["be afraid of + gerund","sodir bo'lishidan qo'rqish (ixtiyorsiz harakat)","He was afraid of getting cramp. She is afraid of being mugged."],["be afraid + infinitiv","qo'rqqanidan qila olmaslik (ongli harakat)","He was afraid to jump. She was afraid to protest."],["be sorry for + gerund","uzr so'rash, afsuslanish","I'm sorry for making so much noise."],["be sorry + infinitiv","afsus yoki qayg'u bildirish","I'm sorry to hear that you've been ill."],["be ashamed of + gerund","oldingi harakatdan uyalish","You should be ashamed of lying to him."],["be ashamed + infinitiv","keyingi harakatdan uyalish","I'm ashamed to tell you what the carpet cost."]]}],"quiz":[{"q":"I remember ___ about the earthquake. (I read it earlier)","o":["to read","reading","read","to have read about"],"a":1,"e":"remember + gerund — oldin bo'lgan harakatni eslash."},{"q":"Please remember ___ Bill tomorrow.","o":["ringing","to ring","ring","rang"],"a":1,"e":"Harakat keyin bajariladi — infinitiv."},{"q":"The grass needs ___.","o":["to cut","cutting","cut","be cut"],"a":1,"e":"need/want/require + gerund yoki majhul infinitiv (to be cut)."},{"q":"I intend you ___ over the department.","o":["taking","to take","take","took"],"a":1,"e":"intend + obyekt dan keyin faqat infinitiv."},{"q":"He was afraid ___. (too frightened to do it)","o":["of jumping","to jump","jumping","jump"],"a":1,"e":"be afraid + infinitiv — qo'rqib ongli harakatni qilolmaslik."},{"q":"She avoids lonely streets. She is afraid ___ mugged.","o":["to be","of being","be","for being"],"a":1,"e":"be afraid of + gerund — ixtiyorsiz sodir bo'lishidan qo'rqish."},{"q":"I'm sorry ___ that you've been ill.","o":["for hearing","to hear","hearing","hear"],"a":1,"e":"be sorry + infinitiv — afsus bildirish."},{"q":"I mean ___ the top by sunrise. (intend)","o":["getting to","to get to","get to","got to"],"a":1,"e":"mean = intend bo'lsa infinitiv."},{"q":"I regret ___ that you have failed the exam.","o":["saying","to say","say","said"],"a":1,"e":"regret to say — rasmiy afsus bilan xabar berish."},{"q":"He agreed to ___ early on Friday.","o":["me leave","my leaving","I leaving","my leave"],"a":1,"e":"agree to + egalik sifati + gerund."}]},{"id":"p8-07","en":"Causative Verbs and Verbs of Preference","uz":"Sababiy fe'llar va afzal ko'rish fe'llari","emoji":"🛠️","level":"B1","group":"Infinitiv, gerund va ergash gaplar","summary":"have / make / get bilan ishni boshqaga qildirish hamda prefer, would rather qurilmalari.","blocks":[{"t":"h","x":"Causative (sababiy) fe'llar"},{"t":"p","x":"Sababiy fe'llar bir shaxs ikkinchi shaxsga birinchi shaxs uchun biror ishni <b>qildirishini</b> bildiradi."},{"t":"table","head":["Qurilma","Misol","Tarjima"],"rows":[["have + someone + do","She has John clean the room.","U Jonga xonani tozalatadi."],["make + someone + do","She makes John clean the room.","U Jonni xonani tozalashga majburlaydi."],["get + someone + to do","She gets John to clean the room.","U Jonni xonani tozalashga ko'ndiradi."]]},{"t":"p","x":"Ishni kim bajarishi muhim bo'lmasa, narsa + V3 ishlatiladi:"},{"t":"formula","x":"have / get + something + done (V3)"},{"t":"ex","en":"I had my car cleaned.","uz":"Mashinamni tozalatdim."},{"t":"ex","en":"I get my car cleaned.","uz":"Mashinamni tozalataman."},{"t":"rule","x":"Diqqat: have va make dan keyin to'siz infinitiv, get dan keyin esa <b>to</b> li infinitiv keladi."},{"t":"h","x":"Afzal ko'rish fe'llari"},{"t":"p","x":"<b>prefer</b> dan keyin gerund ham, infinitiv ham kelishi mumkin."},{"t":"ex","en":"I don't like cities. I prefer to live / living in the country.","uz":"Shaharlarni yoqtirmayman. Qishloqda yashashni afzal ko'raman."},{"t":"formula","x":"prefer (doing) something TO (doing) something else"},{"t":"formula","x":"prefer to do something RATHER THAN do something else"},{"t":"ex","en":"I prefer tea to coffee.","uz":"Men choyni qahvadan afzal ko'raman."},{"t":"ex","en":"I prefer walking to driving.","uz":"Men piyoda yurishni mashina haydashdan afzal ko'raman."},{"t":"ex","en":"I prefer to walk rather than drive.","uz":"Men mashina haydashdan ko'ra piyoda yurishni afzal bilaman."},{"t":"formula","x":"would rather do something THAN do something else"},{"t":"ex","en":"I would rather stay at home than go to the cinema.","uz":"Kinoga borgandan ko'ra uyda qolganim ma'qul."},{"t":"h","x":"Would rather + someone + past"},{"t":"p","x":"Biror kishi boshqa birovning biror ish qilishini xohlasa, <b>would rather someone did something</b> qurilmasi ishlatiladi. Fe'l o'tgan zamonda bo'lsa ham, ma'no hozirgi yoki kelasi zamonni bildiradi."},{"t":"ex","en":"I'd rather cook dinner now.","uz":"Kechki ovqatni hozir pishirganim ma'qul."},{"t":"ex","en":"I'd rather you cooked the dinner now.","uz":"Kechki ovqatni hozir siz pishirsangiz yaxshi bo'lardi."}],"quiz":[{"q":"She gets John ___ the room.","o":["clean","to clean","cleaning","cleaned"],"a":1,"e":"get + kishi + to infinitiv."},{"q":"She has John ___ the room.","o":["to clean","clean","cleaned","cleaning"],"a":1,"e":"have + kishi + to'siz infinitiv."},{"q":"I had my car ___.","o":["clean","to clean","cleaned","cleaning"],"a":2,"e":"have + narsa + V3."},{"q":"I prefer walking ___ driving.","o":["than","to","rather","from"],"a":1,"e":"prefer doing TO doing."},{"q":"I prefer to walk rather than ___.","o":["driving","to driving","drive","drove"],"a":2,"e":"prefer to do rather than do (to'siz)."},{"q":"I would rather stay at home ___ go to the cinema.","o":["to","than","that","rather"],"a":1,"e":"would rather ... than ..."},{"q":"I'd rather you ___ the dinner now.","o":["cook","cooked","to cook","cooking"],"a":1,"e":"would rather + boshqa shaxs + o'tgan zamon (ma'no hozirgi)."},{"q":"She makes John ___ the room.","o":["to clean","cleans","clean","cleaned"],"a":2,"e":"make + kishi + to'siz infinitiv."},{"q":"'I'd rather you cooked dinner now' refers to:","o":["the past","the present/future","a finished action","a habit in the past"],"a":1,"e":"O'tgan zamon shakli bo'lsa ham, ma'no hozirgi/kelasi."}]},{"id":"p8-08","en":"Modal Verbs: Permission and Possibility","uz":"Modal fe'llar: ruxsat va ehtimollik","emoji":"🚦","level":"B1","group":"Majhul nisbat va modal fe'llar","summary":"may, might, can, could bilan ruxsat berish va so'rash, hozirgi va o'tgan ehtimollik hamda ularning inkordagi ma'no farqlari.","blocks":[{"t":"h","x":"Ruxsat (Permission)"},{"t":"p","x":"Ruxsat uchun <b>may, might, can</b> ishlatiladi. <b>can</b> va <b>may</b> hozirgi va kelasi zamon ma'nosida, <b>might</b> esa shart gaplarda va o'tgan zamondagi fe'llardan keyin ishlatiladi."},{"t":"ex","en":"You may go. / You can go. / He said you might go.","uz":"Ketishingiz mumkin. / U ketishingiz mumkinligini aytdi."},{"t":"p","x":"<b>may</b> asosan so'zlovchining o'zi ruxsat berayotganida ishlatiladi. <b>can</b> esa so'zlovchining ruxsatini ham, umumiy (qonun, qoida bo'yicha) ruxsatni ham bildiradi."},{"t":"ex","en":"You may park here. (I allow you, but the police may not.)","uz":"Bu yerda to'xtashingiz mumkin (men ruxsat beraman)."},{"t":"ex","en":"You can park here. (I allow you and the police do too.)","uz":"Bu yerda to'xtash mumkin (qoida bo'yicha ham)."},{"t":"p","x":"O'tmishdagi umumiy ruxsat uchun <b>could</b> ishlatiladi."},{"t":"ex","en":"On Sundays we could stay up late.","uz":"Yakshanbalari kech yotishimiz mumkin edi."},{"t":"rule","x":"Muayyan bir harakatga ruxsat berilib, u bajarilgan bo'lsa, <b>was / were allowed to</b> ishlatiladi: I had a visa, so I was allowed to cross the frontier."},{"t":"p","x":"Ruxsat so'rash uchun: <b>Can I ...? Could I ...? May I ...? Might I ...?</b> — May I leave?"},{"t":"h","x":"Ehtimollik (Possibility)"},{"t":"p","x":"<b>may</b> odatda so'roq gaplarda ishlatilmaydi. So'roq odatda <b>do you think</b> yoki <b>be likely</b> bilan beriladi. <b>might</b> esa so'roqda ishlatilishi mumkin."},{"t":"ex","en":"Do you think he will come? / Is he likely to come?","uz":"U keladi deb o'ylaysizmi? / U kelishi mumkinmi?"},{"t":"ex","en":"Might they be waiting outside the station?","uz":"Ular vokzal tashqarisida kutayotgan bo'lishlari mumkinmi?"},{"t":"p","x":"O'tgan harakatlar haqida taxminda <b>may / might + perfect infinitiv</b> ishlatiladi."},{"t":"ex","en":"He may have gone. (= Perhaps he went. It's possible that he went.)","uz":"U ketgan bo'lishi mumkin."},{"t":"p","x":"Noaniqlik endi mavjud bo'lmasa (natija ma'lum bo'lsa) <b>may</b> emas, <b>might</b> ishlatiladi."},{"t":"ex","en":"He came home alone. You shouldn't have let him do that. He might have got lost.","uz":"U yo'qolib qolishi mumkin edi (lekin yo'qolmadi)."},{"t":"ex","en":"You shouldn't have drunk the wine. It may / might have been drugged.","uz":"Unga dori qo'shilgan bo'lishi mumkin edi."},{"t":"p","x":"<i>It may have been drugged</i> — biz hali ham bilmaymiz. <i>It might have been drugged</i> ham shu ma'noni berishi mumkin, lekin dori qo'shilmaganini bilishimizni ham anglatishi mumkin."},{"t":"rule","x":"Ish hech qachon sinab ko'rilmagan bo'lsa ham <b>might</b> ishlatiladi: Perhaps we should have taken the other road. It might have been quicker."},{"t":"h","x":"Could ehtimollik ma'nosida"},{"t":"p","x":"<b>may / might be</b> o'rnida <b>could be</b> ham ishlatiladi. So'roqda could ham, may / might ham kelaveradi."},{"t":"ex","en":"Where is Tom? — He may / might / could be in the library.","uz":"Tom qayerda? — Kutubxonada bo'lishi mumkin."},{"t":"ex","en":"Could they be waiting for us?","uz":"Ular bizni kutayotgan bo'lishlari mumkinmi?"},{"t":"rule","x":"Inkorda ma'no farq qiladi: <b>may / might not</b> = ehtimol ... emas; <b>couldn't</b> = mutlaqo mumkin emas (inkor xulosa)."},{"t":"table","head":["Gap","Ma'nosi"],"rows":[["He may not be driving the car by himself.","Perhaps he isn't driving the car."],["He couldn't be driving the car by himself.","This is impossible — he can't drive at all."],["He may not be in Namangan.","Perhaps he isn't in Namangan."],["He couldn't be in Namangan.","I'm sure he isn't in Namangan."]]},{"t":"p","x":"<b>could + perfect infinitiv</b> ham <b>may / might + perfect infinitiv</b> o'rnida keladi. So'roqda farq yo'q, inkorda esa ma'no farq qiladi."},{"t":"ex","en":"I wonder how Tom knew about Ann's engagement. — He may / might / could have heard it from Jack.","uz":"U buni Jekdan eshitgan bo'lishi mumkin."},{"t":"ex","en":"Ann might not have seen Tom yesterday. (Perhaps she didn't.) / Ann couldn't have seen Tom yesterday. (It's impossible.)","uz":"Anna kecha Tomni ko'rmagan bo'lishi mumkin. / Anna kecha Tomni ko'rgan bo'lishi mumkin emas."},{"t":"h","x":"Subject + can = imkoniyat bor"},{"t":"p","x":"<b>Ega + can</b> «mumkin» yoki «sharoit imkon beradi» ma'nosini beradi."},{"t":"ex","en":"You can ski. There is enough snow.","uz":"Chang'i uchsangiz bo'ladi — qor yetarli."},{"t":"ex","en":"Can you get to the top of the mountain in a day?","uz":"Bir kunda tog' cho'qqisiga chiqish mumkinmi?"},{"t":"ex","en":"Measles can be quite dangerous.","uz":"Qizamiq ancha xavfli bo'lishi mumkin."}],"quiz":[{"q":"He said you ___ go. (reported permission)","o":["may","might","can","must"],"a":1,"e":"O'tgan zamondagi fe'ldan keyin might ishlatiladi."},{"q":"I had a visa, so I ___ cross the frontier. (particular permitted action)","o":["could","might","was allowed to","may"],"a":2,"e":"Muayyan bajarilgan harakat uchun was/were allowed to."},{"q":"On Sundays we ___ stay up late. (general past permission)","o":["could","might","may","must"],"a":0,"e":"O'tmishdagi umumiy ruxsat — could."},{"q":"Which question about possibility is normal?","o":["May he come?","Is he likely to come?","Mays he come?","May he comes?"],"a":1,"e":"may odatda ehtimollik so'rog'ida ishlatilmaydi; be likely yoki do you think ishlatiladi."},{"q":"He came home alone. He ___ have got lost. (but he didn't)","o":["may","might","must","can"],"a":1,"e":"Noaniqlik qolmagan bo'lsa might ishlatiladi."},{"q":"'He couldn't be driving the car by himself' means:","o":["Perhaps he isn't driving","It's impossible — he can't drive","He was able to drive","He mustn't drive"],"a":1,"e":"couldn't — inkor xulosa, mumkin emas."},{"q":"'He may not be in Namangan' means:","o":["I'm sure he isn't in Namangan","Perhaps he isn't in Namangan","He isn't allowed to be in Namangan","He will be in Namangan"],"a":1,"e":"may not — ehtimollik: balki u yerda emas."},{"q":"He ___ have heard it from Jack. (possibility)","o":["could","must not","can't","shouldn't"],"a":0,"e":"could + perfect infinitiv = may/might + perfect infinitiv."},{"q":"You can ski. There is enough snow. Here 'can' means:","o":["ability","circumstances permit","obligation","deduction"],"a":1,"e":"ega + can — sharoit imkon beradi."},{"q":"Perhaps we should have taken the other road. It ___ have been quicker.","o":["may","might","must","will"],"a":1,"e":"Hech qachon sinab ko'rilmagan holatda might ishlatiladi."}]},{"id":"p8-09","en":"Modal Verbs: Ability and Obligation","uz":"Modal fe'llar: qobiliyat va majburiyat","emoji":"💪","level":"B1","group":"Majhul nisbat va modal fe'llar","summary":"can / could / be able to bilan qobiliyat; ought to, should, must, have (got) to va needn't have bilan majburiyat va maslahat.","blocks":[{"t":"h","x":"Qobiliyat (Ability)"},{"t":"p","x":"Qobiliyat uchun <b>can</b> va <b>be able to</b> ishlatiladi. Kelasi zamondagi qobiliyat uchun faqat <b>shall / will be able to</b>."},{"t":"ex","en":"Our baby will be able to walk in a few weeks.","uz":"Bolamiz bir necha haftadan keyin yura oladi."},{"t":"p","x":"Hozirgi qobiliyat uchun ikkalasi ham mumkin, <b>can</b> ko'proq ishlatiladi: <i>Can you type? / Are you able to type?</i>"},{"t":"p","x":"Shart g'oyasi bo'lganda hozirgi qobiliyat uchun <b>could</b> ishlatiladi."},{"t":"ex","en":"Could you run the business by yourself (if it was necessary)?","uz":"(Zarur bo'lsa) biznesni o'zingiz yurita olarmidingiz?"},{"t":"ex","en":"I could get a copy (if you want).","uz":"(Xohlasangiz) nusxa olib bera olaman."},{"t":"p","x":"O'tmishdagi umumiy qobiliyat uchun <b>could</b> yoki <b>was / were able to</b>."},{"t":"ex","en":"When I was young, I could / was able to climb any tree.","uz":"Yoshligimda istalgan daraxtga chiqa olardim."},{"t":"rule","x":"Muayyan bir holatdagi harakat uchun faqat <b>was / were able to</b> ishlatiladi; bu «uddaladi» (managed) ma'nosini beradi: Although the pilot was badly hurt, he was able to explain what had happened."},{"t":"p","x":"Lekin inkor gaplarda va sezgi fe'llari bilan muayyan harakat uchun ham could, ham was / were able to ishlatiladi."},{"t":"ex","en":"He read the message but he couldn't / wasn't able to understand it.","uz":"U xabarni o'qidi, lekin tushuna olmadi."},{"t":"ex","en":"I could / was able to see him through the window.","uz":"Uni derazadan ko'ra oldim."},{"t":"p","x":"Barcha perfect shakllarda <b>be able</b> ishlatiladi: <i>Since his accident he hasn't been able to walk by himself.</i>"},{"t":"h","x":"Could + perfect infinitiv"},{"t":"list","items":["Bajarilmagan o'tgan qobiliyat: <i>I could have lent you the money. Why didn't you ask?</i>","Bajarilgan-bajarilmagani noma'lum: <i>The money has disappeared. Who could have taken it? — Tom could have taken it. Only he knew where it was.</i>","Norozilik ifodasi: <i>You could have told me!</i>"]},{"t":"table","head":["Gap","Ma'nosi"],"rows":[["He was able to send it.","U yubordi."],["He could have sent it.","U yubormadi yoki yuborgan-yubormagani noma'lum."]]},{"t":"h","x":"Majburiyat (Obligation)"},{"t":"p","x":"<b>ought to / should</b> eganing burchi yoki majburiyatini bildiradi."},{"t":"ex","en":"You should send in accurate tax returns.","uz":"Soliq hisobotlarini aniq topshirishingiz kerak."},{"t":"p","x":"<b>must</b> va <b>have to</b> majburiyat bajarilayotgani yoki bajarilishi haqida taassurot beradi; <b>ought / should</b> da esa majburiyat bajariladi degan tuyg'u bo'lmaydi."},{"t":"ex","en":"I should drive slowly here. It's a built-up area. (He probably isn't going to.) / I must drive slowly here. It's a built-up area. (He really will.)","uz":"Bu yerda sekin haydashim kerak edi... / Bu yerda albatta sekin haydashim kerak."},{"t":"p","x":"<b>should</b> rasmiy eslatma va axborot varaqalarida ishlatiladi; bu yerda must ham bo'ladi, ammo should yumshoqroq va xushmuomalaroq."},{"t":"ex","en":"Candidates should be prepared to answer questions by June.","uz":"Nomzodlar iyungacha savollarga javob berishga tayyor bo'lishlari kerak."},{"t":"p","x":"<b>ought / should</b> maslahat bildiradi; kuchliroq maslahat uchun <b>must</b> yaxshiroq."},{"t":"ex","en":"It's very good. You ought to / should read this. / It's marvellous. You must read this.","uz":"Buni o'qishingiz kerak. / Buni albatta o'qing!"},{"t":"p","x":"<b>ought / should + davomli infinitiv</b> — ega majburiyatini bajarmayotganini bildiradi."},{"t":"ex","en":"He should be studying for his exam. He shouldn't be spending all his time on the beach.","uz":"U imtihonga tayyorlanishi kerak, butun vaqtini plyajda o'tkazmasligi kerak."},{"t":"ex","en":"We should be wearing seat belts.","uz":"Biz xavfsizlik kamarini taqib olishimiz kerak."},{"t":"p","x":"<b>ought / should + perfect infinitiv</b> — bajarilmagan majburiyat."},{"t":"ex","en":"You should have told him that the paint was still wet.","uz":"Unga bo'yoq hali qurimaganini aytishingiz kerak edi."},{"t":"ex","en":"They ought to have stopped at the traffic lights.","uz":"Ular svetoforda to'xtashlari kerak edi."},{"t":"ex","en":"She shouldn't have opened the letter. It wasn't addressed to her.","uz":"U xatni ochmasligi kerak edi."},{"t":"h","x":"Have got to, must, have to"},{"t":"p","x":"Bir martalik harakatlar uchun <b>have to</b> o'rnida <b>have got to</b> ishlatilishi mumkin: <i>have got to / haven't got to / Have I got to? / had got to</i>."},{"t":"ex","en":"I have to go to work every day. / I'm glad I haven't got to go to work today.","uz":"Har kuni ishga borishim kerak. / Bugun ishga bormasligim kerakligidan xursandman."},{"t":"p","x":"<b>must</b> yozma buyruq va ko'rsatmalarda ishlatiladi: <i>Mobile phones must be switched off. Staff must be at their desks by 9.</i>"},{"t":"p","x":"Birinchi shaxsda: <b>have to</b> odatlar uchun, <b>must</b> majburiyat shoshilinch yoki so'zlovchi uchun muhim bo'lganda."},{"t":"ex","en":"I have to take two of these pills a day. / I must tell you about my dream.","uz":"Kuniga ikkita tabletka ichishim kerak. / Tushimni sizga albatta aytib berishim kerak."},{"t":"h","x":"Needn't have + V3"},{"t":"p","x":"Bajarilgan, lekin kerak bo'lmagan harakatni bildiradi."},{"t":"ex","en":"I needn't have written to him because he phoned me shortly afterwards.","uz":"Unga xat yozishim shart emas edi, chunki u ko'p o'tmay qo'ng'iroq qildi."},{"t":"ex","en":"You needn't have brought your umbrella, for we are going by car.","uz":"Soyabon olib kelishingiz shart emas edi, mashinada boramiz."}],"quiz":[{"q":"Our baby ___ walk in a few weeks.","o":["can","could","will be able to","is able"],"a":2,"e":"Kelasi zamondagi qobiliyat uchun faqat will be able to."},{"q":"Although the pilot was badly hurt, he ___ explain what had happened.","o":["could","was able to","can","might"],"a":1,"e":"Muayyan harakat (managed) uchun faqat was able to."},{"q":"Since his accident he hasn't ___ walk by himself.","o":["could","can","been able to","be able"],"a":2,"e":"Perfect shakllarda be able ishlatiladi."},{"q":"I ___ lent you the money. Why didn't you ask?","o":["could have","can have","was able to","must have"],"a":0,"e":"could + perfect infinitiv — bajarilmagan qobiliyat."},{"q":"'He could have sent it' means:","o":["He sent it","He didn't send it, or we don't know","He must send it","He was obliged to send it"],"a":1,"e":"could have — bajarilmagan yoki noma'lum."},{"q":"You ___ have told him the paint was wet. (unfulfilled obligation)","o":["should","must","can","will"],"a":0,"e":"should + perfect infinitiv — bajarilmagan majburiyat."},{"q":"He ___ be studying for his exam, not lying on the beach.","o":["should","can","may","will"],"a":0,"e":"should + davomli infinitiv — majburiyat bajarilmayapti."},{"q":"I ___ written to him because he phoned me shortly afterwards.","o":["mustn't have","needn't have","couldn't have","shouldn't"],"a":1,"e":"needn't have + V3 — bajarilgan, lekin keraksiz harakat."},{"q":"Which is best for a habit (first person)?","o":["I must take two pills a day.","I have to take two pills a day.","I ought take two pills a day.","I should to take two pills a day."],"a":1,"e":"Odatlar uchun have to yaxshiroq."},{"q":"It's marvellous. You ___ read this! (emphatic advice)","o":["must","should","might","could"],"a":0,"e":"Kuchli maslahat uchun must."}]},{"id":"p8-10","en":"Modal Verbs: Deduction and Assumption","uz":"Modal fe'llar: xulosa va taxmin","emoji":"🔍","level":"B2","group":"Majhul nisbat va modal fe'llar","summary":"must, can't / couldn't bilan xulosa chiqarish va will, should, ought to bilan taxmin qilish.","blocks":[{"t":"h","x":"Xulosa (Deduction)"},{"t":"p","x":"<b>must</b> ishonchli xulosa uchun ishlatiladi."},{"t":"ex","en":"I haven't had any sleep for two days. — You must be exhausted.","uz":"Ikki kundan beri uxlamadim. — Juda charchagan bo'lsangiz kerak."},{"t":"ex","en":"The police are stopping all cars. They must be looking for the escaped prisoner.","uz":"Ular qochgan mahbusni qidirayotgan bo'lsa kerak."},{"t":"p","x":"Kitobdagi misol: bizda 3 ta kalit bor, biri eshikni ochadi. Birinchi kalitni olib <i>«This might be the key»</i> deymiz. U ochmagach, ikkinchisini olib <i>«This may be the key»</i> deymiz. Ikki kalit ochmagach, uchinchisini olib <i>«This must be the key»</i> deymiz. Ishonch darajasi: <b>might &lt; may &lt; must</b>."},{"t":"p","x":"O'tgan harakat haqida xulosa: <b>must + perfect infinitiv</b>."},{"t":"ex","en":"He must have come by taxi.","uz":"U taksida kelgan bo'lsa kerak."},{"t":"ex","en":"You must have heard it. The whole town heard it.","uz":"Siz buni eshitgan bo'lsangiz kerak — butun shahar eshitdi."},{"t":"rule","x":"Inkor xulosa uchun <b>mustn't</b> emas, <b>can't / couldn't</b> ishlatiladi."},{"t":"ex","en":"Tom can't be here. He phoned me two hours ago and said he would come tomorrow.","uz":"Tom bu yerda bo'lishi mumkin emas."},{"t":"p","x":"O'tgan harakat haqida inkor xulosa: <b>can't / couldn't + perfect infinitiv</b>."},{"t":"ex","en":"A man answered the phone. I suppose it was her husband. — It can't have been her husband. He died two years ago.","uz":"Bu uning eri bo'lishi mumkin emas — u ikki yil oldin vafot etgan."},{"t":"h","x":"Taxmin (Assumption)"},{"t":"p","x":"<b>will</b> hozirgi va o'tgan zamon taxminlari uchun ishlatiladi."},{"t":"ex","en":"Ring his home number. He will be at home now.","uz":"Uyiga qo'ng'iroq qiling, hozir uyda bo'lsa kerak."},{"t":"ex","en":"He will be expecting a call from you.","uz":"U sizdan qo'ng'iroq kutayotgan bo'lsa kerak."},{"t":"p","x":"<b>should</b> ham taxmin uchun ishlatiladi, lekin u <b>will</b> ga qaraganda kamroq ishonchli."},{"t":"ex","en":"The plane should be landing now.","uz":"Samolyot hozir qo'nayotgan bo'lishi kerak."},{"t":"ex","en":"Tom should know the address. (less sure) / Tom will know the address. (more sure)","uz":"Tom manzilni bilsa kerak. / Tom manzilni albatta biladi."},{"t":"rule","x":"<b>should</b> so'zlovchiga yoqmaydigan taxminlar uchun ishlatilmaydi: Let's not go shopping. The shops will be very crowded."},{"t":"p","x":"Kelasi zamon taxminlari uchun will ham, should ham ishlatiladi."},{"t":"ex","en":"They shouldn't / won't have any difficulty in finding a house.","uz":"Ular uy topishda qiynalmasalar kerak."},{"t":"p","x":"<b>should</b> o'rnida <b>ought to</b> ishlatish mumkin, lekin should ko'proq qo'llanadi: <i>The plane ought to be landing now.</i>"}],"quiz":[{"q":"You haven't slept for two days. You ___ be exhausted.","o":["must","can't","should","may not"],"a":0,"e":"Ishonchli xulosa — must."},{"q":"Tom ___ be here. He said he would come tomorrow.","o":["mustn't","can't","must","should"],"a":1,"e":"Inkor xulosa uchun can't ishlatiladi."},{"q":"It ___ been her husband. He died two years ago.","o":["must have","can't have","should have","will have"],"a":1,"e":"O'tgan inkor xulosa: can't have + V3."},{"q":"He ___ come by taxi. (past deduction, sure)","o":["must have","must","can have","should"],"a":0,"e":"O'tgan xulosa: must + perfect infinitiv."},{"q":"In the three-keys example, the third key is described with:","o":["might","may","must","could"],"a":2,"e":"Ikki kalit ochmagach, uchinchisi uchun must — eng yuqori ishonch."},{"q":"Which assumption is more confident?","o":["Tom should know the address.","Tom will know the address.","Tom ought know the address.","Tom might know the address."],"a":1,"e":"will bilan taxmin should ga qaraganda ishonchliroq."},{"q":"Let's not go shopping. The shops ___ be very crowded.","o":["should","will","ought to","must not"],"a":1,"e":"Yoqimsiz taxminlar uchun should ishlatilmaydi — will."},{"q":"The plane ___ be landing now. (= should)","o":["ought to","must not","can't","needn't"],"a":0,"e":"should o'rnida ought to ishlatilishi mumkin."},{"q":"The police are stopping all cars. They ___ looking for the prisoner.","o":["must be","must","can't be","should have"],"a":0,"e":"Hozirgi jarayon haqida xulosa: must be + V-ing."}]},{"id":"p8-11","en":"Noun Clauses","uz":"Ot ergash gaplar (noun clauses)","emoji":"🧩","level":"B2","group":"Infinitiv, gerund va ergash gaplar","summary":"Ergash gaplarning uch turi va ot vazifasidagi ergash gaplar: that, so'roq so'zlari hamda whether / if bilan boshlanadigan turlari.","blocks":[{"t":"h","x":"Ergash gap turlari"},{"t":"list","items":["Noun clause — ot ergash gap","Adjective clause — sifat (aniqlovchi) ergash gap","Adverb clause — ravish (hol) ergash gap"]},{"t":"p","x":"<b>Noun clause</b> — ot vazifasini bajaradigan tobe gap. U otning har qanday o'rnida kela oladi: ega sifatida, fe'lning to'ldiruvchisi sifatida, <i>to be</i> dan keyin, predlogning to'ldiruvchisi sifatida."},{"t":"p","x":"Ot ergash gaplarning uch turi bor:"},{"t":"list","items":["Darak gapdan hosil bo'lganlar (clause marker: <b>that</b>)","WH-so'roq gaplardan hosil bo'lganlar (clause marker: so'roq so'zi)","Ha/yo'q so'roq gaplardan hosil bo'lganlar (clause marker: <b>whether / if</b>)"]},{"t":"h","x":"1. Darak gapdan: that"},{"t":"p","x":"Har bir ergash gap <b>clause marker</b> (bog'lovchi so'z) bilan boshlanadi. Bu turda <b>that</b> ishlatiladi."},{"t":"ex","en":"Tom plays the piano well. + This is a generally accepted fact. → That Tom plays the piano well is a generally accepted fact.","uz":"Tomning pianinoni yaxshi chalishi hammaga ma'lum haqiqat."},{"t":"p","x":"Ergash gap fe'lning to'ldiruvchisi bo'lsa, <b>that</b> tushirib qoldirilishi mumkin."},{"t":"ex","en":"I know that Tom has to go. = I know Tom has to go.","uz":"Tom ketishi kerakligini bilaman."},{"t":"rule","x":"Ergash gap predlogdan keyin kelsa, <b>that</b> ishlatilmaydi — uning o'rniga <b>what</b> ishlatiladi: I am against what you have said."},{"t":"h","x":"2. WH-so'roqdan: so'roq so'zlari"},{"t":"table","head":["So'z","Nimani bildiradi"],"rows":[["what","fakt, narsa"],["when","vaqt"],["where","joy"],["why","sabab"],["who / whom","shaxs"],["how many","miqdor (sanaladigan)"],["how much","miqdor (sanalmaydigan)"],["how","usul"],["which","tanlov"],["whose","egalik"]]},{"t":"rule","x":"Ergash gapda so'z tartibi darak gapdagidek bo'ladi (inversiya yo'q)."},{"t":"ex","en":"Why did he leave early? → She told us why he had left early.","uz":"U nega erta ketganini aytdi."},{"t":"ex","en":"Where does she live? → He asked where she lived.","uz":"U qayerda yashashini so'radi."},{"t":"h","x":"3. Ha/yo'q so'roqdan: whether / if"},{"t":"p","x":"<b>whether / if</b> ikki yoki undan ortiq muqobil variantni bildiradi."},{"t":"ex","en":"Should I bring my bike with me? → I don't know whether I should bring my bike with me.","uz":"Velosipedimni olib borishim kerakmi-yo'qmi, bilmayman."},{"t":"rule","x":"Odatda whether va if orasida farq yo'q, lekin ergash gap <b>ega</b> yoki <b>predlogning to'ldiruvchisi</b> bo'lsa, <b>if</b> ishlatilmaydi — faqat whether."},{"t":"ex","en":"Did the students finish the exam? → Whether the students finished the exam hasn't been reported to me yet.","uz":"Talabalar imtihonni tugatgan-tugatmagani menga hali xabar qilinmadi."}],"quiz":[{"q":"___ Tom plays the piano well is a generally accepted fact.","o":["What","That","If","Which"],"a":1,"e":"Darak gapdan hosil bo'lgan ot ergash gap that bilan boshlanadi."},{"q":"I am against ___ you have said.","o":["that","what","which","whether"],"a":1,"e":"Predlogdan keyin that emas, what ishlatiladi."},{"q":"In which sentence can 'that' be omitted?","o":["That he left surprised us.","I know that Tom has to go.","I'm against that he said.","That she is ill is clear."],"a":1,"e":"Fe'lning to'ldiruvchisi bo'lgan ergash gapda that tushib qolishi mumkin."},{"q":"He asked where ___.","o":["does she live","she lived","did she live","lives she"],"a":1,"e":"Ergash gapda so'z tartibi darak gapdagidek."},{"q":"___ the students finished the exam hasn't been reported yet.","o":["If","Whether","That","What"],"a":1,"e":"Ega vazifasida if ishlatilmaydi — whether."},{"q":"I don't know ___ I should bring my bike.","o":["that","whether","what","which"],"a":1,"e":"Ha/yo'q so'roqdan hosil bo'lgan ergash gap whether/if bilan."},{"q":"Which clause marker indicates a choice?","o":["whose","which","how","why"],"a":1,"e":"which — tanlovni bildiradi."},{"q":"How many types of noun clauses does the book give?","o":["two","three","four","five"],"a":1,"e":"Darak, WH-so'roq va ha/yo'q so'roqdan hosil bo'lgan — uch tur."},{"q":"She told us why he ___ early.","o":["did leave","had left","did he leave","has he left"],"a":1,"e":"Ergash gapda inversiya bo'lmaydi; ko'chirma gapda zamon orqaga suriladi."}]},{"id":"p8-12","en":"Adjective (Relative) Clauses","uz":"Sifat (nisbiy) ergash gaplar","emoji":"🔗","level":"B2","group":"Infinitiv, gerund va ergash gaplar","summary":"Cheklovchi va cheklamaydigan aniqlovchi ergash gaplar, who / whom / which / that / whose / where / when va ularning qisqartirilgan shakllari.","blocks":[{"t":"p","x":"<b>Adjective clause</b> — sifat vazifasini bajaruvchi tobe gap; u gapdagi otga qo'shimcha ma'lumot beradi. Boshqa nomi — <b>relative clause</b>."},{"t":"ex","en":"The car which has a ribbon on it is mine.","uz":"Ustida lentasi bor mashina meniki."},{"t":"h","x":"Cheklovchi va cheklamaydigan gaplar"},{"t":"table","head":["Turi","Vazifasi","Vergul"],"rows":[["Restrictive (cheklovchi)","Otni boshqa otlardan ajratib, aniqlab beradi","Hech qachon vergul qo'yilmaydi"],["Non-restrictive (cheklamaydigan)","Faqat qo'shimcha ma'lumot beradi","Har doim vergul bilan ajratiladi"]]},{"t":"ex","en":"The boy who wore a white T-shirt and blue pants is my neighbour.","uz":"Oq futbolka va ko'k shim kiygan bola — qo'shnim."},{"t":"ex","en":"The circle, which has a star in it, is used in religious ceremonies.","uz":"Ichida yulduzi bor doira diniy marosimlarda ishlatiladi."},{"t":"rule","x":"Atoqli otni tavsiflovchi gap cheklamaydigan bo'ladi, chunki atoqli ot yagona shaxs, joy yoki narsani bildiradi."},{"t":"ex","en":"A man who works at Nestle is usually late. / Tom, who works at Nestle, is usually late.","uz":"Nestleda ishlaydigan bir kishi odatda kechikadi. / Nestleda ishlovchi Tom odatda kechikadi."},{"t":"h","x":"Nisbiy olmoshlar"},{"t":"list","items":["<b>which</b> — narsa yoki predmet uchun: The table which you bought from an antique shop is beautiful.","<b>who</b> — shaxs, ergash gapda ega bo'lsa: The man who marries that woman will be the luckiest man on Earth.","<b>whom</b> — shaxs, fe'l yoki predlogning to'ldiruvchisi bo'lsa: The girl whom we saw in the park yesterday has been in a terrible accident.","Zamonaviy ingliz tilida whom o'rnida <b>who</b> ham ishlatiladi: The girl who we saw in the park...","<b>that</b> — ham narsa, ham shaxs uchun: The table that you bought... / The girl that we saw..."]},{"t":"rule","x":"Cheklamaydigan gapda <b>that</b> ishlatilmaydi: Virginia, which is said to be quite beautiful, is the home of many senators."},{"t":"h","x":"Predlog bilan"},{"t":"p","x":"Nisbiy olmosh predlogning to'ldiruvchisi bo'lsa, ikki yo'l bor: predlog olmoshdan oldin yoki ergash gap oxirida keladi."},{"t":"ex","en":"The man whom you spoke to is leaving. = The man to whom you spoke is leaving.","uz":"Siz gaplashgan odam ketyapti."},{"t":"h","x":"Olmoshni tushirib qoldirish"},{"t":"p","x":"Nisbiy olmosh ergash gapda <b>to'ldiruvchi</b> bo'lsa, u faqat cheklovchi gaplarda tushirib qoldirilishi mumkin."},{"t":"ex","en":"I suggest that you read the book which I bought at the bookstore. = ...the book I bought at the bookstore.","uz":"Kitob do'konidan olgan kitobimni o'qishingizni maslahat beraman."},{"t":"rule","x":"Nisbiy olmosh ergash gapda <b>ega</b> bo'lsa, uni tushirib bo'lmaydi: I suggest that you read the book which won the prize."},{"t":"h","x":"Where, when, whose"},{"t":"p","x":"<b>where</b> joyni, <b>when</b> vaqtni tavsiflaydi; ular <b>relative adverbs</b> deyiladi va ular bilan predlog kerak emas."},{"t":"ex","en":"The city where I grew up is now famous.","uz":"Men o'sgan shahar hozir mashhur."},{"t":"ex","en":"She would never forget the day when Sam arrived.","uz":"U Sem kelgan kunni hech qachon unutmaydi."},{"t":"p","x":"<b>whose</b> egalikni bildiradi; odatda shaxslar uchun, lekin narsalar uchun ham ishlatiladi."},{"t":"ex","en":"The chairman, whose committee was so successful last term, was re-elected for another term.","uz":"Qo'mitasi o'tgan muddatda muvaffaqiyatli ishlagan rais qayta saylandi."},{"t":"ex","en":"The table whose leg is broken can't be fixed.","uz":"Oyog'i singan stolni tuzatib bo'lmaydi."},{"t":"rule","x":"whose + ot o'rnida faqat narsalar uchun <b>ot + of which</b> ishlatilishi mumkin va u vergul bilan ajratiladi: The table, the leg of which is broken, can't be fixed."},{"t":"h","x":"Qisqartirilgan sifat ergash gaplar"},{"t":"p","x":"Agar ergash gapning egasi (nisbiy olmosh) bosh gapdagi aniqlanayotgan ot bilan bir xil bo'lsa, ergash gap <b>ibora</b>ga qisqartirilishi mumkin. Ibora — ega ham, tuslangan fe'l ham bo'lmagan so'zlar guruhi."},{"t":"ex","en":"The building which is being destroyed is situated in our district. → The building being destroyed is situated in our district.","uz":"Buzilayotgan bino bizning tumanda joylashgan."},{"t":"rule","x":"Ergash gapning egasi boshqa bo'lsa, qisqartirib bo'lmaydi: The building which they are destroying is situated in our district."},{"t":"list","items":["Ergash gapda <b>to be</b> bo'lsa: nisbiy olmosh va to be tushiriladi. The man who is standing near the tree is my uncle. → The man standing near the tree is my uncle.","<b>to be</b> bo'lmasa: nisbiy olmosh tushiriladi va fe'l <b>-ing</b> (present participle) shakliga o'tadi. The Smiths, who live in the southern part of the city, have their own bus. → The Smiths, living in the southern part of the city, have their own bus."]}],"quiz":[{"q":"Tom, ___ works at Nestle, is usually late.","o":["that","who","which","whom"],"a":1,"e":"Cheklamaydigan gapda that ishlatilmaydi; shaxs uchun who."},{"q":"The girl ___ we saw in the park has been in an accident. (object, formal)","o":["who's","whom","which","whose"],"a":1,"e":"Shaxs to'ldiruvchi bo'lsa whom (zamonaviy tilda who ham)."},{"q":"Which sentence is correct?","o":["Virginia, that is beautiful, is a state.","Virginia, which is beautiful, is a state.","Virginia which is beautiful, is a state.","Virginia, whom is beautiful, is a state."],"a":1,"e":"Cheklamaydigan gap vergul bilan va which bilan (that emas)."},{"q":"The man to ___ you spoke is leaving.","o":["who","that","whom","which"],"a":2,"e":"Predlogdan keyin shaxs uchun whom."},{"q":"In which sentence can the relative pronoun be omitted?","o":["I read the book which won the prize.","I read the book which I bought yesterday.","Tom, who lives here, is kind.","The man who called is my uncle."],"a":1,"e":"Olmosh to'ldiruvchi va gap cheklovchi bo'lsa tushib qolishi mumkin."},{"q":"The city ___ I grew up is now famous.","o":["which","where","when","whose"],"a":1,"e":"Joy uchun where; predlog kerak emas."},{"q":"The table ___ leg is broken can't be fixed.","o":["which","whose","whom","that"],"a":1,"e":"Egalik uchun whose."},{"q":"Reduce: The man who is standing near the tree is my uncle.","o":["The man stands near the tree is my uncle.","The man standing near the tree is my uncle.","The man is standing near the tree is my uncle.","The man who standing near the tree is my uncle."],"a":1,"e":"Olmosh va to be tushiriladi."},{"q":"A restrictive adjective clause is ___.","o":["always used with commas","never used with commas","used only with proper nouns","always introduced by whose"],"a":1,"e":"Cheklovchi gap hech qachon vergul bilan ajratilmaydi."},{"q":"Which clause can NOT be reduced?","o":["The building which is being destroyed...","The man who is standing there...","The building which they are destroying...","The Smiths, who live in the south..."],"a":2,"e":"Ergash gap egasi (they) aniqlanayotgan otdan boshqa — qisqartirilmaydi."}]},{"id":"p8-13","en":"Adverb Clauses and Appositives","uz":"Hol ergash gaplar va izohlovchi (appositive)","emoji":"⏱️","level":"B2","group":"Infinitiv, gerund va ergash gaplar","summary":"Ravish (hol) ergash gaplar, ulardagi vergul qoidasi, qisqartirilgan shakllari va izohlovchi otlar.","blocks":[{"t":"h","x":"Adverb clause (hol ergash gap)"},{"t":"p","x":"<b>Adverb clause</b> — ravish vazifasini bajaruvchi tobe gap. U vaqt, joy, qarama-qarshilik, sabab, natija, maqsad, shart, tarz yoki daraja haqida ma'lumot beradi. Uni boshlovchi so'zlar <b>subordinate conjunctions</b> (ergashtiruvchi bog'lovchilar) deyiladi."},{"t":"p","x":"Keng tarqalgan bog'lovchilar: <b>where, wherever, because, since, before, after, until, although, even though, whereas, while, as though, when, whenever, now that, as ... as, in that, so, so that, if, in order that, unless, in case, as if</b>."},{"t":"rule","x":"Hol ergash gap bosh gapdan <b>oldin</b> kelsa, vergul qo'yiladi; bosh gapdan <b>keyin</b> kelsa, vergul qo'yilmaydi."},{"t":"ex","en":"When I see him, I will tell him.","uz":"Uni ko'rganimda aytaman."},{"t":"ex","en":"I will tell him when I see him.","uz":"Uni ko'rganimda aytaman."},{"t":"h","x":"Qisqartirilgan hol ergash gaplar"},{"t":"p","x":"Sifat ergash gaplar kabi, hol ergash gapning egasi bosh gap egasi bilan bir xil bo'lsa, u qisqartirilishi mumkin."},{"t":"list","items":["Ergash gapda <b>to be</b> bo'lsa: avval ega, keyin to be tushiriladi.","<b>to be</b> bo'lmasa: ega tushiriladi va fe'l <b>-ing</b> shakliga o'tadi."]},{"t":"ex","en":"When I was walking in the park, I saw my old friend. → When walking in the park, I saw my old friend.","uz":"Bog'da sayr qilayotib eski do'stimni ko'rdim."},{"t":"ex","en":"Before Bill moved to London, he worked for the BBC. → Before moving to London, Bill worked for the BBC.","uz":"Londonga ko'chishdan oldin Bill BBC da ishlagan."},{"t":"p","x":"Hol ergash gap bosh gapdan oldin kelsa, kitobga ko'ra bog'lovchini ham tushirib qoldirish mumkin."},{"t":"ex","en":"When I was walking in the garden, I saw my old friend. → Walking in the garden, I saw my old friend.","uz":"Bog'da sayr qilib yurib, eski do'stimni ko'rdim."},{"t":"rule","x":"Diqqat: bog'lovchi muhim ma'no tashisa (masalan, <i>before</i>), uni saqlash yaxshiroq, aks holda ma'no noaniq bo'lib qolishi mumkin."},{"t":"h","x":"Appositive (izohlovchi)"},{"t":"p","x":"<b>Appositive</b> — gapdagi boshqa ot haqida qo'shimcha ma'lumot beruvchi ot. U yakka ot yoki artikl, predlog va hokazolar bilan kelgan ot birikmasi bo'lishi mumkin. Odatda egadan keyin keladi va <b>albatta vergul bilan ajratiladi</b>."},{"t":"ex","en":"George Washington, the first president of the USA, was born in Virginia.","uz":"AQShning birinchi prezidenti Jorj Vashington Virjiniyada tug'ilgan."},{"t":"ex","en":"The old tree, a hundred-year-old oak, in front of the house is going to be cut down soon.","uz":"Uy oldidagi yuz yillik eman daraxti tez orada kesiladi."},{"t":"p","x":"Izohlovchi egadan oldin ham kelishi mumkin."},{"t":"ex","en":"The hottest planet in the solar system, Mercury is a mere 36,000,000 miles from the sun.","uz":"Quyosh tizimidagi eng issiq sayyora Merkuriy Quyoshdan bor-yo'g'i 36 million mil uzoqlikda."}],"quiz":[{"q":"Which sentence is punctuated correctly?","o":["I will tell him, when I see him.","When I see him I will tell him, .","When I see him, I will tell him.","When, I see him I will tell him."],"a":2,"e":"Ergash gap oldin kelsa, vergul qo'yiladi."},{"q":"Reduce: When I was walking in the park, I saw my friend.","o":["When walked in the park, I saw my friend.","When walking in the park, I saw my friend.","When I walking in the park, I saw my friend.","When was walking in the park, I saw my friend."],"a":1,"e":"Ega va to be tushiriladi."},{"q":"Reduce: Before Bill moved to London, he worked for the BBC.","o":["Before moved to London, Bill worked for the BBC.","Before moving to London, Bill worked for the BBC.","Before Bill moving to London, he worked for the BBC.","Before to move to London, Bill worked for the BBC."],"a":1,"e":"to be yo'q — ega tushadi, fe'l -ing shakliga o'tadi."},{"q":"An adverb clause can be reduced when:","o":["it has no verb","its subject is the same as the main clause subject","it comes after the main clause only","it begins with because only"],"a":1,"e":"Ikkala gapning egasi bir xil bo'lishi shart."},{"q":"Which word is a subordinate conjunction?","o":["although","and","but","or"],"a":0,"e":"although — ergashtiruvchi bog'lovchi; qolganlari teng bog'lovchilar."},{"q":"George Washington ___ the first president of the USA ___ was born in Virginia.","o":["( no punctuation )","commas: , ... ,","only one comma after Washington","semicolons"],"a":1,"e":"Izohlovchi har doim vergul bilan ajratiladi."},{"q":"In 'The hottest planet in the solar system, Mercury is...', the appositive is:","o":["Mercury","The hottest planet in the solar system","is","the sun"],"a":1,"e":"Izohlovchi bu yerda egadan oldin kelgan."},{"q":"Which sentence needs NO comma?","o":["Because it rained we stayed home.","We stayed home because it rained.","When he came I left.","If you go I'll go."],"a":1,"e":"Ergash gap bosh gapdan keyin kelsa vergul qo'yilmaydi."}]},{"id":"p8-14","en":"Conditional Sentences: Types 1, 2 and 3","uz":"Shart gaplar: 1-, 2- va 3-tur","emoji":"🔀","level":"B1","group":"Ko'chirma gap va murakkab gaplar","summary":"Present va perfect conditional zamonlarining yasalishi hamda shart gaplarning uch asosiy turi.","blocks":[{"t":"h","x":"Shart zamonlari"},{"t":"table","head":["Zamon","Yasalishi","Misol"],"rows":[["Present conditional","I/we: would/should + V; boshqalar: would + V","I would go. We should go. You would go."],["Perfect conditional","I/we: would/should + have + V3; boshqalar: would + have + V3","I would have gone. We should have gone. You would have gone."]]},{"t":"p","x":"Shart gap ikki qismdan iborat: <b>if clause</b> (shart qismi) va <b>main clause</b> (bosh gap)."},{"t":"h","x":"1-tur (real shart)"},{"t":"formula","x":"If + Present Simple, ... will + V"},{"t":"p","x":"Qaysi qism oldin kelishi ahamiyatsiz. 1-tur <i>if</i> qismidagi harakat ancha ehtimolli ekanini bildiradi. <i>if</i> qismida fe'l doim hozirgi zamonda bo'ladi, ammo ma'no hozirgi yoki kelasi zamon bo'lishi mumkin."},{"t":"ex","en":"If it rains, we'll stay at home.","uz":"Yomg'ir yog'sa, uyda qolamiz."},{"t":"ex","en":"The cat will scratch you if you pull her tail.","uz":"Mushukning dumidan tortsang, u seni tirnaydi."},{"t":"h","x":"2-tur (noreal / ehtimoldan uzoq shart)"},{"t":"formula","x":"If + Past Simple, ... would + V"},{"t":"p","x":"Hozirgi yoki kelasi zamonga tegishli. <i>if</i> qismidagi o'tgan zamon noreallik yoki ehtimoldan uzoqlikni bildiradi."},{"t":"ex","en":"If I had a map, I would lend it to you.","uz":"Xaritam bo'lganida, senga berib turardim."},{"t":"p","x":"Taxmin ma'lum faktlarga zid bo'lganda ishlatiladi:"},{"t":"ex","en":"If I lived near my office, I wouldn't be late for work. (But I don't live near it.)","uz":"Ishxonamga yaqin yashaganimda, ishga kechikmasdim."},{"t":"p","x":"<i>if</i> qismidagi harakat sodir bo'lishini kutmaganimizda ishlatiladi:"},{"t":"ex","en":"If a burglar came into my room at night, I would scream. (But I don't expect one to come.)","uz":"Kechasi xonamga o'g'ri kirsa, qichqirib yuborardim."},{"t":"rule","x":"<b>If I/he/she/it were</b> shakli <i>was</i> o'rnida ishlatiladi va to'g'riroq hisoblanadi: If he were an actor, he would be famous. Maslahat iborasi: If I were you, I wouldn't do that."},{"t":"h","x":"3-tur (o'tmishdagi amalga oshmagan shart)"},{"t":"formula","x":"If + Past Perfect, ... would have + V3"},{"t":"p","x":"Vaqt — o'tgan zamon, shart bajarilishi mumkin emas, chunki <i>if</i> qismidagi harakat sodir bo'lmagan. Ya'ni ikkala harakat ham bajarilmagan."},{"t":"ex","en":"If I had known that you were coming, I'd have met you at the station. (But I didn't know, so I didn't meet you.)","uz":"Kelayotganingizni bilganimda, sizni vokzalda kutib olgan bo'lardim."},{"t":"ex","en":"If he had tried to leave the country, he would have been stopped at the frontier. (But he didn't try.)","uz":"U mamlakatni tark etishga uringanida, chegarada to'xtatilgan bo'lardi."}],"quiz":[{"q":"If it ___, we'll stay at home.","o":["will rain","rains","rained","had rained"],"a":1,"e":"1-tur: if + Present Simple."},{"q":"If I had a map, I ___ it to you.","o":["will lend","would lend","lend","would have lent"],"a":1,"e":"2-tur: if + Past Simple, would + V."},{"q":"If I had known you were coming, I ___ you at the station.","o":["would meet","will meet","would have met","met"],"a":2,"e":"3-tur: if + Past Perfect, would have + V3."},{"q":"If he ___ an actor, he would be famous. (more correct form)","o":["is","was","were","be"],"a":2,"e":"2-turda were shakli to'g'riroq hisoblanadi."},{"q":"'If I lived near my office, I wouldn't be late.' Which is true?","o":["I live near my office.","I don't live near my office.","I lived near my office in the past.","I will live near my office."],"a":1,"e":"2-tur faktlarga zid taxmin."},{"q":"'If he had tried to leave, he would have been stopped.' Did he try?","o":["Yes","No","We don't know","He is trying now"],"a":1,"e":"3-turda ikkala harakat ham bajarilmagan."},{"q":"Perfect conditional of 'go' for 'you':","o":["you would go","you would have gone","you will have gone","you had gone"],"a":1,"e":"would + perfect infinitiv."},{"q":"The cat will scratch you if you ___ her tail.","o":["will pull","pull","pulled","would pull"],"a":1,"e":"1-tur: if qismida hozirgi zamon (ma'no kelasi bo'lsa ham)."},{"q":"If I ___ you, I wouldn't do that.","o":["am","was being","were","be"],"a":2,"e":"Maslahat: If I were you..."}]},{"id":"p8-15","en":"Conditionals: Variations, Inversion and Special Uses","uz":"Shart gaplar: variantlar, inversiya va maxsus qo'llanishlar","emoji":"🔁","level":"B2","group":"Ko'chirma gap va murakkab gaplar","summary":"Shart gaplarning uchala turidagi variantlar, aralash shart, inversiya, if dagi will / would / should va if only.","blocks":[{"t":"h","x":"1-tur variantlari: bosh gap"},{"t":"list","items":["<b>if + present + may / might / can</b>: If the fog gets thicker, the plane may / might be diverted. If your documents are in order, you may / can leave.","<b>if + present + must / should / buyruq / iltimos / maslahat</b>: If you want to lose weight, you must / should / ought to eat less bread. If you want to lose weight, eat less bread.","<b>if + ikki hozirgi zamon</b> — avtomatik yoki odatiy natija: If you heat ice, it turns to water."]},{"t":"h","x":"1-tur variantlari: if qismi"},{"t":"list","items":["<b>if + present continuous</b> — hozirgi harakat yoki kelajak rejasi: If you are waiting for a bus, you had better join the queue. If you are staying for another night, I will ask the manager to give you a better room.","<b>if + present perfect</b>: If you have finished dinner, I will ask the waiter for the bill."]},{"t":"h","x":"2-tur variantlari"},{"t":"list","items":["Bosh gapda would o'rnida <b>might / could</b>: If you tried again, you might succeed. If I knew her number, I could ring her up.","Davomli shart shakli: Peter is on holiday; he is touring in Italy. — If I were on holiday, I would be touring in Italy too.","<b>if + past + past</b> — o'tmishdagi avtomatik / odatiy reaksiya: If anyone interrupted him, he got angry.","if qismida <b>past perfect</b> (aralash shart): If he had taken my advice, he would be a rich man now."]},{"t":"h","x":"3-tur variantlari"},{"t":"list","items":["Bosh gapda <b>could / might</b>: If I had found him earlier, we could / might have saved his life.","Perfect conditionalning davomli shakli: I was sitting in the back because Tom was sitting in front. If Tom hadn't been there, I would have been sitting in the front.","if qismida <b>past perfect continuous</b>: If I hadn't been wearing a seat belt, I would have been injured.","2- va 3-turning aralashmasi: The plane I intended to catch crashed and everyone was killed. If I had caught that plane, I would be dead now."]},{"t":"h","x":"Inversiya"},{"t":"p","x":"<b>if + ega + yordamchi fe'l</b> o'rniga <b>yordamchi fe'l + ega</b> qo'yiladi va <b>if</b> tushib qoladi."},{"t":"ex","en":"If I were in his shoes... → Were I in his shoes, I could run faster.","uz":"Uning o'rnida bo'lganimda..."},{"t":"ex","en":"If I had obeyed the rules... → Had I obeyed the rules...","uz":"Qoidalarga rioya qilganimda..."},{"t":"rule","x":"Inversiyada <b>was</b> ishlatilmaydi, faqat <b>were</b>: If I was/were a driver... → Were I a driver, I would drive slowly."},{"t":"h","x":"if qismida will / would / should"},{"t":"list","items":["<b>If you will / would</b> — xushmuomala iltimos (would xushmuomalaroq): If you'll wait a moment... (= Please wait a moment.) If you would fill in this form... (= Please fill in the form.)","<b>will</b> (real) / <b>would</b> (noreal) — xohish-istak: If he will listen to me, I will be able to help him. If Tom would tell me what he wants for dinner, I would cook it. (Tom is unwilling to tell.)","<b>won't</b> — rad etish: If he won't listen to me, I can't help him. (He refuses to listen.)","<b>will</b> — o'jarlik bilan turib olish: If you will play the drums all night, no wonder the neighbours complain.","<b>if + would like / care</b> = if + want / wish, xushmuomalaroq: If you would like to come, I'll get a ticket for you. If he would like to leave his car here, he can.","would like dan keyin obyekt bo'lmasa, would tushadi: If you like, I'll get a ticket for you. If he likes, he can leave his car here.","<b>if + should</b> (1-tur) — harakat unchalik ehtimolli emas; asosan yozma ko'rsatmalarda: If these biscuits should arrive in a damaged condition, please inform us at once."]},{"t":"h","x":"If only"},{"t":"table","head":["Qurilma","Ma'nosi","Misol"],"rows":[["if only + present / future","umid","If only he comes in time! If only he will listen to her!"],["if only + past / past perfect","afsus","If only he didn't smoke! If only you hadn't said that!"],["if only + would","hozirgi harakatdan afsus/norozilik","If only he would drive more slowly!"]]}],"quiz":[{"q":"If you heat ice, it ___ to water.","o":["will turn","turns","would turn","turned"],"a":1,"e":"Avtomatik natija: if + ikki hozirgi zamon."},{"q":"If you ___ dinner, I'll ask the waiter for the bill.","o":["have finished","had finished","would finish","finished"],"a":0,"e":"1-tur if qismida present perfect ham kelishi mumkin."},{"q":"If he had taken my advice, he ___ a rich man now.","o":["would have been","would be","will be","had been"],"a":1,"e":"Aralash shart: o'tmishdagi shart, hozirgi natija."},{"q":"Choose the correct inversion: If I had obeyed the rules...","o":["Had I obeyed the rules...","I had obeyed the rules...","Did I obey the rules...","Have I obeyed the rules..."],"a":0,"e":"Yordamchi fe'l egadan oldin, if tushadi."},{"q":"___ I a driver, I would drive slowly.","o":["Was","Were","If","Am"],"a":1,"e":"Inversiyada faqat were ishlatiladi."},{"q":"If he ___ listen to me, I can't help him. (he refuses)","o":["will","would","won't","shall"],"a":2,"e":"won't — rad etishni bildiradi."},{"q":"If these biscuits ___ arrive damaged, please inform us.","o":["will","should","would","shall be"],"a":1,"e":"if + should — ehtimoli kam holat, yozma ko'rsatmalarda."},{"q":"If only you ___ that! (regret about the past)","o":["don't say","hadn't said","won't say","haven't said"],"a":1,"e":"if only + past perfect — o'tmishdan afsus."},{"q":"If I hadn't been wearing a seat belt, I ___ injured.","o":["would be","will have been","would have been","had been"],"a":2,"e":"3-tur: if qismida past perfect continuous ham bo'ladi."},{"q":"If you ___, I'll get a ticket for you. (no object)","o":["would like","like","liked","will like"],"a":1,"e":"Obyekt bo'lmasa would tushib, if you like qoladi."}]},{"id":"p8-16","en":"The Subjunctive Mood","uz":"Subjunktiv (istak) mayli","emoji":"📜","level":"C1","group":"Ko'chirma gap va murakkab gaplar","summary":"Talab, taklif va zaruratni bildiruvchi fe'l va sifatlardan keyin that + ega + fe'lning oddiy shakli.","blocks":[{"t":"p","x":"<b>Subjunctive mood</b> — bir shaxs boshqa shaxsning biror ish qilishini xohlashini bildiruvchi ayrim fe'llardan keyin fe'lning <b>oddiy (to'siz) shakli</b> ishlatilishi. Bunday gaplarda <b>that</b> albatta bo'lishi kerak."},{"t":"rule","x":"Ega uchinchi shaxs birlikda bo'lsa ham fe'lga -s qo'shilmaydi: that he <b>leave</b> (leaves emas)."},{"t":"h","x":"Fe'llardan keyin"},{"t":"formula","x":"S + V + that + S + bare infinitive"},{"t":"ex","en":"We urge that he leave now.","uz":"Uning hozir ketishini talab qilamiz."},{"t":"p","x":"Bu qurilmada ishlatiladigan fe'llar: <b>advise, ask, command, decree, demand, insist, move, order, prefer, propose, recommend, request, require, stipulate, suggest, urge</b>."},{"t":"ex","en":"The doctor suggested that his patient stop smoking.","uz":"Shifokor bemoriga chekishni tashlashni tavsiya qildi."},{"t":"h","x":"Sifatlardan keyin"},{"t":"formula","x":"It + be + adjective + that + S + bare infinitive"},{"t":"p","x":"Ishlatiladigan sifatlar: <b>advised, important, imperative, mandatory, necessary, obligatory, proposed, recommended, required, suggested, urgent</b>."},{"t":"ex","en":"It is necessary that he find the book.","uz":"Uning kitobni topishi zarur."},{"t":"ex","en":"It was urgent that she leave at once.","uz":"Uning darhol ketishi shoshilinch edi."}],"quiz":[{"q":"We urge that he ___ now.","o":["leaves","leave","left","will leave"],"a":1,"e":"Subjunktivda fe'lning oddiy shakli: leave."},{"q":"The doctor suggested that his patient ___ smoking.","o":["stops","stop","stopped","to stop"],"a":1,"e":"suggest + that + S + bare infinitive."},{"q":"It is necessary that he ___ the book.","o":["finds","find","found","to find"],"a":1,"e":"It is necessary that + S + bare infinitive."},{"q":"It was urgent that she ___ at once.","o":["leaves","left","leave","had left"],"a":2,"e":"O'tgan zamonda ham oddiy shakl: leave."},{"q":"Which word must appear in subjunctive sentences of this type?","o":["to","that","if","which"],"a":1,"e":"Subjunktiv gaplarda that albatta bo'ladi."},{"q":"Which verb is followed by the subjunctive?","o":["demand","enjoy","finish","know"],"a":0,"e":"demand — talabni bildiradi."},{"q":"Which adjective is used in 'It is ___ that he be present'?","o":["happy","imperative","beautiful","tired"],"a":1,"e":"imperative — subjunktiv oladigan sifat."},{"q":"They insisted that she ___ the meeting.","o":["attends","attend","attended","to attend"],"a":1,"e":"insist + that + S + bare infinitive."},{"q":"Which sentence is correct?","o":["I recommend that he takes a rest.","I recommend that he take a rest.","I recommend him that take a rest.","I recommend that he to take a rest."],"a":1,"e":"recommend that + S + bare infinitive (take)."}]},{"id":"p8-17","en":"So and Such","uz":"So va such","emoji":"✨","level":"B1","group":"Ko'chirma gap va murakkab gaplar","summary":"so ... that va such ... that qurilmalari: so sifat va ravish bilan, such otlar bilan ishlatiladi.","blocks":[{"t":"p","x":"Umuman olganda, <b>that</b> qurilmasida <b>so</b> sifat yoki ravish bilan, <b>such</b> esa ot bilan ishlatiladi."},{"t":"formula","x":"S + V + so + adjective / adverb + that + ..."},{"t":"ex","en":"She sang so well that she was asked to audition.","uz":"U shunchalik yaxshi kuyladiki, uni tinglovga taklif qilishdi."},{"t":"ex","en":"The food was so good that he couldn't resist it.","uz":"Ovqat shunchalik mazali ediki, o'zini tutolmadi."},{"t":"formula","x":"S + V + so + many / much / little / few + noun + that + ..."},{"t":"ex","en":"The man brought so many books that he needed assistance to carry them.","uz":"U shunchalik ko'p kitob olib keldiki, ko'tarish uchun yordam kerak bo'ldi."},{"t":"ex","en":"The cooks made so little food that some people were not served.","uz":"Oshpazlar shunchalik kam ovqat qilishdiki, ba'zilarga yetmadi."},{"t":"formula","x":"S + V + such + a/an + adjective + singular countable noun + that + ..."},{"t":"ex","en":"It was such a hot day that several people fainted.","uz":"Shunday issiq kun ediki, bir necha kishi hushidan ketdi."},{"t":"formula","x":"S + V + so + adjective + a/an + singular countable noun + that + ..."},{"t":"ex","en":"It was so hot a day that several people fainted.","uz":"Shunday issiq kun ediki, bir necha kishi hushidan ketdi."},{"t":"formula","x":"S + V + such + adjective + plural countable / uncountable noun + that + ..."},{"t":"ex","en":"This is such sour juice that I cannot drink it.","uz":"Bu sharbat shunchalik nordonki, ichib bo'lmaydi."},{"t":"ex","en":"They are such popular singers that they will likely win an award.","uz":"Ular shunchalik mashhur qo'shiqchilarki, mukofot olishlari aniq."},{"t":"rule","x":"Ko'plik yoki sanalmaydigan ot bilan <b>a/an</b> ishlatilmaydi va <b>so + adjective + noun</b> qurilmasi bo'lmaydi — faqat <b>such</b>."}],"quiz":[{"q":"She sang ___ well that she was asked to audition.","o":["such","so","such a","too"],"a":1,"e":"Ravish bilan so ishlatiladi."},{"q":"It was ___ hot day that several people fainted.","o":["so a","such a","such","so"],"a":1,"e":"such + a + sifat + birlik ot."},{"q":"It was so hot ___ day that several people fainted.","o":["the","a","such","—"],"a":1,"e":"so + sifat + a/an + birlik ot."},{"q":"The man brought ___ books that he needed help.","o":["such many","so many","so much","such a many"],"a":1,"e":"Miqdor so'zlari (many) bilan so."},{"q":"This is ___ sour juice that I cannot drink it.","o":["so","such a","such","so a"],"a":2,"e":"Sanalmaydigan ot bilan such (artiklsiz)."},{"q":"The cooks made ___ food that some people were not served.","o":["so few","so little","such little a","such few"],"a":1,"e":"Sanalmaydigan ot (food) bilan so little."},{"q":"They are ___ popular singers that they will win an award.","o":["so","such","so a","such a"],"a":1,"e":"Ko'plik ot bilan such + sifat + ot."},{"q":"The food was ___ good that he couldn't resist it.","o":["so","such","such a","so much"],"a":0,"e":"Sifat (good) yolg'iz kelsa so ishlatiladi."},{"q":"Which sentence is correct?","o":["They are so popular singers that...","They are such popular singers that...","They are such a popular singers that...","They are so a popular singers that..."],"a":1,"e":"Ko'plik ot bilan faqat such."}]},{"id":"p8-18","en":"Parallel Structure, Pronoun Antecedents and Redundancy","uz":"Parallel tuzilma, olmosh antetsedenti va ortiqchalik","emoji":"🧹","level":"B2","group":"Imlo va uslub","summary":"Ro'yxatdagi qismlarning grammatik bir xilligi, olmoshning aniq otga ishora qilishi va ma'nosi takrorlanuvchi ortiqcha so'zlardan qochish.","blocks":[{"t":"h","x":"Parallel structure (parallel tuzilma)"},{"t":"p","x":"Gapdagi ma'lumot ro'yxat yoki qator shaklida berilsa, barcha qismlar <b>grammatik jihatdan bir xil</b> bo'lishi kerak. Masalan, birinchisi infinitiv bo'lsa, qolganlari ham infinitiv bo'ladi."},{"t":"ex","en":"Peter is rich, handsome and popular.","uz":"Piter boy, kelishgan va mashhur. (sifatlar)"},{"t":"ex","en":"Henry is a lawyer, politician and teacher.","uz":"Genri huquqshunos, siyosatchi va o'qituvchi. (otlar)"},{"t":"ex","en":"The soldiers approached the enemy camp slowly and silently.","uz":"Askarlar dushman lageriga sekin va jim yaqinlashishdi. (ravishlar)"},{"t":"ex","en":"She likes fishing, swimming and surfing.","uz":"U baliq ovi, suzish va serfingni yaxshi ko'radi. (gerundlar)"},{"t":"rule","x":"Xato: She likes fishing, to swim and surfing. To'g'ri: She likes fishing, swimming and surfing."},{"t":"h","x":"Antecedent of pronouns (olmosh antetsedenti)"},{"t":"p","x":"<b>Antecedent</b> — olmosh ishora qiladigan ot. Gapda olmosh ishlatilsa, olmosh va antetsedent mantiqan to'g'ri va aniq bog'langan bo'lishi kerak."},{"t":"ex","en":"Tom is a lawyer. He is very famous.","uz":"Tom huquqshunos. U juda mashhur. (He = Tom)"},{"t":"table","head":["Noto'g'ri / noaniq","To'g'ri"],"rows":[["George dislikes politics because he believes that they are corrupt. (they = ?)","George dislikes politics because he believes that politicians are corrupt."],["Mr. Brown told Mr. Adams that he would have to work all night. (he = kim?)","Mr. Brown said that Mr. Adams would have to work all night."],["Janet visited her friend every day while she was on vacation. (she = kim?)","While Janet was on vacation, she visited her friend every day."]]},{"t":"h","x":"Redundancy (ortiqchalik)"},{"t":"p","x":"Ba'zi ma'lumot keraksiz takrorlangan gap <b>redundant</b> (ortiqcha) deyiladi."},{"t":"table","head":["Ortiqcha birikma","Izoh"],"rows":[["advance forward, proceed forward, progress forward","advance, proceed, progress o'zi «oldinga harakat qilish» degani — forward kerak emas"],["return back, revert back","return va revert «qaytmoq» degani — back kerak emas"],["sufficient enough","ikkalasi bir ma'noda — bittasini ishlating"],["compete together","compete — boshqalarga qarshi musobaqalashish; together ortiqcha"],["reason ... because","ikkalasi sababni bildiradi: the reason is that ..."],["join together","join — birlashtirmoq; together ortiqcha"],["repeat again","repeat — qaytarib aytmoq; again ortiqcha"],["new innovations","innovation — yangi g'oya; new ortiqcha"],["matinee performance","matinee — kunduzgi tomosha; performance ortiqcha"],["same identical","ikkalasi bir ma'noda"],["two twins","twins — ikki aka-uka yoki opa-singil; two ortiqcha"],["the time when","the time va when bir narsani bildiradi"],["the place where","the place va where bir narsani bildiradi"]]},{"t":"ex","en":"✗ That was the place where I saw him for the first time. → ✓ That was the place I saw him for the first time. / That was where I saw him for the first time.","uz":"U yerda men uni birinchi marta ko'rganman."},{"t":"ex","en":"✗ The carpenter joined the two beams together with long nails. → ✓ The carpenter joined the two beams with long nails.","uz":"Duradgor ikki to'sinni uzun mixlar bilan biriktirdi."}],"quiz":[{"q":"Choose the parallel sentence.","o":["She likes fishing, to swim and surfing.","She likes fishing, swimming and surfing.","She likes to fish, swimming and surf.","She likes fish, swimming and to surf."],"a":1,"e":"Ro'yxatdagi barcha qismlar bir xil shaklda (gerund)."},{"q":"Peter is rich, handsome and ___.","o":["popularity","popular","has popularity","popularly"],"a":1,"e":"Sifatlar qatori: rich, handsome, popular."},{"q":"The soldiers approached slowly and ___.","o":["silent","silently","silence","with silent"],"a":1,"e":"Ravishlar qatori: slowly and silently."},{"q":"Which sentence has a clear antecedent?","o":["George dislikes politics because he believes they are corrupt.","George dislikes politics because he believes politicians are corrupt.","George dislikes politics because they are corrupt he believes.","George dislikes it because they are corrupt."],"a":1,"e":"they kimga ishora qilishi aniq emas; politicians deb aniq aytish kerak."},{"q":"Which phrase is NOT redundant?","o":["return back","repeat again","advance","two twins"],"a":2,"e":"advance o'zi yetarli; qolganlarida takror bor."},{"q":"Correct the redundancy: 'We have sufficient enough money.'","o":["We have sufficient enough of money.","We have enough money.","We have sufficient enough.","We have enough sufficient money."],"a":1,"e":"sufficient va enough bir ma'noda — bittasini ishlating."},{"q":"Which is correct?","o":["The reason he left was because he was ill.","The reason he left was that he was ill.","The reason because he left was ill.","Because the reason he left was ill."],"a":1,"e":"reason ... because ortiqcha; the reason ... is that."},{"q":"'Matinee performance' is redundant because matinee means:","o":["an evening show","an afternoon performance","a new idea","a contest"],"a":1,"e":"matinee — kunduzgi tomosha."},{"q":"Choose the sentence without redundancy.","o":["The carpenter joined the beams together with nails.","The carpenter joined the beams with nails.","The carpenter joined together the beams together.","The carpenter together joined the beams."],"a":1,"e":"join o'zi birlashtirish degani — together ortiqcha."},{"q":"Mr. Brown told Mr. Adams that he would have to work all night. The problem is:","o":["wrong tense","unclear antecedent of 'he'","no subject","wrong preposition"],"a":1,"e":"he Brownmi yoki Adamsmi — noaniq."}]}];
